    $row = $db->select_user(
        "SELECT id
         FROM admin_mixer_events
         WHERE order_id = {$orderId}
           AND event_type = 'payout_notification_sent'
         LIMIT 1"
    );

    return is_array($row) && !empty($row['id']);
