function admin_admin_user_find(Mysql_ks $db, int $adminUserId): ?array
{
    admin_ensure_user_runtime_columns($db);

    if ($adminUserId <= 0 || !schema_object_exists($db, 'admin_users')) {
        return null;
    }

    $row = $db->select_user(
        "SELECT
            admin_users.id,
