function admin_dashboard_metrics(Mysql_ks $db): array
{
    $metrics = [
        'customers' => 0,
        'active_customers' => 0,
        'orders' => 0,
        'crypto_open' => 0,
        'bank_open' => 0,
        'news_posts' => 0,
        'email_templates' => 0,
        'faq_pages' => 0,
        'chat_open' => 0,
    ];

    if (schema_object_exists($db, 'customers')) {
        $row = $db->select_user("SELECT COUNT(*) AS total FROM customers");
        $metrics['customers'] = (int)($row['total'] ?? 0);

        $row = $db->select_user("SELECT COUNT(*) AS total FROM customers WHERE status = 'active'");
        $metrics['active_customers'] = (int)($row['total'] ?? 0);
    }

    if (schema_object_exists($db, 'orders')) {
        $row = $db->select_user("SELECT COUNT(*) AS total FROM orders");
        $metrics['orders'] = (int)($row['total'] ?? 0);
    }

    if (schema_object_exists($db, 'crypto_deposit_requests')) {
        $row = $db->select_user("SELECT COUNT(*) AS total FROM crypto_deposit_requests WHERE status IN ('pending', 'pending_payment', 'awaiting_confirmation', 'awaiting_review')");
        $metrics['crypto_open'] = (int)($row['total'] ?? 0);
    }

    if (schema_object_exists($db, 'bank_transfer_requests')) {
        $row = $db->select_user("SELECT COUNT(*) AS total FROM bank_transfer_requests WHERE status IN ('pending_payment', 'awaiting_review')");
        $metrics['bank_open'] = (int)($row['total'] ?? 0);
    }

    if (schema_object_exists($db, 'news_posts')) {
        $row = $db->select_user("SELECT COUNT(*) AS total FROM news_posts");
        $metrics['news_posts'] = (int)($row['total'] ?? 0);
    }

    if (schema_object_exists($db, 'email_templates')) {
        $row = $db->select_user("SELECT COUNT(*) AS total FROM email_templates");
        $metrics['email_templates'] = (int)($row['total'] ?? 0);
    }

    if (schema_object_exists($db, 'static_pages')) {
        $row = $db->select_user("SELECT COUNT(*) AS total FROM static_pages WHERE slug LIKE 'faq-%'");
        $metrics['faq_pages'] = (int)($row['total'] ?? 0);
    }

    if (schema_object_exists($db, 'support_conversations')) {
        $row = $db->select_user("SELECT COUNT(*) AS total FROM support_conversations WHERE conversation_type = 'live_chat'");
        $metrics['chat_open'] = (int)($row['total'] ?? 0);
    }

    return $metrics;
}

function admin_dashboard_subscription_status_counts(Mysql_ks $db): array
{
    $counts = [
        'active' => 0,
        'expired' => 0,
    ];

    if (!schema_object_exists($db, 'orders')) {
        return $counts;
    }

    $safeNow = $db->escape(admin_dashboard_sales_now()->format('Y-m-d H:i:s'));
    $productsJoin = '';
    $subscriptionWhere = '';
    if (schema_object_exists($db, 'products')) {
        $productsJoin = 'LEFT JOIN products ON products.id = orders.product_id';
        if (schema_column_exists($db, 'products', 'product_type')) {
            $subscriptionWhere = "AND (products.id IS NULL OR products.product_type = 'subscription')";
        }
    }

    $row = $db->select_user(
        "SELECT
            COALESCE(SUM(
                CASE
                    WHEN orders.status = 'active'
                     AND orders.expires_at IS NOT NULL
                     AND orders.expires_at > '{$safeNow}'
                    THEN 1 ELSE 0
                END
            ), 0) AS active_total,
            COALESCE(SUM(
                CASE
                    WHEN COALESCE(orders.status, '') <> 'cancelled'
                     AND orders.expires_at IS NOT NULL
                     AND orders.expires_at <= '{$safeNow}'
                    THEN 1 ELSE 0
                END
            ), 0) AS expired_total
         FROM orders
         {$productsJoin}
         WHERE orders.payment_status = 'paid'
         {$subscriptionWhere}"
    );

    if (!is_array($row)) {
        return $counts;
    }

    $counts['active'] = max(0, (int)($row['active_total'] ?? 0));
    $counts['expired'] = max(0, (int)($row['expired_total'] ?? 0));

    return $counts;
}

require_once __DIR__ . '/dashboard_sales.php';

function admin_dashboard_month_label(string $yearMonth, string $localeCode = 'pl'): string
{
    $yearMonth = trim($yearMonth);
    if (!preg_match('/^\d{4}\-\d{2}$/', $yearMonth)) {
        return $yearMonth;
    }

    [$year, $month] = explode('-', $yearMonth, 2);
    $monthNumber = (int)$month;
    if ($monthNumber < 1 || $monthNumber > 12) {
        return $yearMonth;
    }

    $localeCode = strtolower(trim($localeCode));
    $monthsPl = [
        1 => 'styczeń',
        2 => 'luty',
        3 => 'marzec',
        4 => 'kwiecień',
        5 => 'maj',
        6 => 'czerwiec',
        7 => 'lipiec',
        8 => 'sierpień',
        9 => 'wrzesień',
        10 => 'październik',
        11 => 'listopad',
        12 => 'grudzień',
    ];
    $monthsEn = [
        1 => 'January',
        2 => 'February',
        3 => 'March',
        4 => 'April',
        5 => 'May',
        6 => 'June',
        7 => 'July',
        8 => 'August',
        9 => 'September',
        10 => 'October',
        11 => 'November',
        12 => 'December',
    ];

    $monthLabel = $localeCode === 'pl'
        ? ($monthsPl[$monthNumber] ?? $yearMonth)
        : ($monthsEn[$monthNumber] ?? $yearMonth);

    return trim($monthLabel . ' ' . $year);
}

function admin_dashboard_product_sales_summary(Mysql_ks $db, int $limit = 120, ?int $yearFilter = null, ?DateTimeImmutable $asOf = null): array
{
    if (!schema_object_exists($db, 'products') || !schema_object_exists($db, 'orders')) {
        return [];
    }
    // $limit is retained for existing callers. A financial total must include every product.
    $asOf = admin_dashboard_sales_now($asOf);
    $safeNow = $db->escape($asOf->format('Y-m-d H:i:s'));
    $source = admin_dashboard_sales_source_sql($db, $asOf);
    $currencyId = (int)(admin_dashboard_sales_currency($db)['id'] ?? 0);
    $yearFilter = $yearFilter !== null && $yearFilter > 0 ? $yearFilter : null;
    $yearWhere = $yearFilter ? " AND YEAR(sales.sale_at) = {$yearFilter}" : '';
    $activeYearWhere = $yearFilter ? " AND EXISTS (
        SELECT 1 FROM ({$source}) active_sale
        WHERE active_sale.order_id = orders.id AND YEAR(active_sale.sale_at) = {$yearFilter}
    )" : '';
    $historicalName = $db->escape(admin_t(admin_load_messages(admin_current_locale()),
        'dashboard_historical_product_unknown', 'Historical / deleted product'));
    $rows = $db->select_full_user("SELECT catalogue.*,
        COALESCE(active_stats.active_sales_total, 0) AS active_sales_total,
        COALESCE(stats.purchases_total, 0) AS purchases_total,
        COALESCE(stats.renewals_total, 0) AS renewals_total,
        COALESCE(stats.purchases_revenue, 0) AS purchases_revenue,
        COALESCE(stats.renewals_revenue, 0) AS renewals_revenue
        FROM (
            SELECT products.id, products.name, products.duration_hours, products.price_amount,
                currencies.code AS currency_code, product_providers.name AS provider_name
            FROM products
            LEFT JOIN currencies ON currencies.id = products.currency_id
            LEFT JOIN product_providers ON product_providers.id = products.provider_id
            UNION ALL SELECT 0, '{$historicalName}', 0, NULL, NULL, NULL
        ) catalogue
        LEFT JOIN (
            SELECT COALESCE(products.id, 0) AS product_id,
                SUM(sale_type = 'purchase') AS purchases_total,
                SUM(sale_type = 'renewal') AS renewals_total,
                SUM(CASE WHEN sale_type = 'purchase' AND sales.currency_id = {$currencyId} THEN amount ELSE 0 END) AS purchases_revenue,
                SUM(CASE WHEN sale_type = 'renewal' AND sales.currency_id = {$currencyId} THEN amount ELSE 0 END) AS renewals_revenue
            FROM ({$source}) sales LEFT JOIN products ON products.id = sales.product_id
            WHERE 1 = 1 {$yearWhere}
            GROUP BY COALESCE(products.id, 0)
        ) stats ON stats.product_id = catalogue.id
        LEFT JOIN (
            SELECT COALESCE(active_product.id, 0) AS product_id, COUNT(*) AS active_sales_total
            FROM orders LEFT JOIN products active_product ON active_product.id = orders.product_id
            WHERE orders.payment_status = 'paid' AND orders.status = 'active'
                AND (orders.expires_at IS NULL OR orders.expires_at > '{$safeNow}')
                AND COALESCE(orders.initial_sale_paid_at, orders.paid_at, orders.created_at) <= '{$safeNow}'
                {$activeYearWhere}
            GROUP BY COALESCE(active_product.id, 0)
        ) active_stats ON active_stats.product_id = catalogue.id
        WHERE COALESCE(stats.purchases_total, 0) + COALESCE(stats.renewals_total, 0)
            + COALESCE(active_stats.active_sales_total, 0) > 0
        ORDER BY active_sales_total DESC, purchases_total DESC, renewals_total DESC, catalogue.id ASC");
    if ($db->error) {
        throw new RuntimeException('Sales summary query failed: ' . $db->error);
    }
    $revenueMap = admin_dashboard_product_revenue_map($db, $yearFilter, $asOf);
    foreach ($rows as &$row) {
        $row['revenue_by_currency'] = $revenueMap[(int)$row['id']] ?? [];
        $row['duration_label'] = admin_duration_label_from_hours((int)($row['duration_hours'] ?? 0));
        $row['transactions_total'] = (int)$row['purchases_total'] + (int)$row['renewals_total'];
        $row['revenue_total'] = (float)$row['purchases_revenue'] + (float)$row['renewals_revenue'];
    }
    unset($row);
    return $rows;
}

function admin_dashboard_provider_breakdowns(Mysql_ks $db, int $providerLimit = 6, int $productLimit = 5): array
{
    if (!schema_object_exists($db, 'orders') || !schema_object_exists($db, 'products') || !schema_object_exists($db, 'product_providers')) {
        return [];
    }

    $providerLimit = max(1, min(12, $providerLimit));
    $productLimit = max(2, min(8, $productLimit));

    $salesSql = admin_dashboard_sales_source_sql($db);
    $rows = $db->select_full_user(
        "SELECT
            product_providers.id AS provider_id,
            product_providers.name AS provider_name,
            products.id AS product_id,
            products.name AS product_name,
            COUNT(*) AS sold_count,
            COALESCE(SUM(orders.amount), 0) AS revenue_total
         FROM ({$salesSql}) AS orders
         INNER JOIN products ON products.id = orders.product_id
         INNER JOIN product_providers ON product_providers.id = products.provider_id
         WHERE 1 = 1
         GROUP BY product_providers.id, product_providers.name, products.id, products.name
         ORDER BY product_providers.name ASC, sold_count DESC, products.name ASC"
    );

    if (!$rows) {
        return [];
    }

    $palette = ['#111827', '#2563eb', '#14b8a6', '#f59e0b', '#ef4444', '#8b5cf6', '#64748b', '#22c55e'];
    $providers = [];

    foreach ($rows as $row) {
        $providerId = (int)($row['provider_id'] ?? 0);
        if ($providerId <= 0) {
            continue;
        }

        if (!isset($providers[$providerId])) {
            $providers[$providerId] = [
                'provider_id' => $providerId,
                'provider_name' => (string)($row['provider_name'] ?? 'Provider'),
                'total_sold' => 0,
                'total_revenue' => 0.0,
                'revenue_by_currency' => [],
                'products' => [],
            ];
        }

        $soldCount = (int)($row['sold_count'] ?? 0);
        $providers[$providerId]['total_sold'] += $soldCount;
        $providers[$providerId]['total_revenue'] += (float)($row['revenue_total'] ?? 0);
        $providers[$providerId]['products'][] = [
            'product_id' => (int)($row['product_id'] ?? 0),
            'product_name' => (string)($row['product_name'] ?? 'Product'),
            'sold_count' => $soldCount,
        ];
    }

    usort($providers, static function (array $left, array $right): int {
        return ($right['total_sold'] <=> $left['total_sold']);
    });

    $providers = array_slice($providers, 0, $providerLimit);

    foreach ($providers as $providerIndex => $provider) {
        $products = $provider['products'];
        usort($products, static function (array $left, array $right): int {
            return ($right['sold_count'] <=> $left['sold_count']);
        });

        $visibleProducts = array_slice($products, 0, $productLimit);
        $otherCount = 0;
        if (count($products) > $productLimit) {
            foreach (array_slice($products, $productLimit) as $extraProduct) {
                $otherCount += (int)($extraProduct['sold_count'] ?? 0);
            }
            if ($otherCount > 0) {
                $visibleProducts[] = [
                    'product_id' => 0,
                    'product_name' => 'Other',
                    'sold_count' => $otherCount,
                ];
            }
        }

        $startAngle = -90.0;
        $preparedProducts = [];
        foreach ($visibleProducts as $productIndex => $product) {
            $count = (int)($product['sold_count'] ?? 0);
            $percent = $provider['total_sold'] > 0 ? ($count / $provider['total_sold']) * 100 : 0;
            $sliceAngle = max(0.0, min(360.0, 360.0 * ($percent / 100)));
            $preparedProducts[] = [
                'product_id' => (int)($product['product_id'] ?? 0),
                'product_name' => (string)($product['product_name'] ?? 'Product'),
                'sold_count' => $count,
                'percent' => $percent,
                'color' => $palette[$productIndex % count($palette)],
                'start_angle' => $startAngle,
                'end_angle' => $startAngle + $sliceAngle,
            ];
            $startAngle += $sliceAngle;
        }

        $providers[$providerIndex]['products'] = $preparedProducts;
        $providers[$providerIndex]['revenue_by_currency'] = admin_dashboard_provider_revenue($db, (int)$provider['provider_id']);
    }

    return $providers;
}

function admin_dashboard_chart_path(array $series, int $width = 640, int $height = 240, int $paddingX = 28, int $paddingY = 18): string
{
    $points = admin_dashboard_chart_points($series, $width, $height, $paddingX, $paddingY);
    if (!$points) {
        return '';
    }

    if (count($points) === 1) {
        return 'M ' . number_format((float)$points[0]['x'], 2, '.', '') . ' ' . number_format((float)$points[0]['y'], 2, '.', '');
    }

    $firstPoint = $points[0];
    $commands = [
        'M ' . number_format((float)$firstPoint['x'], 2, '.', '') . ' ' . number_format((float)$firstPoint['y'], 2, '.', ''),
    ];

    foreach (array_slice($points, 1) as $point) {
        $commands[] = 'L '
            . number_format((float)$point['x'], 2, '.', '') . ' '
            . number_format((float)$point['y'], 2, '.', '');
    }

    return implode(' ', $commands);
}

function admin_dashboard_chart_scale_max(array $series): int
{
    $maximum = max(1, (int)max(array_merge([0], array_column($series, 'paid_orders'))));
    return $maximum <= 3 ? $maximum : (int)(ceil($maximum / 3) * 3);
}

function admin_dashboard_chart_points(array $series, int $width = 640, int $height = 240, int $paddingX = 28, int $paddingY = 18): array
{
    if (!$series) {
        return [];
    }

    $maxValue = admin_dashboard_chart_scale_max($series);

    $count = count($series);
    $plotWidth = max(1, $width - ($paddingX * 2));
    $plotHeight = max(1, $height - ($paddingY * 2));
    $stepX = $count > 1 ? ($plotWidth / max(1, $count - 1)) : 0;
    $points = [];

    foreach ($series as $index => $point) {
        $value = (int)($point['paid_orders'] ?? 0);
        $points[] = [
            'x' => $count > 1 ? ($paddingX + ($index * $stepX)) : ($width / 2),
            'y' => $height - $paddingY - (($value / $maxValue) * $plotHeight),
            'value' => $value,
            'label' => (string)($point['short_label'] ?? ''),
        ];
    }

    return $points;
}

function admin_dashboard_chart_area_path(array $series, int $width = 640, int $height = 240, int $paddingX = 28, int $paddingY = 18): string
{
    $points = admin_dashboard_chart_points($series, $width, $height, $paddingX, $paddingY);
    if (!$points) {
        return '';
    }

    $linePath = admin_dashboard_chart_path($series, $width, $height, $paddingX, $paddingY);
    if ($linePath === '') {
        return '';
    }

    $baselineY = $height - $paddingY;
    $lastPoint = $points[count($points) - 1];
    $firstPoint = $points[0];

    return $linePath
        . ' L ' . number_format((float)$lastPoint['x'], 2, '.', '') . ' ' . number_format((float)$baselineY, 2, '.', '')
        . ' L ' . number_format((float)$firstPoint['x'], 2, '.', '') . ' ' . number_format((float)$baselineY, 2, '.', '')
        . ' Z';
}

function admin_dashboard_donut_segments(array $products, float $radius = 42.0, float $circumference = 263.8937829): array
{
    $segments = [];
    $offset = 0.0;

    foreach ($products as $product) {
        $percent = (float)($product['percent'] ?? 0);
        $dash = $circumference * ($percent / 100);
        $segments[] = [
            'color' => (string)($product['color'] ?? '#111827'),
            'dash' => $dash,
            'gap' => max(0.0, $circumference - $dash),
            'offset' => $offset,
            'label' => (string)($product['product_name'] ?? 'Product'),
            'count' => (int)($product['sold_count'] ?? 0),
            'percent' => $percent,
            'radius' => $radius,
        ];
        $offset -= $dash;
    }

    return $segments;
}

function admin_recent_orders(Mysql_ks $db, int $limit = 8): array
{
    if (!schema_object_exists($db, 'orders')) {
        return [];
    }

    $limit = max(1, min(20, $limit));
    return $db->select_full_user(
        "SELECT
            orders.id,
            orders.customer_id,
            orders.status,
            orders.payment_status,
            orders.fulfillment_status,
            orders.payment_method,
            orders.order_reference,
            orders.total_amount,
            orders.created_at,
            currencies.code AS currency_code,
            currencies.symbol AS currency_symbol,
            customers.email AS customer_email,
            products.name AS product_name,
            product_providers.name AS provider_name
         FROM orders
         LEFT JOIN customers ON customers.id = orders.customer_id
         LEFT JOIN products ON products.id = orders.product_id
         LEFT JOIN product_providers ON product_providers.id = products.provider_id
         LEFT JOIN currencies ON currencies.id = orders.currency_id
         ORDER BY orders.id DESC
         LIMIT {$limit}"
    );
}

function admin_order_count(Mysql_ks $db, int $customerId = 0): int
{
    if (!schema_object_exists($db, 'orders')) {
        return 0;
    }

    $where = $customerId > 0 ? ' WHERE customer_id = ' . $customerId : '';
    $row = $db->select_user("SELECT COUNT(*) AS total FROM orders{$where}");
    return (int)($row['total'] ?? 0);
}

function admin_order_count_filtered(Mysql_ks $db, int $customerId = 0, int $orderId = 0, string $statusFilter = ''): int
{
    if (!schema_object_exists($db, 'orders')) {
        return 0;
    }

    $statusFilter = strtolower(trim($statusFilter));
    $whereParts = [];
    if ($customerId > 0) {
        $whereParts[] = 'orders.customer_id = ' . $customerId;
    }
    if ($orderId > 0) {
        $whereParts[] = 'orders.id = ' . $orderId;
    }

    $productsJoin = '';
    if ($statusFilter === 'expired') {
        $whereParts[] = "COALESCE(orders.status, '') <> 'cancelled'";
        $whereParts[] = "orders.payment_status = 'paid'";
        $whereParts[] = 'orders.expires_at IS NOT NULL';
        $whereParts[] = 'orders.expires_at <= NOW()';
        if (schema_object_exists($db, 'products')) {
            $productsJoin = 'LEFT JOIN products ON products.id = orders.product_id';
            if (schema_column_exists($db, 'products', 'product_type')) {
                $whereParts[] = "(products.id IS NULL OR products.product_type = 'subscription')";
            }
        }
    }

    $where = $whereParts ? (' WHERE ' . implode(' AND ', $whereParts)) : '';
    $row = $db->select_user(
        "SELECT COUNT(*) AS total
         FROM orders
         {$productsJoin}
         {$where}"
    );
    return (int)($row['total'] ?? 0);
}

function admin_order_rows(Mysql_ks $db, int $limit = 20, int $offset = 0, int $customerId = 0): array
{
    if (!schema_object_exists($db, 'orders')) {
        return [];
    }

    $limit = max(1, min(100, $limit));
    $offset = max(0, $offset);
    $deliveryLinkVisibleSelect = schema_column_exists($db, 'orders', 'delivery_link_visible')
        ? 'orders.delivery_link_visible'
        : '0 AS delivery_link_visible';
    $providerDeliveryLinksEnabledSelect = schema_column_exists($db, 'product_providers', 'supports_delivery_links')
        ? 'product_providers.supports_delivery_links'
        : '1 AS supports_delivery_links';
    $providerUrlReplacementFromSelect = schema_column_exists($db, 'product_providers', 'url_replacement_from')
        ? 'product_providers.url_replacement_from'
        : 'NULL';
    $providerUrlReplacementToSelect = schema_column_exists($db, 'product_providers', 'url_replacement_to')
        ? 'product_providers.url_replacement_to'
        : 'NULL';
    $customerHandleSelect = schema_column_exists($db, 'customers', 'public_handle')
        ? 'customers.public_handle'
        : "'' AS public_handle";
    $progressStartedAtSelect = admin_order_progress_started_at_sql($db);
    $progressDurationHoursSelect = admin_order_progress_duration_hours_sql($db);
    $where = $customerId > 0 ? 'WHERE orders.customer_id = ' . $customerId : '';

    return $db->select_full_user(
        "SELECT
            orders.id,
            orders.customer_id,
            orders.product_id,
            orders.payment_method,
            orders.status,
            orders.payment_status,
            orders.fulfillment_status,
            orders.total_amount,
            orders.order_reference,
            orders.support_note,
            orders.transaction_reference,
            orders.customer_note,
            orders.delivery_link,
            {$deliveryLinkVisibleSelect},
            orders.started_at,
            orders.created_at,
            orders.expires_at,
            {$progressStartedAtSelect} AS progress_started_at,
            {$progressDurationHoursSelect} AS progress_duration_hours,
            orders.paid_at,
            customers.email AS customer_email,
            {$customerHandleSelect},
            products.provider_id,
            products.name AS product_name,
            products.product_type,
            products.is_trial,
            products.duration_hours,
            product_providers.name AS provider_name,
            product_providers.dashboard_url,
            product_providers.supports_manual_delivery,
            {$providerDeliveryLinksEnabledSelect},
            product_providers.supports_url_replacement,
            {$providerUrlReplacementFromSelect} AS url_replacement_from,
            {$providerUrlReplacementToSelect} AS url_replacement_to,
            currencies.code AS currency_code,
            (
                SELECT crypto_deposit_requests.id
                FROM crypto_deposit_requests
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ) AS crypto_payment_id,
            (
                SELECT crypto_deposit_requests.status
                FROM crypto_deposit_requests
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ) AS crypto_payment_status,
            (
                SELECT bank_transfer_requests.id
                FROM bank_transfer_requests
                WHERE bank_transfer_requests.order_id = orders.id
                ORDER BY bank_transfer_requests.id DESC
                LIMIT 1
            ) AS bank_payment_id,
            (
                SELECT bank_transfer_requests.status
                FROM bank_transfer_requests
                WHERE bank_transfer_requests.order_id = orders.id
                ORDER BY bank_transfer_requests.id DESC
                LIMIT 1
            ) AS bank_payment_status,
            (
                SELECT crypto_wallet_addresses.address
                FROM crypto_deposit_requests
                INNER JOIN crypto_wallet_addresses ON crypto_wallet_addresses.id = crypto_deposit_requests.wallet_address_id
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ) AS wallet_address,
            (
                SELECT crypto_wallet_addresses.id
                FROM crypto_deposit_requests
                INNER JOIN crypto_wallet_addresses ON crypto_wallet_addresses.id = crypto_deposit_requests.wallet_address_id
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ) AS wallet_address_id,
            (
                SELECT crypto_wallet_addresses.label
                FROM crypto_deposit_requests
                INNER JOIN crypto_wallet_addresses ON crypto_wallet_addresses.id = crypto_deposit_requests.wallet_address_id
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ) AS wallet_label
         FROM orders
         LEFT JOIN customers ON customers.id = orders.customer_id
         LEFT JOIN products ON products.id = orders.product_id
         LEFT JOIN product_providers ON product_providers.id = products.provider_id
         LEFT JOIN currencies ON currencies.id = orders.currency_id
         {$where}
         ORDER BY orders.id DESC
         LIMIT {$offset}, {$limit}"
    );
}

