function admin_order_balance_activation_context(Mysql_ks $db, array $order): array
{
    $customerId = (int)($order['customer_id'] ?? 0);
    $providerId = (int)($order['provider_id'] ?? 0);
    $productId = (int)($order['product_id'] ?? 0);
    $status = strtolower(trim((string)($order['status'] ?? '')));
    $paymentStatus = strtolower(trim((string)($order['payment_status'] ?? '')));
    $fulfillmentStatus = strtolower(trim((string)($order['fulfillment_status'] ?? '')));
    $requiredAmount = round((float)($order['total_amount'] ?? 0), 2);
    $isAwaitingActivation = $status === 'pending_payment'
        && $paymentStatus === 'paid'
        && !in_array($fulfillmentStatus, ['delivered', 'fulfilled', 'completed'], true);
    $isOpenBalanceActivationCandidate = $customerId > 0
        && $requiredAmount > 0
        && in_array($status, ['pending', 'pending_payment', 'awaiting_review'], true)
        && !in_array($paymentStatus, ['paid', 'refunded', 'archived'], true)
        && !in_array($fulfillmentStatus, ['delivered', 'fulfilled', 'completed', 'cancelled'], true);

    if ($isAwaitingActivation) {
        admin_ensure_order_payment_balance_credit($db, $order);
    }

    $currentBalance = 0.0;
    if ($customerId > 0 && schema_object_exists($db, 'customers') && schema_column_exists($db, 'customers', 'balance_amount')) {
        $customerRow = $db->select_user(
            "SELECT balance_amount
             FROM customers
             WHERE id = {$customerId}
             LIMIT 1"
        );
        if (is_array($customerRow)) {
            $currentBalance = round((float)($customerRow['balance_amount'] ?? 0), 2);
        }
    }

    $existingDebitAmount = 0.0;
    if (schema_object_exists($db, 'customer_balance_runtime_events') && !empty($order['id'])) {
        $debitEvent = $db->select_user(
            "SELECT amount
             FROM customer_balance_runtime_events
             WHERE customer_id = {$customerId}
               AND source_type = 'order_activation'
               AND source_key = '" . $db->escape((string)((int)($order['id'] ?? 0))) . "'
               AND direction = 'debit'
             ORDER BY id DESC
             LIMIT 1"
        );
        if (is_array($debitEvent)) {
            $existingDebitAmount = round((float)($debitEvent['amount'] ?? 0), 2);
        }
    }

    $activationBudget = $existingDebitAmount > 0 ? $existingDebitAmount : $currentBalance;
    $canActivate = $activationBudget + 0.00001 >= $requiredAmount;
    $shortfall = max(0, round($requiredAmount - $activationBudget, 2));
    $hasPartialBalanceForActivation = $isOpenBalanceActivationCandidate
        && $currentBalance > 0
        && !$canActivate;

    $suggestedProduct = null;
    if (
        ($isAwaitingActivation || $hasPartialBalanceForActivation)
        && !$canActivate
        && $providerId > 0
        && $productId > 0
        && strtolower(trim((string)($order['product_type'] ?? 'subscription'))) === 'subscription'
    ) {
        $safeProductType = $db->escape((string)($order['product_type'] ?? 'subscription'));
        $trialFilter = schema_column_exists($db, 'products', 'is_trial')
            ? ' AND products.is_trial = 0'
            : '';
        $candidate = $db->select_user(
            "SELECT
                products.id,
                products.name,
                products.duration_hours,
                products.price_amount,
                products.currency_id,
                currencies.code AS currency_code
             FROM products
             LEFT JOIN currencies ON currencies.id = products.currency_id
             WHERE products.provider_id = {$providerId}
               AND products.is_active = 1
               AND products.product_type = '{$safeProductType}'
               AND products.id <> {$productId}
               {$trialFilter}
               AND products.price_amount > 0
               AND products.price_amount <= " . number_format($activationBudget, 2, '.', '') . "
             ORDER BY products.duration_hours DESC, products.price_amount DESC, products.id ASC
             LIMIT 1"
        );

        if (is_array($candidate) && !empty($candidate['id'])) {
            $candidateDuration = admin_duration_label_from_hours((int)($candidate['duration_hours'] ?? 0));
            $candidateTitle = trim((string)($candidate['name'] ?? ''));
            if ($candidateDuration !== '' && stripos($candidateTitle, $candidateDuration) === false) {
                $candidateTitle = trim($candidateTitle . ' ' . $candidateDuration);
            }
            $candidatePrice = round((float)($candidate['price_amount'] ?? 0), 2);
            $candidateCurrencyCode = trim((string)($candidate['currency_code'] ?? (string)($order['currency_code'] ?? '')));
            $suggestedProduct = [
                'id' => (int)$candidate['id'],
                'name' => $candidateTitle,
                'price_amount' => $candidatePrice,
                'currency_code' => $candidateCurrencyCode,
                'duration_label' => $candidateDuration,
                'price_label' => admin_format_money_value($candidatePrice, $candidateCurrencyCode),
            ];
        }
    }

    return [
        'is_awaiting_activation' => $isAwaitingActivation,
        'current_balance' => $currentBalance,
        'covered_amount' => $activationBudget,
        'balance_debit_already_applied' => $existingDebitAmount > 0,
        'required_amount' => $requiredAmount,
        'shortfall_amount' => $shortfall,
        'can_activate' => $canActivate,
        'needs_attention' => ($isAwaitingActivation || $hasPartialBalanceForActivation) && !$canActivate,
        'has_partial_balance_for_activation' => $hasPartialBalanceForActivation,
        'suggested_product' => $suggestedProduct,
    ];
}

function admin_order_balance_payment_context(Mysql_ks $db, array $order): array
{
    $orderId = (int)($order['id'] ?? 0);
    $customerId = (int)($order['customer_id'] ?? 0);
    $status = strtolower(trim((string)($order['status'] ?? '')));
    $paymentStatus = strtolower(trim((string)($order['payment_status'] ?? '')));
    $fulfillmentStatus = strtolower(trim((string)($order['fulfillment_status'] ?? '')));
    $requiredAmount = round((float)($order['total_amount'] ?? 0), 2);

    $isEligibleOrder = $orderId > 0
        && $customerId > 0
        && $requiredAmount > 0
        && $paymentStatus === 'unpaid'
        && in_array($status, ['pending', 'pending_payment', 'awaiting_review'], true)
        && !in_array($fulfillmentStatus, ['delivered', 'fulfilled', 'completed', 'cancelled'], true);

    $currentBalance = 0.0;
    if ($customerId > 0 && schema_object_exists($db, 'customers') && schema_column_exists($db, 'customers', 'balance_amount')) {
        $customerRow = $db->select_user(
            "SELECT balance_amount
             FROM customers
             WHERE id = {$customerId}
             LIMIT 1"
        );
        if (is_array($customerRow)) {
            $currentBalance = round((float)($customerRow['balance_amount'] ?? 0), 2);
        }
    }

    $canMarkPaidFromBalance = $isEligibleOrder && $currentBalance + 0.00001 >= $requiredAmount;
    $shortfallAmount = max(0, round($requiredAmount - $currentBalance, 2));
    $latestCreditEvent = null;
    $hasRecentTopupCredit = false;

    if ($customerId > 0 && schema_object_exists($db, 'customer_balance_runtime_events')) {
        $latestCreditEvent = $db->select_user(
            "SELECT source_type, source_key, amount, note, created_at
             FROM customer_balance_runtime_events
             WHERE customer_id = {$customerId}
               AND direction = 'credit'
             ORDER BY id DESC
             LIMIT 1"
        );

        if ($canMarkPaidFromBalance && is_array($latestCreditEvent)) {
            $creditSourceType = strtolower(trim((string)($latestCreditEvent['source_type'] ?? '')));
            $creditSourceKey = trim((string)($latestCreditEvent['source_key'] ?? ''));
            $creditCreatedAt = trim((string)($latestCreditEvent['created_at'] ?? ''));
            $orderCreatedAt = trim((string)($order['created_at'] ?? ''));
            $creditTimestamp = $creditCreatedAt !== '' ? (int)strtotime($creditCreatedAt) : 0;
            $orderTimestamp = $orderCreatedAt !== '' ? (int)strtotime($orderCreatedAt) : 0;
            $isSameDayAsNow = $creditTimestamp > 0 && date('Y-m-d', $creditTimestamp) === date('Y-m-d');
            $orderCreditEvent = admin_find_order_payment_balance_credit_event($db, $orderId);
            $orderCreditSourceKey = is_array($orderCreditEvent) ? trim((string)($orderCreditEvent['source_key'] ?? '')) : '';

            if (
                $creditSourceType === 'payment_approval'
                && $creditSourceKey !== ''
                && $creditSourceKey !== $orderCreditSourceKey
                && $isSameDayAsNow
                && ($orderTimestamp <= 0 || $creditTimestamp >= $orderTimestamp)
            ) {
                $hasRecentTopupCredit = true;
            }
        }
    }

    return [
        'is_eligible_order' => $isEligibleOrder,
        'current_balance' => $currentBalance,
        'required_amount' => $requiredAmount,
        'shortfall_amount' => $shortfallAmount,
        'can_mark_paid_from_balance' => $canMarkPaidFromBalance,
        'has_recent_topup_credit' => $hasRecentTopupCredit,
        'latest_credit_event' => is_array($latestCreditEvent) ? $latestCreditEvent : null,
    ];
}

function admin_order_pending_renewal_context(Mysql_ks $db, array $order): array
{
    static $cache = [];

    $orderId = (int)($order['id'] ?? 0);
    $cacheKey = $orderId > 0 ? (string)$orderId : '0';
    if (isset($cache[$cacheKey])) {
        return $cache[$cacheKey];
    }

    $context = [
        'has_pending' => false,
        'has_paid_pending_activation' => false,
        'balance_reserved' => false,
        'renewal_id' => 0,
        'product_id' => 0,
        'status' => '',
        'payment_type' => '',
        'payment_id' => 0,
        'payment_status' => '',
        'payment_amount' => 0.0,
        'payment_amount_label' => '',
        'payment_approved_at' => '',
        'payment_url' => '',
        'customer_balance' => 0.0,
        'customer_balance_label' => '',
    ];

    if ($orderId <= 0 || in_array(strtolower(trim((string)($order['status'] ?? ''))), ['cancelled','refunded','failed','inactive','archived'], true) || !schema_object_exists($db, 'order_renewals')) {
        $cache[$cacheKey] = $context;
        return $context;
    }

    $pendingRenewal = app_order_find_pending_renewal($db, $orderId);
    if (!is_array($pendingRenewal) || empty($pendingRenewal['id'])) {
        $cache[$cacheKey] = $context;
        return $context;
    }

    $renewalStatus = strtolower(trim((string)($pendingRenewal['status'] ?? '')));
    $context['has_pending'] = true;
    $context['status'] = $renewalStatus;
    $context['renewal_id'] = (int)($pendingRenewal['id'] ?? 0);
    $context['product_id'] = (int)($pendingRenewal['product_id'] ?? 0);
    $context['has_paid_pending_activation'] = $renewalStatus === 'paid_pending_activation';

    if ($context['has_paid_pending_activation']) {
        $context['balance_reserved'] = admin_order_renewal_balance_reserved($db, $pendingRenewal);
        $paymentType = strtolower(trim((string)($pendingRenewal['payment_request_type'] ?? '')));
        $paymentId = (int)($pendingRenewal['payment_request_id'] ?? 0);
        if (in_array($paymentType, ['crypto', 'bank'], true) && $paymentId > 0) {
            $payment = admin_payment_find($db, $paymentType, $paymentId);
            if (is_array($payment) && !empty($payment['id'])) {
                $paymentAmount = 0.0;
                if (isset($payment['received_fiat_amount']) && is_numeric((string)$payment['received_fiat_amount'])) {
                    $paymentAmount = $paymentType === 'crypto'
                        ? admin_round_customer_crypto_fiat_credit($payment['received_fiat_amount'])
                        : round((float)$payment['received_fiat_amount'], 2);
                }
                if ($paymentAmount <= 0) {
                    if (isset($payment['requested_amount_value']) && is_numeric((string)$payment['requested_amount_value'])) {
                        $paymentAmount = round((float)$payment['requested_amount_value'], 2);
                    } elseif (isset($payment['amount_value']) && is_numeric((string)$payment['amount_value'])) {
                        $paymentAmount = round((float)$payment['amount_value'], 2);
                    }
                }

                $paymentCurrencyCode = trim((string)($payment['currency_code'] ?? (string)($order['currency_code'] ?? '')));
                $context['payment_type'] = $paymentType;
                $context['payment_id'] = (int)($payment['id'] ?? $paymentId);
                $context['payment_status'] = strtolower(trim((string)($payment['status'] ?? '')));
                $context['payment_amount'] = $paymentAmount;
                $context['payment_amount_label'] = $paymentAmount > 0
                    ? admin_format_money_value($paymentAmount, $paymentCurrencyCode)
                    : '';
                $context['payment_approved_at'] = trim((string)(
                    $payment['approved_at']
                        ?? $payment['confirmed_at']
                        ?? $payment['requested_at']
                        ?? ''
                ));
                $context['payment_url'] = '/admin/?page=payments&payment_type=' . rawurlencode($paymentType) . '&payment_id=' . (int)$context['payment_id'];
            }
        }

        $customerId = (int)($order['customer_id'] ?? $pendingRenewal['customer_id'] ?? 0);
        if ($customerId > 0 && schema_object_exists($db, 'customers') && schema_column_exists($db, 'customers', 'balance_amount')) {
            $customerRow = $db->select_user(
                "SELECT balance_amount
                 FROM customers
                 WHERE id = {$customerId}
                 LIMIT 1"
            );
            if (is_array($customerRow)) {
                $customerBalance = round((float)($customerRow['balance_amount'] ?? 0), 2);
                $context['customer_balance'] = $customerBalance;
                $context['customer_balance_label'] = admin_format_money_value(
                    $customerBalance,
                    (string)($order['currency_code'] ?? '')
                );
            }
        }
    }

    $cache[$cacheKey] = $context;
    return $context;
}

function admin_find_latest_approved_order_payment(Mysql_ks $db, int $orderId): ?array
{
    if ($orderId <= 0) {
        return null;
    }

    $rows = [];

    if (schema_object_exists($db, 'crypto_deposit_requests')) {
        $cryptoRow = $db->select_user(
            "SELECT
                'crypto' AS payment_type,
                crypto_deposit_requests.id,
                crypto_deposit_requests.customer_id,
                crypto_deposit_requests.requested_fiat_amount AS amount_value
             FROM crypto_deposit_requests
             WHERE crypto_deposit_requests.order_id = {$orderId}
               AND crypto_deposit_requests.status IN ('confirmed', 'approved', 'paid', 'completed')
             ORDER BY crypto_deposit_requests.id DESC
             LIMIT 1"
        );
        if (is_array($cryptoRow) && !empty($cryptoRow['id'])) {
            $rows[] = $cryptoRow;
        }
    }

    if (schema_object_exists($db, 'bank_transfer_requests')) {
        $bankRow = $db->select_user(
            "SELECT
                'bank' AS payment_type,
                bank_transfer_requests.id,
                bank_transfer_requests.customer_id,
                bank_transfer_requests.requested_amount AS amount_value
             FROM bank_transfer_requests
             WHERE bank_transfer_requests.order_id = {$orderId}
               AND bank_transfer_requests.status IN ('confirmed', 'approved', 'paid', 'completed')
             ORDER BY bank_transfer_requests.id DESC
             LIMIT 1"
        );
        if (is_array($bankRow) && !empty($bankRow['id'])) {
            $rows[] = $bankRow;
        }
    }

    if (!$rows) {
        return null;
    }

    usort($rows, static function (array $left, array $right): int {
        return ((int)($right['id'] ?? 0)) <=> ((int)($left['id'] ?? 0));
    });

    return $rows[0] ?? null;
}

function admin_ensure_order_payment_balance_credit(Mysql_ks $db, array $order): array
{
    $orderId = (int)($order['id'] ?? 0);
    $customerId = (int)($order['customer_id'] ?? 0);
    $status = strtolower(trim((string)($order['status'] ?? '')));
    $paymentStatus = strtolower(trim((string)($order['payment_status'] ?? '')));
    $fulfillmentStatus = strtolower(trim((string)($order['fulfillment_status'] ?? '')));

    if (
        $orderId <= 0
        || $customerId <= 0
        || $status !== 'pending_payment'
        || $paymentStatus !== 'paid'
        || in_array($fulfillmentStatus, ['delivered', 'fulfilled', 'completed'], true)
    ) {
        return ['ok' => true, 'applied' => false, 'already_applied' => false];
    }

    $existingEvent = admin_find_order_payment_balance_credit_event($db, $orderId);
    if (is_array($existingEvent) && !empty($existingEvent['source_key'])) {
        return ['ok' => true, 'applied' => false, 'already_applied' => true];
    }

    $payment = admin_find_latest_approved_order_payment($db, $orderId);
    if (!is_array($payment) || empty($payment['id'])) {
        return ['ok' => true, 'applied' => false, 'already_applied' => false];
    }

    $paymentId = (int)($payment['id'] ?? 0);
    $paymentType = strtolower(trim((string)($payment['payment_type'] ?? '')));
    $amountValue = round((float)($payment['amount_value'] ?? 0), 2);
    if ($paymentId <= 0 || $amountValue <= 0 || !in_array($paymentType, ['crypto', 'bank'], true)) {
        return ['ok' => true, 'applied' => false, 'already_applied' => false];
    }

    $creditResult = admin_apply_customer_balance_runtime_event(
        $db,
        $customerId,
        $amountValue,
        'credit',
        'payment_approval',
        $paymentType . ':' . $paymentId,
        'Repair credit for approved ' . ucfirst($paymentType) . ' payment #' . $paymentId
    );

    return [
        'ok' => !empty($creditResult['ok']),
        'applied' => !empty($creditResult['ok']) && empty($creditResult['already_applied']),
        'already_applied' => !empty($creditResult['already_applied']),
        'message' => (string)($creditResult['message'] ?? ''),
    ];
}

function admin_cancel_open_order_payment_requests(Mysql_ks $db, int $customerId, int $orderId): void
{
    if ($customerId <= 0 || $orderId <= 0) {
        return;
    }

    $safeNow = date('Y-m-d H:i:s');

    if (schema_object_exists($db, 'crypto_deposit_requests')) {
        app_cancel_crypto_deposit_requests(
            $db,
            "customer_id = {$customerId}
             AND order_id = {$orderId}
             AND status IN ('pending', 'pending_payment', 'awaiting_confirmation', 'awaiting_review')",
            'Released after admin cancelled open order crypto payment request',
            $safeNow
        );
    }

    if (schema_object_exists($db, 'bank_transfer_requests')) {
        app_cancel_bank_transfer_requests(
            $db,
            "customer_id = {$customerId}
             AND order_id = {$orderId}
             AND status IN ('pending_payment', 'awaiting_review')",
            $safeNow
        );
    }
}

function admin_mark_order_paid_from_balance(
    Mysql_ks $db,
    int $orderId,
    int $adminUserId = 0,
    string $ipAddress = ''
): array
{
    $order = admin_order_find($db, $orderId);
    if (!$order) {
        return ['ok' => false, 'message' => 'Order not found.'];
    }

    $balancePaymentContext = admin_order_balance_payment_context($db, $order);
    if (empty($balancePaymentContext['can_mark_paid_from_balance'])) {
        return ['ok' => false, 'message' => 'Customer balance is too low to mark this order as paid.'];
    }

    $customerId = (int)($order['customer_id'] ?? 0);
    $amountValue = round((float)($order['total_amount'] ?? 0), 2);
    if ($customerId <= 0 || $amountValue <= 0) {
        return ['ok' => false, 'message' => 'This order cannot be paid from customer balance.'];
    }

    admin_cancel_open_order_payment_requests($db, $customerId, $orderId);

    $balanceDebitResult = admin_apply_customer_balance_runtime_event(
        $db,
        $customerId,
        $amountValue,
        'debit',
        'order_activation',
        (string)$orderId,
        'Marked as paid from customer balance for order #' . $orderId,
        $adminUserId,
        $ipAddress
    );

    if (empty($balanceDebitResult['ok'])) {
        return $balanceDebitResult;
    }

    $paidAt = trim((string)($order['paid_at'] ?? '')) !== '' ? (string)$order['paid_at'] : date('Y-m-d H:i:s');
    $saveResult = admin_save_order_info(
        $db,
        $orderId,
        [
            'order_reference' => (string)($order['order_reference'] ?? ''),
            'payment_method' => 'balance',
            'total_amount' => number_format((float)($order['total_amount'] ?? 0), 2, '.', ''),
            'customer_note' => (string)($order['customer_note'] ?? ''),
            'support_note' => (string)($order['support_note'] ?? ''),
            'delivery_link' => (string)($order['delivery_link'] ?? ''),
            'transaction_reference' => (string)($order['transaction_reference'] ?? ''),
            'started_at' => (string)($order['started_at'] ?? ''),
            'expires_at' => (string)($order['expires_at'] ?? ''),
            'paid_at' => $paidAt,
            'status' => 'pending_payment',
            'payment_status' => 'paid',
            'fulfillment_status' => 'pending',
            'delivery_link_visible' => !empty($order['delivery_link_visible']) ? '1' : '0',
        ],
        $adminUserId,
        $ipAddress
    );

    if (empty($saveResult['ok'])) {
        if (empty($balanceDebitResult['already_applied'])) {
            admin_apply_customer_balance_runtime_event(
                $db,
                $customerId,
                $amountValue,
                'credit',
                'order_balance_payment_admin_rollback',
                (string)$orderId . ':' . time(),
                'Rollback after failed admin balance payment for order #' . $orderId,
                $adminUserId,
                $ipAddress
            );
        }

        return ['ok' => false, 'message' => (string)($saveResult['message'] ?? 'Unable to mark the order as paid from customer balance.')];
    }

    admin_log_customer_and_admin(
        $db,
        $customerId,
        $adminUserId,
        'order_paid_from_balance',
        'Order #' . $orderId . ' marked as paid from customer balance.',
        $ipAddress
    );

    return ['ok' => true, 'message' => 'Order was marked as paid from customer balance.'];
}

function admin_apply_order_balance_suggestion(
    Mysql_ks $db,
    int $orderId,
    int $productId,
    int $adminUserId = 0,
    string $ipAddress = ''
): array
{
    $order = admin_order_find($db, $orderId);
    if (!$order) {
        return ['ok' => false, 'message' => 'Order not found.'];
    }

    $balanceContext = admin_order_balance_activation_context($db, $order);
    $suggestedProduct = (array)($balanceContext['suggested_product'] ?? []);
    if (empty($balanceContext['needs_attention'])) {
        return ['ok' => false, 'message' => 'This order does not need a balance-based package suggestion.'];
    }
    if ($productId <= 0 || $productId !== (int)($suggestedProduct['id'] ?? 0)) {
        return ['ok' => false, 'message' => 'Suggested package is invalid.'];
    }

    $product = admin_product_basic_row($db, $productId);
    if (!$product || empty($product['is_active'])) {
        return ['ok' => false, 'message' => 'Suggested package is not available.'];
    }

    $durationHours = (int)($product['duration_hours'] ?? 0);
    $newExpiry = $durationHours > 0
        ? app_subscription_expiry_from_base_timestamp(time(), $durationHours)
        : (string)($order['expires_at'] ?? null);
    $previousStatus = strtolower(trim((string)($order['status'] ?? '')));
    $nextStatus = strtotime($newExpiry) > time() ? 'active' : 'expired';

    $updated = $db->update_using_id(
        ['product_id', 'total_amount', 'currency_id', 'expires_at', 'status'],
        [
            $productId,
            number_format((float)($product['price_amount'] ?? 0), 2, '.', ''),
            (int)($product['currency_id'] ?? ($order['product_currency_id'] ?? 1)),
            $newExpiry,
            $nextStatus,
        ],
        'orders',
        $orderId
    );

    if (!$updated) {
        return ['ok' => false, 'message' => 'Unable to apply the suggested package.'];
    }

    $productLabel = trim((string)($product['provider_name'] ?? '') . ' ' . (string)($product['name'] ?? ''));
    admin_log_customer_and_admin(
        $db,
        (int)($order['customer_id'] ?? 0),
        $adminUserId,
        'order_updated',
        'Order #' . $orderId . ' switched to suggested package #' . $productId . ($productLabel !== '' ? ' (' . $productLabel . ')' : '') . '.',
        $ipAddress
    );

    return ['ok' => true, 'message' => 'Suggested package was applied to the order.'];
}

function admin_normalize_datetime_input(?string $value): ?string
{
    $value = trim((string)$value);
    if ($value === '') {
        return null;
    }

    $value = preg_replace('/\s+/', ' ', $value) ?? $value;
    $value = str_replace('T', ' ', trim($value));

    $formats = [
        '!Y-m-d H:i:s',
        '!Y-m-d H:i',
        '!Y-m-d, H:i:s',
        '!Y-m-d, H:i',
        '!d.m.Y H:i:s',
        '!d.m.Y H:i',
        '!d.m.Y, H:i:s',
        '!d.m.Y, H:i',
        '!Y-m-d',
        '!d.m.Y',
    ];

    foreach ($formats as $format) {
        $date = DateTimeImmutable::createFromFormat($format, $value);
        if (!$date instanceof DateTimeImmutable) {
            continue;
        }

        $errors = DateTimeImmutable::getLastErrors();
        if (is_array($errors) && ((int)($errors['warning_count'] ?? 0) > 0 || (int)($errors['error_count'] ?? 0) > 0)) {
            continue;
        }

        return $date->format('Y-m-d H:i:s');
    }

    return null;
}

function admin_datetime_input_invalid(?string $value): bool
{
    return trim((string)$value) !== '' && admin_normalize_datetime_input($value) === null;
}

function admin_order_status_options(string $current = ''): array
{
    $options = ['pending_payment', 'active', 'expired', 'cancelled'];
    $current = trim($current);
    if ($current !== '' && !in_array($current, $options, true)) {
        $options[] = $current;
    }

    return $options;
}

function admin_order_payment_status_options(string $current = ''): array
{
    $options = ['unpaid', 'paid', 'refunded', 'archived'];
    $current = trim($current);
    if ($current !== '' && !in_array($current, $options, true)) {
        $options[] = $current;
    }

    return $options;
}

