}

function admin_order_delivery_link_mode(array $order): string
{
    $deliveryLinksEnabled = !array_key_exists('supports_delivery_links', $order)
        || !empty($order['supports_delivery_links']);

    if (!$deliveryLinksEnabled || trim((string)($order['delivery_link'] ?? '')) === '') {
        return '';
    }

    return !empty($order['delivery_link_visible']) ? 'url' : 'credentials';
}

function admin_order_progress_started_at_sql(Mysql_ks $db): string
{
    if (!schema_object_exists($db, 'order_renewals')) {
        return 'NULL';
    }

    $dateExpression = schema_column_exists($db, 'order_renewals', 'applied_at')
        ? 'COALESCE(progress_renewals.applied_at, progress_renewals.requested_at)'
        : 'progress_renewals.requested_at';
    $statusWhere = schema_column_exists($db, 'order_renewals', 'status')
        ? " AND progress_renewals.status = 'applied'"
        : '';

    return "(
        SELECT MAX({$dateExpression})
        FROM order_renewals AS progress_renewals
        WHERE progress_renewals.order_id = orders.id{$statusWhere}
    )";
}

function admin_order_progress_duration_hours_sql(Mysql_ks $db): string
{
    if (
        !schema_object_exists($db, 'order_renewals')
        || !schema_column_exists($db, 'order_renewals', 'duration_hours')
    ) {
        return 'NULL';
    }

    $dateExpression = schema_column_exists($db, 'order_renewals', 'applied_at')
        ? 'COALESCE(progress_renewals.applied_at, progress_renewals.requested_at)'
        : 'progress_renewals.requested_at';
    $statusWhere = schema_column_exists($db, 'order_renewals', 'status')
        ? " AND progress_renewals.status = 'applied'"
        : '';

    return "(
        SELECT progress_renewals.duration_hours
        FROM order_renewals AS progress_renewals
        WHERE progress_renewals.order_id = orders.id{$statusWhere}
        ORDER BY {$dateExpression} DESC, progress_renewals.id DESC
        LIMIT 1
    )";
}

function admin_order_progress_data(array $order): array
{
    if (!admin_product_type_uses_expiry($order['product_type'] ?? 'subscription')) {
        return [
            'has_expiry' => false,
            'remaining_seconds' => 0,
            'remaining_days' => 0,
            'percent' => 0,
            'color' => '#d1d5db',
            'tone' => 'neutral',
        ];
    }

    $progressStartedAt = !empty($order['progress_started_at']) && function_exists('app_timestamp_from_runtime_datetime')
        ? app_timestamp_from_runtime_datetime((string)$order['progress_started_at'])
        : (!empty($order['progress_started_at']) ? strtotime((string)$order['progress_started_at']) : 0);
    $createdAt = !empty($order['created_at']) && function_exists('app_timestamp_from_runtime_datetime')
        ? app_timestamp_from_runtime_datetime((string)$order['created_at'])
        : (!empty($order['created_at']) ? strtotime((string)$order['created_at']) : 0);
    $startedAt = !empty($order['started_at']) && function_exists('app_timestamp_from_runtime_datetime')
        ? app_timestamp_from_runtime_datetime((string)$order['started_at'])
        : (!empty($order['started_at']) ? strtotime((string)$order['started_at']) : 0);
    $expiresAt = !empty($order['expires_at']) && function_exists('app_timestamp_from_runtime_datetime')
        ? app_timestamp_from_runtime_datetime((string)$order['expires_at'])
        : (!empty($order['expires_at']) ? strtotime((string)$order['expires_at']) : 0);
    $now = time();

    if ($expiresAt <= 0) {
        return [
            'has_expiry' => false,
            'remaining_seconds' => 0,
            'remaining_days' => 0,
            'percent' => 0,
            'color' => '#d1d5db',
            'tone' => 'neutral',
        ];
    }

    $anchorTime = $progressStartedAt > 0
        ? $progressStartedAt
        : ($startedAt > 0 ? $startedAt : ($createdAt > 0 ? $createdAt : $now));
    $totalSeconds = max(1, $expiresAt - $anchorTime);
    $durationHours = (int)($order['progress_duration_hours'] ?? $order['duration_hours'] ?? $order['duration'] ?? 0);
    if ($progressStartedAt > 0 && $durationHours > 0) {
        $renewalPeriodEnd = function_exists('app_subscription_expiry_from_base_timestamp')
            ? app_subscription_expiry_from_base_timestamp($progressStartedAt, $durationHours)
            : date('Y-m-d H:i:s', $progressStartedAt + ($durationHours * 3600));
        $renewalPeriodEndAt = $renewalPeriodEnd !== null && $renewalPeriodEnd !== ''
            ? strtotime($renewalPeriodEnd)
            : 0;
        if ($renewalPeriodEndAt > $progressStartedAt) {
            $totalSeconds = $renewalPeriodEndAt - $progressStartedAt;
        }
    }
    $remainingSeconds = max(0, $expiresAt - $now);
    $percent = (int)round(min(1, $remainingSeconds / $totalSeconds) * 100);
    $remainingDays = $remainingSeconds > 0 ? (int)ceil($remainingSeconds / 86400) : 0;

    if ($remainingSeconds <= 0) {
        $tone = 'expired';
        $color = '#ef4444';
        $percent = 0;
    } elseif ($percent <= 25) {
        $tone = 'danger';
        $color = '#ef4444';
    } elseif ($percent <= 60) {
        $tone = 'warning';
        $color = '#f59e0b';
    } else {
        $tone = 'success';
        $color = '#16a34a';
    }

    return [
        'has_expiry' => true,
        'remaining_seconds' => $remainingSeconds,
        'remaining_days' => $remainingDays,
        'percent' => $percent,
        'color' => $color,
        'tone' => $tone,
    ];
}

function admin_remaining_time_label(int $seconds): string
{
    $seconds = max(0, $seconds);
    if ($seconds === 0) {
        return 'Expired';
    }

    $days = (int)floor($seconds / 86400);
    $hours = (int)floor(($seconds % 86400) / 3600);
    $minutes = (int)floor(($seconds % 3600) / 60);

    if ($days > 0) {
        return $days . 'd ' . $hours . 'h left';
    }
    if ($hours > 0) {
        return $hours . 'h ' . $minutes . 'm left';
    }

    return max(1, $minutes) . 'm left';
}

function admin_search_order_status_badge(array $order, array $messages): array
{
    $status = strtolower(trim((string)($order['status'] ?? '')));
    $payment = strtolower(trim((string)($order['payment_status'] ?? '')));
    $fulfillment = strtolower(trim((string)($order['fulfillment_status'] ?? '')));
    if ($status === 'cancelled' || $fulfillment === 'cancelled') {
        $tone='danger'; $key='enum_cancelled'; $fallback='Cancelled';
    } elseif ($status === 'refunded' || $payment === 'refunded') {
        $tone='danger'; $key='enum_refunded'; $fallback='Refunded';
    } elseif (in_array($status,['failed','inactive','archived'],true)) {
        $tone=$status==='failed'?'danger':'neutral'; $key='enum_'.$status; $fallback=ucfirst($status);
    } elseif ($status === 'expired' || (admin_product_type_uses_expiry($order['product_type'] ?? 'subscription') && (admin_order_progress_data($order)['tone'] ?? '') === 'expired')) {
        $tone='danger'; $key='enum_expired'; $fallback='Expired';
    } elseif (!empty($order['has_paid_pending_renewal']) || ($payment === 'paid' && !in_array($fulfillment,['delivered','fulfilled','completed','shipped','sent'],true))) {
        $tone='warning'; $key='search_order_status_activation'; $fallback='Awaiting activation';
    } elseif ($payment === 'paid' && in_array($fulfillment,['delivered','fulfilled','completed','shipped','sent'],true)) {
        $tone='success'; $key='search_order_status_fulfilled'; $fallback='Fulfilled';
    } elseif ($status === 'pending_payment' || $payment === 'unpaid') {
        $tone='warning'; $key='search_order_status_unpaid'; $fallback='Awaiting payment';
    } else {
        $tone='info'; $key='enum_'.($status ?: 'pending'); $fallback=ucfirst($status ?: 'pending');
    }
    return ['tone'=>$tone, 'label'=>admin_t($messages,$key,$fallback)];
}

function admin_order_status_visual(array $order): array
{
    $status = strtolower(trim((string)($order['status'] ?? '')));
    $paymentStatus = strtolower(trim((string)($order['payment_status'] ?? '')));
    $fulfillmentStatus = strtolower(trim((string)($order['fulfillment_status'] ?? '')));
    $hasPaidPendingRenewal = !empty($order['has_paid_pending_renewal']);

    if ($status === 'cancelled' || $fulfillmentStatus === 'cancelled') {
        return [
            'icon' => 'bi bi-slash-circle-fill',
            'class' => 'admin-order-status-icon--cancelled',
            'label' => 'Cancelled',
        ];
    }

    if ($hasPaidPendingRenewal) {
        return [
            'icon' => 'bi bi-arrow-repeat',
            'class' => 'admin-order-status-icon--awaiting-activation',
            'label' => 'Payment confirmed',
        ];
    }

    if (
        $paymentStatus === 'paid'
        && !in_array($fulfillmentStatus, ['delivered', 'fulfilled', 'completed'], true)
        && !in_array($status, ['active', 'expired', 'cancelled', 'failed', 'inactive'], true)
    ) {
        return [
            'icon' => 'bi bi-arrow-repeat',
            'class' => 'admin-order-status-icon--awaiting-activation',
            'label' => 'Payment confirmed',
        ];
    }

    if ($status === 'pending_payment' || $paymentStatus === 'unpaid' || $fulfillmentStatus === 'pending') {
        return [
            'icon' => 'bi bi-arrow-repeat',
            'class' => 'admin-order-status-icon--pending',
            'label' => 'Pending',
        ];
    }

    if ($status === 'expired') {
        return [
            'icon' => 'bi bi-x-circle-fill',
            'class' => 'admin-order-status-icon--expired',
            'label' => 'Expired',
        ];
    }

    if ($status === 'active' && $paymentStatus === 'paid') {
        return [
            'icon' => 'bi bi-check-circle-fill',
            'class' => 'admin-order-status-icon--active',
            'label' => 'Active',
        ];
    }

    return [
        'icon' => 'bi bi-circle-fill',
        'class' => 'admin-order-status-icon--neutral',
        'label' => ucfirst($status !== '' ? $status : 'status'),
    ];
}

function admin_format_datetime_local(?string $value): string
{
    $value = trim((string)$value);
    if ($value === '') {
        return '';
    }

    $timestamp = function_exists('app_timestamp_from_runtime_datetime')
        ? app_timestamp_from_runtime_datetime($value)
        : strtotime($value);
    if (!is_int($timestamp) || $timestamp <= 0) {
        return '';
    }

    try {
        $timezone = function_exists('app_runtime_timezone_name')
            ? new DateTimeZone(app_runtime_timezone_name())
            : new DateTimeZone(date_default_timezone_get());
    } catch (Throwable $exception) {
        $timezone = new DateTimeZone(date_default_timezone_get());
    }

    return (new DateTimeImmutable('@' . $timestamp))
        ->setTimezone($timezone)
        ->format('Y-m-d\TH:i');
}

function admin_format_datetime_text(?string $value): string
{
    $value = trim((string)$value);
    if ($value === '') {
        return '';
    }

    if (function_exists('app_format_runtime_datetime_local')) {
        return app_format_runtime_datetime_local($value, 'd.m.Y H:i');
    }

    $timestamp = strtotime($value);
    return $timestamp !== false ? date('d.m.Y H:i', $timestamp) : '';
}

function admin_format_money_value($amount, string $currencyCode = ''): string
{
    $currencyCode = trim($currencyCode);
    $currencyLabel = match (strtoupper($currencyCode)) {
        'EUR' => '€',
        'USD' => '$',
        'GBP' => '£',
        'PLN' => 'zł',
        default => $currencyCode,
    };
    if (!is_numeric($amount)) {
        return trim('— ' . $currencyLabel);
    }

    return trim(number_format((float)$amount, 2, '.', '') . ' ' . $currencyLabel);
}

function admin_format_money_value_with_symbol($amount, string $currencyCode = '', string $currencySymbol = ''): string
{
    $currencyCode = trim($currencyCode);
    $currencySymbol = trim($currencySymbol);
    $currencyLabel = $currencySymbol !== '' ? $currencySymbol : $currencyCode;
    $currencyLabel = match (strtoupper($currencyLabel)) { 'EUR'=>'€', 'USD'=>'$', 'GBP'=>'£', 'PLN'=>'zł', default=>$currencyLabel };

    if (!is_numeric($amount)) {
        return trim('— ' . $currencyLabel);
    }

    return trim(number_format((float)$amount, 2, '.', '') . ' ' . $currencyLabel);
}

function admin_compact_datetime_label(?string $value): string
{
    $value = trim((string)$value);
    if ($value === '') {
        return '';
    }

    try {
        $timezone = function_exists('app_runtime_timezone_name')
            ? new DateTimeZone(app_runtime_timezone_name())
            : new DateTimeZone(date_default_timezone_get());
        $timestamp = function_exists('app_timestamp_from_runtime_datetime')
            ? app_timestamp_from_runtime_datetime($value)
            : strtotime($value);
        if (!is_int($timestamp) || $timestamp <= 0) {
            return $value;
        }
        $date = (new DateTimeImmutable('@' . $timestamp))->setTimezone($timezone);
    } catch (Throwable $exception) {
        return $value;
    }

    $today = (new DateTimeImmutable('now', $timezone))->format('Y-m-d');
    if ($date->format('Y-m-d') === $today) {
        return $date->format('H:i');
    }

    if ($date->format('Y') === (new DateTimeImmutable('now', $timezone))->format('Y')) {
        return $date->format('d.m');
    }

    return $date->format('d.m.y');
}

function admin_is_current_day_datetime(?string $value): bool
{
    $value = trim((string)$value);
    if ($value === '') {
        return false;
    }

    try {
        $timezone = function_exists('app_runtime_timezone_name')
            ? new DateTimeZone(app_runtime_timezone_name())
            : new DateTimeZone(date_default_timezone_get());
        $timestamp = function_exists('app_timestamp_from_runtime_datetime')
            ? app_timestamp_from_runtime_datetime($value)
            : strtotime($value);
        if (!is_int($timestamp) || $timestamp <= 0) {
            return false;
        }
        $date = (new DateTimeImmutable('@' . $timestamp))->setTimezone($timezone);
        $today = new DateTimeImmutable('now', $timezone);
    } catch (Throwable $exception) {
        return false;
    }

    return $date->format('Y-m-d') === $today->format('Y-m-d');
}

function admin_country_flag_url(string $countryCode): string
{
    $countryCode = strtoupper(trim($countryCode));
    if ($countryCode === '') {
        return '';
    }

    $flagPath = app_public_path('img/flags/' . $countryCode . '.gif');
    if (!is_file($flagPath)) {
        return '';
    }

    return '/img/flags/' . $countryCode . '.gif';
}

function admin_locale_flag_url(string $localeCode): string
{
    $localeCode = strtolower(trim($localeCode));
    if ($localeCode === 'pl') {
        return admin_country_flag_url('PL');
    }

    if ($localeCode === 'de') {
        return admin_country_flag_url('DE');
    }

    return admin_country_flag_url('GB');
}

function admin_customer_count(Mysql_ks $db): int
{
    if (!schema_object_exists($db, 'customers')) {
        return 0;
    }

    $row = $db->select_user("SELECT COUNT(*) AS total FROM customers");

    return (int)($row['total'] ?? 0);
}

function admin_customer_rows(Mysql_ks $db, int $limit = 20, int $offset = 0): array
{
    if (!schema_object_exists($db, 'customers')) {
        return [];
    }

    app_ensure_customer_runtime_columns($db);

    $limit = max(1, min(50, $limit));
    $offset = max(0, $offset);
    $balanceSelect = schema_column_exists($db, 'customers', 'balance_amount')
        ? 'customers.balance_amount'
        : '0.00 AS balance_amount';
    $ordersTotalSelect = schema_object_exists($db, 'orders')
        ? "(SELECT COUNT(*) FROM orders WHERE orders.customer_id = customers.id)"
        : '0';
    $activeOrdersSelect = schema_object_exists($db, 'orders')
        ? "(SELECT COUNT(*) FROM orders WHERE orders.customer_id = customers.id AND orders.status = 'active')"
        : '0';
    $pendingOrdersSelect = schema_object_exists($db, 'orders')
        ? "(SELECT COUNT(*) FROM orders WHERE orders.customer_id = customers.id AND orders.status = 'pending_payment')"
        : '0';
    $openCryptoPaymentsSelect = schema_object_exists($db, 'crypto_deposit_requests')
        ? "(SELECT COUNT(*) FROM crypto_deposit_requests WHERE crypto_deposit_requests.customer_id = customers.id AND crypto_deposit_requests.status IN ('pending', 'pending_payment', 'awaiting_confirmation', 'awaiting_review'))"
        : '0';
    $openBankPaymentsSelect = schema_object_exists($db, 'bank_transfer_requests')
        ? "(SELECT COUNT(*) FROM bank_transfer_requests WHERE bank_transfer_requests.customer_id = customers.id AND bank_transfer_requests.status IN ('pending_payment', 'awaiting_review'))"
        : '0';
    $publicHandleSelect = schema_column_exists($db, 'customers', 'public_handle')
        ? 'customers.public_handle'
        : "'' AS public_handle";
    $avatarSelect = schema_column_exists($db, 'customers', 'avatar_url')
        ? 'customers.avatar_url'
        : "'' AS avatar_url";

    return $db->select_full_user(
        "SELECT
            customers.id,
            customers.email,
            {$publicHandleSelect},
            {$avatarSelect},
            customers.locale_code,
            customers.country_code,
            customers.status,
            customers.customer_type,
            customers.email_verified_at,
            customers.registered_at,
            customers.last_login_at,
            {$balanceSelect},
            {$ordersTotalSelect} AS orders_total,
            {$activeOrdersSelect} AS orders_active_total,
            {$pendingOrdersSelect} AS orders_pending_total,
            ({$openCryptoPaymentsSelect} + {$openBankPaymentsSelect}) AS open_payments_total
         FROM customers
         ORDER BY customers.id DESC
         LIMIT {$limit} OFFSET {$offset}"
    );
}

function admin_import_email_header_aliases(): array
{
    return [
        'email',
        'e_mail',
        'mail',
        'email_address',
        'emailaddress',
        'e_mail_address',
        'adres_email',
        'adres_mail',
        'user_email',
        'customer_email',
        'client_email',
        'reseller_email',
        'buyer_email',
        'account_email',
        'contact_email',
        'login_email',
    ];
}

function admin_import_header_is_email(string $value): bool
{
    if (str_contains($value, '@')) return false;
    $normalized = admin_import_normalize_header_cell($value);
    if ($normalized === '') {
        return false;
    }

    if (in_array($normalized, admin_import_email_header_aliases(), true)) {
        return true;
    }

    return strpos($normalized, 'email') !== false
        || $normalized === 'mail'
        || substr($normalized, -5) === '_mail';
}

function admin_customer_management_summary(Mysql_ks $db, int $customerId): array
{
    if ($customerId <= 0 || !schema_object_exists($db, 'customers')) {
        return [
            'orders_total' => 0,
            'orders_active_total' => 0,
            'orders_pending_total' => 0,
            'open_payments_total' => 0,
            'wallets_total' => 0,
            'bank_accounts_total' => 0,
        ];
    }

    $ordersTotal = 0;
    $ordersActiveTotal = 0;
    $ordersPendingTotal = 0;
    $openPaymentsTotal = 0;
    $walletsTotal = 0;
    $bankAccountsTotal = 0;

    if (schema_object_exists($db, 'orders')) {
        $row = $db->select_user(
            "SELECT
                COUNT(*) AS orders_total,
                SUM(CASE WHEN status = 'active' THEN 1 ELSE 0 END) AS orders_active_total,
                SUM(CASE WHEN status = 'pending_payment' THEN 1 ELSE 0 END) AS orders_pending_total
             FROM orders
             WHERE customer_id = {$customerId}"
        );
        $ordersTotal = (int)($row['orders_total'] ?? 0);
        $ordersActiveTotal = (int)($row['orders_active_total'] ?? 0);
        $ordersPendingTotal = (int)($row['orders_pending_total'] ?? 0);
    }

    if (schema_object_exists($db, 'crypto_deposit_requests')) {
        $row = $db->select_user(
            "SELECT COUNT(*) AS total
             FROM crypto_deposit_requests
             WHERE customer_id = {$customerId}
               AND status IN ('pending', 'pending_payment', 'awaiting_confirmation', 'awaiting_review')"
        );
        $openPaymentsTotal += (int)($row['total'] ?? 0);
    }

    if (schema_object_exists($db, 'bank_transfer_requests')) {
        $row = $db->select_user(
            "SELECT COUNT(*) AS total
             FROM bank_transfer_requests
             WHERE customer_id = {$customerId}
               AND status IN ('pending_payment', 'awaiting_review')"
        );
        $openPaymentsTotal += (int)($row['total'] ?? 0);
    }

    if (schema_object_exists($db, 'customer_crypto_wallets')) {
        $row = $db->select_user(
            "SELECT COUNT(*) AS total
             FROM customer_crypto_wallets
             WHERE customer_id = {$customerId}"
        );
        $walletsTotal = (int)($row['total'] ?? 0);
    }

    if (schema_object_exists($db, 'customer_bank_accounts')) {
        $row = $db->select_user(
            "SELECT COUNT(*) AS total
             FROM customer_bank_accounts
             WHERE customer_id = {$customerId}"
        );
        $bankAccountsTotal = (int)($row['total'] ?? 0);
    }

    return [
        'orders_total' => $ordersTotal,
        'orders_active_total' => $ordersActiveTotal,
        'orders_pending_total' => $ordersPendingTotal,
        'open_payments_total' => $openPaymentsTotal,
        'wallets_total' => $walletsTotal,
        'bank_accounts_total' => $bankAccountsTotal,
    ];
}

