function admin_customer_delete_group_chat(
    Mysql_ks $db,
    int $customerId,
    int $conversationId,
    int $adminUserId,
    string $ipAddress = ''
): array {
    chat_ensure_group_chat_runtime($db);
    if ($customerId <= 0 || $conversationId <= 0) {
        return ['ok' => false, 'message' => 'Group conversation not found.'];
    }

    $participantKey = chat_participant_key_for_customer($customerId);
    $member = chat_group_member_row($db, $conversationId, $participantKey);
    $conversation = chat_group_conversation_row($db, $conversationId);
    if (
        !$member
        || !$conversation
        || (int)($member['customer_id'] ?? 0) !== $customerId
        || (int)($conversation['group_created_by_customer_id'] ?? 0) !== $customerId
    ) {
        return ['ok' => false, 'message' => 'Only the group owner can remove this group from the customer profile.'];
    }

    $result = chat_delete_group_conversation($db, $conversationId, [
        'participant_type' => 'customer',
        'customer_id' => $customerId,
        'admin_user_id' => $adminUserId,
    ]);

    if (!empty($result['ok'])) {
        $title = chat_group_conversation_title((array)$conversation, 'Group chat');
        admin_log_customer_and_admin(
            $db,
            $customerId,
            $adminUserId,
            'customer_group_chat_deleted',
            'Deleted group chat "' . $title . '" from admin profile.',
            $ipAddress
        );
    }

    return [
        'ok' => !empty($result['ok']),
        'message' => !empty($result['ok'])
            ? 'Group chat deleted successfully.'
            : (string)($result['message'] ?? 'Unable to delete the group chat.'),
    ];
}

function admin_delete_customer_wallet_assignment(
    Mysql_ks $db,
    int $customerId,
    int $walletAssignmentId,
    int $adminUserId,
    string $ipAddress = ''
): array
{
    if (
        $customerId <= 0
        || $walletAssignmentId <= 0
        || !schema_object_exists($db, 'crypto_wallet_assignments')
        || !schema_object_exists($db, 'crypto_wallet_addresses')
    ) {
        return ['ok' => false, 'message' => 'Wallet assignment not found.'];
    }

    $assignment = $db->select_user(
        "SELECT
            crypto_wallet_assignments.id AS wallet_assignment_id,
            crypto_wallet_assignments.wallet_address_id,
            crypto_wallet_addresses.address,
            crypto_assets.code AS crypto_asset_code,
            crypto_assets.name AS crypto_asset_name
         FROM crypto_wallet_assignments
         INNER JOIN crypto_wallet_addresses
           ON crypto_wallet_addresses.id = crypto_wallet_assignments.wallet_address_id
         LEFT JOIN crypto_assets
           ON crypto_assets.id = crypto_wallet_addresses.crypto_asset_id
         WHERE crypto_wallet_assignments.customer_id = {$customerId}
           AND crypto_wallet_assignments.id = {$walletAssignmentId}
           AND crypto_wallet_assignments.status IN ('reserved', 'active')
         LIMIT 1"
    );

    if (!$assignment) {
        return ['ok' => false, 'message' => 'Wallet assignment not found.'];
    }

    $releasedAt = date('Y-m-d H:i:s');
    $deleted = $db->query(
        "UPDATE crypto_wallet_assignments
         SET status = 'released',
             released_at = '{$releasedAt}'
         WHERE customer_id = {$customerId}
           AND id = {$walletAssignmentId}
         LIMIT 1"
    );

    if ($deleted) {
        app_sync_crypto_wallet_address_statuses($db, (int)($assignment['wallet_address_id'] ?? 0));
        $assetLabel = trim((string)($assignment['crypto_asset_name'] ?? ''));
        if ($assetLabel === '') {
            $assetLabel = strtoupper(trim((string)($assignment['crypto_asset_code'] ?? '')));
        }
        $addressLabel = admin_compact_wallet_address((string)($assignment['address'] ?? ''), 6, 5);
        admin_log_customer_and_admin(
            $db,
            $customerId,
            $adminUserId,
            'customer_wallet_assignment_deleted',
            'Removed crypto wallet assignment' . ($assetLabel !== '' ? ' [' . $assetLabel . ']' : '') . ($addressLabel !== '' ? ' ' . $addressLabel : '') . '.',
            $ipAddress
        );
    }

    return [
        'ok' => (bool)$deleted,
        'message' => $deleted ? 'Wallet assignment removed successfully.' : 'Unable to remove wallet assignment.',
    ];
}

