function admin_delete_customer_activity_entry(
    Mysql_ks $db,
    int $customerId,
    int $activityId,
    int $adminUserId,
    string $ipAddress = ''
): array
{
    if ($customerId <= 0 || $activityId <= 0 || !schema_object_exists($db, 'customer_activity_logs')) {
        return ['ok' => false, 'message' => 'History entry not found.'];
    }

    $activityRow = $db->select_user(
        "SELECT
            id,
            action_key,
            description
         FROM customer_activity_logs
         WHERE customer_id = {$customerId}
           AND id = {$activityId}
         LIMIT 1"
    );

    if (!$activityRow) {
        return ['ok' => false, 'message' => 'History entry not found.'];
    }

    $deleted = $db->query(
        "DELETE FROM customer_activity_logs
         WHERE customer_id = {$customerId}
           AND id = {$activityId}
         LIMIT 1"
    );

    if ($deleted && $adminUserId > 0) {
        admin_activity_log(
            $db,
            0,
            $adminUserId,
            'customer_activity_entry_deleted',
            'Deleted customer history entry #' . $activityId . ' for customer #' . $customerId . ': ' . trim((string)($activityRow['action_key'] ?? 'entry')) . '.',
            $ipAddress
        );
    }

    return [
        'ok' => (bool)$deleted,
        'message' => $deleted ? 'History entry removed successfully.' : 'Unable to remove history entry.',
    ];
}

function admin_customer_log(
    Mysql_ks $db,
    int $customerId,
    int $adminUserId,
    string $actionKey,
    string $description,
    string $ipAddress = ''
): void {
    if ($customerId <= 0) {
        return;
    }

    admin_activity_log($db, $customerId, $adminUserId, $actionKey, $description, $ipAddress);
}

function admin_localize_activity_status(string $status): string
{
    $status = trim($status);
    $map = [
        'active' => 'aktywne',
        'archived' => 'zarchiwizowane',
        'awaiting_confirmation' => 'oczekuje na potwierdzenie',
        'awaiting_review' => 'oczekuje na weryfikację',
        'cancelled' => 'anulowane',
        'completed' => 'zakończone',
        'delivered' => 'zrealizowane',
        'failed' => 'nieudane',
        'fulfilled' => 'zrealizowane',
        'paid' => 'opłacone',
        'pending' => 'oczekuje',
        'pending_payment' => 'oczekuje na płatność',
        'rejected' => 'odrzucone',
        'submitted' => 'wysłane',
        'unpaid' => 'nieopłacone',
        'unknown' => 'nieznany',
    ];

    return $map[strtolower($status)] ?? $status;
}

function admin_localize_activity_changes(string $changes): string
{
    $parts = array_map('trim', explode(',', $changes));
    $labels = [
        'status' => 'status',
        'payment' => 'płatność',
        'fulfillment' => 'realizacja',
    ];

    foreach ($parts as &$part) {
        if (preg_match('/^(status|payment|fulfillment)\s+(.+?)\s+->\s+(.+)$/', $part, $matches)) {
            $part = ($labels[$matches[1]] ?? $matches[1])
                . ' ' . admin_localize_activity_status($matches[2])
                . ' -> ' . admin_localize_activity_status($matches[3]);
        }
    }
    unset($part);

    return implode(', ', array_filter($parts, static fn($part): bool => $part !== ''));
}

function admin_localize_activity_description(string $actionKey, string $description): string
{
    if (admin_current_locale() !== 'pl') {
        return $description;
    }

    $description = trim($description);
    if ($description === '') {
        return $description;
    }

    $exact = [
        'Administrator logged in to the admin panel.' => 'Administrator zalogował się do panelu admina.',
        'Customer account created by admin.' => 'Konto użytkownika zostało utworzone przez admina.',
        'Customer password changed by admin.' => 'Hasło użytkownika zostało zmienione przez admina.',
        'Customer profile updated by admin.' => 'Profil użytkownika został zaktualizowany przez admina.',
        'Order updated from admin modal' => 'Zamówienie zaktualizowano w modalu admina',
        'Order activated without customer balance debit by admin.' => 'Zamówienie aktywowano bez pobierania środków z salda klienta.',
        'Order activated with full customer balance debit.' => 'Zapłacono z salda.',
        'Customer balance debited.' => 'Zapłacono z salda.',
        'Activated without balance debit.' => 'Bez pobrania salda.',
    ];
    if (isset($exact[$description])) {
        return $exact[$description];
    }

    $replacements = [
        'Activated order #' => 'Aktywowano zamówienie #',
        ' with available balance. ' => ' z dostępnego salda. ',
        'Marked as paid from customer balance for order #' => 'Oznaczono jako opłacone z salda klienta dla zamówienia #',
        'Rollback after failed admin balance payment for order #' => 'Cofnięcie po nieudanym oznaczeniu płatności z salda dla zamówienia #',
        'Released after cancelled crypto payment request deletion by admin' => 'Zwolniono po usunięciu anulowanego requestu płatności krypto przez admina',
        'Released after crypto payment request deletion by admin' => 'Zwolniono po usunięciu requestu płatności krypto przez admina',
        'Released after crypto payment request status changed to ' => 'Zwolniono po zmianie statusu requestu płatności krypto na ',
        'Cancelled from admin payment editor' => 'Anulowano w edytorze płatności admina',
        'Deleted from admin payments list' => 'Usunięto z listy płatności admina',
        'Converted to balance top-up after order deletion' => 'Zamieniono na doładowanie salda po usunięciu zamówienia',
        'Created as balance top-up after order deletion' => 'Utworzono jako doładowanie salda po usunięciu zamówienia',
    ];
    $description = str_replace(array_keys($replacements), array_values($replacements), $description);

    if (preg_match('/^Order #(\d+) updated(?:: ([^.]+))?\\.(.*)$/', $description, $matches)) {
        $suffix = trim((string)($matches[3] ?? ''));
        $text = 'Zamówienie #' . $matches[1] . ' zaktualizowane';
        if (!empty($matches[2])) {
            $text .= ': ' . admin_localize_activity_changes($matches[2]);
        }
        if ($suffix !== '') {
            $text .= '. ' . rtrim(ltrim($suffix), '.');
        }
        return rtrim($text, '.') . '.';
    }

    if (preg_match('/^Order #(\d+) marked as paid from customer balance\\.$/', $description, $matches)) {
        return 'Zamówienie #' . $matches[1] . ' oznaczono jako opłacone z salda klienta.';
    }

    if (preg_match('/^Order #(\d+) deleted from admin panel\\.$/', $description, $matches)) {
        return 'Zamówienie #' . $matches[1] . ' usunięto z panelu admina.';
    }

    if (preg_match('/^Order #(\d+) switched to suggested package #(\d+)(.*)\\.$/', $description, $matches)) {
        return 'Zamówienie #' . $matches[1] . ' zmieniono na sugerowany pakiet #' . $matches[2] . $matches[3] . '.';
    }

    if (preg_match('/^Customer status changed from (.+?) to (.+)\\.$/', $description, $matches)) {
        return 'Status użytkownika zmieniono z ' . admin_localize_activity_status($matches[1]) . ' na ' . admin_localize_activity_status($matches[2]) . '.';
    }

    if (preg_match('/^Balance (credited|debited) by admin: ([0-9.,]+)(.*)$/', $description, $matches)) {
        return ($matches[1] === 'credited' ? 'Saldo zwiększone przez admina: ' : 'Saldo zmniejszone przez admina: ')
            . $matches[2]
            . $matches[3];
    }

    if (preg_match('/^Balance (credited|debited) automatically: ([0-9.,]+)(.*)$/', $description, $matches)) {
        return ($matches[1] === 'credited' ? 'Saldo zwiększone automatycznie: ' : 'Saldo zmniejszone automatycznie: ')
            . $matches[2]
            . $matches[3];
    }

    if (preg_match('/^Crypto payment request #(\\d+) updated(?:: status ([^\\s.]+) -> ([^\\s.]+))?(?: for order #(\\d+))?(.*)\\.$/', $description, $matches)) {
        $text = 'Request płatności krypto #' . $matches[1] . ' zaktualizowany';
        if (!empty($matches[2])) {
            $text .= ': status ' . admin_localize_activity_status($matches[2]) . ' -> ' . admin_localize_activity_status($matches[3]);
        }
        if (!empty($matches[4])) {
            $text .= ' dla zamówienia #' . $matches[4];
        }
        if (!empty($matches[5])) {
            $text .= str_replace('and invalid order link #', ' i nieprawidłowe powiązanie zamówienia #', $matches[5]);
        }
        return $text . '.';
    }

    if (preg_match('/^Bank payment request #(\\d+) updated(?:: status ([^\\s.]+) -> ([^\\s.]+))?(?: for order #(\\d+))?\\.$/', $description, $matches)) {
        $text = 'Request płatności bankowej #' . $matches[1] . ' zaktualizowany';
        if (!empty($matches[2])) {
            $text .= ': status ' . admin_localize_activity_status($matches[2]) . ' -> ' . admin_localize_activity_status($matches[3]);
        }
        if (!empty($matches[4])) {
            $text .= ' dla zamówienia #' . $matches[4];
        }
        return $text . '.';
    }

    if (preg_match('/^(Crypto|Bank|Legacy crypto|Crypto topup|Bank transfer) payment request #(\\d+) deleted( for order #(\\d+))?\\.$/i', $description, $matches)) {
        $type = strtolower($matches[1]);
        $label = str_contains($type, 'bank') ? 'bankowej' : 'krypto';
        $text = 'Request płatności ' . $label . ' #' . $matches[2] . ' usunięto';
        if (!empty($matches[4])) {
            $text .= ' dla zamówienia #' . $matches[4];
        }
        return $text . '.';
    }

    if (preg_match('/^Bulk deleted cancelled (crypto|bank) payment request #(\\d+)( for order #(\\d+))?\\.$/', $description, $matches)) {
        $text = 'Zbiorczo usunięto anulowany request płatności ' . ($matches[1] === 'bank' ? 'bankowej' : 'krypto') . ' #' . $matches[2];
        if (!empty($matches[4])) {
            $text .= ' dla zamówienia #' . $matches[4];
        }
        return $text . '.';
    }

    if (preg_match('/^Removed crypto wallet assignment(.*)\\.$/', $description, $matches)) {
        return 'Usunięto przypisanie portfela krypto' . $matches[1] . '.';
    }

    if (preg_match('/^Removed bank account assignment(.*)\\.$/', $description, $matches)) {
        return 'Usunięto przypisanie konta bankowego' . $matches[1] . '.';
    }

    if (preg_match('/^Customer account deleted: (.+)\\. Related operational data was removed\\.$/', $description, $matches)) {
        return 'Konto użytkownika usunięte: ' . $matches[1] . '. Powiązane dane operacyjne zostały usunięte.';
    }

    return $description;
}

function admin_localize_order_support_note_text(string $note): string
{
    $note = trim($note);
    if ($note === '') {
        return '';
    }

    $locale = admin_current_locale();
    $replacements = $locale === 'pl'
        ? [
            'Order activated with full customer balance debit.' => 'Zapłacono z salda.',
            'Customer balance debited.' => 'Zapłacono z salda.',
            'Pobrano saldo za zamówienie.' => 'Zapłacono z salda.',
            'Order activated without customer balance debit by admin.' => 'Bez pobrania salda.',
            'Activated without balance debit.' => 'Bez pobrania salda.',
            'Aktywacja bez pobrania salda.' => 'Bez pobrania salda.',
        ]
        : [
            'Order activated with full customer balance debit.' => 'Customer balance debited.',
            'Order activated without customer balance debit by admin.' => 'Activated without balance debit.',
        ];

    return str_replace(array_keys($replacements), array_values($replacements), $note);
}

function admin_order_visible_support_note_text(string $note): string
{
    $note = trim(admin_localize_order_support_note_text($note));
    if ($note === '') {
        return '';
    }

    $neutralNotes = [
        'Zapłacono z salda.',
        'Zapłacono z salda',
        'Customer balance debited.',
        'Customer balance debited',
        'Order activated with full customer balance debit.',
        'Order activated with full customer balance debit',
        'Pobrano saldo za zamówienie.',
        'Pobrano saldo za zamówienie',
    ];
    $neutralLookup = array_fill_keys(array_map(static function (string $value): string {
        return strtolower(trim(preg_replace('/\s+/u', ' ', $value) ?? $value));
    }, $neutralNotes), true);

    $visibleLines = [];
    foreach (preg_split('/\R/u', $note) ?: [] as $line) {
        $line = trim((string)$line);
        if ($line === '') {
            continue;
        }
        $normalized = strtolower(trim(preg_replace('/\s+/u', ' ', $line) ?? $line));
        if (isset($neutralLookup[$normalized])) {
            continue;
        }
        $visibleLines[] = $line;
    }

    return trim(implode("\n", $visibleLines));
}

function admin_activity_log(
    Mysql_ks $db,
    int $customerId,
    int $adminUserId,
    string $actionKey,
    string $description,
    string $ipAddress = ''
): void {
    if (!schema_object_exists($db, 'customer_activity_logs')) {
        return;
    }

    $description = admin_localize_activity_description($actionKey, $description);

    $insertColumns = ['customer_id', 'admin_user_id', 'actor_type', 'action_key', 'description', 'ip_address'];
    $insertValues = [$customerId > 0 ? $customerId : null, $adminUserId > 0 ? $adminUserId : null, 'admin', $actionKey, $description, $ipAddress !== '' ? $ipAddress : null];

    if (schema_column_exists($db, 'customer_activity_logs', 'created_at')) {
        $insertColumns[] = 'created_at';
        $insertValues[] = function_exists('app_current_datetime_string')
            ? app_current_datetime_string()
            : date('Y-m-d H:i:s');
    }

    $db->insert($insertColumns, $insertValues, 'customer_activity_logs');
}

function admin_log_customer_and_admin(
    Mysql_ks $db,
    int $customerId,
    int $adminUserId,
    string $actionKey,
    string $description,
    string $ipAddress = ''
): void {
    admin_customer_log($db, $customerId, $adminUserId, $actionKey, $description, $ipAddress);

    if ($adminUserId > 0) {
        admin_activity_log($db, 0, $adminUserId, $actionKey, $description, $ipAddress);
    }
}

function admin_save_customer_profile(Mysql_ks $db, int $customerId, array $payload, int $adminUserId, string $ipAddress = ''): array
{
    if ($customerId <= 0 || !schema_object_exists($db, 'customers')) {
        return ['ok' => false, 'message' => 'Customer not found.'];
    }

    $current = admin_customer_detail_row($db, $customerId);
    if (!$current) {
        return ['ok' => false, 'message' => 'Customer not found.'];
    }

    $email = strtolower(trim((string)($payload['email'] ?? '')));
    if ($email === '' || !filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return ['ok' => false, 'message' => 'Enter a valid email address.'];
    }

    $existing = app_find_customer_by_email($db, $email);
    if ($existing && (int)($existing['id'] ?? 0) !== $customerId) {
        return ['ok' => false, 'message' => 'This email address is already assigned to another user.'];
    }

    $handleResult = app_resolve_customer_public_handle(
        $db,
        (string)($payload['public_handle'] ?? ($current['public_handle'] ?? '')),
        $email,
        $customerId
    );
    if (empty($handleResult['ok'])) {
        return ['ok' => false, 'message' => (string)($handleResult['message'] ?? 'Unable to save username.')];
    }

    $localeCode = admin_normalize_locale((string)($payload['locale_code'] ?? 'en'));
    $countryCode = strtoupper(substr(trim((string)($payload['country_code'] ?? '')), 0, 2));
    $ipValue = trim((string)($payload['ip_address'] ?? ''));
    $status = strtolower(trim((string)($payload['status'] ?? 'active')));
    if (!in_array($status, ['active', 'blocked', 'inactive'], true)) {
        $status = 'active';
    }
    $customerType = app_normalize_customer_type((string)($payload['customer_type'] ?? ($current['customer_type'] ?? 'client')));

    $emailVerifiedAt = admin_normalize_datetime_input((string)($payload['email_verified_at'] ?? ''));
    $registeredAt = admin_normalize_datetime_input((string)($payload['registered_at'] ?? ''));
    $lastLoginAt = admin_normalize_datetime_input((string)($payload['last_login_at'] ?? ''));
    if ($registeredAt === null) {
        $registeredAt = (string)($current['registered_at'] ?? date('Y-m-d H:i:s'));
    }
    $emailNotification = isset($payload['email_notification']) ? 1 : 0;
    $updateColumns = [
        'email',
        'public_handle',
        'locale_code',
        'country_code',
        'ip_address',
        'status',
        'customer_type',
        'email_verified_at',
        'registered_at',
        'last_login_at',
    ];
    $updateValues = [
        $email,
        (string)($handleResult['handle'] ?? ''),
        $localeCode,
        $countryCode !== '' ? $countryCode : null,
        $ipValue !== '' ? $ipValue : null,
        $status,
        $customerType,
        $emailVerifiedAt,
        $registeredAt,
        $lastLoginAt,
    ];

    $notificationColumn = app_customer_notification_storage_column($db);
    if ($notificationColumn !== '') {
        $updateColumns[] = $notificationColumn;
        $updateValues[] = $emailNotification;
    }

    $updated = $db->update_using_id($updateColumns, $updateValues, 'customers', $customerId);

    if (!$updated) {
        return ['ok' => false, 'message' => 'Unable to save customer profile.'];
    }

    if (isset($payload['provider_visibility_form_present'])) {
        $visibleProviderIds = array_map('intval', (array)($payload['visible_provider_ids'] ?? []));
        app_save_customer_provider_visibility($db, $customerId, $visibleProviderIds);
    }

    $actionKey = 'profile_updated';
    $description = 'Customer profile updated by admin.';
    if ((string)($current['status'] ?? '') !== $status) {
        $actionKey = $status === 'blocked' ? 'customer_blocked' : 'customer_status_changed';
        $description = 'Customer status changed from ' . (string)($current['status'] ?? 'unknown') . ' to ' . $status . '.';
    }

    admin_log_customer_and_admin($db, $customerId, $adminUserId, $actionKey, $description, $ipAddress);

    if ((string)($current['status'] ?? '') !== 'blocked' && $status === 'blocked') {
        app_queue_account_blocked_notification($db, $customerId);
    }

    return ['ok' => true, 'message' => 'Customer profile saved.'];
}

function admin_customer_provider_visibility_rows(Mysql_ks $db, int $customerId): array
{
    $customerId = (int)$customerId;
    if ($customerId <= 0 || !schema_object_exists($db, 'product_providers')) {
        return [];
    }

    app_ensure_customer_provider_visibility_runtime_table($db);
    $visibilityJoin = schema_object_exists($db, 'customer_provider_visibility')
        ? "LEFT JOIN customer_provider_visibility
              ON customer_provider_visibility.provider_id = product_providers.id
             AND customer_provider_visibility.customer_id = {$customerId}"
        : '';
    $visibilitySelect = schema_object_exists($db, 'customer_provider_visibility')
        ? 'COALESCE(customer_provider_visibility.is_visible, 1) AS is_visible'
        : '1 AS is_visible';

    return $db->select_full_user(
        "SELECT
            product_providers.id,
            product_providers.name,
            product_providers.is_active,
            {$visibilitySelect}
         FROM product_providers
         {$visibilityJoin}
         ORDER BY product_providers.name ASC, product_providers.id ASC"
    );
}

function admin_customer_visible_provider_ids(Mysql_ks $db, int $customerId, bool $activeOnly = true): array
{
    $rows = admin_customer_provider_visibility_rows($db, $customerId);
    if (!$rows) {
        return [];
    }

    $visibleProviderIds = [];
    foreach ($rows as $row) {
        $providerId = (int)($row['id'] ?? 0);
        if ($providerId <= 0) {
            continue;
        }
        if ($activeOnly && empty($row['is_active'])) {
            continue;
        }
        if ((int)($row['is_visible'] ?? 1) !== 1) {
            continue;
        }
        $visibleProviderIds[] = $providerId;
    }

    return array_values(array_unique($visibleProviderIds));
}

function admin_customer_provider_visibility_intro(array $messages, ?string $customerType = null, array $settings = []): string
{
    $type = app_normalize_customer_type((string)$customerType);
    if ($type === 'reseller' && admin_credits_sales_enabled($settings)) {
        return admin_t($messages, 'customer_provider_visibility_intro_credits', 'New users see all active providers by default. Uncheck a provider here to hide its credits products from this user in Buy credits.');
    }

    return admin_t($messages, 'customer_provider_visibility_intro', 'New users see all active providers by default. Uncheck a provider here to hide its products from this user in Add new subscription.');
}

function admin_provider_visibility_option_rows(Mysql_ks $db): array
{
    if (!schema_object_exists($db, 'product_providers')) {
        return [];
    }

    return $db->select_full_user(
        "SELECT
            product_providers.id,
            product_providers.name,
            product_providers.is_active,
            1 AS is_visible
         FROM product_providers
         ORDER BY product_providers.name ASC, product_providers.id ASC"
    );
}

function admin_adjust_customer_balance(Mysql_ks $db, int $customerId, array $payload, int $adminUserId, string $ipAddress = ''): array
{
    if ($customerId <= 0 || !schema_object_exists($db, 'customers')) {
        return ['ok' => false, 'message' => 'Customer not found.'];
    }

    if (!schema_column_exists($db, 'customers', 'balance_amount')) {
        return ['ok' => false, 'message' => 'Balance is not available in this database schema yet.'];
    }

    $customer = admin_customer_detail_row($db, $customerId);
    if (!$customer) {
        return ['ok' => false, 'message' => 'Customer not found.'];
    }

    $amount = str_replace(',', '.', trim((string)($payload['adjustment_amount'] ?? '')));
    if ($amount === '' || !is_numeric($amount) || (float)$amount <= 0) {
        return ['ok' => false, 'message' => 'Enter a valid adjustment amount.'];
    }

    $direction = strtolower(trim((string)($payload['adjustment_direction'] ?? 'credit')));
    if (!in_array($direction, ['credit', 'debit'], true)) {
        $direction = 'credit';
    }

    $note = trim((string)($payload['adjustment_note'] ?? ''));
    $currentBalance = (float)($customer['balance_amount'] ?? 0);
    $delta = round((float)$amount, 2);
    $newBalance = $direction === 'debit'
        ? max(0, round($currentBalance - $delta, 2))
        : round($currentBalance + $delta, 2);

    $updated = $db->update_using_id(
        ['balance_amount'],
        [number_format($newBalance, 2, '.', '')],
        'customers',
        $customerId
    );

    if (!$updated) {
        return ['ok' => false, 'message' => 'Unable to update customer balance.'];
    }

    $description = ($direction === 'debit' ? 'Balance debited by admin: ' : 'Balance credited by admin: ')
        . number_format($delta, 2, '.', '');
    if ($note !== '') {
        $description .= ' (' . $note . ')';
    }

    admin_log_customer_and_admin(
        $db,
        $customerId,
        $adminUserId,
        $direction === 'debit' ? 'balance_debit' : 'balance_credit',
        $description,
        $ipAddress
    );

    return ['ok' => true, 'message' => 'Customer balance updated.'];
}

function admin_ensure_customer_balance_runtime_table(Mysql_ks $db): void
{
    app_ensure_customer_balance_runtime_table($db);
}

function admin_apply_customer_balance_runtime_event(
    Mysql_ks $db,
    int $customerId,
    float $amount,
    string $direction,
    string $sourceType,
    string $sourceKey,
    string $note,
    int $adminUserId = 0,
    string $ipAddress = '',
    bool $joinTransaction = false
): array
{
    $note = admin_localize_activity_description('balance_event_note', $note);

    $result = app_apply_customer_balance_runtime_event(
        $db,
        $customerId,
        $amount,
        $direction,
        $sourceType,
        $sourceKey,
        $note,
        'admin',
        $adminUserId,
        $ipAddress,
        $joinTransaction
    );

    if (!empty($result['ok']) && empty($result['already_applied']) && $adminUserId > 0) {
        admin_activity_log(
            $db,
            0,
            $adminUserId,
            strtolower(trim($direction)) === 'debit' ? 'balance_debit' : 'balance_credit',
            trim((string)(
                (strtolower(trim($direction)) === 'debit' ? 'Balance debited automatically: ' : 'Balance credited automatically: ')
                . number_format(round($amount, 2), 2, '.', '')
                . (trim($note) !== '' ? ' (' . trim($note) . ')' : '')
            )),
            $ipAddress
        );
    }

    return $result;
}

function admin_payment_default_status(string $paymentType): string
{
    $paymentType = strtolower(trim($paymentType));
    return ($paymentType === 'crypto' || $paymentType === 'crypto_topup') ? 'pending' : 'pending_payment';
}

function admin_payment_review_status(string $paymentType): string
{
    $paymentType = strtolower(trim($paymentType));
    return 'awaiting_review';
}

function admin_payment_success_statuses(string $paymentType): array
{
    $paymentType = strtolower(trim($paymentType));
    if ($paymentType === 'crypto_topup') {
        return ['archived'];
    }

    return ['confirmed', 'approved', 'paid', 'completed', 'archived'];
}

function admin_round_customer_crypto_fiat_credit($amount): float
{
    if ($amount === null || $amount === '' || !is_numeric((string)$amount)) {
        return 0.0;
    }

    $amount = (float)$amount;
    if ($amount <= 0) {
        return 0.0;
    }

    return round(round($amount * 2) / 2, 2);
}

function admin_payment_cancelled_statuses(string $paymentType): array
{
    $paymentType = strtolower(trim($paymentType));
    if ($paymentType === 'crypto_topup') {
        return [];
    }

    return ['cancelled', 'rejected', 'failed'];
}

function admin_payment_expired_statuses(string $paymentType): array
{
    $paymentType = strtolower(trim($paymentType));
    if ($paymentType === 'crypto_topup') {
        return [];
    }

    return ['expired'];
}

function admin_payment_runtime_statuses(Mysql_ks $db, string $paymentType): array
{
    $paymentType = strtolower(trim($paymentType));
    if ($paymentType === 'crypto_topup') {
        return ['pending', 'archived'];
    }

    $tableName = $paymentType === 'crypto' ? 'crypto_deposit_requests' : 'bank_transfer_requests';
    $knownStatuses = $paymentType === 'crypto'
        ? ['pending', 'awaiting_review', 'awaiting_confirmation', 'expired', 'confirmed', 'approved', 'paid', 'completed', 'cancelled', 'rejected', 'failed', 'archived']
        : ['pending_payment', 'awaiting_review', 'expired', 'confirmed', 'approved', 'paid', 'completed', 'cancelled', 'rejected', 'failed', 'archived'];

    if (!schema_object_exists($db, $tableName)) {
        return $knownStatuses;
    }

    $rows = $db->select_full_user("SELECT DISTINCT status FROM {$tableName}");
    if (!is_array($rows)) {
        return $knownStatuses;
    }

    $foundStatuses = [];
    foreach ($rows as $row) {
        $status = strtolower(trim((string)($row['status'] ?? '')));
        if ($status !== '') {
            $foundStatuses[] = $status;
        }
    }

    return array_values(array_unique(array_merge($knownStatuses, $foundStatuses)));
}

function admin_payment_statuses_for_scope(Mysql_ks $db, string $paymentType, string $scope): array
{
    $paymentType = strtolower(trim($paymentType));
    $scope = strtolower(trim($scope));
    $successStatuses = admin_payment_success_statuses($paymentType);
    $approvedStatuses = array_values(array_filter($successStatuses, static function (string $status): bool {
        return $status !== 'archived';
    }));

    if ($paymentType === 'crypto' || $paymentType === 'crypto_topup') {
        $openStatuses = $paymentType === 'crypto_topup' ? ['pending'] : ['pending', 'awaiting_review', 'awaiting_confirmation'];
        $allStatuses = admin_payment_runtime_statuses($db, $paymentType);
        if ($scope === 'new') {
            return ['pending'];
        }
        if ($scope === 'review' && $paymentType !== 'crypto_topup') {
            return ['awaiting_review', 'awaiting_confirmation'];
        }
        if ($scope === 'approved' && $paymentType !== 'crypto_topup') {
            return $approvedStatuses;
        }
        if ($scope === 'expired' && $paymentType !== 'crypto_topup') {
            return admin_payment_expired_statuses($paymentType);
        }
        if ($scope === 'cancelled' && $paymentType !== 'crypto_topup') {
            return admin_payment_cancelled_statuses($paymentType);
        }
    } else {
        $openStatuses = ['pending_payment', 'awaiting_review'];
        $allStatuses = admin_payment_runtime_statuses($db, $paymentType);
        if ($scope === 'new') {
            return ['pending_payment'];
        }
        if ($scope === 'review') {
            return ['awaiting_review'];
        }
        if ($scope === 'approved') {
            return $approvedStatuses;
        }
        if ($scope === 'expired') {
            return admin_payment_expired_statuses($paymentType);
        }
        if ($scope === 'cancelled') {
            return admin_payment_cancelled_statuses($paymentType);
        }
    }

    if ($scope === 'archived') {
        return array_values(array_filter($allStatuses, static function (string $status): bool {
            return $status === 'archived';
        }));
    }

    if ($scope === 'open') {
        return array_values(array_filter($allStatuses, static function (string $status) use ($openStatuses): bool {
            return in_array($status, $openStatuses, true);
        }));
    }

    if ($scope === 'all') {
        return $allStatuses;
    }

    return $allStatuses;
}

function admin_payment_rows(Mysql_ks $db, int $limit = 10, int $customerId = 0, string $scope = 'open', string $paymentTypeFilter = '', bool $includeBankTransfers = true): array
{
    $rows = [];
    $limit = max(1, min(100, $limit));
    $customerWhere = $customerId > 0 ? ' AND %s.customer_id = ' . $customerId : '';
    $paymentTypeFilter = strtolower(trim($paymentTypeFilter));
    app_ensure_payment_request_runtime_columns($db);

    if (($paymentTypeFilter === '' || $paymentTypeFilter === 'crypto') && schema_object_exists($db, 'crypto_deposit_requests')) {
        $cryptoStatuses = admin_payment_statuses_for_scope($db, 'crypto', $scope);
        $cryptoStatusSql = "'" . implode("','", array_map([$db, 'escape'], $cryptoStatuses)) . "'";
        $cryptoRows = $db->select_full_user(
            "SELECT
                'crypto' AS payment_type,
                crypto_deposit_requests.id,
                crypto_deposit_requests.order_id,
                crypto_deposit_requests.customer_id,
                crypto_deposit_requests.status,
                crypto_deposit_requests.requested_fiat_amount AS amount_value,
                crypto_deposit_requests.requested_crypto_amount AS amount_crypto,
                crypto_deposit_requests.requested_fiat_amount AS requested_amount_value,
                crypto_deposit_requests.requested_crypto_amount AS requested_amount_crypto,
                crypto_deposit_requests.received_fiat_amount,
                crypto_deposit_requests.received_crypto_amount,
                crypto_deposit_requests.exchange_rate,
                COALESCE(crypto_deposit_requests.requested_at, crypto_deposit_requests.expires_at) AS requested_at,
                crypto_deposit_requests.expires_at,
                crypto_wallet_addresses.id AS wallet_address_id,
                crypto_wallet_addresses.address AS payment_reference,
                crypto_wallet_addresses.address AS wallet_address,
                crypto_wallet_addresses.label AS wallet_label,
                crypto_wallet_addresses.network_code AS network_code,
                customers.email AS customer_email,
                NULLIF(TRIM(customers.public_handle), '') AS public_handle,
                crypto_assets.code AS asset_code,
                crypto_assets.name AS asset_name,
                crypto_assets.logo_url AS asset_logo_url,
                currencies.code AS currency_code,
                currencies.symbol AS currency_symbol,
                (orders.id IS NOT NULL AND (".admin_topbar_order_task_where_sql().")) AS order_needs_action,
                EXISTS(SELECT 1 FROM crypto_deposit_transactions tx WHERE tx.deposit_request_id=crypto_deposit_requests.id AND tx.status='auto_accepted') AS auto_accepted
             FROM crypto_deposit_requests
             LEFT JOIN customers ON customers.id = crypto_deposit_requests.customer_id
             LEFT JOIN orders ON orders.id=crypto_deposit_requests.order_id
             LEFT JOIN currencies ON currencies.id = crypto_deposit_requests.fiat_currency_id
             LEFT JOIN crypto_assets ON crypto_assets.id = crypto_deposit_requests.crypto_asset_id
             LEFT JOIN crypto_wallet_addresses ON crypto_wallet_addresses.id = crypto_deposit_requests.wallet_address_id
             WHERE crypto_deposit_requests.status IN ({$cryptoStatusSql})
             " . sprintf($customerWhere, 'crypto_deposit_requests') . "
             ORDER BY crypto_deposit_requests.id DESC
             LIMIT {$limit}"
        );
        $rows = array_merge($rows, $cryptoRows);
    }

    if (($paymentTypeFilter === '' || $paymentTypeFilter === 'crypto') && schema_object_exists($db, 'crypto_topups')) {
        $legacyTopupsTable = schema_read_target($db, 'crypto_topups');
        $legacyTopupProductPriceColumn = schema_read_column($db, 'crypto_topups', 'product_price', 'package_price');
        $legacyTopupCreatedAtColumn = schema_read_column($db, 'crypto_topups', 'created_at', 'date');
        $legacyTopupStatusColumn = schema_read_column($db, 'crypto_topups', 'is_active', 'status');
        $legacyWhere = [];
        if ($scope === 'new' || $scope === 'open') {
            $legacyWhere[] = $legacyTopupsTable . '.' . $legacyTopupStatusColumn . ' = 0';
        } elseif ($scope === 'review') {
            $legacyWhere[] = '1 = 0';
        } elseif ($scope === 'archived') {
            $legacyWhere[] = $legacyTopupsTable . '.' . $legacyTopupStatusColumn . ' <> 0';
        }
        if ($customerId > 0) {
            $legacyWhere[] = $legacyTopupsTable . '.user_id = ' . $customerId;
        }

        $legacySqlWhere = $legacyWhere ? 'WHERE ' . implode(' AND ', $legacyWhere) : '';
        $legacyRows = $db->select_full_user(
            "SELECT
                'crypto_topup' AS payment_type,
                {$legacyTopupsTable}.id,
                NULL AS order_id,
                {$legacyTopupsTable}.user_id AS customer_id,
                CASE WHEN {$legacyTopupsTable}.{$legacyTopupStatusColumn} = 0 THEN 'pending' ELSE 'archived' END AS status,
                {$legacyTopupsTable}.{$legacyTopupProductPriceColumn} AS amount_value,
                {$legacyTopupsTable}.crypto_amount AS amount_crypto,
                {$legacyTopupsTable}.{$legacyTopupCreatedAtColumn} AS requested_at,
                NULL AS expires_at,
                NULL AS wallet_address_id,
                cryptocurrency.adress_code AS payment_reference,
                cryptocurrency.adress_code AS wallet_address,
                '' AS wallet_label,
                '' AS network_code,
                customers.email AS customer_email,
                NULLIF(TRIM(customers.public_handle), '') AS public_handle,
                UPPER(COALESCE(cryptocurrency.symbol, '')) AS asset_code,
                cryptocurrency.name AS asset_name,
                cryptocurrency.logo_url AS asset_logo_url,
                '' AS currency_code,
                '' AS currency_symbol
             FROM {$legacyTopupsTable}
             LEFT JOIN customers ON customers.id = {$legacyTopupsTable}.user_id
             LEFT JOIN cryptocurrency ON cryptocurrency.id = {$legacyTopupsTable}.crypto_id
             {$legacySqlWhere}
             ORDER BY {$legacyTopupsTable}.id DESC
             LIMIT {$limit}"
        );
        $rows = array_merge($rows, $legacyRows);
    }

    if ($includeBankTransfers && ($paymentTypeFilter === '' || $paymentTypeFilter === 'bank') && schema_object_exists($db, 'bank_transfer_requests')) {
        $bankStatuses = admin_payment_statuses_for_scope($db, 'bank', $scope);
        $bankStatusSql = "'" . implode("','", array_map([$db, 'escape'], $bankStatuses)) . "'";
        $bankRows = $db->select_full_user(
            "SELECT
                'bank' AS payment_type,
                bank_transfer_requests.id,
                bank_transfer_requests.order_id,
                bank_transfer_requests.customer_id,
                bank_transfer_requests.status,
                bank_transfer_requests.requested_amount AS amount_value,
                NULL AS amount_crypto,
                COALESCE(bank_transfer_requests.requested_at, bank_transfer_requests.expires_at) AS requested_at,
                bank_transfer_requests.expires_at,
                NULL AS wallet_address_id,
                bank_transfer_requests.payment_reference AS payment_reference,
                '' AS wallet_address,
                '' AS wallet_label,
                '' AS network_code,
                customers.email AS customer_email,
                NULLIF(TRIM(customers.public_handle), '') AS public_handle,
                '' AS asset_code,
                '' AS asset_name,
                '' AS asset_logo_url,
                currencies.code AS currency_code,
                currencies.symbol AS currency_symbol
             FROM bank_transfer_requests
             LEFT JOIN customers ON customers.id = bank_transfer_requests.customer_id
             LEFT JOIN currencies ON currencies.id = bank_transfer_requests.currency_id
             WHERE bank_transfer_requests.status IN ({$bankStatusSql})
             " . sprintf($customerWhere, 'bank_transfer_requests') . "
             ORDER BY bank_transfer_requests.id DESC
             LIMIT {$limit}"
        );
        $rows = array_merge($rows, $bankRows);
    }

    usort($rows, static function (array $left, array $right): int {
        return strcmp((string)($right['requested_at'] ?? ''), (string)($left['requested_at'] ?? ''));
    });

    return array_slice($rows, 0, $limit);
}

function admin_payment_summary(Mysql_ks $db, int $customerId = 0, bool $includeBankTransfers = true): array
{
    $summary = [
        'total' => 0,
        'open_total' => 0,
        'new_total' => 0,
        'review_total' => 0,
        'approved_total' => 0,
        'archived_total' => 0,
        'expired_total' => 0,
        'cancelled_total' => 0,
        'crypto_total' => 0,
        'crypto_cancelled_total' => 0,
        'bank_total' => 0,
        'bank_cancelled_total' => 0,
    ];

    $customerWhereCrypto = $customerId > 0 ? ' WHERE customer_id = ' . $customerId : '';
    $customerWhereBank = $customerId > 0 ? ' WHERE customer_id = ' . $customerId : '';

    if (schema_object_exists($db, 'crypto_deposit_requests')) {
        $row = $db->select_user(
            "SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN status = 'pending' THEN 1 ELSE 0 END) AS pending_total,
                SUM(CASE WHEN status IN ('awaiting_review', 'awaiting_confirmation') THEN 1 ELSE 0 END) AS review_total,
                SUM(CASE WHEN status = 'expired' THEN 1 ELSE 0 END) AS expired_total,
                SUM(CASE WHEN status IN ('cancelled', 'rejected', 'failed') THEN 1 ELSE 0 END) AS cancelled_total,
                SUM(CASE WHEN status IN ('confirmed', 'approved', 'paid', 'completed') THEN 1 ELSE 0 END) AS approved_total,
                SUM(CASE WHEN status = 'archived' THEN 1 ELSE 0 END) AS archived_total
             FROM crypto_deposit_requests" . $customerWhereCrypto
        );

        $summary['crypto_total'] += (int)($row['total'] ?? 0);
        $summary['new_total'] += (int)($row['pending_total'] ?? 0);
        $summary['review_total'] += (int)($row['review_total'] ?? 0);
        $summary['expired_total'] += (int)($row['expired_total'] ?? 0);
        $summary['approved_total'] += (int)($row['approved_total'] ?? 0);
        $summary['crypto_cancelled_total'] += (int)($row['cancelled_total'] ?? 0);
        $summary['cancelled_total'] += (int)($row['cancelled_total'] ?? 0);
        $summary['archived_total'] += (int)($row['archived_total'] ?? 0);
    }

    if (schema_object_exists($db, 'crypto_topups')) {
        $legacyTopupsTable = schema_read_target($db, 'crypto_topups');
        $legacyTopupStatusColumn = schema_read_column($db, 'crypto_topups', 'is_active', 'status');
        $legacyCustomerWhere = $customerId > 0 ? ' WHERE user_id = ' . $customerId : '';
        $row = $db->select_user(
            "SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN {$legacyTopupStatusColumn} = 0 THEN 1 ELSE 0 END) AS pending_total,
                SUM(CASE WHEN {$legacyTopupStatusColumn} <> 0 THEN 1 ELSE 0 END) AS archived_total
             FROM {$legacyTopupsTable}{$legacyCustomerWhere}"
        );

        $summary['crypto_total'] += (int)($row['total'] ?? 0);
        $summary['new_total'] += (int)($row['pending_total'] ?? 0);
        $summary['archived_total'] += (int)($row['archived_total'] ?? 0);
    }

    if ($includeBankTransfers && schema_object_exists($db, 'bank_transfer_requests')) {
        $row = $db->select_user(
            "SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN status = 'pending_payment' THEN 1 ELSE 0 END) AS pending_total,
                SUM(CASE WHEN status = 'awaiting_review' THEN 1 ELSE 0 END) AS review_total,
                SUM(CASE WHEN status = 'expired' THEN 1 ELSE 0 END) AS expired_total,
                SUM(CASE WHEN status IN ('cancelled', 'rejected', 'failed') THEN 1 ELSE 0 END) AS cancelled_total,
                SUM(CASE WHEN status IN ('confirmed', 'approved', 'paid', 'completed') THEN 1 ELSE 0 END) AS approved_total,
                SUM(CASE WHEN status = 'archived' THEN 1 ELSE 0 END) AS archived_total
             FROM bank_transfer_requests" . $customerWhereBank
        );

        $summary['bank_total'] += (int)($row['total'] ?? 0);
        $summary['new_total'] += (int)($row['pending_total'] ?? 0);
        $summary['review_total'] += (int)($row['review_total'] ?? 0);
        $summary['expired_total'] += (int)($row['expired_total'] ?? 0);
        $summary['approved_total'] += (int)($row['approved_total'] ?? 0);
        $summary['bank_cancelled_total'] += (int)($row['cancelled_total'] ?? 0);
        $summary['cancelled_total'] += (int)($row['cancelled_total'] ?? 0);
        $summary['archived_total'] += (int)($row['archived_total'] ?? 0);
    }

    $summary['total'] = $summary['crypto_total'] + $summary['bank_total'];
    $summary['open_total'] = $summary['new_total'] + $summary['review_total'];

    return $summary;
}

/** Sidebar count needs only open statuses, not aggregate history totals. */
function admin_payment_open_count(Mysql_ks $db, bool $includeBankTransfers = true): int
{
    $total = 0;
    foreach ([
        ['crypto_deposit_requests', "status IN ('pending','awaiting_review','awaiting_confirmation')", true],
        ['bank_transfer_requests', "status IN ('pending_payment','awaiting_review')", $includeBankTransfers],
    ] as [$table, $where, $enabled]) {
        if ($enabled && schema_object_exists($db, $table)) {
            $row = $db->select_user("SELECT COUNT(*) AS total FROM {$table} WHERE {$where}");
            $total += (int)($row['total'] ?? 0);
        }
    }
    if (schema_object_exists($db, 'crypto_topups')) {
        $table = schema_read_target($db, 'crypto_topups');
        $status = schema_read_column($db, 'crypto_topups', 'is_active', 'status');
        $row = $db->select_user("SELECT COUNT(*) AS total FROM {$table} WHERE {$status}=0");
        $total += (int)($row['total'] ?? 0);
    }
    return $total;
}

function admin_topbar_notification_payment_rows(Mysql_ks $db, bool $includeBankTransfers = true, int $limit = 8): array
{
    return admin_payment_rows($db, max(1, min(20, $limit)), 0, 'open', '', $includeBankTransfers);
}

/** A paid renewal remains actionable even while the underlying order is active or expired. */
function admin_topbar_order_task_where_sql(): string
{
    return "orders.payment_status = 'paid'
        AND COALESCE(orders.status, '') NOT IN ('cancelled','refunded','failed','inactive','archived')
        AND (
            (orders.status <> 'expired' AND (orders.status NOT IN ('active','approved','completed','fulfilled')
                OR COALESCE(orders.fulfillment_status, '') NOT IN ('delivered','fulfilled','completed','shipped','sent')))
            OR EXISTS (SELECT 1 FROM order_renewals
                WHERE order_renewals.order_id = orders.id AND order_renewals.status = 'paid_pending_activation')
        )";
}

function admin_topbar_order_task(array $row, array $messages): array
{
    $renewal = !empty($row['has_paid_pending_renewal']);
    $subscription = admin_product_type_uses_expiry($row['product_type'] ?? 'subscription');
    $providerUrl = trim((string)($row['dashboard_url'] ?? ''));
    $parts = parse_url($providerUrl);
    if (!$parts || !in_array(strtolower((string)($parts['scheme'] ?? '')), ['http','https'], true)
        || empty($parts['host']) || isset($parts['user']) || isset($parts['pass']) || preg_match('/[\x00-\x20\x7f]/', $providerUrl)) $providerUrl = '';
    $titleRow = $row;
    if ($renewal) {
        $titleRow['product_name'] = ($row['renewal_product_name'] ?? '') ?: ($row['product_name'] ?? '');
        $titleRow['duration_hours'] = $row['renewal_duration_hours'] ?? $row['duration_hours'] ?? 0;
    }
    $paymentType = $renewal ? (string)($row['renewal_payment_type'] ?? '') : (!empty($row['crypto_payment_id']) ? 'crypto' : 'bank');
    $paymentId = $renewal ? (int)($row['renewal_payment_id'] ?? 0) : (int)($row[$paymentType . '_payment_id'] ?? 0);
    return [
        'kind' => $renewal ? 'renewal' : ($subscription ? 'activation' : 'fulfillment'),
        'title' => admin_t($messages, $renewal ? 'topbar_task_renewal' : 'topbar_task_fulfillment', $renewal ? 'Renewal to complete' : 'Order to complete'),
        'product' => admin_order_product_title($titleRow, $messages),
        'amount' => admin_format_money_value_with_symbol(
            $renewal ? ($row['renewal_price_amount'] ?? null) : ($row['total_amount'] ?? null),
            (string)($row['task_currency_code'] ?? $row['currency_code'] ?? ''),
            (string)($row['task_currency_symbol'] ?? $row['currency_symbol'] ?? '')
        ),
        'step_one' => admin_t($messages, $renewal ? 'topbar_task_extend_provider' : ($subscription ? 'topbar_task_activate_provider' : 'topbar_task_deliver'), $renewal ? 'Extend the subscription in the provider panel.' : 'Prepare access for the customer.'),
        'step_two' => admin_t($messages, $renewal ? 'topbar_task_confirm_renewal' : 'topbar_task_confirm_order', $renewal ? 'In Orders, confirm the extension in the Renew tab.' : 'In Orders, set the status to ACTIVE and save.'),
        'provider_url' => $providerUrl,
        'order_url' => '/admin/?page=orders&order_id=' . (int)$row['id'],
        'payment_url' => $paymentId > 0 && in_array($paymentType, ['crypto','bank'], true) ? '/admin/?page=payments&payment_type=' . $paymentType . '&payment_id=' . $paymentId : '',
    ];
}

function admin_topbar_order_tasks_html(array $taskRows, int $taskTotal, array $messages): string
{
    ob_start();
    require __DIR__ . '/partials/notification-order-tasks.php';
    return (string)ob_get_clean();
}

function admin_topbar_notification_order_rows(Mysql_ks $db, int $limit = 8, int $orderId = 0): array
{
    if (!schema_object_exists($db, 'orders')) {
        return [];
    }

    app_ensure_customer_runtime_columns($db);
    app_ensure_order_renewal_runtime_columns($db);
    $taskWhere = admin_topbar_order_task_where_sql();
    $orderWhere = $orderId > 0 ? " AND orders.id = {$orderId}" : "";

    $limit = max(1, min(20, $limit));
    $customerHandleSelect = schema_column_exists($db, 'customers', 'public_handle')
        ? 'customers.public_handle'
        : "'' AS public_handle";

    return $db->select_full_user(
        "SELECT
            orders.id,
            orders.customer_id,
            orders.product_id,
            orders.payment_method,
            orders.status,
            orders.payment_status,
            orders.fulfillment_status,
            orders.total_amount,
            orders.created_at,
            orders.paid_at,
            orders.expires_at,
            task_renewal.id AS pending_renewal_id,
            (task_renewal.id IS NOT NULL) AS has_paid_pending_renewal,
            task_renewal.price_amount AS renewal_price_amount,
            task_renewal.duration_hours AS renewal_duration_hours,
            task_renewal.paid_at AS renewal_paid_at,
            task_renewal.payment_request_type AS renewal_payment_type,
            task_renewal.payment_request_id AS renewal_payment_id,
            renewal_product.name AS renewal_product_name,
            COALESCE(task_renewal.paid_at, task_renewal.requested_at, orders.paid_at, orders.created_at) AS task_waiting_since,
            customers.email AS customer_email,
            {$customerHandleSelect},
            products.provider_id,
            products.name AS product_name,
            products.duration_hours,
            products.product_type,
            product_providers.name AS provider_name,
            product_providers.dashboard_url,
            currencies.code AS currency_code,
            currencies.symbol AS currency_symbol,
            COALESCE(renewal_currency.code, currencies.code) AS task_currency_code,
            COALESCE(renewal_currency.symbol, currencies.symbol) AS task_currency_symbol,
            (
                SELECT crypto_deposit_requests.id
                FROM crypto_deposit_requests
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ) AS crypto_payment_id,
            (
                SELECT bank_transfer_requests.id
                FROM bank_transfer_requests
                WHERE bank_transfer_requests.order_id = orders.id
                ORDER BY bank_transfer_requests.id DESC
                LIMIT 1
            ) AS bank_payment_id,
            (
                SELECT crypto_wallet_addresses.id
                FROM crypto_deposit_requests
                INNER JOIN crypto_wallet_addresses ON crypto_wallet_addresses.id = crypto_deposit_requests.wallet_address_id
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ) AS wallet_address_id,
            (
                SELECT crypto_wallet_addresses.address
                FROM crypto_deposit_requests
                INNER JOIN crypto_wallet_addresses ON crypto_wallet_addresses.id = crypto_deposit_requests.wallet_address_id
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ) AS wallet_address,
            (
                SELECT crypto_wallet_addresses.label
                FROM crypto_deposit_requests
                INNER JOIN crypto_wallet_addresses ON crypto_wallet_addresses.id = crypto_deposit_requests.wallet_address_id
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ) AS wallet_label,
            (
                SELECT crypto_wallet_addresses.network_code
                FROM crypto_deposit_requests
                INNER JOIN crypto_wallet_addresses ON crypto_wallet_addresses.id = crypto_deposit_requests.wallet_address_id
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ) AS wallet_network_code,
            (
                SELECT crypto_assets.code
                FROM crypto_deposit_requests
                INNER JOIN crypto_assets ON crypto_assets.id = crypto_deposit_requests.crypto_asset_id
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ) AS wallet_asset_code
         FROM orders
         LEFT JOIN order_renewals AS task_renewal ON task_renewal.id = (
             SELECT id FROM order_renewals
             WHERE order_id = orders.id AND status = 'paid_pending_activation'
             ORDER BY id DESC LIMIT 1
         )
         LEFT JOIN products AS renewal_product ON renewal_product.id = task_renewal.product_id
         LEFT JOIN currencies AS renewal_currency ON renewal_currency.id = task_renewal.currency_id
         LEFT JOIN customers ON customers.id = orders.customer_id
         LEFT JOIN products ON products.id = orders.product_id
         LEFT JOIN product_providers ON product_providers.id = products.provider_id
         LEFT JOIN currencies ON currencies.id = orders.currency_id
         WHERE {$taskWhere}{$orderWhere}
         ORDER BY task_waiting_since ASC, orders.id ASC
         LIMIT {$limit}"
    );
}

function admin_topbar_notification_order_count(Mysql_ks $db): int
{
    if (!schema_object_exists($db, 'orders')) return 0;
    app_ensure_order_renewal_runtime_columns($db);
    $where = admin_topbar_order_task_where_sql();
    $row = $db->select_user("SELECT COUNT(*) AS total FROM orders WHERE {$where}");
    return (int)($row['total'] ?? 0);
}

function admin_topbar_notification_new_customer_rows(Mysql_ks $db, int $limit = 5): array
{
    if (!schema_object_exists($db, 'customers')) {
        return [];
    }

    app_ensure_customer_runtime_columns($db);

    $limit = max(1, min(20, $limit));
    $handleSql = schema_column_exists($db, 'customers', 'public_handle')
        ? 'customers.public_handle'
        : "'' AS public_handle";
    $avatarSql = schema_column_exists($db, 'customers', 'avatar_url')
        ? 'customers.avatar_url'
        : "'' AS avatar_url";

    return $db->select_full_user(
        "SELECT
            customers.id,
            customers.email,
            {$handleSql},
            {$avatarSql},
            customers.status,
            customers.registered_at,
            customers.last_login_at
         FROM customers
         WHERE DATE(customers.registered_at) = CURDATE()
         ORDER BY customers.registered_at DESC, customers.id DESC
         LIMIT {$limit}"
    );
}

function admin_topbar_notification_auto_accepted_crypto_payment_rows(Mysql_ks $db, int $limit = 5, int $hours = 24): array
{
    if (
        !schema_object_exists($db, 'crypto_deposit_transactions')
        || !schema_object_exists($db, 'crypto_deposit_requests')
    ) {
        return [];
    }

    app_ensure_payment_request_runtime_columns($db);
    app_ensure_customer_runtime_columns($db);

    $limit = max(1, min(20, $limit));
    $hours = max(1, min(168, $hours));
    $handleSql = schema_column_exists($db, 'customers', 'public_handle')
        ? 'customers.public_handle'
        : "'' AS public_handle";
    $txStatusSql = schema_column_exists($db, 'crypto_deposit_transactions', 'status')
        ? "AND crypto_deposit_transactions.status = 'auto_accepted'"
        : '';
    $txReceivedAtSql = schema_column_exists($db, 'crypto_deposit_transactions', 'received_at')
        ? 'crypto_deposit_transactions.received_at'
        : 'NULL';
    $txAmountFiatSql = schema_column_exists($db, 'crypto_deposit_transactions', 'amount_fiat')
        ? 'crypto_deposit_transactions.amount_fiat'
        : 'NULL';
    $txAmountCryptoSql = schema_column_exists($db, 'crypto_deposit_transactions', 'amount_crypto')
        ? 'crypto_deposit_transactions.amount_crypto'
        : 'NULL';
    $txHashSql = schema_column_exists($db, 'crypto_deposit_transactions', 'transaction_hash')
        ? 'crypto_deposit_transactions.transaction_hash'
        : "''";
    $receivedCryptoSql = schema_column_exists($db, 'crypto_deposit_requests', 'received_crypto_amount')
        ? 'crypto_deposit_requests.received_crypto_amount'
        : 'NULL';
    $receivedFiatSql = schema_column_exists($db, 'crypto_deposit_requests', 'received_fiat_amount')
        ? 'crypto_deposit_requests.received_fiat_amount'
        : 'NULL';

    return $db->select_full_user(
        "SELECT
            crypto_deposit_transactions.id AS transaction_id,
            crypto_deposit_requests.id AS payment_id,
            crypto_deposit_requests.order_id,
            crypto_deposit_requests.customer_id,
            crypto_deposit_requests.status AS payment_status,
            (orders.id IS NOT NULL AND (".admin_topbar_order_task_where_sql().")) AS order_needs_action,
            {$txHashSql} AS transaction_hash,
            {$txReceivedAtSql} AS received_at,
            COALESCE({$receivedCryptoSql}, {$txAmountCryptoSql}, crypto_deposit_requests.requested_crypto_amount, 0) AS amount_crypto,
            COALESCE({$receivedFiatSql}, {$txAmountFiatSql}, crypto_deposit_requests.requested_fiat_amount, 0) AS amount_fiat,
            customers.email AS customer_email,
            {$handleSql},
            currencies.code AS currency_code,
            currencies.symbol AS currency_symbol,
            crypto_assets.code AS asset_code,
            crypto_assets.name AS asset_name,
            crypto_assets.logo_url AS asset_logo_url,
            COALESCE(direct_wallet.network_code, assigned_wallet.network_code, '') AS network_code
         FROM crypto_deposit_transactions
         INNER JOIN crypto_deposit_requests
           ON crypto_deposit_requests.id = crypto_deposit_transactions.deposit_request_id
         LEFT JOIN customers ON customers.id = crypto_deposit_requests.customer_id
         LEFT JOIN orders ON orders.id=crypto_deposit_requests.order_id
         LEFT JOIN currencies ON currencies.id = crypto_deposit_requests.fiat_currency_id
         LEFT JOIN crypto_assets ON crypto_assets.id = crypto_deposit_requests.crypto_asset_id
         LEFT JOIN crypto_wallet_assignments AS payment_assignment
           ON payment_assignment.id = crypto_deposit_requests.wallet_assignment_id
         LEFT JOIN crypto_wallet_addresses AS direct_wallet
           ON direct_wallet.id = crypto_deposit_requests.wallet_address_id
         LEFT JOIN crypto_wallet_addresses AS assigned_wallet
           ON assigned_wallet.id = payment_assignment.wallet_address_id
         WHERE crypto_deposit_requests.status IN ('approved','archived') AND {$txReceivedAtSql} IS NOT NULL
           AND {$txReceivedAtSql} >= DATE_SUB(UTC_TIMESTAMP(), INTERVAL {$hours} HOUR)
           {$txStatusSql}
         ORDER BY {$txReceivedAtSql} DESC, crypto_deposit_transactions.id DESC
         LIMIT {$limit}"
    );
}

function admin_topbar_notification_expiring_subscription_data(Mysql_ks $db, int $limit = 8, int $hours = 24): array
{
    if (!schema_object_exists($db, 'orders')) {
        return ['total' => 0, 'rows' => []];
    }

    app_ensure_customer_runtime_columns($db);

    $limit = max(1, min(20, $limit));
    $hours = max(1, min(168, $hours));
    $handleSql = schema_column_exists($db, 'customers', 'public_handle')
        ? 'customers.public_handle'
        : "'' AS public_handle";

    $whereSql = "orders.status = 'active'
           AND COALESCE(orders.payment_status, '') = 'paid'
           AND orders.expires_at IS NOT NULL
           AND orders.expires_at > NOW()
           AND orders.expires_at <= DATE_ADD(NOW(), INTERVAL {$hours} HOUR)";

    $countRow = $db->select_user(
        "SELECT COUNT(*) AS total
         FROM orders
         WHERE {$whereSql}"
    );

    $rows = $db->select_full_user(
        "SELECT
            orders.id,
            orders.customer_id,
            orders.product_id,
            orders.total_amount,
            orders.expires_at,
            customers.email AS customer_email,
            {$handleSql},
            products.provider_id,
            products.name AS product_name,
            product_providers.name AS provider_name,
            product_providers.dashboard_url,
            currencies.code AS currency_code
         FROM orders
         LEFT JOIN customers ON customers.id = orders.customer_id
         LEFT JOIN products ON products.id = orders.product_id
         LEFT JOIN product_providers ON product_providers.id = products.provider_id
         LEFT JOIN currencies ON currencies.id = orders.currency_id
         WHERE {$whereSql}
         ORDER BY orders.expires_at ASC, orders.id ASC
         LIMIT {$limit}"
    );

    return [
        'total' => (int)($countRow['total'] ?? 0),
        'rows' => $rows,
    ];
}

