function admin_topbar_manual_backup_notice(array $settings, int $intervalHours = 168): array
{
    $lastBackupAt = trim((string)($settings['manual_database_backup_last_downloaded_at'] ?? ''));
    $lastBackupTimestamp = $lastBackupAt !== '' ? strtotime($lastBackupAt) : false;
    $intervalHours = max(1, $intervalHours);
    $isOverdue = $lastBackupTimestamp === false || (time() - $lastBackupTimestamp) >= ($intervalHours * 3600);

    return [
        'show' => $isOverdue,
        'last_backup_at' => $lastBackupAt,
        'last_backup_label' => $lastBackupTimestamp !== false ? date('d.m.Y H:i', $lastBackupTimestamp) : '',
        'last_backup_compact_label' => $lastBackupTimestamp !== false ? admin_compact_datetime_label($lastBackupAt) : '',
        'interval_hours' => $intervalHours,
    ];
}

function admin_topbar_admin_panel_subscription_notice(array $settings, int $warningDays = 7, ?int $now = null): array
{
    $paidUntil = trim((string)($settings['admin_panel_subscription_paid_until'] ?? ''));
    $renewalUrl = trim((string)($settings['admin_panel_subscription_renewal_url'] ?? ''));
    $tiersConfig = app_panel_tiers_config(Mysql_ks::get_instance());
    if (!empty($tiersConfig['enabled'])) $renewalUrl = '#adminPanelTierPaymentModal';
    $paidUntilTimestamp = app_panel_subscription_paid_until_timestamp($settings);
    $warningDays = max(1, $warningDays);

    if ($paidUntilTimestamp === null) {
        return [
            'show' => false,
            'paid_until' => $paidUntil,
            'paid_until_label' => '',
            'renewal_url' => $renewalUrl,
            'days_left' => null,
            'is_expired' => false,
        ];
    }

    $secondsLeft = $paidUntilTimestamp - ($now ?? time());
    $daysLeft = $secondsLeft >= 0
        ? (int)ceil($secondsLeft / 86400)
        : -1 * (int)ceil(abs($secondsLeft) / 86400);
    $isExpired = $secondsLeft < 0;
    $show = $isExpired || $daysLeft < $warningDays;

    return [
        'show' => $show,
        'paid_until' => $paidUntil,
        'paid_until_label' => date('d.m.Y', $paidUntilTimestamp),
        'renewal_url' => $renewalUrl,
        'days_left' => $daysLeft,
        'is_expired' => $isExpired,
        'warning_days' => $warningDays,
    ];
}

function admin_topbar_notification_count(Mysql_ks $db, array $settings, ?int $taskTotal = null): int
{
    $payments = admin_topbar_notification_payment_rows($db, admin_bank_transfers_enabled($settings), 8);
    $taskTotal = $taskTotal ?? admin_topbar_notification_order_count($db);
    $autoAcceptedPayments = admin_topbar_notification_auto_accepted_crypto_payment_rows($db, 5, 24);
    $backup = admin_topbar_manual_backup_notice($settings, 168);
    $adminPanelSubscription = admin_topbar_admin_panel_subscription_notice($settings, 7);

    return count($payments)
        + $taskTotal
        + count($autoAcceptedPayments)
        + (!empty($adminPanelSubscription['show']) ? 1 : 0)
        + (!empty($backup['show']) ? 1 : 0);
}

function admin_topbar_apply_order_action(
    Mysql_ks $db,
    int $orderId,
    string $action,
    int $adminUserId = 0,
    string $ipAddress = ''
): array
{
    $order = admin_order_find($db, $orderId);
    if (!$order) {
        return ['ok' => false, 'message' => 'Order not found.'];
    }

    $action = strtolower(trim($action));
    if (!in_array($action, ['accept', 'reject'], true)) {
        return ['ok' => false, 'message' => 'Unsupported order action.'];
    }

    $payload = [
        'order_reference' => (string)($order['order_reference'] ?? ''),
        'payment_method' => (string)($order['payment_method'] ?? ''),
        'total_amount' => number_format((float)($order['total_amount'] ?? 0), 2, '.', ''),
        'customer_note' => (string)($order['customer_note'] ?? ''),
        'support_note' => (string)($order['support_note'] ?? ''),
        'delivery_link' => (string)($order['delivery_link'] ?? ''),
        'transaction_reference' => (string)($order['transaction_reference'] ?? ''),
        'started_at' => (string)($order['started_at'] ?? ''),
        'expires_at' => (string)($order['expires_at'] ?? ''),
        'paid_at' => (string)($order['paid_at'] ?? ''),
        'delivery_link_visible' => !empty($order['delivery_link_visible']) ? '1' : '0',
        'status' => $action === 'accept' ? 'active' : 'cancelled',
        'payment_status' => (string)($order['payment_status'] ?? 'paid'),
        'fulfillment_status' => $action === 'accept' ? 'delivered' : 'cancelled',
    ];

    return admin_save_order_info($db, $orderId, $payload, $adminUserId, $ipAddress);
}

function admin_delete_cancelled_payments(
    Mysql_ks $db,
    int $customerId = 0,
    string $paymentTypeFilter = '',
    bool $includeBankTransfers = true,
    int $adminUserId = 0,
    string $ipAddress = ''
): array
{
    $paymentTypeFilter = strtolower(trim($paymentTypeFilter));
    $cancelledStatuses = "'cancelled','rejected','failed'";
    $deletedTotal = 0;
    $settings = admin_app_settings($db);
    $releaseWalletAssignments = admin_crypto_wallet_shared_assignments_enabled($settings);

    if ($paymentTypeFilter === '' || $paymentTypeFilter === 'crypto') {
        if (schema_object_exists($db, 'crypto_deposit_requests')) {
            $whereSql = "status IN ({$cancelledStatuses})";
            if ($customerId > 0) {
                $whereSql .= ' AND customer_id = ' . $customerId;
            }
            $rows = $db->select_full_user(
                "SELECT id, customer_id, order_id, wallet_assignment_id
                 FROM crypto_deposit_requests
                 WHERE {$whereSql}"
            );

            foreach ($rows as $row) {
                $deleted = $db->delete_using_id('crypto_deposit_requests', (int)($row['id'] ?? 0));
                if ($deleted) {
                    if ($releaseWalletAssignments && !empty($row['wallet_assignment_id'])) {
                        app_release_crypto_wallet_assignment_if_unused(
                            $db,
                            (int)$row['wallet_assignment_id'],
                            'Released after cancelled crypto payment request deletion by admin'
                        );
                    }
                    $deletedTotal++;
                    $description = 'Bulk deleted cancelled crypto payment request #' . (int)($row['id'] ?? 0);
                    if (!empty($row['order_id'])) {
                        $description .= ' for order #' . (int)$row['order_id'];
                    }
                    admin_log_customer_and_admin(
                        $db,
                        (int)($row['customer_id'] ?? 0),
                        $adminUserId,
                        'payment_deleted',
                        $description . '.',
                        $ipAddress
                    );
                }
            }
        }
    }

    if (($paymentTypeFilter === '' || $paymentTypeFilter === 'bank') && $includeBankTransfers && schema_object_exists($db, 'bank_transfer_requests')) {
        $whereSql = "status IN ({$cancelledStatuses})";
        if ($customerId > 0) {
            $whereSql .= ' AND customer_id = ' . $customerId;
        }
        $rows = $db->select_full_user(
            "SELECT id, customer_id, order_id
             FROM bank_transfer_requests
             WHERE {$whereSql}"
        );

        foreach ($rows as $row) {
            $deleted = $db->delete_using_id('bank_transfer_requests', (int)($row['id'] ?? 0));
            if ($deleted) {
                $deletedTotal++;
                $description = 'Bulk deleted cancelled bank payment request #' . (int)($row['id'] ?? 0);
                if (!empty($row['order_id'])) {
                    $description .= ' for order #' . (int)$row['order_id'];
                }
                admin_log_customer_and_admin(
                    $db,
                    (int)($row['customer_id'] ?? 0),
                    $adminUserId,
                    'payment_deleted',
                    $description . '.',
                    $ipAddress
                );
            }
        }
    }

    return [
        'ok' => true,
        'deleted_total' => $deletedTotal,
        'message' => $deletedTotal > 0
            ? 'Cancelled payment requests deleted successfully.'
            : 'There are no cancelled payment requests to delete.',
    ];
}

/** Status guidance is presentation only; it never changes or confirms a payment. */
function admin_payment_status_guidance(string $paymentType, string $status, ?string $locale = null): array
{
    $pl = ($locale ?? admin_current_locale()) === 'pl';
    $crypto = $paymentType === 'crypto';
    $items = [
        'pending' => ['warning', 'bi-clock-history', 'Oczekuje na wpłatę', 'Awaiting payment', 'Wybierz, gdy czekasz na przelew klienta i wpłata nie została jeszcze potwierdzona. Ten status nie oznacza otrzymania środków.', 'Use while waiting for the customer transfer, before payment is verified. This status does not mean funds have been received.'],
        'awaiting_review' => ['info', 'bi-search', 'Wymaga weryfikacji', 'Needs review', 'Wpłata wymaga sprawdzenia. Zweryfikuj kwotę, odbiorcę i datę przed akceptacją. Wybierz, gdy płatność wymaga ręcznej oceny.', 'Check the amount, recipient and date before accepting. Use when the payment needs manual review.'],
        'awaiting_confirmation' => ['info', 'bi-hourglass-split', 'Oczekuje na potwierdzenie', 'Awaiting confirmation', 'Wybierz, gdy zgłoszona wpłata czeka jeszcze na potwierdzenie. Przed akceptacją upewnij się, że środki dotarły; przy krypto sprawdź też potwierdzenia sieci.', 'Use when a reported transfer still needs confirmation. Verify receipt before accepting; for crypto also check network confirmations.'],
        'expired' => ['danger', 'bi-exclamation-circle-fill', 'Termin płatności minął', 'Payment deadline passed', 'Termin prośby o wpłatę upłynął. Sprawdź także spóźnione przelewy, zanim poprosisz klienta o ponowną płatność. Wybierz, gdy termin minął i wpłata nie jest potwierdzona.', 'The request deadline has passed. Check for late transfers before asking the customer to pay again. Use when the deadline has passed without verified payment.'],
        'approved' => ['success', 'bi-check-circle-fill', 'Płatność zatwierdzona', 'Payment approved', $crypto ? 'Wybierz dopiero po otrzymaniu wpłaty. Środki są na portfelu, na który wpłacił klient. Jeśli płatność dotyczy zamówienia, najpierw dokończ jego realizację w Zamówieniach. Następnie wypłać środki na swój główny portfel i przenieś płatność do archiwum.' : 'Wybierz dopiero po sprawdzeniu, że wpłata klienta dotarła i ma prawidłową kwotę. Realizację lub przedłużenie zamówienia dokończ w Zamówieniach.', $crypto ? 'Use only after receiving the payment. The funds are in the wallet used by the customer. For an order payment, first complete fulfilment in Orders. Then transfer funds to your main wallet and archive the payment.' : 'Use only after verifying receipt and the correct amount. Complete order fulfilment or renewal in Orders.'],
        'archived' => ['neutral', 'bi-archive', 'Płatność w archiwum', 'Payment archived', $crypto ? 'Wybierz po rozliczeniu płatności i wypłacie środków na swój główny portfel. Archiwizacja zachowuje historię, ale sama nie wykonuje przelewu.' : 'Wybierz po zakończeniu obsługi i rozliczeniu płatności. Archiwizacja zachowuje historię; nie wykonuje przelewu ani zwrotu.', $crypto ? 'Use after reconciliation and withdrawal to your main wallet. Archiving preserves history but does not transfer funds.' : 'Use after processing and reconciling the payment. Archiving preserves history and does not transfer or refund funds.'],
        'cancelled' => ['danger', 'bi-x-circle-fill', 'Płatność anulowana', 'Payment cancelled', 'Wybierz, gdy prośba o wpłatę nie będzie dalej realizowana. Anulowanie nie zwraca środków. Jeśli klient zdążył zapłacić, zweryfikuj wpłatę przed wystawieniem kolejnej prośby.', 'Use when the payment request will not proceed. Cancellation does not refund funds. Check any transfer already sent before creating another request.'],
        'failed' => ['danger', 'bi-exclamation-triangle-fill', 'Płatność nieudana', 'Payment failed', 'Wybierz po potwierdzeniu, że próba płatności się nie powiodła. Sprawdź rzeczywisty stan wpłaty, zanim poprosisz klienta o ponowienie.', 'Use after confirming the payment attempt failed. Verify the actual transfer before requesting another payment.'],
        'rejected' => ['danger', 'bi-x-circle-fill', 'Płatność odrzucona', 'Payment rejected', 'Wybierz po weryfikacji, gdy wpłata nie może zostać zaakceptowana. Odrzucenie samo nie wykonuje zwrotu środków.', 'Use after review when the payment cannot be accepted. Rejection does not itself refund funds.'],
    ];
    $items['pending_payment'] = $items['pending'];
    foreach (['confirmed', 'paid', 'completed'] as $alias) {
        $items[$alias] = $items['approved'];
    }
    if ($paymentType === 'crypto_topup') {
        $items['pending'] = ['warning', 'bi-clock-history', 'Doładowanie oczekuje na obsługę', 'Top-up awaiting processing', 'To starszy zapis doładowania krypto, który nie został zarchiwizowany. Zweryfikuj wpłatę i rozliczenie przed zmianą statusu.', 'This legacy crypto top-up has not been archived. Verify receipt and reconciliation before changing its status.'];
        $items['archived'] = ['neutral', 'bi-archive', 'Doładowanie w archiwum', 'Top-up archived', 'Wybierz po sprawdzeniu i zakończeniu obsługi doładowania. Zmiana tego statusu porządkuje zapis; sama nie potwierdza transakcji ani nie wykonuje wypłaty.', 'Use after verifying and processing the top-up. This status organises the record; it does not verify a transaction or withdraw funds.'];
    }
    $item = $items[strtolower(trim($status))] ?? ['neutral', 'bi-info-circle-fill', 'Status niestandardowy', 'Custom status', 'To status ze starszego lub niestandardowego zapisu. Sprawdź historię płatności przed zmianą. Sam wybór opcji nie zapisuje zmian.', 'This is a legacy or custom status. Review payment history before changing it. Selecting an option does not save changes.'];
    return ['tone' => $item[0], 'icon' => $item[1], 'title' => $item[$pl ? 2 : 3], 'text' => $item[$pl ? 4 : 5]];
}

function admin_payment_status_options(string $paymentType, string $current = ''): array
{
    $paymentType = strtolower(trim($paymentType));
    $current = strtolower(trim($current));

    if ($paymentType === 'crypto') {
        $options = ['pending', 'awaiting_review', 'expired', 'approved', 'archived', 'cancelled'];
    } elseif ($paymentType === 'crypto_topup') {
        $options = ['pending', 'archived'];
    } else {
        $options = ['pending_payment', 'awaiting_review', 'expired', 'approved', 'archived', 'cancelled'];
    }

    if ($current !== '' && !in_array($current, $options, true)) {
        $options[] = $current;
    }

    return $options;
}

function admin_payment_find(Mysql_ks $db, string $paymentType, int $paymentId): ?array
{
    $paymentType = strtolower(trim($paymentType));
    if ($paymentId <= 0) {
        return null;
    }

    app_ensure_payment_request_runtime_columns($db);

    if ($paymentType === 'crypto' && schema_object_exists($db, 'crypto_deposit_requests')) {
        $row = $db->select_user(
            "SELECT
                'crypto' AS payment_type,
                crypto_deposit_requests.id,
                crypto_deposit_requests.order_id,
                crypto_deposit_requests.customer_id,
                crypto_deposit_requests.crypto_asset_id,
                crypto_deposit_requests.fiat_currency_id,
                crypto_deposit_requests.status,
                crypto_deposit_requests.wallet_assignment_id,
                crypto_deposit_requests.requested_fiat_amount AS amount_value,
                crypto_deposit_requests.requested_crypto_amount AS amount_crypto,
                crypto_deposit_requests.requested_fiat_amount AS requested_amount_value,
                crypto_deposit_requests.requested_crypto_amount AS requested_amount_crypto,
                crypto_deposit_requests.received_fiat_amount,
                crypto_deposit_requests.received_crypto_amount,
                crypto_deposit_requests.exchange_rate,
                COALESCE(crypto_deposit_requests.requested_at, crypto_deposit_requests.expires_at) AS requested_at,
                crypto_deposit_requests.expires_at,
                crypto_deposit_requests.cancelled_at,
                crypto_deposit_requests.request_note,
                crypto_deposit_requests.created_by_admin_user_id,
                customers.email AS customer_email,
                NULLIF(TRIM(customers.public_handle), '') AS public_handle,
                currencies.code AS currency_code,
                currencies.symbol AS currency_symbol,
                crypto_assets.code AS asset_code,
                crypto_assets.name AS asset_name,
                crypto_assets.logo_url AS asset_logo_url,
                COALESCE(direct_wallet.id, assigned_wallet.id) AS wallet_address_id,
                COALESCE(direct_wallet.address, assigned_wallet.address) AS wallet_address,
                COALESCE(direct_wallet.label, assigned_wallet.label) AS wallet_label,
                COALESCE(direct_wallet.network_code, assigned_wallet.network_code) AS network_code,
                COALESCE(direct_wallet.memo_tag, assigned_wallet.memo_tag) AS payment_reference,
                orders.status AS order_status,
                (orders.id IS NOT NULL AND (".admin_topbar_order_task_where_sql().")) AS order_needs_action,
                EXISTS(SELECT 1 FROM crypto_deposit_transactions tx WHERE tx.deposit_request_id=crypto_deposit_requests.id AND tx.status='auto_accepted') AS auto_accepted
             FROM crypto_deposit_requests
             LEFT JOIN customers ON customers.id = crypto_deposit_requests.customer_id
             LEFT JOIN currencies ON currencies.id = crypto_deposit_requests.fiat_currency_id
             LEFT JOIN crypto_assets ON crypto_assets.id = crypto_deposit_requests.crypto_asset_id
             LEFT JOIN crypto_wallet_assignments AS payment_assignment
               ON payment_assignment.id = crypto_deposit_requests.wallet_assignment_id
             LEFT JOIN crypto_wallet_addresses AS direct_wallet
               ON direct_wallet.id = crypto_deposit_requests.wallet_address_id
             LEFT JOIN crypto_wallet_addresses AS assigned_wallet
               ON assigned_wallet.id = payment_assignment.wallet_address_id
             LEFT JOIN orders ON orders.id = crypto_deposit_requests.order_id
             WHERE crypto_deposit_requests.id = {$paymentId}
             LIMIT 1"
        );

        return is_array($row) ? $row : null;
    }

    if ($paymentType === 'crypto_topup' && schema_object_exists($db, 'crypto_topups')) {
        $legacyTopupsTable = schema_read_target($db, 'crypto_topups');
        $legacyTopupProductPriceColumn = schema_read_column($db, 'crypto_topups', 'product_price', 'package_price');
        $legacyTopupCreatedAtColumn = schema_read_column($db, 'crypto_topups', 'created_at', 'date');
        $legacyTopupStatusColumn = schema_read_column($db, 'crypto_topups', 'is_active', 'status');
        $row = $db->select_user(
            "SELECT
                'crypto_topup' AS payment_type,
                {$legacyTopupsTable}.id,
                NULL AS order_id,
                {$legacyTopupsTable}.user_id AS customer_id,
                CASE WHEN {$legacyTopupsTable}.{$legacyTopupStatusColumn} = 0 THEN 'pending' ELSE 'archived' END AS status,
                {$legacyTopupsTable}.{$legacyTopupProductPriceColumn} AS amount_value,
                {$legacyTopupsTable}.crypto_amount AS amount_crypto,
                {$legacyTopupsTable}.{$legacyTopupCreatedAtColumn} AS requested_at,
                NULL AS expires_at,
                NULL AS request_note,
                NULL AS created_by_admin_user_id,
                customers.email AS customer_email,
                '' AS currency_code,
                '' AS currency_symbol,
                UPPER(COALESCE(cryptocurrency.symbol, '')) AS asset_code,
                cryptocurrency.name AS asset_name,
                cryptocurrency.logo_url AS asset_logo_url,
                cryptocurrency.adress_code AS wallet_address,
                NULL AS order_status
             FROM {$legacyTopupsTable}
             LEFT JOIN customers ON customers.id = {$legacyTopupsTable}.user_id
             LEFT JOIN cryptocurrency ON cryptocurrency.id = {$legacyTopupsTable}.crypto_id
             WHERE {$legacyTopupsTable}.id = {$paymentId}
             LIMIT 1"
        );

        return is_array($row) ? $row : null;
    }

    if ($paymentType === 'bank' && schema_object_exists($db, 'bank_transfer_requests')) {
        app_ensure_payment_request_runtime_columns($db);
        $row = $db->select_user(
            "SELECT
                'bank' AS payment_type,
                bank_transfer_requests.id,
                bank_transfer_requests.order_id,
                bank_transfer_requests.customer_id,
                bank_transfer_requests.bank_account_id,
                bank_transfer_requests.bank_account_assignment_id,
                bank_transfer_requests.currency_id,
                bank_transfer_requests.status,
                bank_transfer_requests.requested_amount AS amount_value,
                COALESCE(bank_transfer_requests.requested_at, bank_transfer_requests.expires_at) AS requested_at,
                bank_transfer_requests.expires_at,
                bank_transfer_requests.submitted_at,
                bank_transfer_requests.approved_at,
                bank_transfer_requests.rejected_at,
                bank_transfer_requests.cancelled_at,
                bank_transfer_requests.payment_reference,
                bank_transfer_requests.payer_name,
                bank_transfer_requests.payer_bank_name,
                bank_transfer_requests.customer_transfer_note,
                bank_transfer_requests.admin_review_note,
                bank_transfer_requests.created_by_admin_user_id,
                bank_transfer_requests.approved_by_admin_user_id,
                customers.email AS customer_email,
                currencies.code AS currency_code,
                currencies.symbol AS currency_symbol,
                bank_accounts.label AS bank_label,
                bank_accounts.bank_name,
                bank_accounts.iban,
                orders.status AS order_status
             FROM bank_transfer_requests
             LEFT JOIN customers ON customers.id = bank_transfer_requests.customer_id
             LEFT JOIN currencies ON currencies.id = bank_transfer_requests.currency_id
             LEFT JOIN bank_accounts ON bank_accounts.id = bank_transfer_requests.bank_account_id
             LEFT JOIN orders ON orders.id = bank_transfer_requests.order_id
             WHERE bank_transfer_requests.id = {$paymentId}
             LIMIT 1"
        );

        return is_array($row) ? $row : null;
    }

    return null;
}

function admin_save_payment(Mysql_ks $db, string $paymentType, int $paymentId, array $input, int $adminUserId = 0, string $ipAddress = ''): array
{
    $payment = admin_payment_find($db, $paymentType, $paymentId);
    if (!$payment) return ['ok' => false, 'message' => 'Payment request not found.'];
    $key = 'payment:' . substr(hash('sha256', (string)getenv('DB_NAME')), 0, 16) . ':' . (int)$payment['customer_id'];
    $lock = $db->select_user("SELECT GET_LOCK('" . $db->escape($key) . "', 0) acquired");
    if ((int)($lock['acquired'] ?? 0) !== 1) return ['ok' => false, 'message' => 'Another payment operation is in progress. Please retry shortly.'];
    try {
        $result = admin_save_payment_locked($db, $paymentType, $paymentId, $input, $adminUserId, $ipAddress);
        if (!empty($result['ok'])
            && in_array(strtolower((string)$payment['status']), admin_payment_success_statuses($paymentType), true)
            && isset($input['status'])
            && !in_array(strtolower(trim((string)$input['status'])), admin_payment_success_statuses($paymentType), true)) {
            $fresh = admin_payment_find($db, $paymentType, $paymentId);
            if (is_array($fresh) && !admin_sync_order_after_payment_reversal($db, $payment, $fresh)) {
                return ['ok' => false, 'message' => 'Unable to update the linked order after changing payment approval. Refresh and retry.'];
            }
        }
        return $result;
    } finally {
        $db->select_user("SELECT RELEASE_LOCK('" . $db->escape($key) . "') released");
    }
}

/** Revoke only unfinished work tied to this payment; preserve fulfilled access and ledger entries. */
function admin_sync_order_after_payment_reversal(Mysql_ks $db, array $previous, array $current): bool
{
    $type = (string)($previous['payment_type'] ?? '');
    $orderId = (int)($previous['order_id'] ?? 0);
    $paymentId = (int)($previous['id'] ?? 0);
    if ($orderId <= 0 || $paymentId <= 0 || !in_array($type, ['crypto', 'bank'], true)
        || in_array(strtolower((string)($current['status'] ?? '')), admin_payment_success_statuses($type), true)) return true;
    app_panel_tiers_capture($db, $orderId);
    $safeType = $db->escape($type);
    $renewal = $db->select_user("SELECT id, status FROM order_renewals
        WHERE order_id = {$orderId} AND payment_request_type = '{$safeType}' AND payment_request_id = {$paymentId}
        ORDER BY id DESC LIMIT 1");
    if ($db->error) return false;
    if (is_array($renewal) && !empty($renewal['id'])) {
        if ($renewal['status'] !== 'paid_pending_activation') return true;
        return (bool)$db->update_using_id(['status', 'paid_at'], ['pending_payment', null], 'order_renewals', (int)$renewal['id']);
    }
    $credit = admin_find_order_payment_balance_credit_event($db, $orderId);
    if (is_array($credit) && (string)$credit['source_key'] !== $type . ':' . $paymentId) return true;
    // The original payment may be edited after an order has already been fulfilled.
    return $db->query("UPDATE orders SET payment_status = 'unpaid', paid_at = NULL
        WHERE id = {$orderId} AND customer_id = " . (int)($previous['customer_id'] ?? 0) . "
          AND status IN ('pending_payment','pending','awaiting_review','pending_activation')
          AND payment_status = 'paid' AND COALESCE(payment_method, '') <> 'balance'
          AND COALESCE(fulfillment_status, '') NOT IN ('delivered','fulfilled','completed','shipped','sent')") !== false;
}

function admin_save_payment_locked(
    Mysql_ks $db,
    string $paymentType,
    int $paymentId,
    array $input,
    int $adminUserId = 0,
    string $ipAddress = ''
): array
{
    $messages = admin_load_messages(admin_current_locale());
    $payment = admin_payment_find($db, $paymentType, $paymentId);
    if (!is_array($payment) || empty($payment['id'])) {
        return ['ok' => false, 'message' => 'Payment request not found.'];
    }

    app_ensure_payment_request_runtime_columns($db);

    $paymentType = strtolower((string)$payment['payment_type']);
    $status = strtolower(trim((string)($input['status'] ?? (string)($payment['status'] ?? ''))));
    $previousStatus = strtolower(trim((string)($payment['status'] ?? '')));
    if ($status === 'archived' && $previousStatus !== 'archived' && $paymentType === 'crypto') {
        if (!in_array($previousStatus, admin_payment_success_statuses($paymentType), true)) {
            return ['ok'=>false,'message'=>admin_t($messages,'payment_archive_requires_approval','Approve the received payment before archiving it.')];
        }
        if (!empty($payment['order_needs_action'])) {
            return ['ok'=>false,'message'=>admin_t($messages,'payment_archive_requires_fulfilment','Complete the linked order before withdrawing funds and archiving the payment.')];
        }
    }

    if (!in_array($status, admin_payment_status_options($paymentType, (string)($payment['status'] ?? '')), true)) {
        $status = (string)($payment['status'] ?? '');
    }

    $linkedOrderIdRaw = trim((string)($input['order_id'] ?? ($payment['order_id'] ?? '')));
    $linkedOrderId = 0;
    $currentOrderId = (int)($payment['order_id'] ?? 0);
    $autoClearedInvalidOrderLink = false;
    if ($linkedOrderIdRaw !== '') {
        if (!ctype_digit($linkedOrderIdRaw)) {
            return ['ok' => false, 'message' => 'Order number must be a valid ID.'];
        }
        $linkedOrderId = (int)$linkedOrderIdRaw;
        if ($linkedOrderId > 0) {
            $orderRow = $db->select_user(
                "SELECT id
                 FROM orders
                 WHERE id = {$linkedOrderId}
                   AND customer_id = " . (int)($payment['customer_id'] ?? 0) . "
                 LIMIT 1"
            );
            if (!is_array($orderRow) || empty($orderRow['id'])) {
                if ($linkedOrderId === $currentOrderId) {
                    $linkedOrderId = 0;
                    $autoClearedInvalidOrderLink = true;
                } else {
                    return ['ok' => false, 'message' => 'Selected order does not belong to this customer.'];
                }
            }
        }
    }
    $linkedOrderIdValue = $linkedOrderId > 0 ? $linkedOrderId : null;

    if ($paymentType === 'crypto') {
        $requestedAt = admin_normalize_datetime_input($input['requested_at'] ?? null) ?? (string)($payment['requested_at'] ?? date('Y-m-d H:i:s'));
        $expiresAt = admin_normalize_datetime_input($input['expires_at'] ?? null);
        $cancelledAt = in_array($status, admin_payment_cancelled_statuses($paymentType), true)
            ? (admin_normalize_datetime_input($input['cancelled_at'] ?? null) ?? (trim((string)($payment['cancelled_at'] ?? '')) !== '' ? (string)$payment['cancelled_at'] : date('Y-m-d H:i:s')))
            : null;
        $requestNote = trim((string)($input['request_note'] ?? ''));
        $walletAddress = trim((string)($input['wallet_address'] ?? ($payment['wallet_address'] ?? '')));
        $paymentReference = trim((string)($input['payment_reference'] ?? ($payment['payment_reference'] ?? '')));
        $amountValueRaw = str_replace(',', '.', trim((string)($input['amount_value'] ?? ($payment['amount_value'] ?? ''))));
        $amountCryptoRaw = str_replace(',', '.', trim((string)($input['amount_crypto'] ?? ($payment['amount_crypto'] ?? ''))));
        $receivedCryptoProvided = array_key_exists('received_crypto_amount', $input);
        $receivedFiatProvided = array_key_exists('received_fiat_amount', $input);
        $receivedCryptoRaw = $receivedCryptoProvided
            ? str_replace(',', '.', trim((string)($input['received_crypto_amount'] ?? '')))
            : trim((string)($payment['received_crypto_amount'] ?? ''));
        $receivedFiatRaw = $receivedFiatProvided
            ? str_replace(',', '.', trim((string)($input['received_fiat_amount'] ?? '')))
            : trim((string)($payment['received_fiat_actual_amount'] ?? $payment['received_fiat_amount'] ?? ''));
        if ($amountValueRaw === '' || !is_numeric($amountValueRaw) || (float)$amountValueRaw <= 0) {
            return ['ok' => false, 'message' => 'Amount must be a valid number.'];
        }
        if ($amountCryptoRaw === '' || !is_numeric($amountCryptoRaw) || (float)$amountCryptoRaw < 0) {
            return ['ok' => false, 'message' => 'Crypto amount must be a valid number.'];
        }
        if ($receivedCryptoRaw !== '' && (!is_numeric($receivedCryptoRaw) || (float)$receivedCryptoRaw <= 0)) {
            return ['ok' => false, 'message' => 'Received crypto amount must be a valid number.'];
        }
        if ($receivedFiatRaw !== '' && (!is_numeric($receivedFiatRaw) || (float)$receivedFiatRaw <= 0)) {
            return ['ok' => false, 'message' => 'Received fiat amount must be a valid number.'];
        }
        if ($walletAddress === '') {
            return ['ok' => false, 'message' => 'Wallet address is required.'];
        }

        $amountValue = round((float)$amountValueRaw, 2);
        $amountCrypto = round((float)$amountCryptoRaw, 8);
        $receivedCrypto = $receivedCryptoRaw !== '' ? round((float)$receivedCryptoRaw, 8) : null;
        $receivedFiatActual = $receivedFiatRaw !== '' ? round((float)$receivedFiatRaw, 2) : null;
        $receivedFiat = $receivedFiatRaw !== '' ? admin_round_customer_crypto_fiat_credit($receivedFiatRaw) : null;
        if (in_array($status, admin_payment_success_statuses($paymentType), true)) {
            if ($receivedCrypto === null) {
                $receivedCrypto = $amountCrypto;
            }
            if ($receivedFiat === null) {
                $receivedFiat = $amountValue;
            }
        }
        $walletAddressId = admin_crypto_payment_wallet_address_id($db, $payment);
        if ($walletAddressId <= 0) {
            return ['ok' => false, 'message' => 'Wallet address record is unavailable for this payment.'];
        }

        admin_ensure_crypto_wallet_address_indexes($db);

        $paymentWalletNetworkCode = admin_normalize_crypto_wallet_network(
            (string)($payment['asset_code'] ?? $payment['crypto_asset_code'] ?? ''),
            (string)($payment['network_code'] ?? ''),
            $walletAddress
        );
        $duplicateContext = admin_crypto_wallet_address_duplicate_context(
            $db,
            $walletAddress,
            (int)($payment['crypto_asset_id'] ?? 0),
            $paymentWalletNetworkCode,
            $walletAddressId
        );
        if (!empty($duplicateContext['has_existing']) && empty($duplicateContext['can_reuse'])) {
            return [
                'ok' => false,
                'message' => admin_t($messages, (string)($duplicateContext['message_key'] ?? ''), (string)($duplicateContext['message'] ?? 'This wallet address already exists in the database.')),
            ];
        }

        $walletUpdateFields = ['address', 'memo_tag'];
        $walletUpdateValues = [$walletAddress, $paymentReference !== '' ? $paymentReference : null];
        if (!empty($duplicateContext['has_existing']) && !empty($duplicateContext['can_reuse'])) {
            $canonicalWallet = is_array($duplicateContext['canonical'] ?? null) ? $duplicateContext['canonical'] : [];
            foreach (['owner_full_name', 'wallet_provider', 'notes'] as $walletSyncField) {
                $walletSyncValue = trim((string)($canonicalWallet[$walletSyncField] ?? ''));
                if ($walletSyncValue !== '') {
                    $walletUpdateFields[] = $walletSyncField;
                    $walletUpdateValues[] = $walletSyncValue;
                }
            }
        }

        $db->update_using_id(
            $walletUpdateFields,
            $walletUpdateValues,
            'crypto_wallet_addresses',
            $walletAddressId
        );

        if (in_array($status, app_payment_open_crypto_statuses(), true)) {
            $settings = admin_app_settings($db);
            if (!app_crypto_deposit_wallet_payload_is_valid(
                $db,
                (int)($payment['customer_id'] ?? 0),
                (int)($payment['crypto_asset_id'] ?? 0),
                $walletAddressId,
                (int)($payment['wallet_assignment_id'] ?? 0),
                $settings
            )) {
                return ['ok' => false, 'message' => 'Wallet assignment is no longer valid for this customer. Renew the crypto request to assign a free wallet.'];
            }
        }

        $cryptoUpdateFields = ['status', 'order_id', 'wallet_address_id', 'requested_at', 'expires_at', 'cancelled_at', 'requested_fiat_amount', 'requested_crypto_amount', 'request_note'];
        $cryptoUpdateValues = [$status, $linkedOrderIdValue, $walletAddressId, $requestedAt, $expiresAt, $cancelledAt, $amountValue, $amountCrypto, $requestNote !== '' ? $requestNote : null];
        if (schema_column_exists($db, 'crypto_deposit_requests', 'received_crypto_amount')) {
            $cryptoUpdateFields[] = 'received_crypto_amount';
            $cryptoUpdateValues[] = $receivedCrypto;
        }
        if (schema_column_exists($db, 'crypto_deposit_requests', 'received_fiat_amount')) {
            $cryptoUpdateFields[] = 'received_fiat_amount';
            $cryptoUpdateValues[] = $receivedFiat;
        }
        if (schema_column_exists($db, 'crypto_deposit_requests', 'received_fiat_actual_amount')) {
            $cryptoUpdateFields[] = 'received_fiat_actual_amount';
            $cryptoUpdateValues[] = $receivedFiatActual;
        }

        $updated = $db->update_using_id(
            $cryptoUpdateFields,
            $cryptoUpdateValues,
            'crypto_deposit_requests',
            $paymentId
        );

        if ($updated) {
            $description = 'Crypto payment request #' . $paymentId . ' updated';
            if ((string)($payment['status'] ?? '') !== $status) {
                $description .= ': status ' . (string)($payment['status'] ?? 'unknown') . ' -> ' . $status;
            }
            if ($linkedOrderId > 0) {
                $description .= ' for order #' . $linkedOrderId;
            } elseif ($autoClearedInvalidOrderLink) {
                $description .= ' and invalid order link #' . $currentOrderId . ' was cleared automatically';
            }

            admin_log_customer_and_admin(
                $db,
                (int)($payment['customer_id'] ?? 0),
                $adminUserId,
                'payment_updated',
                $description . '.',
                $ipAddress
            );
        }

        $successStatuses = admin_payment_success_statuses($paymentType);
        if ($updated && in_array($status, $successStatuses, true)) {
            $finalizeResult = admin_finalize_successful_payment($db, $paymentType, $paymentId, $adminUserId, $ipAddress);
            if (empty($finalizeResult['ok'])) {
                return $finalizeResult;
            }

            if (empty($finalizeResult['underpaid_order']) && empty($finalizeResult['already_applied'])) {
                if ($linkedOrderId > 0) {
                    admin_notify_order_payment_approved_live_chat($db, (int)($payment['customer_id'] ?? 0));
                } else {
                    admin_notify_topup_payment_approved_live_chat($db, (int)($payment['customer_id'] ?? 0));
                }
            }

            return [
                'ok' => true,
                'message' => 'Payment request saved successfully.',
                'already_applied' => !empty($finalizeResult['already_applied']),
                'order_id' => !empty($finalizeResult['underpaid_order']) ? 0 : (int)($finalizeResult['order_id'] ?? 0),
                'linked_order_id' => (int)($finalizeResult['order_id'] ?? 0),
                'customer_id' => (int)($finalizeResult['customer_id'] ?? 0),
                'underpaid_order' => !empty($finalizeResult['underpaid_order']),
                'credited_fiat_amount' => isset($finalizeResult['credited_fiat_amount']) ? (float)$finalizeResult['credited_fiat_amount'] : null,
                'expected_fiat_amount' => isset($finalizeResult['expected_fiat_amount']) ? (float)$finalizeResult['expected_fiat_amount'] : null,
                'shortfall_fiat_amount' => isset($finalizeResult['shortfall_fiat_amount']) ? (float)$finalizeResult['shortfall_fiat_amount'] : null,
            ];
        }

        if (
            $updated
            && admin_crypto_wallet_shared_assignments_enabled(admin_app_settings($db))
            && in_array($status, admin_payment_cancelled_statuses($paymentType), true)
            && !empty($payment['wallet_assignment_id'])
        ) {
            app_release_crypto_wallet_assignment_if_unused(
                $db,
                (int)$payment['wallet_assignment_id'],
                'Released after crypto payment request status changed to ' . $status
            );
        }

        if ($updated && in_array($status, admin_payment_cancelled_statuses($paymentType), true) && !empty($payment['order_id'])) {
            app_order_cancel_pending_renewal(
                $db,
                (int)$payment['order_id'],
                'Cancelled from admin payment editor',
                'crypto',
                $paymentId
            );
        }

        return [
            'ok' => (bool)$updated,
            'message' => $updated ? 'Payment request saved successfully.' : 'Unable to save payment request.',
        ];
    }

    if ($paymentType === 'crypto_topup') {
        $requestedAt = admin_normalize_datetime_input($input['requested_at'] ?? null) ?? (string)($payment['requested_at'] ?? date('Y-m-d H:i:s'));
        $amountValueRaw = str_replace(',', '.', trim((string)($input['amount_value'] ?? ($payment['amount_value'] ?? ''))));
        $amountCryptoRaw = str_replace(',', '.', trim((string)($input['amount_crypto'] ?? ($payment['amount_crypto'] ?? ''))));
        if ($amountValueRaw === '' || !is_numeric($amountValueRaw) || (float)$amountValueRaw <= 0) {
            return ['ok' => false, 'message' => 'Amount must be a valid number.'];
        }
        if ($amountCryptoRaw === '' || !is_numeric($amountCryptoRaw) || (float)$amountCryptoRaw < 0) {
            return ['ok' => false, 'message' => 'Crypto amount must be a valid number.'];
        }

        $amountValue = round((float)$amountValueRaw, 2);
        $amountCrypto = round((float)$amountCryptoRaw, 8);
        $writeTable = schema_write_target('crypto_topups');
        $legacyTopupProductPriceColumn = schema_read_column($db, 'crypto_topups', 'product_price', 'package_price');
        $legacyTopupCreatedAtColumn = schema_read_column($db, 'crypto_topups', 'created_at', 'date');
        $legacyTopupStatusColumn = schema_read_column($db, 'crypto_topups', 'is_active', 'status');
        $updated = $db->update_using_id(
            [$legacyTopupStatusColumn, $legacyTopupCreatedAtColumn, $legacyTopupProductPriceColumn, 'crypto_amount'],
            [$status === 'archived' ? 1 : 0, $requestedAt, $amountValue, $amountCrypto],
            $writeTable,
            $paymentId
        );

        if ($updated) {
            admin_log_customer_and_admin(
                $db,
                (int)($payment['customer_id'] ?? 0),
                $adminUserId,
                'payment_updated',
                'Legacy crypto payment request #' . $paymentId . ' updated: status ' . (string)($payment['status'] ?? 'unknown') . ' -> ' . $status . '.',
                $ipAddress
            );
        }

        $successStatuses = admin_payment_success_statuses($paymentType);
        if (
            $updated
            && in_array($status, $successStatuses, true)
            && !in_array($previousStatus, $successStatuses, true)
        ) {
            admin_notify_topup_payment_approved_live_chat($db, (int)($payment['customer_id'] ?? 0));
        }

        return [
            'ok' => (bool)$updated,
            'message' => $updated ? 'Payment request saved successfully.' : 'Unable to save payment request.',
        ];
    }

    $requestedAt = admin_normalize_datetime_input($input['requested_at'] ?? null) ?? (string)($payment['requested_at'] ?? date('Y-m-d H:i:s'));
    $expiresAt = admin_normalize_datetime_input($input['expires_at'] ?? null);
    $submittedAt = admin_normalize_datetime_input($input['submitted_at'] ?? null);
    $approvedAt = admin_normalize_datetime_input($input['approved_at'] ?? null);
    $rejectedAt = admin_normalize_datetime_input($input['rejected_at'] ?? null);
    app_ensure_payment_request_runtime_columns($db);
    $cancelledAt = in_array($status, admin_payment_cancelled_statuses($paymentType), true)
        ? (admin_normalize_datetime_input($input['cancelled_at'] ?? null) ?? (trim((string)($payment['cancelled_at'] ?? '')) !== '' ? (string)$payment['cancelled_at'] : date('Y-m-d H:i:s')))
        : null;
    $paymentReference = trim((string)($input['payment_reference'] ?? ''));
    $amountValueRaw = str_replace(',', '.', trim((string)($input['amount_value'] ?? ($payment['amount_value'] ?? ''))));
    $payerName = trim((string)($input['payer_name'] ?? ''));
    $payerBankName = trim((string)($input['payer_bank_name'] ?? ''));
    $customerTransferNote = trim((string)($input['customer_transfer_note'] ?? ''));
    $adminReviewNote = trim((string)($input['admin_review_note'] ?? ''));
    if ($amountValueRaw === '' || !is_numeric($amountValueRaw) || (float)$amountValueRaw <= 0) {
        return ['ok' => false, 'message' => 'Amount must be a valid number.'];
    }
    $amountValue = round((float)$amountValueRaw, 2);

    $updated = $db->update_using_id(
        ['status', 'order_id', 'requested_amount', 'requested_at', 'expires_at', 'submitted_at', 'approved_at', 'rejected_at', 'cancelled_at', 'payment_reference', 'payer_name', 'payer_bank_name', 'customer_transfer_note', 'admin_review_note'],
        [
            $status,
            $linkedOrderIdValue,
            $amountValue,
            $requestedAt,
            $expiresAt,
            $submittedAt,
            $approvedAt,
            $rejectedAt,
            $cancelledAt,
            $paymentReference !== '' ? $paymentReference : null,
            $payerName !== '' ? $payerName : null,
            $payerBankName !== '' ? $payerBankName : null,
            $customerTransferNote !== '' ? $customerTransferNote : null,
            $adminReviewNote !== '' ? $adminReviewNote : null,
        ],
        'bank_transfer_requests',
        $paymentId
    );

    if ($updated) {
        $description = 'Bank payment request #' . $paymentId . ' updated';
        if ((string)($payment['status'] ?? '') !== $status) {
            $description .= ': status ' . (string)($payment['status'] ?? 'unknown') . ' -> ' . $status;
        }
        if ($linkedOrderId > 0) {
            $description .= ' for order #' . $linkedOrderId;
        }

        admin_log_customer_and_admin(
            $db,
            (int)($payment['customer_id'] ?? 0),
            $adminUserId,
            'payment_updated',
            $description . '.',
            $ipAddress
        );
    }

    if ($updated && in_array($status, admin_payment_cancelled_statuses($paymentType), true) && !empty($payment['order_id'])) {
        app_order_cancel_pending_renewal(
            $db,
            (int)$payment['order_id'],
            'Cancelled from admin payment editor',
            'bank',
            $paymentId
        );
    }

    $successStatuses = admin_payment_success_statuses($paymentType);
    if ($updated && in_array($status, $successStatuses, true)) {
        $finalizeResult = admin_finalize_successful_payment($db, $paymentType, $paymentId, $adminUserId, $ipAddress);
        if (empty($finalizeResult['ok'])) {
            return $finalizeResult;
        }

        if (empty($finalizeResult['underpaid_order']) && empty($finalizeResult['already_applied'])) {
            if ($linkedOrderId > 0) {
                admin_notify_order_payment_approved_live_chat($db, (int)($payment['customer_id'] ?? 0));
            } else {
                admin_notify_topup_payment_approved_live_chat($db, (int)($payment['customer_id'] ?? 0));
            }
        }

        return [
            'ok' => true,
            'message' => 'Payment request saved successfully.',
            'already_applied' => !empty($finalizeResult['already_applied']),
            'order_id' => !empty($finalizeResult['underpaid_order']) ? 0 : (int)($finalizeResult['order_id'] ?? 0),
            'linked_order_id' => (int)($finalizeResult['order_id'] ?? 0),
            'customer_id' => (int)($finalizeResult['customer_id'] ?? 0),
            'underpaid_order' => !empty($finalizeResult['underpaid_order']),
            'credited_fiat_amount' => isset($finalizeResult['credited_fiat_amount']) ? (float)$finalizeResult['credited_fiat_amount'] : null,
            'expected_fiat_amount' => isset($finalizeResult['expected_fiat_amount']) ? (float)$finalizeResult['expected_fiat_amount'] : null,
            'shortfall_fiat_amount' => isset($finalizeResult['shortfall_fiat_amount']) ? (float)$finalizeResult['shortfall_fiat_amount'] : null,
        ];
    }

    return [
        'ok' => (bool)$updated,
        'message' => $updated ? 'Payment request saved successfully.' : 'Unable to save payment request.',
    ];
}

function admin_topup_payment_approved_live_chat_message(string $localeCode): string
{
    $localeCode = app_normalize_email_locale($localeCode);

    if ($localeCode === 'pl') {
        return 'Dziękujemy za płatność. Kwota została dodana do salda konta. Aby dokonać zakupu, przejdź do zakładki ZAMÓWIENIA i wybierz Subskrypcje.';
    }

    return 'Thank you for your payment. The amount has been added to your account balance. To make a purchase, go to the ORDERS tab and choose Subscriptions.';
}

function admin_notify_topup_payment_approved_live_chat(Mysql_ks $db, int $customerId): array
{
    if ($customerId <= 0) {
        return ['ok' => false, 'message' => 'Customer not found.'];
    }

    $customer = app_find_customer_by_id($db, $customerId);
    if (!is_array($customer) || empty($customer['id'])) {
        return ['ok' => false, 'message' => 'Customer not found.'];
    }

    $messageBody = admin_topup_payment_approved_live_chat_message((string)($customer['locale_code'] ?? 'en'));
    if (trim($messageBody) === '') {
        return ['ok' => false, 'message' => 'Live chat message is empty.'];
    }

    $inserted = app_insert_live_chat_admin_message($db, $customerId, $messageBody);

    return [
        'ok' => $inserted,
        'message' => $inserted ? 'Top-up approval live chat message created.' : 'Unable to create top-up approval live chat message.',
    ];
}

