function admin_finalize_successful_payment(
    Mysql_ks $db,
    string $paymentType,
    int $paymentId,
    int $adminUserId = 0,
    string $ipAddress = ''
): array
{
    $payment = admin_payment_find($db, $paymentType, $paymentId);
    if (!is_array($payment) || empty($payment['id'])) {
        return ['ok' => false, 'message' => 'Payment request not found.'];
    }

    $paymentType = strtolower((string)($payment['payment_type'] ?? $paymentType));
    if (!in_array($paymentType, ['crypto', 'bank'], true)) {
        return ['ok' => true];
    }

    $status = strtolower(trim((string)($payment['status'] ?? '')));
    if (!in_array($status, admin_payment_success_statuses($paymentType), true)) {
        return ['ok' => true];
    }

    $customerId = (int)($payment['customer_id'] ?? 0);
    $orderId = (int)($payment['order_id'] ?? 0);
    $expectedFiatAmount = round((float)(
        isset($payment['requested_amount_value']) && $payment['requested_amount_value'] !== null && $payment['requested_amount_value'] !== ''
            ? $payment['requested_amount_value']
            : ($payment['amount_value'] ?? 0)
    ), 2);
    $creditAmountRaw = (
        isset($payment['received_fiat_amount']) && $payment['received_fiat_amount'] !== null && $payment['received_fiat_amount'] !== ''
            ? $payment['received_fiat_amount']
            : ($payment['amount_value'] ?? 0)
    );
    $amountValue = $paymentType === 'crypto'
        ? admin_round_customer_crypto_fiat_credit($creditAmountRaw)
        : round((float)$creditAmountRaw, 2);
    if ($customerId <= 0 || $amountValue <= 0) {
        return ['ok' => false, 'message' => 'This payment cannot be credited to customer balance.'];
    }

    $currentPaymentSourceKey = $paymentType . ':' . $paymentId;
    $pendingRenewalForPayment = $orderId > 0 ? app_order_find_pending_renewal($db, $orderId, $paymentType, $paymentId, true) : null;
    $balanceAlreadyAppliedForThisPayment = false;

    if ($orderId > 0 && !$pendingRenewalForPayment
        && schema_object_exists($db, 'customer_balance_runtime_events')) {
        // An applied renewal has its own credited payment. Archiving/re-saving it must
        // not treat it as a second payment for the original purchase or credit it again.
        $appliedRenewal = $db->select_user("SELECT r.id FROM order_renewals r
            INNER JOIN customer_balance_runtime_events e ON e.customer_id = r.customer_id
                AND e.source_type = 'payment_approval' AND e.direction = 'credit'
                AND e.source_key = '" . $db->escape($currentPaymentSourceKey) . "'
            WHERE r.order_id = {$orderId} AND r.customer_id = {$customerId}
                AND r.payment_request_type = '" . $db->escape($paymentType) . "'
                AND r.payment_request_id = {$paymentId} AND r.status = 'applied'
            LIMIT 1");
        if ($db->error) return ['ok' => false, 'message' => 'Unable to verify the settled renewal payment.'];
        if (!empty($appliedRenewal['id'])) {
            return ['ok' => true, 'already_applied' => true, 'order_id' => $orderId,
                'customer_id' => $customerId, 'underpaid_order' => false];
        }
    }

    if ($orderId > 0 && !$pendingRenewalForPayment) {
        $existingOrderCreditEvent = admin_find_order_payment_balance_credit_event($db, $orderId);
        if (is_array($existingOrderCreditEvent) && !empty($existingOrderCreditEvent['source_key'])) {
            $creditedSourceKey = (string)($existingOrderCreditEvent['source_key'] ?? '');
            if ($creditedSourceKey === $currentPaymentSourceKey) {
                $balanceAlreadyAppliedForThisPayment = true;
            } else {
                return [
                    'ok' => false,
                    'message' => 'This order was already credited to customer balance from another payment request.',
                ];
            }
        }
    } elseif (
        schema_object_exists($db, 'customer_balance_runtime_events')
    ) {
        $currentPaymentEvent = $db->select_user(
            "SELECT id
             FROM customer_balance_runtime_events
             WHERE source_type = 'payment_approval'
               AND source_key = '" . $db->escape($currentPaymentSourceKey) . "'
               AND direction = 'credit'
             LIMIT 1"
        );
        $balanceAlreadyAppliedForThisPayment = is_array($currentPaymentEvent) && !empty($currentPaymentEvent['id']);
    }

    $balanceCreditResult = [
        'ok' => true,
        'already_applied' => $balanceAlreadyAppliedForThisPayment,
    ];

    if (!$balanceAlreadyAppliedForThisPayment) {
        $balanceCreditResult = admin_apply_customer_balance_runtime_event(
            $db,
            $customerId,
            $amountValue,
            'credit',
            'payment_approval',
            $currentPaymentSourceKey,
            'Approved ' . ucfirst($paymentType) . ' payment #' . $paymentId,
            $adminUserId,
            $ipAddress
        );
        if (empty($balanceCreditResult['ok'])) {
            return $balanceCreditResult;
        }
    }

    if ($paymentType === 'crypto') {
        $assignmentEnsureResult = admin_ensure_crypto_wallet_assignment_for_payment(
            $db,
            $payment,
            $adminUserId,
            admin_app_settings($db),
            $ipAddress
        );
        if (empty($assignmentEnsureResult['ok'])) {
            return $assignmentEnsureResult;
        }
    } elseif ($paymentType === 'bank') {
        $assignmentEnsureResult = admin_ensure_bank_account_assignment_for_payment(
            $db,
            $payment,
            $adminUserId,
            admin_app_settings($db),
            $ipAddress
        );
        if (empty($assignmentEnsureResult['ok'])) {
            return $assignmentEnsureResult;
        }
    }

    if ($orderId > 0) {
        $underpaidShortfall = $expectedFiatAmount > 0
            ? round(max(0, $expectedFiatAmount - $amountValue), 2)
            : 0.0;
        $isUnderpaidOrder = $expectedFiatAmount > 0 && $underpaidShortfall >= 0.01;

        if ($isUnderpaidOrder) {
            return [
                'ok' => true,
                'already_applied' => !empty($balanceCreditResult['already_applied']),
                'order_id' => $orderId,
                'customer_id' => $customerId,
                'underpaid_order' => true,
                'credited_fiat_amount' => $amountValue,
                'expected_fiat_amount' => $expectedFiatAmount,
                'shortfall_fiat_amount' => $underpaidShortfall,
            ];
        }

        $pendingRenewal = $pendingRenewalForPayment;
        if (!$pendingRenewal) {
            $fallbackRenewal = app_order_find_pending_renewal($db, $orderId);
            if (is_array($fallbackRenewal) && !empty($fallbackRenewal['id'])) {
                $fallbackPaymentId = (int)($fallbackRenewal['payment_request_id'] ?? 0);
                $fallbackPaymentType = strtolower(trim((string)($fallbackRenewal['payment_request_type'] ?? '')));
                if ($fallbackPaymentId <= 0 || $fallbackPaymentType === '') {
                    $pendingRenewal = $fallbackRenewal;
                }
            }
        }
        if ($pendingRenewal) {
            $renewalId = (int)($pendingRenewal['id'] ?? 0);
            if ($renewalId <= 0) {
                return ['ok' => false, 'message' => 'Pending renewal record is invalid.'];
            }

            $approvalTimestamp = function_exists('app_current_datetime_string') ? app_current_datetime_string() : date('Y-m-d H:i:s');
            $renewalNote = trim((string)($pendingRenewal['renewal_note'] ?? ''));
            $approvalNote = 'Payment approved on ' . $approvalTimestamp . '. Waiting for manual extension in admin panel.';
            // Re-approval must not append the same notice until the VARCHAR(255) overflows.
            $approvedRenewalNote = strpos($renewalNote, 'Waiting for manual extension in admin panel.') !== false
                ? $renewalNote : ($renewalNote !== '' ? $renewalNote . "\n" . $approvalNote : $approvalNote);
            if (mb_strlen($approvedRenewalNote, 'UTF-8') > 255) $approvedRenewalNote = $renewalNote;
            $updatedRenewal = $db->update_using_id(
                ['renewal_note'],
                [$approvedRenewalNote],
                'order_renewals',
                $renewalId
            );
            if (!$updatedRenewal) {
                return ['ok' => false, 'message' => 'Unable to mark renewal as paid.'];
            }

            $renewalAmount = round((float)($pendingRenewal['price_amount'] ?? 0), 2);
            if ($renewalAmount > 0) {
                $reserveResult = admin_apply_customer_balance_runtime_event(
                    $db,
                    $customerId,
                    $renewalAmount,
                    'debit',
                    'order_extension',
                    'renewal:' . $renewalId,
                    'Reserved from approved ' . ucfirst($paymentType) . ' payment #' . $paymentId . ' for renewal #' . $renewalId . ' in order #' . $orderId,
                    $adminUserId,
                    $ipAddress
                );
                if (empty($reserveResult['ok'])) {
                    return $reserveResult;
                }
            }

            $orderPaymentUpdated = app_mark_order_renewal_paid($db, $orderId, $renewalId, $approvalTimestamp);
            if (!$orderPaymentUpdated) {
                return ['ok' => false, 'message' => 'Unable to record renewal payment.'];
            }
            app_panel_tiers_capture($db, $orderId);

            return [
                'ok' => true,
                'already_applied' => !empty($balanceCreditResult['already_applied']),
                'order_id' => $orderId,
                'customer_id' => $customerId,
                'underpaid_order' => false,
                'pending_renewal' => true,
                'pending_renewal_id' => $renewalId,
            ];

        }

        $order = admin_order_find($db, $orderId);
        if (!$order) {
            return ['ok' => false, 'message' => 'Linked order not found.'];
        }

        $orderSaveResult = admin_save_order_info(
            $db,
            $orderId,
            [
                'order_reference' => (string)($order['order_reference'] ?? ''),
                'payment_method' => (string)($order['payment_method'] ?? ''),
                'total_amount' => number_format((float)($order['total_amount'] ?? 0), 2, '.', ''),
                'customer_note' => (string)($order['customer_note'] ?? ''),
                'support_note' => (string)($order['support_note'] ?? ''),
                'delivery_link' => (string)($order['delivery_link'] ?? ''),
                'transaction_reference' => (string)($order['transaction_reference'] ?? ''),
                'started_at' => (string)($order['started_at'] ?? ''),
                'expires_at' => (string)($order['expires_at'] ?? ''),
                'paid_at' => trim((string)($order['paid_at'] ?? '')) !== '' ? (string)$order['paid_at'] : date('Y-m-d H:i:s'),
                'status' => in_array(strtolower(trim((string)($order['status'] ?? 'pending'))), ['active', 'expired', 'cancelled'], true)
                    ? (string)($order['status'] ?? 'pending')
                    : 'pending_payment',
                'payment_status' => 'paid',
                'fulfillment_status' => (string)($order['fulfillment_status'] ?? 'pending'),
                'delivery_link_visible' => !empty($order['delivery_link_visible']) ? '1' : '0',
            ],
            $adminUserId,
            $ipAddress
        );

        if (empty($orderSaveResult['ok'])) {
            return $orderSaveResult;
        }
    }

    return [
        'ok' => true,
        'already_applied' => !empty($balanceCreditResult['already_applied']),
        'order_id' => $orderId,
        'customer_id' => $customerId,
        'underpaid_order' => false,
    ];
}

function admin_delete_payment(
    Mysql_ks $db,
    string $paymentType,
    int $paymentId,
    int $adminUserId = 0,
    string $ipAddress = ''
): array
{
    $payment = admin_payment_find($db, $paymentType, $paymentId);
    if (!is_array($payment) || empty($payment['id'])) {
        return ['ok' => false, 'message' => 'Payment request not found.'];
    }

    $paymentType = strtolower((string)$payment['payment_type']);
    if ($paymentType === 'crypto') {
        $tableName = 'crypto_deposit_requests';
    } elseif ($paymentType === 'crypto_topup') {
        $tableName = schema_write_target('crypto_topups');
    } else {
        if (!in_array(strtolower(trim((string)($payment['status'] ?? ''))), admin_payment_cancelled_statuses($paymentType), true)) {
            return ['ok' => false, 'message' => 'Only cancelled payments can be deleted permanently.'];
        }
        $tableName = $paymentType === 'crypto' ? 'crypto_deposit_requests' : 'bank_transfer_requests';
    }

    if ($paymentType === 'crypto') {
        // Recheck eligibility in the DELETE itself, so a newly approved payment survives.
        $creditGuard = schema_object_exists($db, 'customer_balance_runtime_events')
            ? " AND NOT EXISTS (SELECT 1 FROM customer_balance_runtime_events e WHERE e.source_type='payment_approval' AND e.source_key='crypto:{$paymentId}' AND e.direction='credit')"
            : '';
        $result = $db->query("DELETE FROM crypto_deposit_requests WHERE id={$paymentId}
            AND (status IN ('cancelled','rejected','failed')
                 OR (COALESCE(received_crypto_amount,0)=0 AND (status='expired'
                     OR (status IN ('pending','pending_payment','awaiting_confirmation','awaiting_review') AND expires_at IS NOT NULL AND expires_at<=NOW())))){$creditGuard}");
        $deleted = $result && (int)$db->affected_rows > 0;
    } else {
        $deleted = $db->delete_using_id($tableName, $paymentId);
    }

    if ($deleted) {
        if (!empty($payment['order_id']) && in_array($paymentType, ['crypto', 'bank'], true)) {
            app_order_cancel_pending_renewal(
                $db,
                (int)$payment['order_id'],
                'Deleted from admin payments list',
                $paymentType,
                $paymentId
            );
        }
        if ($paymentType === 'crypto' && !empty($payment['wallet_assignment_id'])) {
            app_release_crypto_wallet_assignment_if_unused(
                $db,
                (int)$payment['wallet_assignment_id'],
                'Released after crypto payment request deletion by admin'
            );
        }

        $description = ucfirst(str_replace('_', ' ', $paymentType)) . ' payment request #' . $paymentId . ' deleted';
        if (!empty($payment['order_id'])) {
            $description .= ' for order #' . (int)$payment['order_id'];
        }

        admin_log_customer_and_admin(
            $db,
            (int)($payment['customer_id'] ?? 0),
            $adminUserId,
            'payment_deleted',
            $description . '.',
            $ipAddress
        );
    }

    return [
        'ok' => (bool)$deleted,
        'message' => $deleted ? 'Payment request deleted successfully.' : 'Unable to delete payment request.',
    ];
}

function admin_find_order_payment_balance_credit_event(Mysql_ks $db, int $orderId): ?array
{
    if (
        $orderId <= 0
        || !schema_object_exists($db, 'customer_balance_runtime_events')
    ) {
        return null;
    }

    $eventRows = [];

    if (schema_object_exists($db, 'crypto_deposit_requests')) {
        $cryptoEventRows = $db->select_full_user(
            "SELECT
                customer_balance_runtime_events.id AS event_id,
                customer_balance_runtime_events.source_type,
                customer_balance_runtime_events.source_key,
                'crypto' AS payment_type,
                crypto_deposit_requests.id AS payment_id
             FROM customer_balance_runtime_events
             INNER JOIN crypto_deposit_requests
                ON customer_balance_runtime_events.source_type = 'payment_approval'
               AND customer_balance_runtime_events.source_key = CONCAT('crypto:', crypto_deposit_requests.id)
             WHERE customer_balance_runtime_events.direction = 'credit'
               AND crypto_deposit_requests.order_id = {$orderId}"
        );
        if (is_array($cryptoEventRows) && $cryptoEventRows) {
            $eventRows = array_merge($eventRows, $cryptoEventRows);
        }
    }

    if (schema_object_exists($db, 'bank_transfer_requests')) {
        $bankEventRows = $db->select_full_user(
            "SELECT
                customer_balance_runtime_events.id AS event_id,
                customer_balance_runtime_events.source_type,
                customer_balance_runtime_events.source_key,
                'bank' AS payment_type,
                bank_transfer_requests.id AS payment_id
             FROM customer_balance_runtime_events
             INNER JOIN bank_transfer_requests
                ON customer_balance_runtime_events.source_type = 'payment_approval'
               AND customer_balance_runtime_events.source_key = CONCAT('bank:', bank_transfer_requests.id)
             WHERE customer_balance_runtime_events.direction = 'credit'
               AND bank_transfer_requests.order_id = {$orderId}"
        );
        if (is_array($bankEventRows) && $bankEventRows) {
            $eventRows = array_merge($eventRows, $bankEventRows);
        }
    }

    if (!$eventRows) {
        return null;
    }

    usort($eventRows, static function (array $left, array $right): int {
        return ((int)($left['event_id'] ?? 0)) <=> ((int)($right['event_id'] ?? 0));
    });

    return isset($eventRows[0]) && is_array($eventRows[0]) ? $eventRows[0] : null;
}

function admin_payment_accept_with_order(
    Mysql_ks $db,
    string $paymentType,
    int $paymentId,
    int $adminUserId = 0,
    string $ipAddress = '',
    array $input = []
): array
{
    $payment = admin_payment_find($db, $paymentType, $paymentId);
    if (!is_array($payment) || empty($payment['id'])) {
        return ['ok' => false, 'message' => 'Payment request not found.'];
    }

    $paymentType = strtolower((string)($payment['payment_type'] ?? $paymentType));
    if (!in_array($paymentType, ['crypto', 'crypto_topup', 'bank'], true)) {
        return ['ok' => false, 'message' => 'This payment cannot be accepted from topbar.'];
    }

    $paymentUpdateInput = [];
    if ($paymentType === 'crypto_topup') {
        $paymentUpdateInput = [
            'status' => 'archived',
            'requested_at' => (string)($payment['requested_at'] ?? ''),
        ];
    } elseif ($paymentType === 'crypto') {
        $paymentUpdateInput = [
            'status' => 'approved',
            'requested_at' => (string)($payment['requested_at'] ?? ''),
            'expires_at' => (string)($payment['expires_at'] ?? ''),
            'request_note' => (string)($payment['request_note'] ?? ''),
        ];
        if (array_key_exists('received_crypto_amount', $input)) {
            $paymentUpdateInput['received_crypto_amount'] = (string)($input['received_crypto_amount'] ?? '');
        }
        if (array_key_exists('received_fiat_amount', $input)) {
            $paymentUpdateInput['received_fiat_amount'] = (string)($input['received_fiat_amount'] ?? '');
        }
    } else {
        $paymentUpdateInput = [
            'status' => 'approved',
            'requested_at' => (string)($payment['requested_at'] ?? ''),
            'expires_at' => (string)($payment['expires_at'] ?? ''),
            'submitted_at' => (string)($payment['submitted_at'] ?? ''),
            'approved_at' => trim((string)($payment['approved_at'] ?? '')) !== '' ? (string)$payment['approved_at'] : date('Y-m-d H:i:s'),
            'rejected_at' => null,
            'payment_reference' => (string)($payment['payment_reference'] ?? ''),
            'payer_name' => (string)($payment['payer_name'] ?? ''),
            'payer_bank_name' => (string)($payment['payer_bank_name'] ?? ''),
            'customer_transfer_note' => (string)($payment['customer_transfer_note'] ?? ''),
            'admin_review_note' => (string)($payment['admin_review_note'] ?? ''),
        ];
    }

    $saveResult = admin_save_payment(
        $db,
        $paymentType,
        $paymentId,
        $paymentUpdateInput,
        $adminUserId,
        $ipAddress
    );
    if (empty($saveResult['ok'])) {
        return $saveResult;
    }

    return [
        'ok' => true,
        'message' => $paymentType === 'crypto_topup'
            ? 'Top-up payment was accepted and the customer was notified in live chat.'
            : (
                !empty($saveResult['underpaid_order'])
                    ? 'Payment was accepted and customer balance was credited, but the linked order remains unpaid because the received amount is lower than requested.'
                    : (
                        !empty($saveResult['already_applied'])
                    ? 'Payment was accepted, but customer balance was not credited again because this payment was already processed earlier.'
                    : 'Payment was accepted and customer balance was credited.'
                    )
            ),
        'order_id' => !empty($saveResult['underpaid_order']) ? 0 : (int)($saveResult['order_id'] ?? ($payment['order_id'] ?? 0)),
        'linked_order_id' => (int)($saveResult['linked_order_id'] ?? ($payment['order_id'] ?? 0)),
        'customer_id' => (int)($saveResult['customer_id'] ?? ($payment['customer_id'] ?? 0)),
        'already_applied' => !empty($saveResult['already_applied']),
        'underpaid_order' => !empty($saveResult['underpaid_order']),
        'credited_fiat_amount' => isset($saveResult['credited_fiat_amount']) ? (float)$saveResult['credited_fiat_amount'] : null,
        'expected_fiat_amount' => isset($saveResult['expected_fiat_amount']) ? (float)$saveResult['expected_fiat_amount'] : null,
        'shortfall_fiat_amount' => isset($saveResult['shortfall_fiat_amount']) ? (float)$saveResult['shortfall_fiat_amount'] : null,
    ];
}

function admin_topbar_notification_order_row_by_id(Mysql_ks $db, int $orderId): ?array
{
    if ($orderId <= 0) return null;
    $rows = admin_topbar_notification_order_rows($db, 1, $orderId);
    return $rows[0] ?? null;
}

function admin_payment_cancel_with_order(
    Mysql_ks $db,
    string $paymentType,
    int $paymentId,
    int $adminUserId = 0,
    string $ipAddress = ''
): array
{
    $payment = admin_payment_find($db, $paymentType, $paymentId);
    if (!is_array($payment) || empty($payment['id'])) {
        return ['ok' => false, 'message' => 'Payment request not found.'];
    }

    $paymentType = strtolower((string)($payment['payment_type'] ?? $paymentType));
    if (!in_array($paymentType, ['crypto', 'bank'], true)) {
        return ['ok' => false, 'message' => 'This payment cannot be cancelled from topbar.'];
    }

    $orderId = (int)($payment['order_id'] ?? 0);

    if ($paymentType === 'crypto') {
        $paymentSaveResult = admin_save_payment(
            $db,
            $paymentType,
            $paymentId,
            [
                'status' => 'cancelled',
                'requested_at' => (string)($payment['requested_at'] ?? ''),
                'expires_at' => (string)($payment['expires_at'] ?? ''),
                'request_note' => (string)($payment['request_note'] ?? ''),
            ],
            $adminUserId,
            $ipAddress
        );
    } else {
        $paymentSaveResult = admin_save_payment(
            $db,
            $paymentType,
            $paymentId,
            [
                'status' => 'cancelled',
                'requested_at' => (string)($payment['requested_at'] ?? ''),
                'expires_at' => (string)($payment['expires_at'] ?? ''),
                'submitted_at' => (string)($payment['submitted_at'] ?? ''),
                'approved_at' => null,
                'rejected_at' => date('Y-m-d H:i:s'),
                'payment_reference' => (string)($payment['payment_reference'] ?? ''),
                'payer_name' => (string)($payment['payer_name'] ?? ''),
                'payer_bank_name' => (string)($payment['payer_bank_name'] ?? ''),
                'customer_transfer_note' => (string)($payment['customer_transfer_note'] ?? ''),
                'admin_review_note' => (string)($payment['admin_review_note'] ?? ''),
            ],
            $adminUserId,
            $ipAddress
        );
    }

    if (empty($paymentSaveResult['ok'])) {
        return $paymentSaveResult;
    }

    if ($orderId <= 0) {
        return [
            'ok' => true,
            'message' => 'Payment was cancelled successfully.',
            'order_id' => 0,
        ];
    }

    $order = admin_order_find($db, $orderId);
    if (!$order) {
        admin_log_customer_and_admin(
            $db,
            (int)($payment['customer_id'] ?? 0),
            $adminUserId,
            'payment_cancelled',
            'Payment request #' . $paymentId . ' was cancelled and stale linked order #' . $orderId . ' was ignored automatically.',
            $ipAddress
        );

        return [
            'ok' => true,
            'message' => 'Payment was cancelled successfully.',
            'order_id' => $orderId,
        ];
    }

    if (strtolower(trim((string)($order['payment_status'] ?? ''))) !== 'paid') {
        $db->query(
            "UPDATE orders
             SET payment_method = NULL
             WHERE id = {$orderId}"
        );
    }

    return [
        'ok' => true,
        'message' => 'Payment was cancelled successfully.',
        'order_id' => $orderId,
    ];
}

function admin_payment_asset_logo_url(string $assetCode, string $fallbackPath = ''): string
{
    $assetCode = strtolower(trim($assetCode));
    $fallbackPath = trim($fallbackPath);

    if ($assetCode !== '') {
        $builtIn = admin_crypto_asset_logo_url($assetCode);
        if ($builtIn !== '/img/crypto/blockchain.png') {
            return $builtIn;
        }
    }

    if ($fallbackPath !== '') {
        if (strpos($fallbackPath, 'http://') === 0 || strpos($fallbackPath, 'https://') === 0 || strpos($fallbackPath, '/') === 0) {
            return $fallbackPath;
        }
        return '/' . ltrim($fallbackPath, '/');
    }

    return '/img/crypto/blockchain.png';
}

function admin_decimal_input_value($value, int $scale = 8): string
{
    if ($value === null || $value === '') {
        return '';
    }

    if (!is_numeric((string)$value)) {
        return trim((string)$value);
    }

    $formatted = number_format((float)$value, max(0, $scale), '.', '');
    if ($scale > 0) {
        $formatted = rtrim(rtrim($formatted, '0'), '.');
    }

    return $formatted === '-0' ? '0' : $formatted;
}

function admin_build_crypto_accept_payload(array $paymentRow, array $messages): array
{
    $paymentType = strtolower(trim((string)($paymentRow['payment_type'] ?? '')));
    if ($paymentType !== 'crypto') {
        return [];
    }

    $assetCode = trim((string)($paymentRow['asset_code'] ?? ''));
    $assetName = trim((string)($paymentRow['asset_name'] ?? $assetCode));
    $walletAddress = trim((string)($paymentRow['wallet_address'] ?? ''));
    $networkCode = trim((string)($paymentRow['network_code'] ?? ''));
    $customerId = (int)($paymentRow['customer_id'] ?? 0);
    $handle = trim((string)($paymentRow['public_handle'] ?? ''));
    $handleLabel = $handle !== '' ? '@' . ltrim($handle, '@') : '';
    $requestedFiatRaw = isset($paymentRow['requested_amount_value']) && $paymentRow['requested_amount_value'] !== null
        ? (float)$paymentRow['requested_amount_value']
        : (float)($paymentRow['amount_value'] ?? 0);
    $requestedCryptoRaw = isset($paymentRow['requested_amount_crypto']) && $paymentRow['requested_amount_crypto'] !== null
        ? (float)$paymentRow['requested_amount_crypto']
        : (float)($paymentRow['amount_crypto'] ?? 0);
    $receivedFiatSource = $paymentRow['received_fiat_actual_amount'] ?? $paymentRow['received_fiat_amount'] ?? null;
    $receivedFiatRaw = $receivedFiatSource !== null && $receivedFiatSource !== ''
        ? round((float)$receivedFiatSource, 2)
        : null;
    $receivedCryptoRaw = isset($paymentRow['received_crypto_amount']) && $paymentRow['received_crypto_amount'] !== null && $paymentRow['received_crypto_amount'] !== ''
        ? (float)$paymentRow['received_crypto_amount']
        : null;
    $exchangeRate = (float)($paymentRow['exchange_rate'] ?? 0);
    if ($exchangeRate <= 0 && $requestedCryptoRaw > 0) {
        $exchangeRate = $requestedFiatRaw / $requestedCryptoRaw;
    }

    return [
        'payment_type' => 'crypto',
        'payment_id' => (int)($paymentRow['id'] ?? 0),
        'customer_id' => $customerId,
        'order_id' => (int)($paymentRow['order_id'] ?? 0),
        'status_label' => admin_t(
            $messages,
            'enum_' . (string)($paymentRow['status'] ?? ''),
            ucfirst(str_replace('_', ' ', (string)($paymentRow['status'] ?? '')))
        ),
        'customer_handle' => $handleLabel,
        'customer_email' => (string)($paymentRow['customer_email'] ?? ''),
        'customer_url' => $customerId > 0 ? '/admin/?page=users&customer_id=' . $customerId : '',
        'wallet_label' => trim((string)($paymentRow['wallet_label'] ?? '')),
        'wallet_address' => $walletAddress,
        'wallet_address_compact' => $walletAddress !== '' ? admin_compact_wallet_address($walletAddress, 8, 5) : '',
        'explorer_url' => $walletAddress !== '' ? admin_crypto_wallet_explorer_url($assetCode, $networkCode, $walletAddress) : '',
        'asset_code' => strtoupper($assetCode),
        'asset_name' => $assetName,
        'asset_logo_url' => admin_payment_asset_logo_url($assetCode, (string)($paymentRow['asset_logo_url'] ?? '')),
        'requested_crypto_amount' => admin_decimal_input_value($requestedCryptoRaw, 8),
        'requested_crypto_label' => admin_decimal_input_value($requestedCryptoRaw, 8) . ($assetCode !== '' ? ' ' . strtoupper($assetCode) : ''),
        'requested_fiat_amount' => number_format($requestedFiatRaw, 2, '.', ''),
        'currency_code' => (string)($paymentRow['currency_code'] ?? ''),
        'currency_symbol' => (string)($paymentRow['currency_symbol'] ?? ''),
        'requested_fiat_label' => admin_format_money_value_with_symbol(
            $requestedFiatRaw,
            (string)($paymentRow['currency_code'] ?? ''),
            (string)($paymentRow['currency_symbol'] ?? '')
        ),
        'received_crypto_amount' => $receivedCryptoRaw !== null ? admin_decimal_input_value($receivedCryptoRaw, 8) : '',
        'received_fiat_amount' => $receivedFiatRaw !== null ? number_format($receivedFiatRaw, 2, '.', '') : '',
        'exchange_rate' => $exchangeRate > 0 ? number_format($exchangeRate, 8, '.', '') : '',
        'requested_at_label' => admin_compact_datetime_label((string)($paymentRow['requested_at'] ?? '')),
        'requested_at_timestamp' => app_timestamp_from_runtime_datetime((string)($paymentRow['requested_at'] ?? '')),
        'can_cancel' => in_array((string)($paymentRow['status'] ?? ''), ['pending','pending_payment','awaiting_confirmation','awaiting_review','expired'], true),
        'is_topup' => (int)($paymentRow['order_id'] ?? 0) <= 0 ? 1 : 0,
    ];
}

