function admin_optional_media_url(string $path): string
{
    $path = trim($path);
    if ($path === '') {
        return '';
    }

    if (strpos($path, 'http://') === 0 || strpos($path, 'https://') === 0 || strpos($path, '/') === 0) {
        return $path;
    }

    return '/' . ltrim($path, '/');
}

function admin_payment_apply_quick_action(
    Mysql_ks $db,
    string $paymentType,
    int $paymentId,
    string $action,
    int $adminUserId = 0,
    string $ipAddress = '',
    array $input = []
): array
{
    $paymentType = strtolower(trim($paymentType));
    $action = strtolower(trim($action));

    if (!in_array($paymentType, ['crypto', 'crypto_topup', 'bank'], true) || $paymentId <= 0) {
        return ['ok' => false, 'message' => 'Payment request not found.'];
    }

    if ($action === 'delete') {
        return admin_delete_payment($db, $paymentType, $paymentId, $adminUserId, $ipAddress);
    }

    if ($action === 'accept') {
        return admin_payment_accept_with_order($db, $paymentType, $paymentId, $adminUserId, $ipAddress, $input);
    }

    if ($action === 'cancel') {
        return admin_payment_cancel_with_order($db, $paymentType, $paymentId, $adminUserId, $ipAddress);
    }

    if ($action === 'renew') {
        return admin_payment_renew_request($db, $paymentType, $paymentId, $adminUserId, $ipAddress);
    }

    $payment = admin_payment_find($db, $paymentType, $paymentId);
    if (!is_array($payment) || empty($payment['id'])) {
        return ['ok' => false, 'message' => 'Payment request not found.'];
    }

    if ($action === 'review') {
        return admin_save_payment($db, $paymentType, $paymentId, [
            'status' => admin_payment_review_status($paymentType),
        ], $adminUserId, $ipAddress);
    }

    if ($action === 'archive') {
        return admin_save_payment($db, $paymentType, $paymentId, [
            'status' => 'archived',
        ], $adminUserId, $ipAddress);
    }

    if ($action === 'reopen') {
        return admin_save_payment($db, $paymentType, $paymentId, [
            'status' => admin_payment_default_status($paymentType),
        ], $adminUserId, $ipAddress);
    }

    return ['ok' => false, 'message' => 'Payment action is invalid.'];
}

function admin_payment_renew_request(
    Mysql_ks $db,
    string $paymentType,
    int $paymentId,
    int $adminUserId = 0,
    string $ipAddress = ''
): array
{
    $payment = admin_payment_find($db, $paymentType, $paymentId);
    if (!is_array($payment) || empty($payment['id'])) {
        return ['ok' => false, 'message' => 'Payment request not found.'];
    }

    $status = strtolower(trim((string)($payment['status'] ?? '')));
    if (!in_array($status, array_merge(admin_payment_expired_statuses($paymentType), admin_payment_cancelled_statuses($paymentType)), true)) {
        return ['ok' => false, 'message' => 'Only expired or cancelled payments can be renewed.'];
    }

    if ($paymentType === 'crypto') {
        return admin_payment_renew_crypto_request($db, $payment, $adminUserId, $ipAddress);
    }

    if ($paymentType === 'bank') {
        return admin_payment_renew_bank_request($db, $payment, $adminUserId, $ipAddress);
    }

    return ['ok' => false, 'message' => 'This payment type cannot be renewed.'];
}

function admin_payment_renew_crypto_request(Mysql_ks $db, array $payment, int $adminUserId = 0, string $ipAddress = ''): array
{
    $settings = admin_app_settings($db);
    if (empty($settings['crypto_payments_enabled'])) {
        return ['ok' => false, 'message' => 'Crypto payments are disabled.'];
    }

    $customerId = (int)($payment['customer_id'] ?? 0);
    $orderId = (int)($payment['order_id'] ?? 0);
    $assetId = (int)($payment['crypto_asset_id'] ?? 0);
    $amountValue = (float)($payment['amount_value'] ?? 0);

    if ($customerId <= 0 || $assetId <= 0 || $amountValue <= 0) {
        return ['ok' => false, 'message' => 'Payment payload is incomplete.'];
    }

    $preview = admin_chat_crypto_payment_preview($db, $customerId, $assetId, $amountValue, [], $orderId > 0);
    if (empty($preview['ok'])) {
        return ['ok' => false, 'message' => (string)($preview['message'] ?? 'Unable to renew crypto payment request.')];
    }

    $walletAddressId = (int)($preview['wallet_address_id'] ?? admin_crypto_payment_wallet_address_id($db, $payment));
    $walletAssignmentId = (int)($preview['wallet_assignment_id'] ?? 0);
    $currencyId = (int)($preview['currency_id'] ?? ($payment['fiat_currency_id'] ?? 0));
    $rate = (float)($preview['rate'] ?? 0);
    $requestedCryptoAmount = round((float)($preview['crypto_amount'] ?? 0), 8);

    if ($walletAddressId <= 0 || $currencyId <= 0 || $rate <= 0 || $requestedCryptoAmount <= 0) {
        return ['ok' => false, 'message' => 'Unable to renew crypto payment request.'];
    }

    if ($walletAssignmentId <= 0) {
        $assignResult = admin_assign_crypto_wallet_customer($db, $walletAddressId, $customerId, $adminUserId, $settings, $ipAddress);
        if (empty($assignResult['ok'])) {
            return ['ok' => false, 'message' => (string)($assignResult['message'] ?? 'Unable to assign wallet.')];
        }
        $walletAssignmentId = (int)($assignResult['wallet_assignment_id'] ?? 0);
    }

    $db->start();

    $now = date('Y-m-d H:i:s');
    $expiresAt = date('Y-m-d H:i:s', strtotime('+1 hour'));
    $orderCondition = $orderId > 0 ? "order_id = {$orderId}" : "order_id IS NULL";
    $db->query(
        "UPDATE crypto_deposit_requests
         SET status = 'cancelled',
             cancelled_at = CASE
                 WHEN cancelled_at IS NULL THEN '{$now}'
                 ELSE cancelled_at
             END
         WHERE customer_id = {$customerId}
           AND {$orderCondition}
           AND status IN ('pending', 'pending_payment', 'awaiting_confirmation', 'awaiting_review')"
    );

    $openWalletRequest = $db->select_user(
        "SELECT
            crypto_deposit_requests.id,
            crypto_deposit_requests.customer_id,
            crypto_deposit_requests.order_id
         FROM crypto_deposit_requests
         LEFT JOIN crypto_wallet_assignments AS open_assignment
           ON open_assignment.id = crypto_deposit_requests.wallet_assignment_id
         WHERE (
                crypto_deposit_requests.wallet_address_id = {$walletAddressId}
             OR open_assignment.wallet_address_id = {$walletAddressId}
         )
           AND crypto_deposit_requests.status IN ('pending', 'pending_payment', 'awaiting_confirmation', 'awaiting_review')
         ORDER BY crypto_deposit_requests.id DESC
         LIMIT 1"
    );

    $newPaymentId = 0;
    if (is_array($openWalletRequest) && !empty($openWalletRequest['id'])) {
        $openOrderId = (int)($openWalletRequest['order_id'] ?? 0);
        if ((int)($openWalletRequest['customer_id'] ?? 0) !== $customerId || $openOrderId !== $orderId) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'This wallet already has an active payment request.'];
        }

        if (!app_crypto_deposit_wallet_payload_is_valid($db, $customerId, $assetId, $walletAddressId, $walletAssignmentId, $settings)) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Wallet assignment could not be confirmed.'];
        }

        $updated = $db->update_using_id(
            [
                'crypto_asset_id',
                'wallet_address_id',
                'wallet_assignment_id',
                'requested_fiat_amount',
                'fiat_currency_id',
                'exchange_rate',
                'requested_crypto_amount',
                'requested_at',
                'expires_at',
                'request_note',
                'status',
                'cancelled_at',
            ],
            [
                $assetId,
                $walletAddressId,
                $walletAssignmentId > 0 ? $walletAssignmentId : null,
                $amountValue,
                $currencyId,
                $rate,
                $requestedCryptoAmount,
                $now,
                $expiresAt,
                admin_localize_payment_request_note('Renewed from admin payments'),
                'pending',
                null,
            ],
            'crypto_deposit_requests',
            (int)$openWalletRequest['id']
        );
        if (!$updated) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Unable to renew crypto payment request.'];
        }
        $newPaymentId = (int)$openWalletRequest['id'];
    } else {
        $newPaymentId = app_create_crypto_deposit_request($db, [
            'customer_id' => $customerId,
            'order_id' => $orderId > 0 ? $orderId : null,
            'crypto_asset_id' => $assetId,
            'wallet_address_id' => $walletAddressId,
            'wallet_assignment_id' => $walletAssignmentId > 0 ? $walletAssignmentId : null,
            'requested_fiat_amount' => $amountValue,
            'fiat_currency_id' => $currencyId,
            'exchange_rate' => $rate,
            'requested_crypto_amount' => $requestedCryptoAmount,
            'assignment_mode' => 'manual',
            'status' => 'pending',
            'created_by_admin_user_id' => $adminUserId > 0 ? $adminUserId : null,
            'requested_at' => $now,
            'expires_at' => $expiresAt,
            'request_note' => admin_localize_payment_request_note('Renewed from admin payments'),
        ], true);
        if ($newPaymentId <= 0) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Unable to create renewed crypto payment request.'];
        }
    }

    if ($orderId > 0) {
        app_queue_payment_request_notification($db, $orderId, $customerId);
        app_queue_support_payment_request_notification($db, $orderId, $customerId, 'crypto');
    }

    app_delete_cancelled_crypto_requests_for_asset($db, $customerId, $assetId);

    $db->commit();

    admin_log_customer_and_admin(
        $db,
        $customerId,
        $adminUserId,
        'payment_renewed',
        'Crypto payment request #' . (int)($payment['id'] ?? 0) . ' renewed as #' . $newPaymentId . '.',
        $ipAddress
    );

    return ['ok' => true, 'message' => 'Payment request renewed.', 'payment_id' => $newPaymentId, 'payment_type' => 'crypto'];
}

function admin_payment_renew_bank_request(Mysql_ks $db, array $payment, int $adminUserId = 0, string $ipAddress = ''): array
{
    $settings = admin_app_settings($db);
    if (!admin_bank_transfers_enabled($settings)) {
        return ['ok' => false, 'message' => 'Bank transfers are disabled.'];
    }

    $customerId = (int)($payment['customer_id'] ?? 0);
    $orderId = (int)($payment['order_id'] ?? 0);
    $bankAccountId = (int)($payment['bank_account_id'] ?? 0);
    $bankAccountAssignmentId = (int)($payment['bank_account_assignment_id'] ?? 0);
    $currencyId = (int)($payment['currency_id'] ?? 0);
    $amountValue = (float)($payment['amount_value'] ?? 0);
    if ($customerId <= 0 || $bankAccountId <= 0 || $currencyId <= 0 || $amountValue <= 0) {
        return ['ok' => false, 'message' => 'Payment payload is incomplete.'];
    }

    $preview = admin_chat_bank_payment_preview($db, $customerId, $amountValue, $bankAccountId, []);
    if (empty($preview['ok'])) {
        return ['ok' => false, 'message' => (string)($preview['message'] ?? 'Bank account is unavailable.')];
    }

    if ($bankAccountAssignmentId <= 0) {
        $assignResult = admin_assign_bank_account_customer($db, $bankAccountId, $customerId, $adminUserId, $settings, $ipAddress);
        if (empty($assignResult['ok'])) {
            return ['ok' => false, 'message' => (string)($assignResult['message'] ?? 'Unable to assign bank account.')];
        }
        $assignments = admin_customer_active_bank_assignments($db, $customerId);
        foreach ($assignments as $assignment) {
            if ((int)($assignment['bank_account_id'] ?? 0) === $bankAccountId) {
                $bankAccountAssignmentId = (int)($assignment['bank_account_assignment_id'] ?? 0);
                break;
            }
        }
    }

    if ($bankAccountAssignmentId <= 0) {
        $bankAccountAssignmentId = (int)($preview['bank_account_assignment_id'] ?? 0);
    }

    $db->start();

    $now = date('Y-m-d H:i:s');
    $expiresAt = date('Y-m-d H:i:s', strtotime('+72 hours'));
    $orderCondition = $orderId > 0 ? "order_id = {$orderId}" : "order_id IS NULL";
    app_cancel_bank_transfer_requests(
        $db,
        "customer_id = {$customerId}
         AND {$orderCondition}
         AND status IN ('pending_payment', 'awaiting_review')",
        $now
    );

    $openBankRequest = $db->select_user(
        "SELECT id, customer_id, order_id
         FROM bank_transfer_requests
         WHERE bank_account_id = {$bankAccountId}
           AND status IN ('pending_payment', 'awaiting_review')
         ORDER BY id DESC
         LIMIT 1"
    );

    $newPaymentId = 0;
    if (is_array($openBankRequest) && !empty($openBankRequest['id'])) {
        $openOrderId = (int)($openBankRequest['order_id'] ?? 0);
        if ((int)($openBankRequest['customer_id'] ?? 0) !== $customerId || $openOrderId !== $orderId) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'This bank account already has an active payment request.'];
        }

        $updated = $db->update_using_id(
            [
                'bank_account_id',
                'bank_account_assignment_id',
                'requested_amount',
                'currency_id',
                'payment_reference',
                'requested_at',
                'expires_at',
                'customer_transfer_note',
                'status',
            ],
            [
                $bankAccountAssignmentId > 0 ? $bankAccountAssignmentId : null,
                $amountValue,
                $currencyId,
                '',
                $now,
                $expiresAt,
                admin_localize_payment_request_note('Renewed from admin payments'),
                'pending_payment',
            ],
            'bank_transfer_requests',
            (int)$openBankRequest['id']
        );
        if (!$updated) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Unable to renew bank payment request.'];
        }
        $newPaymentId = (int)$openBankRequest['id'];
    } else {
        $created = $db->insert(
            [
                'customer_id',
                'order_id',
                'bank_account_id',
                'bank_account_assignment_id',
                'requested_amount',
                'currency_id',
                'payment_reference',
                'status',
                'created_by_admin_user_id',
                'requested_at',
                'expires_at',
                'customer_transfer_note',
            ],
            [
                $customerId,
                $orderId > 0 ? $orderId : null,
                $bankAccountId,
                $bankAccountAssignmentId > 0 ? $bankAccountAssignmentId : null,
                $amountValue,
                $currencyId,
                '',
                'pending_payment',
                $adminUserId > 0 ? $adminUserId : null,
                $now,
                $expiresAt,
                admin_localize_payment_request_note('Renewed from admin payments'),
            ],
            'bank_transfer_requests'
        );
        if (!$created || (int)$db->id() <= 0) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Unable to create renewed bank payment request.'];
        }
        $newPaymentId = (int)$db->id();
    }

    $paymentReference = admin_chat_bank_reference_build(
        (string)($preview['payment_reference_template'] ?? ''),
        $customerId,
        $newPaymentId,
        $orderId
    );
    $db->update_using_id(['payment_reference'], [$paymentReference], 'bank_transfer_requests', $newPaymentId);

    if ($orderId > 0) {
        app_queue_payment_request_notification($db, $orderId, $customerId);
        app_queue_support_payment_request_notification($db, $orderId, $customerId, 'bank transfer');
    }

    $db->commit();

    admin_log_customer_and_admin(
        $db,
        $customerId,
        $adminUserId,
        'payment_renewed',
        'Bank payment request #' . (int)($payment['id'] ?? 0) . ' renewed as #' . $newPaymentId . '.',
        $ipAddress
    );

    return ['ok' => true, 'message' => 'Payment request renewed.', 'payment_id' => $newPaymentId, 'payment_type' => 'bank'];
}

function admin_payment_type_label(string $paymentType, array $messages): string
{
    $paymentType = strtolower(trim($paymentType));
    if ($paymentType === 'crypto') {
        return admin_t($messages, 'payment_type_crypto', 'Crypto');
    }

    if ($paymentType === 'crypto_topup') {
        return admin_t($messages, 'payment_type_crypto', 'Crypto');
    }

    if ($paymentType === 'bank') {
        return admin_t($messages, 'payment_type_bank', 'Bank transfer');
    }

    return $paymentType !== '' ? ucfirst(str_replace('_', ' ', $paymentType)) : admin_t($messages, 'col_type', 'Type');
}

function admin_payment_type_badge_class(string $paymentType): string
{
    $paymentType = strtolower(trim($paymentType));
    if ($paymentType === 'crypto' || $paymentType === 'crypto_topup') {
        return 'admin-status-pill--assigned';
    }

    if ($paymentType === 'bank') {
        return 'admin-status-pill--available';
    }

    return 'admin-status-pill--muted';
}

function admin_payment_status_badge_class(string $status): string
{
    $status = strtolower(trim($status));

    if ($status === 'pending' || $status === 'pending_payment') {
        return 'admin-status-pill--warning';
    }

    if ($status === 'awaiting_confirmation' || $status === 'awaiting_review') {
        return 'admin-status-pill--assigned';
    }

    if ($status === 'archived') {
        return 'admin-status-pill--muted';
    }

    if ($status === 'expired') {
        return 'admin-status-pill--danger';
    }

    if (in_array($status, ['confirmed', 'approved', 'paid', 'completed'], true)) {
        return 'admin-status-pill--available';
    }

    if (in_array($status, ['cancelled', 'rejected', 'failed'], true)) {
        return 'admin-status-pill--danger';
    }

    return 'admin-status-pill--available';
}

function admin_payment_status_is_archived(string $status): bool
{
    return strtolower(trim($status)) === 'archived';
}

function admin_compact_wallet_address(string $value, int $prefixLength = 4, int $suffixLength = 5): string
{
    $value = trim($value);
    if ($value === '') {
        return '';
    }

    $minimumVisibleLength = $prefixLength + $suffixLength + 3;
    if (strlen($value) <= $minimumVisibleLength) {
        return $value;
    }

    return substr($value, 0, $prefixLength) . '...' . substr($value, -$suffixLength);
}

function admin_payment_progress_state(string $status): array
{
    $status = strtolower(trim($status));

    if ($status === 'archived') {
        return [
            'show_bar' => false,
            'tone' => 'success',
            'percent' => 0,
            'status_label_key' => 'payment_stage_archived',
            'status_fallback' => 'Archived',
        ];
    }

    if ($status === 'awaiting_confirmation' || $status === 'awaiting_review') {
        return [
            'show_bar' => true,
            'tone' => 'warning',
            'percent' => 56,
            'status_label_key' => 'payment_stage_review',
            'status_fallback' => 'Verification',
        ];
    }

    if (in_array($status, ['cancelled', 'rejected', 'failed'], true)) {
        return [
            'show_bar' => false,
            'tone' => 'danger',
            'percent' => 0,
            'status_label_key' => 'enum_cancelled',
            'status_fallback' => 'Cancelled',
        ];
    }

    if (in_array($status, ['success', 'confirmed', 'approved', 'paid', 'completed'], true)) {
        return [
            'show_bar' => true,
            'tone' => 'success',
            'percent' => 100,
            'status_label_key' => 'payment_stage_success',
            'status_fallback' => 'Success',
        ];
    }

    return [
        'show_bar' => true,
        'tone' => 'neutral',
        'percent' => 16,
        'status_label_key' => 'payment_stage_new',
        'status_fallback' => 'Pending',
    ];
}

function admin_product_count(Mysql_ks $db): int
{
    if (!schema_object_exists($db, 'products')) {
