         ORDER BY crypto_wallet_addresses.id DESC
         LIMIT {$offset}, {$limit}"
    );
}

function admin_crypto_wallet_count_filtered(Mysql_ks $db, int $walletId = 0): int
{
    if (!schema_object_exists($db, 'crypto_wallet_addresses')) {
        return 0;
    }

    $whereParts = [];
    if ($walletId > 0) {
        $whereParts[] = 'crypto_wallet_addresses.id = ' . $walletId;
    }

    $whereSql = $whereParts ? 'WHERE ' . implode(' AND ', $whereParts) : '';
    $row = $db->select_user(
        "SELECT COUNT(*) AS total
         FROM crypto_wallet_addresses
         {$whereSql}"
    );

    return (int)($row['total'] ?? 0);
}

function admin_crypto_wallet_rows_filtered(Mysql_ks $db, int $limit = 20, int $offset = 0, int $walletId = 0): array
{
    if (!schema_object_exists($db, 'crypto_wallet_addresses')) {
        return [];
    }

    $limit = max(1, min(50, $limit));
    $offset = max(0, $offset);
    $whereParts = [];
    if ($walletId > 0) {
        $whereParts[] = 'crypto_wallet_addresses.id = ' . $walletId;
    }
    $whereSql = $whereParts ? 'WHERE ' . implode(' AND ', $whereParts) : '';

    return $db->select_full_user(
        "SELECT
            crypto_wallet_addresses.id,
            crypto_wallet_addresses.crypto_asset_id,
            crypto_wallet_addresses.label,
            crypto_wallet_addresses.owner_full_name,
            crypto_wallet_addresses.address,
            crypto_wallet_addresses.network_code,
            crypto_wallet_addresses.memo_tag,
            crypto_wallet_addresses.wallet_provider,
            crypto_wallet_addresses.status,
            crypto_wallet_addresses.notes,
            crypto_assets.code AS asset_code,
            crypto_assets.name AS asset_name,
            crypto_assets.logo_url AS asset_logo_url,
            (
                SELECT customers.email
                FROM crypto_wallet_assignments
                INNER JOIN customers ON customers.id = crypto_wallet_assignments.customer_id
                WHERE crypto_wallet_assignments.wallet_address_id = crypto_wallet_addresses.id
                  AND crypto_wallet_assignments.status IN ('reserved', 'active')
                ORDER BY crypto_wallet_assignments.assigned_at DESC, crypto_wallet_assignments.id DESC
                LIMIT 1
            ) AS assigned_customer_email,
            (
                SELECT crypto_wallet_assignments.customer_id
                FROM crypto_wallet_assignments
                WHERE crypto_wallet_assignments.wallet_address_id = crypto_wallet_addresses.id
                  AND crypto_wallet_assignments.status IN ('reserved', 'active')
                ORDER BY crypto_wallet_assignments.assigned_at DESC, crypto_wallet_assignments.id DESC
                LIMIT 1
            ) AS assigned_customer_id,
            (
                SELECT NULLIF(TRIM(customers.public_handle), '')
                FROM crypto_wallet_assignments
                INNER JOIN customers ON customers.id = crypto_wallet_assignments.customer_id
                WHERE crypto_wallet_assignments.wallet_address_id = crypto_wallet_addresses.id
                  AND crypto_wallet_assignments.status IN ('reserved', 'active')
                ORDER BY crypto_wallet_assignments.assigned_at DESC, crypto_wallet_assignments.id DESC
                LIMIT 1
            ) AS assigned_customer_public_handle,
            (
                SELECT COUNT(*)
                FROM crypto_wallet_assignments
                WHERE crypto_wallet_assignments.wallet_address_id = crypto_wallet_addresses.id
                  AND crypto_wallet_assignments.status IN ('reserved', 'active')
            ) AS active_assignment_count,
            crypto_wallet_addresses.updated_at
         FROM crypto_wallet_addresses
         LEFT JOIN crypto_assets ON crypto_assets.id = crypto_wallet_addresses.crypto_asset_id
         {$whereSql}
         ORDER BY crypto_wallet_addresses.id DESC
         LIMIT {$offset}, {$limit}"
    );
}

function admin_crypto_wallet_asset_summary_rows(Mysql_ks $db): array
{
    if (!schema_object_exists($db, 'crypto_wallet_addresses') || !schema_object_exists($db, 'crypto_assets')) {
        return [];
    }

    $settings = admin_app_settings($db);
    $sharedEnabled = admin_crypto_wallet_shared_assignments_enabled($settings);
    $paymentAssetFilterSql = admin_crypto_customer_payment_asset_sql_filter($db, 'crypto_assets');
    $availableCountSql = $sharedEnabled
        ? "CASE
                WHEN crypto_wallet_addresses.disabled_at IS NULL
                 AND crypto_wallet_addresses.status IN ('available', 'assigned')
                THEN 1
                ELSE 0
           END"
        : "CASE
                WHEN crypto_wallet_addresses.disabled_at IS NULL
                 AND crypto_wallet_addresses.status = 'available'
                THEN 1
                ELSE 0
           END";

    return $db->select_full_user(
        "SELECT
            crypto_assets.id AS asset_id,
            crypto_assets.code AS asset_code,
            crypto_assets.name AS asset_name,
            crypto_assets.logo_url AS asset_logo_url,
            COALESCE(SUM(
                {$availableCountSql}
            ), 0) AS available_count,
            COUNT(crypto_wallet_addresses.id) AS total_count
         FROM crypto_assets
         LEFT JOIN crypto_wallet_addresses
            ON crypto_wallet_addresses.crypto_asset_id = crypto_assets.id
         WHERE crypto_assets.is_active = 1
           {$paymentAssetFilterSql}
         GROUP BY crypto_assets.id, crypto_assets.code, crypto_assets.name, crypto_assets.logo_url
         ORDER BY crypto_assets.code ASC, crypto_assets.id ASC"
    );
}

function admin_crypto_asset_rows(Mysql_ks $db, bool $onlyActive = false): array
{
    if (!schema_object_exists($db, 'crypto_assets')) {
        return [];
    }

    $whereSql = $onlyActive ? 'WHERE is_active = 1' : '';

    return $db->select_full_user(
        "SELECT id, code, name, coingecko_id, logo_url, current_rate_fiat, rate_updated_at, is_active
         FROM crypto_assets
         {$whereSql}
         ORDER BY is_active DESC, name ASC, id ASC"
    );
}

function admin_default_coingecko_id(string $assetCode): string
{
    $assetCode = strtoupper(trim($assetCode));
    $map = [
        'BTC' => 'bitcoin',
        'BCH' => 'bitcoin-cash',
        'LTC' => 'litecoin',
        'ETH' => 'ethereum',
        'DOGE' => 'dogecoin',
        'BNB' => 'binancecoin',
        'USDT' => 'tether',
        'CRO' => 'crypto-com-chain',
        'SOL' => 'solana',
        'USDC' => 'usd-coin',
        'POL' => 'polygon-ecosystem-token',
        'MATIC' => 'matic-network',
        'XRP' => 'ripple',
        'TRX' => 'tron',
    ];

    return $map[$assetCode] ?? '';
}

function admin_http_json(string $url, int $timeoutSeconds = 20, int $connectTimeoutSeconds = 10): ?array
{
    if (app_crypto_api_policy($url) !== null) {
        $raw = app_crypto_api_request($url, null, false, $timeoutSeconds);
        $decoded = $raw !== null ? json_decode($raw, true) : null;
        return is_array($decoded) ? $decoded : null;
    }
    if ($url === '') {
        return null;
    }

    $timeoutSeconds = max(1, min(30, $timeoutSeconds));
    $connectTimeoutSeconds = max(1, min($timeoutSeconds, $connectTimeoutSeconds));

    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_CONNECTTIMEOUT => $connectTimeoutSeconds,
            CURLOPT_TIMEOUT => $timeoutSeconds,
            CURLOPT_HTTPHEADER => [
                'Accept: application/json',
                'User-Agent: Reseller-Admin/1.0',
            ],
        ]);

        $response = curl_exec($ch);
        $httpCode = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);

        if (!is_string($response) || $response === '' || $httpCode >= 400) {
            return null;
        }

        $decoded = json_decode($response, true);
        return is_array($decoded) ? $decoded : null;
    }

    $context = stream_context_create([
        'http' => [
            'method' => 'GET',
            'timeout' => $timeoutSeconds,
            'header' => "Accept: application/json\r\nUser-Agent: Reseller-Admin/1.0\r\n",
        ],
    ]);

    $response = @file_get_contents($url, false, $context);
    if (!is_string($response) || $response === '') {
        return null;
    }

    $decoded = json_decode($response, true);
    return is_array($decoded) ? $decoded : null;
}

function admin_http_text(string $url, int $timeoutSeconds = 20, int $connectTimeoutSeconds = 10): ?string
{
    if (app_crypto_api_policy($url) !== null) return app_crypto_api_request($url, null, true, $timeoutSeconds);
    if ($url === '') {
        return null;
    }

    $timeoutSeconds = max(1, min(30, $timeoutSeconds));
    $connectTimeoutSeconds = max(1, min($timeoutSeconds, $connectTimeoutSeconds));

    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_CONNECTTIMEOUT => $connectTimeoutSeconds,
            CURLOPT_TIMEOUT => $timeoutSeconds,
            CURLOPT_HTTPHEADER => [
                'Accept: text/plain, application/json',
                'User-Agent: Reseller-Admin/1.0',
            ],
        ]);

        $response = curl_exec($ch);
        $httpCode = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);

        if (!is_string($response) || $response === '' || $httpCode >= 400) {
            return null;
        }

        return $response;
    }

    $context = stream_context_create([
        'http' => [
            'method' => 'GET',
            'timeout' => $timeoutSeconds,
            'header' => "Accept: text/plain, application/json\r\nUser-Agent: Reseller-Admin/1.0\r\n",
        ],
    ]);

    $response = @file_get_contents($url, false, $context);
    return is_string($response) && $response !== '' ? $response : null;
}

function admin_http_post_json(string $url, array $payload): ?array
{
    if (app_crypto_api_policy($url) !== null) {
        $raw = app_crypto_api_request($url, $payload);
        $decoded = $raw !== null ? json_decode($raw, true) : null;
        return is_array($decoded) ? $decoded : null;
    }
    if ($url === '') {
        return null;
    }

    $jsonPayload = json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    if (!is_string($jsonPayload) || $jsonPayload === '') {
        return null;
    }

    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_CONNECTTIMEOUT => 10,
            CURLOPT_TIMEOUT => 20,
            CURLOPT_POST => true,
            CURLOPT_POSTFIELDS => $jsonPayload,
            CURLOPT_HTTPHEADER => [
                'Accept: application/json',
                'Content-Type: application/json',
                'User-Agent: Reseller-Admin/1.0',
            ],
        ]);

        $response = curl_exec($ch);
        $httpCode = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);

        if (!is_string($response) || $response === '' || $httpCode >= 400) {
            return null;
        }

        $decoded = json_decode($response, true);
        return is_array($decoded) ? $decoded : null;
    }

    $context = stream_context_create([
        'http' => [
            'method' => 'POST',
            'timeout' => 20,
            'header' => "Accept: application/json\r\nContent-Type: application/json\r\nUser-Agent: Reseller-Admin/1.0\r\n",
            'content' => $jsonPayload,
        ],
    ]);

    $response = @file_get_contents($url, false, $context);
    if (!is_string($response) || $response === '') {
        return null;
    }

    $decoded = json_decode($response, true);
    return is_array($decoded) ? $decoded : null;
}

function admin_refresh_crypto_asset_rates(Mysql_ks $db, string $vsCurrency = 'USD', int $cacheTtl = 900, array $assetCodes = [], bool $includeInactive = false, bool $refreshRates = true): array
{
    if (!schema_object_exists($db, 'crypto_assets')) {
        return [];
    }

    $vsCurrency = strtoupper(trim($vsCurrency));
    if ($vsCurrency === '') {
        $vsCurrency = 'USD';
    }
    $cacheTtl = max(60, $cacheTtl);
    $vsCurrencyLower = strtolower($vsCurrency);
    $now = time();
    $assetCodes = array_values(array_unique(array_filter(array_map(
        static fn($code): string => strtoupper(trim((string)$code)),
        $assetCodes
    ))));
    $whereParts = [];
    if (!$includeInactive) {
        $whereParts[] = 'is_active = 1';
    }
    if ($assetCodes) {
        $escapedCodes = array_map(static fn($code): string => "'" . $db->escape($code) . "'", $assetCodes);
        $whereParts[] = 'UPPER(code) IN (' . implode(', ', $escapedCodes) . ')';
    }
    $whereSql = $whereParts ? 'WHERE ' . implode(' AND ', $whereParts) : '';

    $rows = $db->select_full_user(
        "SELECT
            id,
            code,
            name,
            coingecko_id,
            logo_url,
            current_rate_fiat,
            rate_currency_code,
            rate_updated_at,
            updated_at,
            is_active
         FROM crypto_assets
         {$whereSql}
         ORDER BY name ASC, id ASC"
    );

    if (!$rows) {
        return [];
    }

    $needsRefresh = false;
    $coingeckoIds = [];
    foreach ($rows as $index => $row) {
        $code = (string)($row['code'] ?? '');
        $coingeckoId = trim((string)($row['coingecko_id'] ?? ''));
        if ($coingeckoId === '') {
            $coingeckoId = admin_default_coingecko_id($code);
            $rows[$index]['coingecko_id'] = $coingeckoId;
        }

            if ($coingeckoId !== '') {
                $coingeckoIds[$coingeckoId] = true;
            }

            $rows[$index]['rate_refreshed_now'] = 0;
            $rows[$index]['rate_refresh_label'] = '';
            $rate = isset($row['current_rate_fiat']) ? (float)$row['current_rate_fiat'] : 0.0;
            $rateCurrencyCode = strtoupper(trim((string)($row['rate_currency_code'] ?? '')));
            $rateUpdatedAt = !empty($row['rate_updated_at']) ? app_timestamp_from_utc_datetime((string)$row['rate_updated_at']) : 0;
            if ($coingeckoId === '' || $rate <= 0 || $rateCurrencyCode !== $vsCurrency || $rateUpdatedAt <= 0 || $rateUpdatedAt > $now + 60 || ($now - $rateUpdatedAt) >= $cacheTtl) {
                $needsRefresh = true;
            }
        }

    if ($refreshRates && $needsRefresh && $coingeckoIds) {
        $payload = app_crypto_cached_prices(array_keys($coingeckoIds), $vsCurrency, $cacheTtl);

        if (is_array($payload)) {
            $persistRates = app_crypto_rate_should_persist($db, $vsCurrency);
            foreach ($rows as $index => $row) {
                $assetId = (int)($row['id'] ?? 0);
                $coingeckoId = (string)($row['coingecko_id'] ?? '');
                if ($assetId <= 0 || $coingeckoId === '' || empty($payload[$coingeckoId][$vsCurrencyLower])) {
                    continue;
                }

                $price = (float)$payload[$coingeckoId][$vsCurrencyLower];
                    $updatedAt = !empty($payload[$coingeckoId]['last_updated_at'])
                        ? app_datetime_utc_from_unix_timestamp((int)$payload[$coingeckoId]['last_updated_at'])
                        : app_datetime_utc_from_unix_timestamp($now);
                    $newRate = ['current_rate_fiat' => $price, 'rate_currency_code' => $vsCurrency, 'rate_updated_at' => $updatedAt];
                    if (!app_crypto_rate_is_usable($newRate, $vsCurrency)) continue;
                    if ($price === (float)($row['current_rate_fiat'] ?? 0) && $vsCurrency === ($row['rate_currency_code'] ?? '') && $updatedAt === ($row['rate_updated_at'] ?? '')) continue;
                    $refreshRecordedAt = app_format_utc_datetime_local(app_datetime_utc_from_unix_timestamp($now));

                    if ($persistRates) $db->update_using_id(
                        ['coingecko_id', 'current_rate_fiat', 'rate_currency_code', 'rate_updated_at'],
                        [$coingeckoId, $price, $vsCurrency, $updatedAt],
                    'crypto_assets',
                    $assetId
                );

                    $rows[$index]['current_rate_fiat'] = $price;
                    $rows[$index]['rate_currency_code'] = $vsCurrency;
                    $rows[$index]['rate_updated_at'] = $updatedAt;
                    $rows[$index]['updated_at'] = $refreshRecordedAt;
                    $rows[$index]['rate_refreshed_now'] = 1;
                    $rows[$index]['rate_refresh_label'] = $refreshRecordedAt;
                }
            }
        }

    return $rows;
}

function admin_topbar_converter_asset_rows(Mysql_ks $db, string $vsCurrency = 'USD', int $cacheTtl = 900, bool $refreshRates = true): array
{
    $rowsByCode = [];

    foreach (admin_refresh_crypto_asset_rates($db, $vsCurrency, $cacheTtl, [], false, $refreshRates) as $assetRow) {
        $assetCode = strtoupper(trim((string)($assetRow['code'] ?? '')));
        $assetRate = isset($assetRow['current_rate_fiat']) ? (float)$assetRow['current_rate_fiat'] : 0.0;
        if ($assetCode === '' || $assetRate <= 0 || !app_crypto_rate_is_usable($assetRow, $vsCurrency) || strtoupper((string)($assetRow['rate_currency_code'] ?? '')) !== strtoupper($vsCurrency) || empty($assetRow['is_active'])) {
            continue;
        }

        $rowsByCode[$assetCode] = $assetRow;
    }

    if (!isset($rowsByCode['USDT'])) {
        foreach (admin_refresh_crypto_asset_rates($db, $vsCurrency, $cacheTtl, ['USDT'], true, $refreshRates) as $assetRow) {
            $assetCode = strtoupper(trim((string)($assetRow['code'] ?? '')));
            $assetRate = isset($assetRow['current_rate_fiat']) ? (float)$assetRow['current_rate_fiat'] : 0.0;
            if ($assetCode !== 'USDT' || $assetRate <= 0 || !app_crypto_rate_is_usable($assetRow, $vsCurrency) || strtoupper((string)($assetRow['rate_currency_code'] ?? '')) !== strtoupper($vsCurrency)) {
                continue;
            }

            $rowsByCode['USDT'] = $assetRow;
        }
    }

    uasort($rowsByCode, static function (array $left, array $right): int {
        $leftName = trim((string)($left['name'] ?? ''));
        $rightName = trim((string)($right['name'] ?? ''));
        $byName = strcasecmp($leftName, $rightName);
        if ($byName !== 0) {
            return $byName;
        }

        return strcasecmp((string)($left['code'] ?? ''), (string)($right['code'] ?? ''));
    });

    return array_values($rowsByCode);
}

function admin_topbar_converter_fiat_cache_file(string $baseCurrency): string
{
    $safeBaseCurrency = preg_replace('/[^A-Z]/', '', strtoupper($baseCurrency));
    if ($safeBaseCurrency === '') {
        $safeBaseCurrency = 'USD';
    }

    return rtrim(sys_get_temp_dir(), DIRECTORY_SEPARATOR)
        . DIRECTORY_SEPARATOR
        . 'subme_topbar_converter_fiat_'
        . strtolower($safeBaseCurrency)
        . '.json';
}

function admin_topbar_converter_fiat_payload(string $baseCurrency = 'USD', int $cacheTtl = 900, bool $refreshRates = true): array
{
    $baseCurrency = strtoupper(trim($baseCurrency));
    if ($baseCurrency === '') {
        $baseCurrency = 'USD';
    }

    $currencyCodes = array_values(array_unique([$baseCurrency, 'PLN', 'GBP']));
    $currencySymbols = [
        'USD' => '$',
        'EUR' => '€',
        'GBP' => '£',
        'PLN' => 'zł',
    ];
    $currencyNames = [
        'USD' => 'US Dollar',
        'EUR' => 'Euro',
        'GBP' => 'British Pound',
        'PLN' => 'Polish Zloty',
    ];
    $cachePath = admin_topbar_converter_fiat_cache_file($baseCurrency);
    $cachedPayload = null;

    if (is_file($cachePath)) {
        $decodedCache = json_decode((string)@file_get_contents($cachePath), true);
        if (is_array($decodedCache) && !empty($decodedCache['items']) && is_array($decodedCache['items'])) {
            $cachedPayload = $decodedCache;
            $cachedCodes = [];
            foreach ($decodedCache['items'] as $cachedItem) {
                $cachedCode = strtoupper(trim((string)($cachedItem['code'] ?? '')));
                if ($cachedCode !== '') {
                    $cachedCodes[$cachedCode] = true;
                }
            }
            $cacheIsComplete = count(array_intersect($currencyCodes, array_keys($cachedCodes))) === count($currencyCodes);
            if (
                $cacheIsComplete
                && $cacheTtl > 0
                && (time() - (int)@filemtime($cachePath)) < max(60, $cacheTtl)
            ) {
                return array_values($decodedCache['items']);
            }
        }
    }

    if (!$refreshRates) {
        if ($cachedPayload !== null) {
            return array_map(static function (array $item): array {
                $item['is_stale'] = 1;
                return $item;
            }, array_values($cachedPayload['items']));
        }
        return [[
            'id' => 'fiat:' . $baseCurrency, 'key' => 'fiat:' . $baseCurrency,
            'type' => 'fiat', 'code' => $baseCurrency, 'name' => $currencyNames[$baseCurrency] ?? $baseCurrency,
            'symbol' => $currencySymbols[$baseCurrency] ?? $baseCurrency, 'logo_url' => '',
            'rate' => 1.0, 'rate_label' => '1.00000000', 'rate_updated_at' => '',
            'rate_updated_label' => '', 'is_stale' => 1,
        ]];
    }

    $vsCurrencies = strtolower(implode(',', $currencyCodes));
    $coingeckoPayload = admin_http_json(
        'https://api.coingecko.com/api/v3/simple/price?ids=bitcoin'
        . '&vs_currencies=' . rawurlencode($vsCurrencies)
        . '&include_last_updated_at=true&precision=full',
        10,
        5
    );
    $bitcoinRates = is_array($coingeckoPayload['bitcoin'] ?? null)
        ? $coingeckoPayload['bitcoin']
        : [];
    $baseBitcoinRate = isset($bitcoinRates[strtolower($baseCurrency)])
        ? (float)$bitcoinRates[strtolower($baseCurrency)]
        : 0.0;
    $updatedTimestamp = isset($bitcoinRates['last_updated_at'])
        ? (int)$bitcoinRates['last_updated_at']
        : time();
    $ratesInBaseCurrency = [$baseCurrency => 1.0];

    if ($baseBitcoinRate > 0) {
        foreach ($currencyCodes as $currencyCode) {
            $bitcoinRate = isset($bitcoinRates[strtolower($currencyCode)])
                ? (float)$bitcoinRates[strtolower($currencyCode)]
                : 0.0;
            if ($bitcoinRate > 0) {
                $ratesInBaseCurrency[$currencyCode] = $baseBitcoinRate / $bitcoinRate;
            }
        }
    }

    if (count($ratesInBaseCurrency) < count($currencyCodes)) {
        $fallbackCodes = array_values(array_filter(
            $currencyCodes,
            static fn(string $currencyCode): bool => $currencyCode !== $baseCurrency
        ));
        $fallbackPayload = $fallbackCodes
            ? admin_http_json(
                'https://api.frankfurter.app/latest?from='
                . rawurlencode($baseCurrency)
                . '&to='
                . rawurlencode(implode(',', $fallbackCodes)),
                10,
                5
            )
            : null;
        $fallbackRates = is_array($fallbackPayload['rates'] ?? null) ? $fallbackPayload['rates'] : [];

        foreach ($fallbackCodes as $currencyCode) {
            if (isset($ratesInBaseCurrency[$currencyCode])) {
                continue;
            }
            $targetPerBase = isset($fallbackRates[$currencyCode]) ? (float)$fallbackRates[$currencyCode] : 0.0;
            if ($targetPerBase > 0) {
                $ratesInBaseCurrency[$currencyCode] = 1 / $targetPerBase;
            }
        }
    }

    $updatedAt = app_datetime_utc_from_unix_timestamp($updatedTimestamp > 0 ? $updatedTimestamp : time());
    $updatedLabel = app_format_utc_datetime_local($updatedAt);
    $items = [];

    foreach ($currencyCodes as $currencyCode) {
        $rate = isset($ratesInBaseCurrency[$currencyCode])
            ? (float)$ratesInBaseCurrency[$currencyCode]
            : 0.0;
        if ($rate <= 0) {
            continue;
        }

        $items[] = [
            'id' => 'fiat:' . $currencyCode,
            'key' => 'fiat:' . $currencyCode,
            'type' => 'fiat',
            'code' => $currencyCode,
            'name' => $currencyNames[$currencyCode] ?? $currencyCode,
            'symbol' => $currencySymbols[$currencyCode] ?? $currencyCode,
            'logo_url' => '',
            'rate' => $rate,
            'rate_label' => number_format($rate, 8, '.', ''),
            'rate_updated_at' => $updatedAt,
            'rate_updated_label' => $updatedLabel,
            'is_stale' => 0,
        ];
    }

    if (count($items) < count($currencyCodes) && $cachedPayload !== null) {
        $itemsByCode = [];
        foreach ($items as $item) {
            $itemsByCode[strtoupper((string)($item['code'] ?? ''))] = $item;
        }
        foreach ($cachedPayload['items'] as $cachedItem) {
            $cachedCode = strtoupper(trim((string)($cachedItem['code'] ?? '')));
            if ($cachedCode !== '' && !isset($itemsByCode[$cachedCode])) {
                $cachedItem['is_stale'] = 1;
                $itemsByCode[$cachedCode] = $cachedItem;
            }
        }
        $items = [];
        foreach ($currencyCodes as $currencyCode) {
            if (isset($itemsByCode[$currencyCode])) {
                $items[] = $itemsByCode[$currencyCode];
            }
        }
    }

    if (count($items) === count($currencyCodes)) {
        @file_put_contents(
            $cachePath,
            json_encode(
                ['base_currency' => $baseCurrency, 'items' => $items],
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
            ),
            LOCK_EX
        );
    }

    return $items;
}

function admin_topbar_converter_asset_payload(Mysql_ks $db, string $vsCurrency = 'USD', int $cacheTtl = 900, bool $refreshRates = true): array
{
    $items = [];

    foreach (admin_topbar_converter_asset_rows($db, $vsCurrency, $cacheTtl, $refreshRates) as $assetRow) {
        $assetUpdatedAt = trim((string)($assetRow['rate_updated_at'] ?? ''));
        $assetUpdatedTimestamp = $assetUpdatedAt !== '' ? app_timestamp_from_utc_datetime($assetUpdatedAt) : false;

        $items[] = [
            'id' => (int)($assetRow['id'] ?? 0),
            'key' => 'crypto:' . (int)($assetRow['id'] ?? 0),
            'type' => 'crypto',
            'code' => strtoupper((string)($assetRow['code'] ?? '')),
            'name' => (string)($assetRow['name'] ?? ''),
            'symbol' => '',
            'logo_url' => app_crypto_logo_by_code((string)($assetRow['code'] ?? ''), (string)($assetRow['logo_url'] ?? '')),
            'rate' => isset($assetRow['current_rate_fiat']) ? (float)$assetRow['current_rate_fiat'] : 0.0,
            'rate_label' => app_format_crypto_rate($assetRow['current_rate_fiat'] ?? null),
            'rate_updated_at' => $assetUpdatedAt,
            'rate_updated_label' => $assetUpdatedAt !== '' ? app_format_utc_datetime_local($assetUpdatedAt) : '',
            'is_stale' => !$assetUpdatedTimestamp || (time() - (int)$assetUpdatedTimestamp) >= 900 ? 1 : 0,
        ];
    }

    return array_merge(admin_topbar_converter_fiat_payload($vsCurrency, $cacheTtl, $refreshRates), $items);
}

function admin_crypto_asset_count(Mysql_ks $db): int
{
    if (!schema_object_exists($db, 'crypto_assets')) {
        return 0;
    }

    $row = $db->select_user("SELECT COUNT(*) AS total FROM crypto_assets");
    return (int)($row['total'] ?? 0);
}

function admin_crypto_asset_is_protected($asset): bool
{
    if (is_array($asset)) {
        $assetCode = strtoupper(trim((string)($asset['code'] ?? '')));
    } else {
        $assetCode = strtoupper(trim((string)$asset));
    }

    return $assetCode === 'BTC';
}

function admin_crypto_asset_find(Mysql_ks $db, int $assetId): ?array
{
    if ($assetId <= 0 || !schema_object_exists($db, 'crypto_assets')) {
        return null;
    }

    $row = $db->select_user(
        "SELECT id, code, name, coingecko_id, logo_url, current_rate_fiat, rate_updated_at, is_active
         FROM crypto_assets
         WHERE id = {$assetId}
         LIMIT 1"
    );

    return is_array($row) ? $row : null;
}

function admin_save_crypto_asset(Mysql_ks $db, int $assetId, array $input): array
{
    $asset = admin_crypto_asset_find($db, $assetId);
    if (!$asset) {
        return ['ok' => false, 'message' => 'Asset not found.'];
    }

    $name = trim((string)($input['name'] ?? ''));
    $coingeckoId = trim((string)($input['coingecko_id'] ?? ''));
    $logoUrl = array_key_exists('logo_url', $input)
        ? trim((string)($input['logo_url'] ?? ''))
        : trim((string)($asset['logo_url'] ?? ''));
    $isActive = isset($input['is_active']) && (string)$input['is_active'] === '1' ? 1 : 0;
    $isProtected = admin_crypto_asset_is_protected($asset);

    if ($name === '') {
        return ['ok' => false, 'message' => 'Asset name is required.'];
    }

    if ($isProtected) {
        $isActive = 1;
    }

    if ($coingeckoId === '') {
        $coingeckoId = admin_default_coingecko_id((string)($asset['code'] ?? ''));
    }

    $updated = $db->update_using_id(
        ['name', 'coingecko_id', 'logo_url', 'is_active'],
        [$name, $coingeckoId !== '' ? $coingeckoId : null, $logoUrl !== '' ? $logoUrl : null, $isActive],
        'crypto_assets',
        $assetId
    );

    return [
        'ok' => (bool)$updated,
        'message' => $updated ? 'Asset saved successfully.' : 'Unable to save asset.',
    ];
}

function admin_crypto_asset_network_options(string $assetCode): array
{
    $assetCode = strtoupper(trim($assetCode));
    $fixed = [
        'BTC' => ['bitcoin' => 'Bitcoin'],
        'BCH' => ['bitcoin-cash' => 'Bitcoin Cash'],
        'LTC' => ['litecoin' => 'Litecoin'],
        'DOGE' => ['dogecoin' => 'Dogecoin'],
        'ETH' => ['ethereum' => 'Ethereum'],
        'BNB' => ['bnb' => 'BNB Smart Chain'],
        'CRO' => ['cronos' => 'Cronos'],
        'SOL' => ['solana' => 'Solana'],
        'POL' => ['polygon' => 'Polygon'],
        'MATIC' => ['polygon' => 'Polygon'],
        'XRP' => ['ripple' => 'XRP Ledger'],
        'TRX' => ['tron' => 'TRON'],
    ];

    if (isset($fixed[$assetCode])) {
        return $fixed[$assetCode];
    }

    if ($assetCode === 'USDT' || $assetCode === 'USDC') {
        return [
            'ethereum' => 'Ethereum (ERC20)',
            'polygon' => 'Polygon',
            'bnb' => 'BNB Smart Chain',
            'tron' => 'Tron (TRC20)',
            'solana' => 'Solana',
        ];
    }

    return [];
}

function admin_crypto_asset_allows_network_choice(string $assetCode): bool
{
    return count(admin_crypto_asset_network_options($assetCode)) > 1;
}

function admin_crypto_network_label(string $networkCode): string
{
    $labels = [
        'bitcoin' => 'Bitcoin',
        'bitcoin-cash' => 'Bitcoin Cash',
        'litecoin' => 'Litecoin',
        'dogecoin' => 'Dogecoin',
        'ethereum' => 'Ethereum',
        'polygon' => 'Polygon',
        'bnb' => 'BNB Smart Chain',
        'tron' => 'TRON',
        'cronos' => 'Cronos',
        'solana' => 'Solana',
        'ripple' => 'XRP Ledger',
    ];

    $networkCode = strtolower(trim($networkCode));
    return $labels[$networkCode] ?? ucfirst(str_replace('-', ' ', $networkCode));
}

function admin_crypto_wallet_provider_options(?string $currentProvider = null): array
{
    $options = [
        '' => 'Choose provider',
        'TrustWallet' => 'TrustWallet',
        'MetaMask' => 'MetaMask',
        'KrakenWallet' => 'KrakenWallet',
    ];

    $currentProvider = trim((string)$currentProvider);
    if ($currentProvider !== '' && !isset($options[$currentProvider])) {
        $options[$currentProvider] = $currentProvider;
    }

    return $options;
}

function admin_infer_stablecoin_network_by_address(string $address): string
{
    $address = trim($address);
    if ($address === '') {
        return 'ethereum';
    }

    if (strpos($address, 'T') === 0) {
        return 'tron';
    }

    if (strpos($address, '0x') === 0 || strpos($address, '0X') === 0) {
        return 'ethereum';
    }

    if (strpos($address, 'cro') === 0) {
        return 'cronos';
    }

    if (strlen($address) >= 32 && preg_match('/^[1-9A-HJ-NP-Za-km-z]+$/', $address)) {
        return 'solana';
    }

    return 'ethereum';
}

function admin_normalize_crypto_wallet_network(string $assetCode, string $requestedNetworkCode, string $address = ''): string
{
    $assetCode = strtoupper(trim($assetCode));
    $options = admin_crypto_asset_network_options($assetCode);
    if (!$options) {
        return '';
    }

    if (!admin_crypto_asset_allows_network_choice($assetCode)) {
        return (string)array_key_first($options);
    }

    $requestedNetworkCode = strtolower(trim($requestedNetworkCode));
    if ($requestedNetworkCode !== '' && isset($options[$requestedNetworkCode])) {
        return $requestedNetworkCode;
    }

    if ($assetCode === 'USDT' || $assetCode === 'USDC') {
        $inferred = admin_infer_stablecoin_network_by_address($address);
        if (isset($options[$inferred])) {
            return $inferred;
        }
    }

    return (string)array_key_first($options);
}

function admin_crypto_wallet_network_is_evm(string $networkCode): bool
{
    return in_array(strtolower(trim($networkCode)), ['ethereum', 'bnb', 'polygon', 'cronos'], true);
}

function admin_crypto_wallet_address_is_evm_format(string $address): bool
{
    return preg_match('/^0x[a-fA-F0-9]{40}$/', trim($address)) === 1;
}

function admin_schema_index_exists(Mysql_ks $db, string $tableName, string $indexName): bool
{
    $row = $db->select_user(
        "SELECT COUNT(*) AS total
         FROM information_schema.STATISTICS
         WHERE TABLE_SCHEMA = DATABASE()
           AND TABLE_NAME = '" . $db->escape($tableName) . "'
           AND INDEX_NAME = '" . $db->escape($indexName) . "'
         LIMIT 1"
    );

    return is_array($row) && (int)($row['total'] ?? 0) > 0;
}

function admin_ensure_crypto_wallet_address_indexes(Mysql_ks $db): void
{
    static $done = false;
    if ($done || !schema_object_exists($db, 'crypto_wallet_addresses')) {
        return;
    }
    $done = true;

    if (admin_schema_index_exists($db, 'crypto_wallet_addresses', 'uniq_crypto_wallet_addresses_address')) {
        $db->query('ALTER TABLE `crypto_wallet_addresses` DROP INDEX `uniq_crypto_wallet_addresses_address`');
    }

    if (!admin_schema_index_exists($db, 'crypto_wallet_addresses', 'idx_crypto_wallet_addresses_address')) {
        $db->query('ALTER TABLE `crypto_wallet_addresses` ADD INDEX `idx_crypto_wallet_addresses_address` (`address`)');
    }

    if (!admin_schema_index_exists($db, 'crypto_wallet_addresses', 'uniq_crypto_wallet_addresses_asset_network_address')) {
        $db->query('ALTER TABLE `crypto_wallet_addresses` ADD UNIQUE KEY `uniq_crypto_wallet_addresses_asset_network_address` (`crypto_asset_id`, `network_code`, `address`)');
    }
}

function admin_crypto_wallet_existing_address_rows(Mysql_ks $db, string $address, int $excludeWalletId = 0): array
{
    $address = trim($address);
    if ($address === '' || !schema_object_exists($db, 'crypto_wallet_addresses')) {
        return [];
    }

    $excludeSql = $excludeWalletId > 0 ? ' AND wallet.id <> ' . $excludeWalletId : '';
    $rows = $db->select_full_user(
        "SELECT
            wallet.id,
            wallet.crypto_asset_id,
            wallet.label,
            wallet.owner_full_name,
            wallet.address,
            wallet.network_code,
            wallet.memo_tag,
            wallet.wallet_provider,
            wallet.notes,
            asset.code AS asset_code,
            asset.name AS asset_name
         FROM crypto_wallet_addresses AS wallet
         LEFT JOIN crypto_assets AS asset ON asset.id = wallet.crypto_asset_id
         WHERE wallet.address = '" . $db->escape($address) . "'
           {$excludeSql}
         ORDER BY wallet.id ASC"
    );

    return is_array($rows) ? $rows : [];
}

function admin_crypto_wallet_address_duplicate_context(
    Mysql_ks $db,
    string $address,
    int $cryptoAssetId,
    string $networkCode,
    int $excludeWalletId = 0
): array {
    $rows = admin_crypto_wallet_existing_address_rows($db, $address, $excludeWalletId);
    if (!$rows) {
        return [
            'has_existing' => false,
            'can_reuse' => true,
            'rows' => [],
            'canonical' => null,
            'message' => '',
        ];
    }

    $networkCode = strtolower(trim($networkCode));
    $isEvmAddress = admin_crypto_wallet_address_is_evm_format($address);
    $isRequestedEvm = $isEvmAddress && admin_crypto_wallet_network_is_evm($networkCode);
    $hasSameAssetNetwork = false;
    $hasNonEvmExisting = false;
    foreach ($rows as $row) {
        $rowNetwork = strtolower(trim((string)($row['network_code'] ?? '')));
        if ((int)($row['crypto_asset_id'] ?? 0) === $cryptoAssetId && $rowNetwork === $networkCode) {
            $hasSameAssetNetwork = true;
            break;
        }
        if (!$isEvmAddress || !admin_crypto_wallet_network_is_evm($rowNetwork)) {
            $hasNonEvmExisting = true;
        }
    }

    if ($hasSameAssetNetwork) {
        return [
            'has_existing' => true,
            'can_reuse' => false,
            'rows' => $rows,
            'canonical' => $rows[0],
            'message_key' => 'wallet_address_duplicate_same_asset_network',
            'message' => 'This wallet address already exists for this asset and network.',
        ];
    }

    if (!$isRequestedEvm || $hasNonEvmExisting) {
        return [
            'has_existing' => true,
            'can_reuse' => false,
            'rows' => $rows,
            'canonical' => $rows[0],
            'message_key' => 'wallet_address_duplicate_database',
            'message' => 'This wallet address already exists in the database.',
        ];
    }

    return [
        'has_existing' => true,
        'can_reuse' => true,
        'rows' => $rows,
        'canonical' => $rows[0],
        'message_key' => 'wallet_address_evm_reuse_notice',
        'message' => 'This EVM wallet address already exists. Owner details will be reused for consistency.',
    ];
}

function admin_crypto_wallet_existing_address_lookup_payload(Mysql_ks $db, string $address, int $cryptoAssetId = 0, string $networkCode = '', int $excludeWalletId = 0, array $messages = []): array
{
    $asset = $cryptoAssetId > 0 ? $db->select_user("SELECT id, code FROM crypto_assets WHERE id = {$cryptoAssetId} LIMIT 1") : null;
    $assetCode = is_array($asset) ? (string)($asset['code'] ?? '') : '';
    $networkCode = $assetCode !== ''
        ? admin_normalize_crypto_wallet_network($assetCode, $networkCode, $address)
        : strtolower(trim($networkCode));
    $context = admin_crypto_wallet_address_duplicate_context($db, $address, $cryptoAssetId, $networkCode, $excludeWalletId);
    $canonical = is_array($context['canonical'] ?? null) ? $context['canonical'] : [];
    $wallets = [];

    foreach ((array)($context['rows'] ?? []) as $row) {
        $wallets[] = [
            'id' => (int)($row['id'] ?? 0),
            'asset_code' => (string)($row['asset_code'] ?? ''),
            'asset_name' => (string)($row['asset_name'] ?? ''),
            'network_code' => (string)($row['network_code'] ?? ''),
            'network_label' => admin_crypto_network_label((string)($row['network_code'] ?? '')),
            'label' => (string)($row['label'] ?? ''),
        ];
    }

    return [
        'ok' => true,
        'found' => !empty($context['has_existing']),
        'can_reuse' => !empty($context['can_reuse']),
        'message' => admin_t($messages, (string)($context['message_key'] ?? ''), (string)($context['message'] ?? '')),
        'message_key' => (string)($context['message_key'] ?? ''),
        'owner_full_name' => (string)($canonical['owner_full_name'] ?? ''),
        'wallet_provider' => (string)($canonical['wallet_provider'] ?? ''),
        'notes' => (string)($canonical['notes'] ?? ''),
        'memo_tag' => (string)($canonical['memo_tag'] ?? ''),
        'wallets' => $wallets,
    ];
}

function admin_crypto_wallet_companion_target_for_asset(string $assetCode, string $networkCode): array
{
    $assetCode = strtoupper(trim($assetCode));
    $networkCode = strtolower(trim($networkCode));
    if (!admin_crypto_wallet_network_is_evm($networkCode)) {
        return [];
    }

    if (in_array($assetCode, ['ETH', 'BNB', 'POL', 'MATIC'], true)) {
        $usdtNetworks = admin_crypto_asset_network_options('USDT');
        return isset($usdtNetworks[$networkCode])
            ? ['asset_code' => 'USDT', 'network_code' => $networkCode]
            : [];
    }

    if ($assetCode === 'USDT') {
        return ['asset_code' => 'ETH', 'network_code' => 'ethereum'];
    }

    return [];
}

function admin_crypto_wallet_active_customer_payment_asset(Mysql_ks $db, string $assetCode): ?array
{
    $assetCode = strtoupper(trim($assetCode));
    if ($assetCode === '' || !schema_object_exists($db, 'crypto_assets') || !admin_crypto_asset_allows_customer_payments($assetCode)) {
        return null;
    }

    $asset = $db->select_user("SELECT id, code, is_active FROM crypto_assets WHERE UPPER(code) = '" . $db->escape($assetCode) . "' LIMIT 1");
    if (!is_array($asset) || (int)($asset['id'] ?? 0) <= 0 || empty($asset['is_active'])) {
        return null;
    }

    return $asset;
}

function admin_crypto_wallet_active_usdt_asset(Mysql_ks $db): ?array
{
    return admin_crypto_wallet_active_customer_payment_asset($db, 'USDT');
}

function admin_crypto_wallet_create_evm_companion(
    Mysql_ks $db,
    string $sourceAssetCode,
    string $sourceNetworkCode,
    string $label,
    string $ownerFullName,
    string $address,
    string $memoTag,
    string $walletProvider,
    string $status,
    string $notes,
    $disabledAtValue,
    int $adminUserId
): array {
    $messages = admin_load_messages(admin_current_locale());
    $target = admin_crypto_wallet_companion_target_for_asset($sourceAssetCode, $sourceNetworkCode);
    $targetAssetCode = strtoupper((string)($target['asset_code'] ?? ''));
    $networkCode = strtolower((string)($target['network_code'] ?? ''));
    $targetAsset = $targetAssetCode !== ''
        ? admin_crypto_wallet_active_customer_payment_asset($db, $targetAssetCode)
        : null;
    if (!is_array($targetAsset) || $networkCode === '' || !admin_crypto_wallet_address_is_evm_format($address)) {
        return ['ok' => true, 'created' => false, 'wallet_id' => 0];
    }

    $targetAssetId = (int)$targetAsset['id'];
    $existing = $db->select_user(
        "SELECT id
         FROM crypto_wallet_addresses
         WHERE crypto_asset_id = {$targetAssetId}
           AND network_code = '" . $db->escape($networkCode) . "'
           AND address = '" . $db->escape($address) . "'
         LIMIT 1"
    );
    if (is_array($existing) && (int)($existing['id'] ?? 0) > 0) {
        return ['ok' => true, 'created' => false, 'wallet_id' => (int)$existing['id']];
    }

    $duplicateContext = admin_crypto_wallet_address_duplicate_context($db, $address, $targetAssetId, $networkCode, 0);
    if (!empty($duplicateContext['has_existing']) && empty($duplicateContext['can_reuse'])) {
        return [
            'ok' => false,
            'created' => false,
            'wallet_id' => 0,
            'message' => admin_t($messages, (string)($duplicateContext['message_key'] ?? ''), (string)($duplicateContext['message'] ?? 'This wallet address already exists in the database.')),
        ];
    }

    $insertOk = $db->insert(
        ['crypto_asset_id', 'label', 'owner_full_name', 'address', 'network_code', 'memo_tag', 'wallet_provider', 'status', 'notes', 'disabled_at', 'created_by_admin_user_id'],
        [$targetAssetId, $label, $ownerFullName, $address, $networkCode, $memoTag !== '' ? $memoTag : null, $walletProvider !== '' ? $walletProvider : null, $status, $notes !== '' ? $notes : null, $disabledAtValue, $adminUserId],
        'crypto_wallet_addresses'
    );

    if (!$insertOk || (int)$db->id() <= 0) {
        return [
            'ok' => false,
            'created' => false,
            'wallet_id' => 0,
            'message' => admin_t($messages, 'wallet_error_create_evm_companion_failed', 'Unable to create paired EVM wallet for this address.'),
        ];
    }

    return ['ok' => true, 'created' => true, 'wallet_id' => (int)$db->id()];
}

function admin_toggle_crypto_asset(Mysql_ks $db, int $assetId): array
{
    $asset = admin_crypto_asset_find($db, $assetId);
    if (!$asset) {
        return ['ok' => false, 'message' => 'Asset not found.'];
    }

    if (admin_crypto_asset_is_protected($asset)) {
        return ['ok' => false, 'message' => 'Bitcoin cannot be disabled or removed.'];
    }

    $nextState = !empty($asset['is_active']) ? 0 : 1;
    $updated = $db->update_using_id(['is_active'], [$nextState], 'crypto_assets', $assetId);

    return [
        'ok' => (bool)$updated,
        'message' => $updated ? 'Asset status updated.' : 'Unable to update asset status.',
    ];
}

function admin_duration_label_from_hours(int $hours): string
{
    $hours = max(0, $hours);
    if ($hours === 0) {
        return '0h';
    }

    if ($hours % 8760 === 0) {
        $years = (int)($hours / 8760);
        return $years . ' ' . ($years === 1 ? 'Year' : 'Years');
    }

    if ($hours % 720 === 0) {
        $months = (int)($hours / 720);
        return $months . ' ' . ($months === 1 ? 'Month' : 'Months');
    }

    if ($hours % 24 === 0) {
        $days = (int)($hours / 24);
        return $days . ' ' . ($days === 1 ? 'Day' : 'Days');
    }

    return $hours . 'h';
}

function admin_product_duration_options(int $currentHours = 720): array
{
    $options = [6, 12, 24, 720, 1440, 2160, 2880, 3600, 4320, 8760];
    $currentHours = max(0, $currentHours);

    if ($currentHours > 0 && !in_array($currentHours, $options, true)) {
        $options[] = $currentHours;
    }

    sort($options, SORT_NUMERIC);

    return array_map(static function (int $hours): array {
        return [
            'value' => $hours,
            'label' => admin_duration_label_from_hours($hours),
        ];
    }, $options);
}

function admin_product_subscription_requires_trial(int $durationHours): bool
{
    return $durationHours > 0 && $durationHours <= 24;
}

function admin_format_product_option_label(array $productRow): string
{
    $provider = trim((string)($productRow['provider_name'] ?? ''));
    $name = trim((string)($productRow['name'] ?? ''));
    $productType = admin_normalize_product_type($productRow['product_type'] ?? 'subscription');
    $duration = $productType === 'subscription'
        ? admin_duration_label_from_hours((int)($productRow['duration_hours'] ?? 0))
        : '';
    $amount = trim((string)($productRow['price_amount'] ?? '0.00'));
    $currency = trim((string)($productRow['currency_code'] ?? ''));

    $parts = [];
    if ($provider !== '') {
        $parts[] = $provider;
    }
    if ($name !== '') {
        $parts[] = $name;
    }
    if ($duration !== '') {
        $parts[] = $duration;
    }

    $label = implode(' - ', $parts);
    if ($amount !== '' || $currency !== '') {
        $label .= ' · ' . trim($amount . ' ' . $currency);
    }

    return trim($label);
}

function admin_order_product_title(array $orderRow, ?array $messages = null): string
{
    $provider = trim((string)($orderRow['provider_name'] ?? ''));
    $productName = trim((string)($orderRow['product_name'] ?? ''));
    $productType = admin_normalize_product_type((string)($orderRow['product_type'] ?? 'subscription'));
    $durationLabel = admin_duration_label_from_hours((int)($orderRow['duration_hours'] ?? 0));

    if ($productType !== 'subscription') {
        if ($productName !== '') {
            return $productName;
        }
        if ($provider !== '') {
            return $provider;
        }

        return $messages !== null
            ? admin_t($messages, 'product_type_' . $productType, ucfirst($productType))
            : ucfirst($productType);
    }

    if ($provider !== '' && $productName !== '') {
        return $provider . ' / ' . $productName;
    }
    if ($productName !== '') {
        return $productName;
    }
    if ($provider !== '' && $durationLabel !== '') {
        return trim($provider . ' ' . $durationLabel);
    }
    if ($provider !== '') {
        return $provider;
    }
    if ($durationLabel !== '') {
        return $durationLabel;
    }

    return $messages !== null
        ? admin_t($messages, 'col_product', 'Product')
        : 'Product';
}

function admin_product_basic_row(Mysql_ks $db, int $productId): ?array
{
    if ($productId <= 0 || !schema_object_exists($db, 'products')) {
        return null;
    }

    $row = $db->select_user(
        "SELECT
            products.id,
            products.provider_id,
            products.name,
            products.product_type,
            products.duration_hours,
            products.price_amount,
            products.currency_id,
            products.is_active,
            product_providers.name AS provider_name,
            product_providers.supports_manual_delivery,
            " . (schema_column_exists($db, 'product_providers', 'supports_delivery_links') ? "product_providers.supports_delivery_links," : "1 AS supports_delivery_links,") . "
            currencies.code AS currency_code
         FROM products
         LEFT JOIN product_providers ON product_providers.id = products.provider_id
         LEFT JOIN currencies ON currencies.id = products.currency_id
         WHERE products.id = {$productId}
         LIMIT 1"
    );

    return is_array($row) ? $row : null;
}

function admin_create_order(Mysql_ks $db, array $input, ?float $quotedAmount = null): array
{
    $customerId = (int)($input['customer_id'] ?? 0);
    $productId = (int)($input['product_id'] ?? 0);
    $customer = admin_customer_basic_row($db, $customerId);
    $product = admin_product_basic_row($db, $productId);

    if (!$customer) {
        return ['ok' => false, 'message' => 'Customer not found.'];
    }

    if (!$product || empty($product['is_active'])) {
        return ['ok' => false, 'message' => 'Product is not available.'];
    }

    if (!app_customer_provider_is_visible($db, $customerId, (int)($product['provider_id'] ?? 0))) {
        return ['ok' => false, 'message' => 'Selected product is not available for this user.'];
    }

    if ($quotedAmount !== null && (!is_finite($quotedAmount) || $quotedAmount <= 0)) {
        return ['ok' => false, 'message' => 'Invalid quoted order amount.'];
    }

    $note = trim((string)($input['customer_note'] ?? ''));
    $hasDeliveryLink = isset($input['has_delivery_link']) && (string)$input['has_delivery_link'] === '1';
    $deliveryLink = $hasDeliveryLink ? trim((string)($input['delivery_link'] ?? '')) : '';
    $deliveryLinksEnabled = !array_key_exists('supports_delivery_links', $product) || !empty($product['supports_delivery_links']);
    if (!$deliveryLinksEnabled) {
        $hasDeliveryLink = false;
        $deliveryLink = '';
    }
    $deliveryLinkVisible = $deliveryLinksEnabled && $hasDeliveryLink && $deliveryLink !== '' && empty($product['supports_manual_delivery']) ? 1 : 0;

    if ($hasDeliveryLink && $deliveryLink !== '' && filter_var($deliveryLink, FILTER_VALIDATE_URL) === false) {
        return ['ok' => false, 'message' => 'Delivery URL must be a valid link.'];
    }

    $durationHours = (int)($product['duration_hours'] ?? 0);
    $expiresAt = empty($input['defer_expiry']) && admin_product_type_uses_expiry($product['product_type'] ?? 'subscription') && $durationHours > 0
        ? app_subscription_expiry_from_base_timestamp(time(), $durationHours)
        : null;
    $orderReference = 'ADM-' . date('YmdHis') . '-' . $customerId;
    $insertFields = [
        'customer_id',
        'product_id',
        'order_reference',
        'source_system',
        'payment_method',
        'total_amount',
        'currency_id',
        'status',
        'payment_status',
        'fulfillment_status',
        'customer_note',
        'delivery_link',
        'expires_at',
    ];
    $insertValues = [
        $customerId,
        $productId,
        $orderReference,
        'native',
        null,
        $quotedAmount !== null ? number_format($quotedAmount, 2, '.', '') : (string)($product['price_amount'] ?? '0.00'),
        (int)($product['currency_id'] ?? 1),
        'pending_payment',
        'unpaid',
        'pending',
        $note !== '' ? $note : null,
        ($hasDeliveryLink && $deliveryLink !== '') ? $deliveryLink : null,
        $expiresAt,
    ];

    if (schema_column_exists($db, 'orders', 'delivery_link_visible')) {
        array_splice($insertFields, 12, 0, ['delivery_link_visible']);
        array_splice($insertValues, 12, 0, [$deliveryLinkVisible]);
    }

    if (schema_column_exists($db, 'orders', 'created_at') && function_exists('app_current_datetime_string')) {
        $insertFields[] = 'created_at';
        $insertValues[] = app_current_datetime_string();
    }

    $inserted = $db->insert($insertFields, $insertValues, 'orders');

    if (!$inserted) {
        return ['ok' => false, 'message' => 'Unable to create order.'];
    }

    $orderId = (int)$db->id();
    if (schema_object_exists($db, 'order_status_events')) {
        $eventFields = ['order_id', 'admin_user_id', 'old_status', 'new_status', 'event_note'];
        $eventValues = [$orderId, isset($_SESSION['admin_user_id']) ? (int)$_SESSION['admin_user_id'] : null, null, 'pending_payment', 'Order created from admin panel'];
        if (schema_column_exists($db, 'order_status_events', 'created_at') && function_exists('app_current_datetime_string')) {
            $eventFields[] = 'created_at';
            $eventValues[] = app_current_datetime_string();
        }
        $db->insert($eventFields, $eventValues, 'order_status_events');
    }

    app_queue_order_created_notification($db, $orderId);

    return ['ok' => true, 'message' => 'Order created successfully.', 'order_id' => $orderId];
}

function admin_save_order_info(
    Mysql_ks $db,
    int $orderId,
    array $input,
    int $adminUserId = 0,
    string $ipAddress = ''
): array
{
    app_panel_tiers_capture($db, $orderId);
    $order = admin_order_find($db, $orderId);
    if (!$order) {
        return ['ok' => false, 'message' => 'Order not found.'];
    }

    $totalAmountRaw = trim((string)($input['total_amount'] ?? ''));
    if ($totalAmountRaw === '' || !is_numeric($totalAmountRaw)) {
        return ['ok' => false, 'message' => 'Amount must be a valid number.'];
    }
    if ((float)$totalAmountRaw < 0) {
        return ['ok' => false, 'message' => 'Amount cannot be negative.'];
    }

    $deliveryLink = trim((string)($input['delivery_link'] ?? ''));
    $deliveryLinkVisible = isset($input['delivery_link_visible']) && (string)($input['delivery_link_visible']) === '1' ? 1 : 0;
    $deliveryLinksEnabled = !array_key_exists('supports_delivery_links', $order) || !empty($order['supports_delivery_links']);
    if ($deliveryLink !== '' && filter_var($deliveryLink, FILTER_VALIDATE_URL) === false) {
        return ['ok' => false, 'message' => 'Delivery URL must be a valid link.'];
    }
    if (!$deliveryLinksEnabled) {
        $deliveryLinkVisible = 0;
    }
    if ($deliveryLink === '') {
        $deliveryLinkVisible = 0;
    }

    $paymentMethod = trim((string)($input['payment_method'] ?? ''));
    if (!in_array($paymentMethod, admin_order_payment_method_options((string)($order['payment_method'] ?? '')), true)) {
        $paymentMethod = '';
    }

    $status = trim((string)($input['status'] ?? ''));
    $paymentStatus = trim((string)($input['payment_status'] ?? ''));
    $fulfillmentStatus = trim((string)($input['fulfillment_status'] ?? ''));

    if ($status === 'active') {
        $paymentStatus = 'paid';
        $fulfillmentStatus = 'delivered';
    } elseif ($status === 'pending_payment') {
        if ($paymentStatus !== 'paid') {
            $paymentStatus = 'unpaid';
        }
        $fulfillmentStatus = 'pending';
    }

    if (!in_array($status, admin_order_status_options((string)($order['status'] ?? '')), true)) {
        return ['ok' => false, 'message' => 'Order status is invalid.'];
    }
    if (!in_array($paymentStatus, admin_order_payment_status_options((string)($order['payment_status'] ?? '')), true)) {
        return ['ok' => false, 'message' => 'Payment status is invalid.'];
    }
    if (!in_array($fulfillmentStatus, admin_order_fulfillment_status_options((string)($order['fulfillment_status'] ?? '')), true)) {
        return ['ok' => false, 'message' => 'Fulfillment status is invalid.'];
    }

    if (admin_datetime_input_invalid($input['started_at'] ?? null)) {
        return ['ok' => false, 'message' => 'Start date format is invalid. Use e.g. 2026-05-02 17:42 or 23.08.2026 17:42.'];
    }
    if (admin_datetime_input_invalid($input['expires_at'] ?? null)) {
        return ['ok' => false, 'message' => 'Expiry date format is invalid. Use e.g. 2026-05-02 17:42 or 23.08.2026 17:42.'];
    }
    if (admin_datetime_input_invalid($input['paid_at'] ?? null)) {
        return ['ok' => false, 'message' => 'Paid date format is invalid. Use e.g. 2026-05-02 17:42 or 23.08.2026 17:42.'];
    }

    $startedAt = admin_normalize_datetime_input($input['started_at'] ?? null);
    $expiresAt = admin_normalize_datetime_input($input['expires_at'] ?? null);
    $paidAt = admin_normalize_datetime_input($input['paid_at'] ?? null);
    $usesExpiry = admin_product_type_uses_expiry($order['product_type'] ?? 'subscription');

    if (!$usesExpiry) {
        $startedAt = null;
        $expiresAt = null;
    }

    if ($usesExpiry && $status === 'active' && $startedAt === null) {
        $startedAt = date('Y-m-d H:i:s');
    }

    if ($paymentStatus === 'paid' && $paidAt === null) {
        $paidAt = date('Y-m-d H:i:s');
    }

    $wasActiveBefore = strtolower(trim((string)($order['status'] ?? ''))) === 'active';
    $becomesActiveNow = $status === 'active';
    $balanceActivationContext = admin_order_balance_activation_context($db, $order);
    $activationBalanceMode = strtolower(trim((string)($input['activation_balance_mode'] ?? 'require_full')));
    if (!in_array($activationBalanceMode, ['require_full', 'debit_available', 'skip_debit'], true)) {
        $activationBalanceMode = 'require_full';
    }
    $activationBalanceEventNote = '';
    $activationLocale = admin_current_locale();
    if (!$wasActiveBefore && $becomesActiveNow) {
        $activationRequiredAmount = round((float)$totalAmountRaw, 2);
        $activationCurrentBalance = round((float)($balanceActivationContext['current_balance'] ?? 0), 2);
        $activationExistingDebitAmount = round((float)(
            !empty($balanceActivationContext['balance_debit_already_applied'])
                ? ($balanceActivationContext['covered_amount'] ?? 0)
                : 0
        ), 2);
        $activationBudget = $activationExistingDebitAmount > 0 ? $activationExistingDebitAmount : $activationCurrentBalance;
        $canActivateWithFullBalance = $activationBudget + 0.00001 >= $activationRequiredAmount;

        if ($activationBalanceMode === 'skip_debit') {
            $activationBalanceEventNote = $activationLocale === 'pl'
                ? 'Bez pobrania salda.'
                : 'Activated without balance debit.';
        } elseif ($canActivateWithFullBalance) {
            if (empty($balanceActivationContext['balance_debit_already_applied'])) {
                $balanceDebitResult = admin_apply_customer_balance_runtime_event(
                    $db,
                    (int)($order['customer_id'] ?? 0),
                    $activationRequiredAmount,
                    'debit',
                    'order_activation',
                    (string)$orderId,
                    $activationLocale === 'pl'
                        ? 'Aktywowano zamówienie #' . $orderId . '.'
                        : 'Activated order #' . $orderId . '.',
                    $adminUserId,
                    $ipAddress
                );
                if (empty($balanceDebitResult['ok'])) {
                    return $balanceDebitResult;
                }
            }
            $activationBalanceEventNote = $activationLocale === 'pl'
                ? 'Zapłacono z salda.'
                : 'Customer balance debited.';
        } elseif ($activationBalanceMode === 'debit_available') {
            $partialDebitAmount = $activationExistingDebitAmount > 0
                ? 0.0
                : min(max(0.0, $activationCurrentBalance), $activationRequiredAmount);
            if ($activationExistingDebitAmount <= 0 && $partialDebitAmount <= 0.00001) {
                return ['ok' => false, 'message' => 'No customer balance is available for this order. Activate without charging the balance if the payment was handled outside the balance.'];
            }
            $shortfallAmount = max(0.0, round($activationRequiredAmount - ($activationExistingDebitAmount > 0 ? $activationExistingDebitAmount : $partialDebitAmount), 2));
            $activationCurrencyCode = strtoupper(trim((string)($order['currency_code'] ?? '')));
            $shortfallNote = ($activationLocale === 'pl' ? 'Za mało -' : 'Low balance -')
                . number_format($shortfallAmount, 2, '.', '')
                . ($activationCurrencyCode !== '' ? ' ' . $activationCurrencyCode : '')
                . '.';
            if ($partialDebitAmount > 0) {
                $balanceDebitResult = admin_apply_customer_balance_runtime_event(
                    $db,
                    (int)($order['customer_id'] ?? 0),
                    $partialDebitAmount,
                    'debit',
                    'order_activation',
                    (string)$orderId,
                    $activationLocale === 'pl'
                        ? 'Aktywowano zamówienie #' . $orderId . ' z dostępnego salda. ' . $shortfallNote
                        : 'Activated order #' . $orderId . ' with available balance. ' . $shortfallNote,
                    $adminUserId,
                    $ipAddress
                );
                if (empty($balanceDebitResult['ok'])) {
                    return $balanceDebitResult;
                }
            }
            $activationBalanceEventNote = $shortfallNote;
        } else {
            return ['ok' => false, 'message' => 'Customer balance is too low to activate this order. Choose whether to deduct the available balance or activate without charging the balance.'];
        }
    }

    if ($activationBalanceEventNote !== '') {
        $supportNoteInput = admin_localize_order_support_note_text(trim((string)($input['support_note'] ?? '')));
        if (stripos($supportNoteInput, $activationBalanceEventNote) === false) {
            $input['support_note'] = trim($supportNoteInput . ($supportNoteInput !== '' ? "\n" : '') . $activationBalanceEventNote);
        } else {
            $input['support_note'] = $supportNoteInput;
        }
    }
    $supportNoteValue = admin_localize_order_support_note_text(trim((string)($input['support_note'] ?? '')));

    $updateFields = [
        'order_reference',
        'payment_method',
        'total_amount',
        'customer_note',
        'support_note',
        'delivery_link',
        'transaction_reference',
        'started_at',
        'expires_at',
        'paid_at',
        'status',
        'payment_status',
        'fulfillment_status',
    ];
    $updateValues = [
        trim((string)($input['order_reference'] ?? '')) ?: null,
        $paymentMethod !== '' ? $paymentMethod : null,
        number_format((float)$totalAmountRaw, 2, '.', ''),
        trim((string)($input['customer_note'] ?? '')) ?: null,
        $supportNoteValue !== '' ? $supportNoteValue : null,
        $deliveryLink !== '' ? $deliveryLink : null,
        trim((string)($input['transaction_reference'] ?? '')) ?: null,
        $startedAt,
        $expiresAt,
        $paidAt,
        $status,
        $paymentStatus,
        $fulfillmentStatus,
    ];

    if (schema_column_exists($db, 'orders', 'delivery_link_visible')) {
        array_splice($updateFields, 6, 0, ['delivery_link_visible']);
        array_splice($updateValues, 6, 0, [$deliveryLinkVisible]);
    }

    $updated = $db->update_using_id($updateFields, $updateValues, 'orders', $orderId);

    if ($updated && !$wasActiveBefore && $becomesActiveNow) {
        admin_cancel_open_order_payment_requests(
            $db,
            (int)($order['customer_id'] ?? 0),
            $orderId
        );
    }

    if ($updated && schema_object_exists($db, 'order_status_events') && $status !== (string)($order['status'] ?? '')) {
        $eventFields = ['order_id', 'admin_user_id', 'old_status', 'new_status', 'event_note'];
        $eventNote = $activationBalanceEventNote !== '' ? $activationBalanceEventNote : 'Order updated from admin modal';
        $eventValues = [$orderId, isset($_SESSION['admin_user_id']) ? (int)$_SESSION['admin_user_id'] : null, (string)($order['status'] ?? ''), $status, admin_localize_activity_description('order_status_event', $eventNote)];
        if (schema_column_exists($db, 'order_status_events', 'created_at') && function_exists('app_current_datetime_string')) {
            $eventFields[] = 'created_at';
            $eventValues[] = app_current_datetime_string();
        }
        $db->insert($eventFields, $eventValues, 'order_status_events');
    }

    $billingDeliveryResult = null;
    if ($updated) {
        $freshOrder = admin_order_find($db, $orderId);
        if (is_array($freshOrder)) {
            app_queue_order_transition_notifications($db, $order, $freshOrder);
        }

        $changes = [];
        if ((string)($order['status'] ?? '') !== $status) {
            $changes[] = 'status ' . (string)($order['status'] ?? 'unknown') . ' -> ' . $status;
        }
        if ((string)($order['payment_status'] ?? '') !== $paymentStatus) {
            $changes[] = 'payment ' . (string)($order['payment_status'] ?? 'unknown') . ' -> ' . $paymentStatus;
        }
        if ((string)($order['fulfillment_status'] ?? '') !== $fulfillmentStatus) {
            $changes[] = 'fulfillment ' . (string)($order['fulfillment_status'] ?? 'unknown') . ' -> ' . $fulfillmentStatus;
        }

        $actionKey = ((string)($order['payment_status'] ?? '') !== 'paid' && $paymentStatus === 'paid')
            ? 'order_payment_approved'
            : 'order_updated';

        $activityDescription = 'Order #' . $orderId . ' updated' . ($changes ? ': ' . implode(', ', $changes) . '.' : '.');
        if ($activationBalanceEventNote !== '') {
            $activityDescription .= ' ' . rtrim($activationBalanceEventNote, '.') . '.';
        }

        admin_log_customer_and_admin(
            $db,
            (int)($order['customer_id'] ?? 0),
            $adminUserId,
            $actionKey,
            $activityDescription,
            $ipAddress
        );

        if (!$wasActiveBefore && $becomesActiveNow && !empty($input['issue_billing_document_email'])) {
            $billingDeliveryResult = admin_billing_issue_and_email_for_order($db, $orderId, $adminUserId);
        }
    }

    $resultMessage = $updated ? 'Order updated successfully.' : 'Unable to update order.';
    if ($updated && is_array($billingDeliveryResult)) {
        $isPolishAdmin = admin_current_locale() === 'pl';
        $resultMessage .= !empty($billingDeliveryResult['ok'])
            ? ($isPolishAdmin ? ' Rachunek został wystawiony i wysłany.' : ' Billing document issued and emailed.')
            : ($isPolishAdmin ? ' Rachunek nie został wysłany: ' : ' Billing document was not sent: ')
                . (string)($billingDeliveryResult['message'] ?? ($isPolishAdmin ? 'sprawdź ustawienia modułu Rachunki.' : 'check Billing settings.'));
    }

    return [
        'ok' => (bool)$updated,
        'message' => $resultMessage,
    ];
}

function admin_order_product_can_extend(array $product): bool
{
    if (empty($product['is_active'])) {
        return false;
    }

    if (strtolower(trim((string)($product['product_type'] ?? 'subscription'))) !== 'subscription') {
        return false;
    }

    if (!empty($product['is_trial'])) {
        return false;
    }

    return (int)($product['duration_hours'] ?? 0) > 24;
}

function admin_order_can_delete(array $order): bool
{
    $status = strtolower(trim((string)($order['status'] ?? '')));
    $paymentStatus = strtolower(trim((string)($order['payment_status'] ?? '')));
    $fulfillmentStatus = strtolower(trim((string)($order['fulfillment_status'] ?? '')));

    if (in_array($status, ['expired', 'cancelled', 'failed', 'inactive', 'pending_payment'], true)) {
        return true;
    }

    $usesSubscriptionTiming = admin_product_type_uses_expiry($order['product_type'] ?? 'subscription');
    if ($usesSubscriptionTiming && (string)(admin_order_progress_data($order)['tone'] ?? '') === 'expired') {
        return true;
    }

    $isActiveStatus = in_array($status, ['active', 'approved', 'completed', 'fulfilled'], true);
    $isPaid = $paymentStatus === 'paid';
    $isFulfilled = in_array($fulfillmentStatus, ['delivered', 'fulfilled', 'completed', 'shipped', 'sent'], true);

    return !($isActiveStatus && $isPaid && $isFulfilled);
}

function admin_delete_order(
    Mysql_ks $db,
    int $orderId,
    int $adminUserId = 0,
    string $ipAddress = ''
): array
{
    app_panel_tiers_capture($db, $orderId);
    $order = admin_order_find($db, $orderId);
    if (!$order) {
        return ['ok' => false, 'message' => 'Order not found.'];
    }

    if (!admin_order_can_delete($order)) {
        return [
            'ok' => false,
            'message' => 'An active and completed order cannot be deleted.',
            'message_key' => 'order_delete_active_blocked',
        ];
    }

    $customerId = (int)($order['customer_id'] ?? 0);

    admin_cancel_open_order_payment_requests($db, $customerId, $orderId);

    if (schema_object_exists($db, 'crypto_deposit_requests') && schema_column_exists($db, 'crypto_deposit_requests', 'order_id')) {
        @$db->query(
            "UPDATE crypto_deposit_requests
             SET order_id = NULL,
                 request_note = CONCAT(
                     COALESCE(NULLIF(request_note, ''), 'Created as balance top-up after order deletion'),
                     CASE
                         WHEN COALESCE(request_note, '') LIKE '%Converted to balance top-up after order deletion%'
                         THEN ''
                         ELSE '\nConverted to balance top-up after order deletion'
                     END
                 )
             WHERE order_id = {$orderId}"
        );
    }

    if (schema_object_exists($db, 'bank_transfer_requests') && schema_column_exists($db, 'bank_transfer_requests', 'order_id')) {
        @$db->query(
            "UPDATE bank_transfer_requests
             SET order_id = NULL,
                 admin_review_note = CONCAT(
                     COALESCE(NULLIF(admin_review_note, ''), 'Created as balance top-up after order deletion'),
                     CASE
                         WHEN COALESCE(admin_review_note, '') LIKE '%Converted to balance top-up after order deletion%'
                         THEN ''
                         ELSE '\nConverted to balance top-up after order deletion'
                     END
                 )
             WHERE order_id = {$orderId}"
        );
    }

    if (schema_object_exists($db, 'order_status_events')) {
        @$db->query("DELETE FROM order_status_events WHERE order_id = {$orderId}");
    }

    $deleted = $db->delete_using_id('orders', $orderId);
    if (!$deleted) {
        return ['ok' => false, 'message' => 'Unable to delete order.'];
    }

    admin_log_customer_and_admin(
        $db,
        (int)($order['customer_id'] ?? 0),
        $adminUserId,
        'order_deleted',
        'Order #' . $orderId . ' deleted from admin panel.',
        $ipAddress
    );

    return ['ok' => true, 'message' => 'Order deleted successfully.'];
}

/** Validate the exact renewal reservation, including customer and full amount. */
function admin_order_renewal_balance_state(Mysql_ks $db, array $renewal): string
{
    $id = (int)($renewal['id'] ?? 0);
    $customerId = (int)($renewal['customer_id'] ?? 0);
    $amount = round((float)($renewal['price_amount'] ?? 0), 2);
    if ($id <= 0 || $customerId <= 0 || $amount <= 0 || !schema_object_exists($db, 'customer_balance_runtime_events')) return 'missing';
    $events = $db->select_full_user("SELECT customer_id, amount FROM customer_balance_runtime_events
        WHERE source_type = 'order_extension' AND direction = 'debit'
          AND source_key IN ('renewal:{$id}', 'renewal:balance:{$id}') LIMIT 2");
    if ($db->error) return 'invalid';
    if (!$events) return 'missing';
    foreach ($events as $event) {
        if ((int)$event['customer_id'] !== $customerId || abs(round((float)$event['amount'], 2) - $amount) > 0.00001) return 'invalid';
    }
    return count($events) === 1 ? 'reserved' : 'invalid';
}

function admin_order_renewal_balance_reserved(Mysql_ks $db, array $renewal): bool
{
    return admin_order_renewal_balance_state($db, $renewal) === 'reserved';
}

function admin_extend_order(
    Mysql_ks $db,
    int $orderId,
    int $productId,
    bool $chargeCustomerBalance = true,
    string $overrideExpiresAt = '',
    ?string $expectedExpiresAt = null,
    int $expectedRenewalId = 0,
    string $supportNote = ''
): array {
    $order = admin_order_find($db, $orderId);
    if (!$order) return ['ok' => false, 'message' => 'Order not found.'];
    // Share the payment lock: approval and manual extension cannot race for one customer.
    $key = 'payment:' . substr(hash('sha256', (string)getenv('DB_NAME')), 0, 16) . ':' . (int)$order['customer_id'];
    $lock = $db->select_user("SELECT GET_LOCK('" . $db->escape($key) . "', 0) acquired");
    if ((int)($lock['acquired'] ?? 0) !== 1) return ['ok' => false, 'message' => 'Another payment operation is in progress. Please retry shortly.'];
    try {
        $result = admin_extend_order_locked($db, $orderId, $productId, $chargeCustomerBalance, $overrideExpiresAt, $expectedExpiresAt, $expectedRenewalId, $supportNote);
        $messageKeys = [
            'This renewal has already been applied.' => 'order_extend_already_applied',
            'The order changed after this form was opened. Refresh before extending it again.' => 'order_extend_changed',
            'Renewal balance reservation does not match its customer or amount. Verify the payment before extending.' => 'order_extend_reservation_mismatch',
            'Customer balance is too low for this action.' => 'order_extend_low_balance',
            'Unable to complete subscription extension. Refresh the order and check the balance before retrying.' => 'order_extend_failed',
        ];
        if (isset($messageKeys[$result['message'] ?? ''])) $result['message_key'] = $messageKeys[$result['message']];
        return $result;
    } finally {
        $db->select_user("SELECT RELEASE_LOCK('" . $db->escape($key) . "') released");
    }
}

function admin_extend_order_locked(
    Mysql_ks $db,
    int $orderId,
    int $productId,
    bool $chargeCustomerBalance = true,
    string $overrideExpiresAt = '',
    ?string $expectedExpiresAt = null,
    int $expectedRenewalId = 0,
    string $supportNote = ''
): array
{
    $supportNote = trim($supportNote);
    if ((function_exists('mb_strlen') ? mb_strlen($supportNote,'UTF-8') : strlen($supportNote)) > 4000) return ['ok'=>false,'message'=>'Support annotation is too long.','message_key'=>'order_extend_support_note_too_long'];
    app_panel_tiers_capture($db, $orderId);
    $order = admin_order_find($db, $orderId);
    $product = admin_product_basic_row($db, $productId);
    $adminUserId = isset($_SESSION['admin_user_id']) ? (int)$_SESSION['admin_user_id'] : 0;
    $ipAddress = (string)($_SERVER['REMOTE_ADDR'] ?? '');

    if (!$order) {
        return ['ok' => false, 'message' => 'Order not found.'];
    }

    if (!$product || empty($product['is_active'])) {
        return ['ok' => false, 'message' => 'Extension package is not available.'];
    }

    if ((int)($product['provider_id'] ?? 0) <= 0 || (int)($product['provider_id'] ?? 0) !== (int)($order['provider_id'] ?? 0)) {
        return ['ok' => false, 'message' => 'You can only extend the order with a package from the same provider.'];
    }

    if (!admin_order_product_can_extend($product)) {
        return ['ok' => false, 'message' => 'Selected package cannot be used for subscription extension.'];
    }

    $orderStatus = strtolower(trim((string)($order['status'] ?? '')));
    $orderPaymentStatus = strtolower(trim((string)($order['payment_status'] ?? '')));
    if (!in_array($orderStatus, ['active', 'expired'], true) || $orderPaymentStatus !== 'paid') {
        return ['ok' => false, 'message' => 'Only active or expired paid orders can be extended.'];
    }

    if ($expectedRenewalId > 0) {
        $submittedRenewal = $db->select_user("SELECT status, product_id FROM order_renewals WHERE id = {$expectedRenewalId} AND order_id = {$orderId} LIMIT 1");
        if (($submittedRenewal['status'] ?? '') === 'applied' && (int)$submittedRenewal['product_id'] === $productId) {
            return ['ok' => true, 'already_applied' => true, 'message' => 'This renewal has already been applied.'];
        }
    }
    if ($expectedExpiresAt !== null && trim((string)($order['expires_at'] ?? '')) !== trim($expectedExpiresAt)) {
        return ['ok' => false, 'message' => 'The order changed after this form was opened. Refresh before extending it again.'];
    }

    $durationHours = (int)($product['duration_hours'] ?? 0);
    if ($durationHours <= 0) {
        return ['ok' => false, 'message' => 'Selected package has no duration.'];
    }

    $pendingRenewal = app_order_find_pending_renewal($db, $orderId);
    if (is_array($pendingRenewal) && !empty($pendingRenewal['id']) && strtolower(trim((string)($pendingRenewal['status'] ?? ''))) === 'paid_pending_activation') {
        $pendingProductId = (int)($pendingRenewal['product_id'] ?? 0);
        if ($pendingProductId > 0 && $pendingProductId !== $productId) {
            return ['ok' => false, 'message' => 'This payment was approved for another package. Select the same package or create a new payment request.'];
        }

        if (trim((string)$overrideExpiresAt) !== '') {
            $overrideExpiresAtTimestamp = app_timestamp_from_runtime_datetime(str_replace('T', ' ', (string)$overrideExpiresAt));
            if ($overrideExpiresAtTimestamp <= 0) {
                return ['ok' => false, 'message' => 'Invalid custom expiry date format.'];
            }
            $currentExpiry = !empty($order['expires_at']) && function_exists('app_timestamp_from_runtime_datetime')
                ? app_timestamp_from_runtime_datetime((string)$order['expires_at'])
                : (!empty($order['expires_at']) ? strtotime((string)$order['expires_at']) : 0);
            $baseTimestamp = $currentExpiry > time() ? $currentExpiry : time();
            if ($overrideExpiresAtTimestamp <= $baseTimestamp) {
                return ['ok' => false, 'message' => 'Custom expiry date must be later than current extension base date.'];
            }

            if (schema_object_exists($db, 'order_renewals')) {
                $db->update_using_id(
                    ['target_expires_at'],
                    [date('Y-m-d H:i:s', $overrideExpiresAtTimestamp)],
                    'order_renewals',
                    (int)($pendingRenewal['id'] ?? 0)
                );
            }
        }

        $reservationState = admin_order_renewal_balance_state($db, $pendingRenewal);
        if ($reservationState === 'invalid') return ['ok' => false, 'message' => 'Renewal balance reservation does not match its customer or amount. Verify the payment before extending.'];
        $applyResult = app_apply_pending_order_renewal(
            $db,
            (int)$pendingRenewal['id'],
            'admin',
            $adminUserId,
            $ipAddress,
            $reservationState === 'reserved',
            $supportNote
        );
        if (empty($applyResult['ok'])) {
            return $applyResult;
        }

        return [
            'ok' => true,
            'message' => 'Subscription extended successfully.',
        ];
    }

    $now = time();
    $currentExpiry = !empty($order['expires_at']) && function_exists('app_timestamp_from_runtime_datetime')
        ? app_timestamp_from_runtime_datetime((string)$order['expires_at'])
        : (!empty($order['expires_at']) ? strtotime((string)$order['expires_at']) : 0);
    $baseTimestamp = $currentExpiry > $now ? $currentExpiry : $now;
    $normalizedOverrideExpiresAt = trim((string)$overrideExpiresAt);
    if ($normalizedOverrideExpiresAt !== '') {
        $overrideExpiresAtTimestamp = app_timestamp_from_runtime_datetime(str_replace('T', ' ', $normalizedOverrideExpiresAt));
        if ($overrideExpiresAtTimestamp <= 0) {
            return ['ok' => false, 'message' => 'Invalid custom expiry date format.'];
        }
        if ($overrideExpiresAtTimestamp <= $baseTimestamp) {
            return ['ok' => false, 'message' => 'Custom expiry date must be later than current extension base date.'];
        }
        $newExpiry = date('Y-m-d H:i:s', $overrideExpiresAtTimestamp);
    } else {
        $newExpiry = app_subscription_expiry_from_base_timestamp($baseTimestamp, $durationHours);
    }
    $extensionAmount = round((float)($product['price_amount'] ?? 0), 2);
    $previousStatus = strtolower(trim((string)($order['status'] ?? '')));
    $nextStatus = strtotime($newExpiry) > time() ? 'active' : 'expired';

    app_ensure_sales_runtime_columns($db);
    app_ensure_order_renewal_runtime_columns($db);
    app_ensure_customer_balance_runtime_table($db);
    if (!$db->query('START TRANSACTION')) return ['ok' => false, 'message' => 'Unable to start extension.'];
    try {
        $lockedOrder = $db->select_user("SELECT expires_at, status, payment_status, support_note FROM orders WHERE id = {$orderId} FOR UPDATE");
        if (!is_array($lockedOrder) || (string)($lockedOrder['expires_at'] ?? '') !== (string)($order['expires_at'] ?? '')
            || !in_array((string)$lockedOrder['status'], ['active', 'expired'], true) || (string)$lockedOrder['payment_status'] !== 'paid') {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'The order changed after this form was opened. Refresh before extending it again.'];
        }
        $combinedSupportNote = (string)($lockedOrder['support_note'] ?? '');
        if ($supportNote !== '') $combinedSupportNote = rtrim($combinedSupportNote) . ($combinedSupportNote !== '' ? "\n" : '') . $supportNote;
        if (strlen($combinedSupportNote) > 65535) throw new RuntimeException('Support note exceeds storage limit.');
        app_preserve_initial_order_sale($db, $orderId);

        if ($chargeCustomerBalance && $extensionAmount > 0) {
            $balanceDebitResult = admin_apply_customer_balance_runtime_event(
                $db,
                (int)($order['customer_id'] ?? 0),
                $extensionAmount,
                'debit',
                'order_extension',
                $orderId . ':' . $productId . ':' . $newExpiry,
                'Extended order #' . $orderId . ' with package #' . $productId,
                $adminUserId,
                $ipAddress,
                true
            );
            if (empty($balanceDebitResult['ok'])) {
                $db->query('ROLLBACK');
                return $balanceDebitResult;
            }
        }

        $updated = $db->update_using_id(
            ['product_id', 'total_amount', 'currency_id', 'expires_at', 'status', 'support_note'],
            [
                $productId,
                number_format((float)($product['price_amount'] ?? 0), 2, '.', ''),
                (int)($product['currency_id'] ?? ($order['product_currency_id'] ?? 1)),
                $newExpiry,
                $nextStatus,
                $combinedSupportNote,
            ],
            'orders',
            $orderId
        );

        if (!$updated) throw new RuntimeException('Unable to update order expiry.');

        if (schema_object_exists($db, 'order_renewals')) {
            app_ensure_order_renewal_runtime_columns($db);
            $renewalInserted = $db->insert(
                ['order_id', 'customer_id', 'product_id', 'price_amount', 'currency_id', 'duration_hours', 'status', 'requested_at', 'applied_at', 'paid_at', 'target_expires_at', 'renewal_note'],
                [
                    $orderId,
                    (int)($order['customer_id'] ?? 0),
                    $productId,
                    $chargeCustomerBalance ? $extensionAmount : 0,
                    (int)($product['currency_id'] ?? ($order['product_currency_id'] ?? 1)),
                    $durationHours,
                    'applied',
                    app_current_datetime_string(),
                    app_current_datetime_string(),
                    $chargeCustomerBalance ? app_current_datetime_string() : null,
                    $newExpiry,
                    $chargeCustomerBalance ? 'Extended from admin panel' : 'Extended from admin panel without charging customer balance',
                ],
                'order_renewals'
            );
            if (!$renewalInserted) throw new RuntimeException('Unable to record subscription extension.');
        }

        if ($updated && schema_object_exists($db, 'order_status_events')) {
            $db->insert(
                ['order_id', 'admin_user_id', 'old_status', 'new_status', 'event_note'],
                [
                    $orderId,
                    $adminUserId > 0 ? $adminUserId : null,
                    (string)($order['status'] ?? ''),
                    $nextStatus,
                    'Order extended by ' . admin_duration_label_from_hours($durationHours) . ($chargeCustomerBalance ? '' : ' without charging customer balance')
                ],
                'order_status_events'
            );
        }

        if (!$db->query('COMMIT')) throw new RuntimeException('Unable to complete subscription extension.');
    } catch (Throwable $exception) {
        $db->query('ROLLBACK');
        return ['ok' => false, 'message' => 'Unable to complete subscription extension. Refresh the order and check the balance before retrying.'];
    }

    if ($updated) {
        if (!$chargeCustomerBalance) {
            app_customer_activity_log(
                $db,
                (int)($order['customer_id'] ?? 0),
                'order_extended',
                'Subscription in order #' . $orderId . ' was extended until ' . $newExpiry . ' by admin without charging account balance.',
                'admin',
                $adminUserId,
                $ipAddress
            );
            admin_activity_log(
                $db,
                0,
                $adminUserId,
                'order_extended',
                'Extended order #' . $orderId . ' with package #' . $productId . ' without charging customer balance.',
                $ipAddress
            );
        }
        app_queue_order_extended_notification($db, $orderId);
    }

    return [
        'ok' => (bool)$updated,
        'message' => $updated ? 'Subscription extended successfully.' : 'Unable to extend subscription.',
        'status_changed' => $updated ? ($previousStatus !== $nextStatus) : false,
        'next_status' => $updated ? $nextStatus : '',
    ];
}

function admin_customer_basic_row(Mysql_ks $db, int $customerId): ?array
{
    if ($customerId <= 0 || !schema_object_exists($db, 'customers')) {
        return null;
    }

    $row = $db->select_user(
        "SELECT id, email, public_handle, avatar_url, status, locale_code
         FROM customers
         WHERE id = {$customerId}
         LIMIT 1"
    );

    return is_array($row) ? $row : null;
}

function admin_create_customer_from_email(Mysql_ks $db, string $email, array $settings, string $clientIp = ''): array
{
    $email = strtolower(trim($email));
    if ($email === '' || !filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return ['ok' => false, 'message' => 'Please enter a valid email address.'];
    }

    $existingCustomer = app_find_customer_by_email($db, $email);
    if ($existingCustomer) {
        return [
            'ok' => true,
            'customer' => [
                'id' => (int)($existingCustomer['id'] ?? 0),
                'email' => (string)($existingCustomer['email'] ?? ''),
                'status' => (string)($existingCustomer['status'] ?? ''),
                'locale_code' => (string)($existingCustomer['locale_code'] ?? ''),
                'created' => false,
            ],
        ];
    }

    $localeCode = trim((string)($settings['default_locale_code'] ?? 'en'));
    if ($localeCode === '') {
        $localeCode = 'en';
    }

    $currentTime = date('Y-m-d H:i:s');
    $temporaryPassword = bin2hex(random_bytes(12));
    $customerId = app_insert_customer_registration(
        $db,
        $email,
        $temporaryPassword,
        $localeCode,
        $currentTime,
        $clientIp,
        1
    );

    if ($customerId <= 0) {
        return ['ok' => false, 'message' => 'Unable to create customer.'];
    }

    $customer = app_find_customer_by_id($db, $customerId);
    if (!$customer) {
        return ['ok' => false, 'message' => 'Customer was created, but could not be loaded.'];
    }

    app_queue_account_created_notification($db, $customerId);

    return [
        'ok' => true,
        'customer' => [
            'id' => (int)($customer['id'] ?? 0),
            'email' => (string)($customer['email'] ?? ''),
            'status' => (string)($customer['status'] ?? ''),
            'locale_code' => (string)($customer['locale_code'] ?? ''),
            'created' => true,
        ],
    ];
}

function admin_customer_status_options(string $current = ''): array
{
    $options = ['active', 'inactive', 'blocked'];
    $current = strtolower(trim($current));
    if ($current !== '' && !in_array($current, $options, true)) {
        $options[] = $current;
    }

    return $options;
}

function admin_generate_customer_password(int $length = 12): string
{
    $alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%';
    $alphabetLength = strlen($alphabet);
    $length = max(10, min(32, $length));
    $password = '';

    for ($i = 0; $i < $length; $i++) {
        $password .= $alphabet[random_int(0, $alphabetLength - 1)];
    }

    return $password;
}

function admin_queue_customer_password_email(
    Mysql_ks $db,
    int $customerId,
    string $email,
    string $plainPassword,
    string $localeCode,
    bool $deliverNow = true
): array {
    $result = app_email_queue_template(
        $db,
        'password-reset',
        $email,
        [
            'customer_email' => $email,
            'password' => $plainPassword,
        ],
        $customerId,
        null,
        0,
        $deliverNow,
        $localeCode
    );

    $queueId = (int)($result['queue_id'] ?? 0);
    if ($queueId <= 0 || !schema_object_exists($db, 'outbound_email_queue')) {
        return $result;
    }

    $queueRow = $db->select_user(
        "SELECT status, last_error
         FROM outbound_email_queue
         WHERE id = {$queueId}
         LIMIT 1"
    );

    if (!is_array($queueRow)) {
        return $result;
    }

    $status = strtolower(trim((string)($queueRow['status'] ?? 'pending')));
    $lastError = trim((string)($queueRow['last_error'] ?? ''));

    $result['status'] = $status;
    $result['sent'] = $status === 'sent';
    $result['failed'] = $status === 'failed';
    $result['last_error'] = $lastError;

    if ($status === 'failed' && $lastError !== '') {
        $result['message'] = $lastError;
    }

    return $result;
}

function admin_create_customer_account(
    Mysql_ks $db,
    string $email,
    string $plainPassword,
    array $options,
    int $adminUserId,
    string $ipAddress = ''
): array {
    if (!schema_object_exists($db, 'customers')) {
        return ['ok' => false, 'message' => 'Customers table is missing.'];
    }

    app_ensure_customer_runtime_columns($db);

    $email = strtolower(trim($email));
    if ($email === '' || !filter_var($email, FILTER_VALIDATE_EMAIL)) {
        return ['ok' => false, 'message' => 'Enter a valid email address.'];
    }

    $existing = app_find_customer_by_email($db, $email);
    if ($existing) {
        return ['ok' => false, 'message' => 'This email address is already assigned to another user.'];
    }

    $plainPassword = trim($plainPassword);
    if ($plainPassword === '') {
        $plainPassword = admin_generate_customer_password();
    }

    $localeCode = admin_normalize_locale((string)($options['locale_code'] ?? 'en'));
    $status = strtolower(trim((string)($options['status'] ?? 'active')));
    $customerType = app_normalize_customer_type((string)($options['customer_type'] ?? 'client'));
    if (!in_array($status, admin_customer_status_options($status), true)) {
        $status = 'active';
    }
    if ($customerType === '') {
        $customerType = 'client';
    }

    $sendPasswordEmail = !empty($options['send_password_email']);
    $emailNotification = array_key_exists('email_notification', $options)
        ? (!empty($options['email_notification']) ? 1 : 0)
        : (array_key_exists('is_newsletter_subscribed', $options) ? (!empty($options['is_newsletter_subscribed']) ? 1 : 0) : 1);
    $currentTime = date('Y-m-d H:i:s');
    $handleResult = app_resolve_customer_public_handle($db, (string)($options['public_handle'] ?? ''), $email);
    if (empty($handleResult['ok'])) {
        return ['ok' => false, 'message' => (string)($handleResult['message'] ?? 'Unable to generate username.')];
    }

    $storedHash = '';
    if (!empty($options['import_password_hash']) && !empty($options['imported_account'])) {
        require_once __DIR__.'/customer_import_lib.php';
        $importCredential = admin_customer_import_password((string)$options['import_password_hash']);
        if ($importCredential['mode'] !== 'hash') return ['ok'=>false,'message'=>'Unsupported password hash.'];
        $storedHash = $importCredential['value'];
    }
    if ($storedHash === '') $storedHash = password_hash($plainPassword, PASSWORD_DEFAULT);

    $insertFields = [
        'email',
        'public_handle',
        'password_hash',
        'password_hash_algorithm',
        'locale_code',
        'ip_address',
        'status',
        'customer_type',
        'email_verified_at',
        'registered_at',
        'last_login_at',
    ];
    $insertValues = [
        $email,
        (string)($handleResult['handle'] ?? ''),
        $storedHash,
        'password_hash',
        $localeCode,
        empty($options['imported_account']) && $ipAddress !== '' ? $ipAddress : null,
        $status,
        $customerType,
        $currentTime,
        $currentTime,
        null,
    ];

    $notificationColumn = app_customer_notification_storage_column($db);
    if ($notificationColumn !== '') {
        $insertFields[] = $notificationColumn;
        $insertValues[] = $emailNotification;
    }

    $inserted = $db->insert($insertFields, $insertValues, 'customers');

    if (!$inserted) {
        return ['ok' => false, 'message' => 'Unable to create customer.'];
    }

    $customerId = (int)$db->id();
    if ($customerId <= 0) {
        return ['ok' => false, 'message' => 'Customer was created, but could not be loaded.'];
    }

    if (array_key_exists('provider_visibility_form_present', $options)) {
        $visibleProviderIds = array_map('intval', (array)($options['visible_provider_ids'] ?? []));
        app_save_customer_provider_visibility($db, $customerId, $visibleProviderIds);
    }

    admin_log_customer_and_admin(
        $db,
        $customerId,
        $adminUserId,
        'account_created',
        'Customer account created by admin.',
        $ipAddress
    );

    $emailResult = ['ok' => false, 'queued' => false];
    if ($sendPasswordEmail) {
        $emailResult = admin_queue_customer_password_email($db, $customerId, $email, $plainPassword, $localeCode, empty($options['defer_password_email']));
    }

    return [
        'ok' => true,
        'message' => 'Customer created successfully.',
        'customer_id' => $customerId,
        'email' => $email,
        'password' => $plainPassword,
        'locale_code' => $localeCode,
        'status' => $status,
        'email_notification' => $emailResult,
    ];
}

function admin_set_customer_password(
    Mysql_ks $db,
    int $customerId,
    array $payload,
    int $adminUserId,
    string $ipAddress = ''
): array {
    if ($customerId <= 0 || !schema_object_exists($db, 'customers')) {
        return ['ok' => false, 'message' => 'Customer not found.', 'message_key' => 'customer_not_found'];
    }

    $customer = app_find_customer_by_id($db, $customerId);
    if (!$customer) {
        return ['ok' => false, 'message' => 'Customer not found.', 'message_key' => 'customer_not_found'];
    }

    $password = trim((string)($payload['new_password'] ?? ''));
    $repeatPassword = trim((string)($payload['repeat_password'] ?? ''));
    $sendPasswordEmail = !empty($payload['send_password_email']);

    if ($password === '') {
        return ['ok' => false, 'message' => 'Enter a new password.', 'message_key' => 'change_password_error_new_required'];
    }

    if (strlen($password) > 72) {
        return ['ok' => false, 'message' => 'New password must be shorter than 72 characters.', 'message_key' => 'change_password_error_new_long'];
    }

    if ($password !== $repeatPassword) {
        return ['ok' => false, 'message' => 'The new passwords do not match.', 'message_key' => 'change_password_error_mismatch'];
    }

    $updated = app_store_customer_password($db, $customerId, $password);
    if (!$updated) {
        return ['ok' => false, 'message' => 'Unable to save the new password.', 'message_key' => 'customer_password_save_error'];
    }

    admin_log_customer_and_admin(
        $db,
        $customerId,
        $adminUserId,
        'password_changed',
        'Customer password changed by admin.',
        $ipAddress
    );

    if ($sendPasswordEmail) {
        $email = strtolower(trim((string)($customer['email'] ?? '')));
        if ($email === '' || !filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return [
                'ok' => false,
                'password_updated' => true,
                'alert_type' => 'warning',
                'message' => 'The password was updated, but the customer email address is invalid.',
                'message_key' => 'customer_password_resend_invalid_email',
            ];
        }

        $emailResult = admin_queue_customer_password_email(
            $db,
            $customerId,
            $email,
            $password,
            admin_normalize_locale((string)($customer['locale_code'] ?? 'en'))
        );

        if (empty($emailResult['ok']) || !empty($emailResult['failed']) || empty($emailResult['queued'])) {
            return [
                'ok' => false,
                'password_updated' => true,
                'alert_type' => 'warning',
                'message' => 'The password was updated, but the email could not be sent.',
                'message_key' => 'customer_password_resend_error',
                'email_notification' => $emailResult,
            ];
        }

        return [
            'ok' => true,
            'message' => 'The password was updated and queued for email delivery.',
            'message_key' => 'customer_password_resent',
            'email_notification' => $emailResult,
        ];
    }

    return ['ok' => true, 'message' => 'Customer password has been updated.', 'message_key' => 'customer_password_saved'];
}

function admin_delete_customer_account(Mysql_ks $db, int $customerId, int $adminUserId, string $ipAddress = ''): array
{
    if ($customerId <= 0 || !schema_object_exists($db, 'customers')) {
        return ['ok' => false, 'message' => 'Customer not found.'];
    }

    $customer = admin_customer_detail_row($db, $customerId);
    if (!$customer) {
        return ['ok' => false, 'message' => 'Customer not found.'];
    }

    app_panel_tiers_capture($db, 0, $customerId);

    $customerEmail = (string)($customer['email'] ?? '');

    $db->start();

    if (schema_object_exists($db, 'support_messages')) {
        $db->query(
            "UPDATE support_messages
             SET customer_id = NULL
             WHERE customer_id = {$customerId}"
        );
    }

    if (schema_object_exists($db, 'support_conversations')) {
        $db->query(
            "UPDATE support_conversations
             SET customer_id = NULL
             WHERE customer_id = {$customerId}"
        );
    }

    if (schema_object_exists($db, 'customer_activity_logs')) {
        $db->query(
            "UPDATE customer_activity_logs
             SET customer_id = NULL
             WHERE customer_id = {$customerId}"
        );
    }

    if (schema_object_exists($db, 'crypto_deposit_transactions')) {
        $db->query(
            "UPDATE crypto_deposit_transactions
             SET customer_id = NULL
             WHERE customer_id = {$customerId}"
        );
    }

    if (schema_object_exists($db, 'bank_transfer_requests')) {
        $db->query("DELETE FROM bank_transfer_requests WHERE customer_id = {$customerId}");
    }

    if (schema_object_exists($db, 'crypto_deposit_requests')) {
        $db->query("DELETE FROM crypto_deposit_requests WHERE customer_id = {$customerId}");
    }

    if (schema_object_exists($db, 'bank_account_assignments')) {
        $db->query("DELETE FROM bank_account_assignments WHERE customer_id = {$customerId}");
    }

    if (schema_object_exists($db, 'crypto_wallet_assignments')) {
        $db->query("DELETE FROM crypto_wallet_assignments WHERE customer_id = {$customerId}");
    }

    if (schema_object_exists($db, 'referrals')) {
        $db->query(
            "DELETE FROM referrals
             WHERE referrer_customer_id = {$customerId}
                OR referred_customer_id = {$customerId}"
        );
    }

    if (schema_object_exists($db, 'orders')) {
        $db->query("DELETE FROM orders WHERE customer_id = {$customerId}");
    }

    $deleted = $db->delete_using_id('customers', $customerId);
    if (!$deleted) {
        $db->query('ROLLBACK');
        return ['ok' => false, 'message' => 'Unable to delete customer account.'];
    }

    admin_activity_log(
        $db,
        0,
        $adminUserId,
        'customer_deleted',
        'Customer account deleted: ' . $customerEmail . '. Related operational data was removed.',
        $ipAddress
    );

    $db->commit();

    return ['ok' => true, 'message' => 'Customer account deleted successfully.'];
}

function admin_import_detect_delimiter(array $lines): string
{
    // Header structure outweighs incidental commas/semicolons inside passwords.
    $first=(string)($lines[0]??'');
    foreach(["\t",';',',','|'] as $candidate){
        $cells=str_getcsv($first,$candidate,'"','');
        if(count($cells)>1)foreach($cells as $cell)if(admin_import_header_is_email((string)$cell))return $candidate;
    }
    $candidates = [",", ";", "\t", "|"];
    $bestDelimiter = ',';
    $bestScore = -1;
    $sample = array_slice($lines, 0, 5);

    foreach ($candidates as $delimiter) {
        $score = 0;
        foreach ($sample as $line) {
            $score += substr_count($line, $delimiter);
        }

        if ($score > $bestScore) {
            $bestScore = $score;
            $bestDelimiter = $delimiter;
        }
    }

    return $bestDelimiter;
}

function admin_import_normalize_header_cell(string $value): string
{
    $value = strtolower(trim($value));
    $value = preg_replace('/[^a-z0-9]+/', '_', $value) ?? $value;
    return trim($value, '_');
}

function admin_import_extract_email_from_cell(string $value): string
{
    $value = trim($value);
    if ($value !== '' && filter_var($value, FILTER_VALIDATE_EMAIL)) {
        return strtolower($value);
    }

    if (preg_match('/[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}/i', $value, $matches)) {
        return strtolower((string)($matches[0] ?? ''));
    }

    return '';
}

function admin_parse_customer_import_source(string $rawInput): array
{
    require_once __DIR__.'/customer_import_lib.php';
    return admin_customer_import_parse($rawInput);
}

function admin_import_customer_accounts(Mysql_ks $db,string $rawInput,array $options,int $adminUserId,string $ipAddress=''): array
{
    require_once __DIR__.'/customer_import_lib.php';
    $parsed=admin_customer_import_parse($rawInput,$options);
    if(empty($parsed['ok']))return $parsed;
    if(count($parsed['items'])>25)return ['ok'=>false,'message'=>'Użyj podglądu i importu partiami, aby wgrać większą listę.'];
    $counts=['created'=>0,'skipped'=>0,'failed'=>0];
    foreach($parsed['items'] as $item){$result=admin_customer_import_row($db,$item,$options,$adminUserId,$ipAddress);$counts[$result['kind']]++;}
    return ['ok'=>$counts['created']+$counts['skipped']>0,'message'=>'Dodano: '.$counts['created'].'. Pominięto istniejące: '.$counts['skipped'].'. Błędy: '.$counts['failed'].'.','created_count'=>$counts['created'],'skipped_count'=>$counts['skipped']];
}

function admin_customer_active_bank_assignments(Mysql_ks $db, int $customerId): array
{
