function admin_customer_has_pending_crypto_payment(Mysql_ks $db, int $customerId): bool
{
    if ($customerId <= 0 || !schema_object_exists($db, 'crypto_deposit_requests')) {
        return false;
    }

    $row = $db->select_user(
        "SELECT COUNT(*) AS total
         FROM crypto_deposit_requests
         WHERE customer_id = {$customerId}
           AND ((status IN ('pending', 'pending_payment', 'awaiting_confirmation', 'awaiting_review')
                 AND (expires_at IS NULL OR expires_at > NOW() OR COALESCE(received_crypto_amount,0)>0))
                OR (status='expired' AND COALESCE(received_crypto_amount,0)>0))"
    );
    return (int)($row['total'] ?? 0) > 0;
}

function admin_dedupe_customer_crypto_assignment_rows(array $rows): array
{
    if (!$rows) {
        return [];
    }

    $deduped = [];
    $seen = [];
    foreach ($rows as $row) {
        $walletAddressId = (int)($row['wallet_address_id'] ?? 0);
        $address = strtolower(trim((string)($row['address'] ?? '')));
        $key = $walletAddressId > 0 ? 'wallet:' . $walletAddressId : 'address:' . $address;
        if ($key === 'address:' || isset($seen[$key])) {
            continue;
        }

        $seen[$key] = true;
        $deduped[] = $row;
    }

    return $deduped;
}

function admin_dedupe_wallet_assignment_rows(array $rows): array
{
    if (!$rows) {
        return [];
    }

    $deduped = [];
    $seen = [];
    foreach ($rows as $row) {
        $customerId = (int)($row['customer_id'] ?? 0);
        $customerEmail = strtolower(trim((string)($row['customer_email'] ?? '')));
        $key = $customerId > 0 ? 'customer:' . $customerId : 'email:' . $customerEmail;
        if ($key === 'email:' || isset($seen[$key])) {
            continue;
        }

        $seen[$key] = true;
        $deduped[] = $row;
    }

    return $deduped;
}

function admin_cleanup_duplicate_crypto_wallet_assignments(
    Mysql_ks $db,
    int $walletId,
    int $customerId,
    int $keepAssignmentId = 0,
    int $adminUserId = 0,
    string $note = 'Released duplicate crypto wallet assignment'
): int {
    if (
        $walletId <= 0
        || $customerId <= 0
        || !schema_object_exists($db, 'crypto_wallet_assignments')
    ) {
        return 0;
    }

    $rows = $db->select_full_user(
        "SELECT id
         FROM crypto_wallet_assignments
         WHERE wallet_address_id = {$walletId}
           AND customer_id = {$customerId}
           AND status IN ('reserved', 'active')
         ORDER BY assigned_at DESC, id DESC"
    );
    if (count($rows) <= 1) {
        return 0;
    }

    if ($keepAssignmentId <= 0) {
        $keepAssignmentId = (int)($rows[0]['id'] ?? 0);
    }
    if ($keepAssignmentId <= 0) {
        return 0;
    }

    $safeNote = $db->escape($note);
    $releasedBySql = $adminUserId > 0 ? (string)$adminUserId : 'NULL';
    $releasedTotal = 0;
    foreach ($rows as $row) {
        $assignmentId = (int)($row['id'] ?? 0);
        if ($assignmentId <= 0 || $assignmentId === $keepAssignmentId) {
            continue;
        }

        $released = $db->query(
            "UPDATE crypto_wallet_assignments
             SET status = 'released',
                 released_at = NOW(),
                 released_by_admin_user_id = {$releasedBySql},
                 assignment_note = CONCAT(COALESCE(assignment_note, ''), '\n{$safeNote}')
             WHERE id = {$assignmentId}
               AND status IN ('reserved', 'active')"
        );
        if ($released) {
            $releasedTotal++;
        }
    }

    if ($releasedTotal > 0) {
        app_sync_crypto_wallet_address_statuses($db, $walletId);
    }

    return $releasedTotal;
}

function admin_customer_active_crypto_assignments(Mysql_ks $db, int $customerId, string $assetCode = ''): array
{
    if ($customerId <= 0) {
        return [];
    }

    $assetCode = strtoupper(trim($assetCode));
    $viewAssetFilter = '';
    $baseAssetFilter = '';
    if ($assetCode !== '') {
        $escapedAssetCode = $db->escape($assetCode);
        $viewAssetFilter = " AND crypto_asset_code = '" . $escapedAssetCode . "'";
        $baseAssetFilter = " AND asset.code = '" . $escapedAssetCode . "'";
    }

    $rows = [];
    if (schema_object_exists($db, 'customer_crypto_wallets')) {
        $rows = $db->select_full_user(
            "SELECT
                customer_crypto_wallets.wallet_assignment_id,
                customer_crypto_wallets.wallet_address_id,
                customer_crypto_wallets.customer_id,
                customer_crypto_wallets.customer_email,
                customer_crypto_wallets.crypto_asset_code,
                customer_crypto_wallets.crypto_asset_name,
                customer_crypto_wallets.label,
                customer_crypto_wallets.address,
                customer_crypto_wallets.network_code,
                customer_crypto_wallets.wallet_provider,
                customer_crypto_wallets.owner_full_name,
                customer_crypto_wallets.status,
                customer_crypto_wallets.assigned_at,
                crypto_wallet_addresses.notes AS wallet_notes,
                crypto_wallet_addresses.memo_tag
             FROM customer_crypto_wallets
             LEFT JOIN crypto_wallet_addresses
               ON crypto_wallet_addresses.id = customer_crypto_wallets.wallet_address_id
             WHERE customer_crypto_wallets.customer_id = {$customerId}
               AND customer_crypto_wallets.status IN ('reserved', 'active')
               {$viewAssetFilter}
             ORDER BY customer_crypto_wallets.assigned_at DESC, customer_crypto_wallets.wallet_assignment_id DESC"
        );
    }

    if ($rows) {
        return $rows;
    }

    if (
        !schema_object_exists($db, 'crypto_wallet_assignments')
        || !schema_object_exists($db, 'crypto_wallet_addresses')
        || !schema_object_exists($db, 'crypto_assets')
        || !schema_object_exists($db, 'customers')
    ) {
        return [];
    }

    $rows = $db->select_full_user(
        "SELECT
            assignment.id AS wallet_assignment_id,
            wallet.id AS wallet_address_id,
            assignment.customer_id,
            customer.email AS customer_email,
            asset.code AS crypto_asset_code,
            asset.name AS crypto_asset_name,
            wallet.label,
            wallet.address,
            wallet.network_code,
            wallet.memo_tag,
            wallet.wallet_provider,
            wallet.owner_full_name,
            wallet.notes AS wallet_notes,
            assignment.status,
            assignment.assigned_at
         FROM crypto_wallet_assignments AS assignment
         INNER JOIN crypto_wallet_addresses AS wallet
           ON wallet.id = assignment.wallet_address_id
         INNER JOIN crypto_assets AS asset
           ON asset.id = wallet.crypto_asset_id
         INNER JOIN customers AS customer
           ON customer.id = assignment.customer_id
         WHERE assignment.customer_id = {$customerId}
           AND assignment.status IN ('reserved', 'active')
           {$baseAssetFilter}
         ORDER BY assignment.assigned_at DESC, assignment.id DESC"
    );

    return admin_dedupe_customer_crypto_assignment_rows($rows);
}

function admin_chat_payment_amount_options(float $min = 1.0, float $max = 200.0, float $step = 1.0): array
{
    $options = [];
    for ($value = $min; $value <= $max; $value += $step) {
        $options[] = number_format($value, 2, '.', '');
    }

    return $options;
}

function admin_chat_payment_amount_normalize($amount): float
{
    if (!is_scalar($amount) || is_bool($amount)) { return 0.0; }
    $text = str_replace(',', '.', trim((string)$amount));
    if (!is_numeric($text)) { return 0.0; }
    $numeric = (float)$text;
    if (!is_finite($numeric) || $numeric < 1.0 || $numeric > 200.0) { return 0.0; }
    return round($numeric, 2);
}

