function admin_chat_crypto_payment_preview(Mysql_ks $db, int $customerId, int $assetId, $amount, array $messages, bool $serverQuotedAmount = false): array
{
    $settings = admin_app_settings($db);
    $currencyContext = admin_chat_payment_currency_context($db);
    $amountValue = $serverQuotedAmount && is_numeric($amount) && is_finite((float)$amount) && (float)$amount > 0 && (float)$amount <= 99999999.99
        ? round((float)$amount, 2) : admin_chat_payment_amount_normalize($amount);
    if ($customerId <= 0 || $assetId <= 0 || $amountValue <= 0) {
        return ['ok' => false, 'message' => 'Invalid crypto payment preview payload.'];
    }

    if (!admin_crypto_wallet_shared_assignments_enabled($settings)) {
        app_enforce_single_customer_crypto_wallet_per_asset(
            $db,
            $customerId,
            $assetId,
            'Normalized single crypto wallet per customer asset before admin crypto preview'
        );
    }

    $assetRows = admin_chat_payment_crypto_assets($db, $customerId, $currencyContext);
    $selectedAsset = null;
    foreach ($assetRows as $assetRow) {
        if ((int)$assetRow['id'] === $assetId) {
            $selectedAsset = $assetRow;
            break;
        }
    }

    if (!$selectedAsset) {
        return ['ok' => false, 'message' => 'Crypto asset not available.'];
    }

    $rate = (float)($selectedAsset['rate'] ?? 0.0);
    if ($rate <= 0) {
        return ['ok' => false, 'message' => 'Crypto exchange rate is unavailable.'];
    }

    $assignments = admin_customer_active_crypto_assignments($db, $customerId, (string)$selectedAsset['code']);
    $assignment = null;
    foreach ($assignments as $candidateAssignment) {
        if (
            admin_crypto_wallet_shared_assignments_enabled($settings)
            || app_crypto_deposit_wallet_payload_is_valid(
                $db,
                $customerId,
                (int)$selectedAsset['id'],
                (int)($candidateAssignment['wallet_address_id'] ?? 0),
                (int)($candidateAssignment['wallet_assignment_id'] ?? 0),
                $settings
            )
        ) {
            $assignment = $candidateAssignment;
            break;
        }
    }
    $availableWallet = null;
    if (!$assignment) {
        $availableWallet = admin_chat_available_crypto_wallet_for_asset($db, (int)$selectedAsset['id'], $customerId, $settings);
        if (!$availableWallet) {
            return [
                'ok' => false,
                'message' => 'No wallet available for this asset.',
                'preview_html' => admin_chat_crypto_wallet_pool_help_html($messages, $settings, (string)($selectedAsset['name'] ?? $selectedAsset['code'] ?? '')),
            ];
        }
    }

    $walletAddress = trim((string)($assignment['address'] ?? $availableWallet['address'] ?? ''));
    $walletOwner = trim((string)($assignment['owner_full_name'] ?? $availableWallet['owner_full_name'] ?? ''));
    $walletNotes = trim((string)($assignment['wallet_notes'] ?? $availableWallet['notes'] ?? ''));
    $walletOwnerLocation = app_wallet_owner_location_resolve($walletOwner, $walletNotes);
    $requestedCryptoAmount = sprintf('%.8f', $amountValue / $rate);

    $preview = [
        'ok' => true,
        'asset_id' => (int)$selectedAsset['id'],
        'asset_name' => (string)$selectedAsset['name'],
        'asset_code' => (string)$selectedAsset['code'],
        'asset_logo_url' => (string)$selectedAsset['logo_url'],
        'rate' => $rate,
        'fiat_amount' => $amountValue,
        'fiat_amount_label' => app_format_money_value($amountValue, (string)$currencyContext['currency_symbol'], (string)$currencyContext['currency_code']),
        'crypto_amount' => $requestedCryptoAmount,
        'crypto_amount_label' => rtrim(rtrim($requestedCryptoAmount, '0'), '.') . ' ' . (string)$selectedAsset['code'],
        'currency_id' => (int)$currencyContext['currency_id'],
        'currency_code' => (string)$currencyContext['currency_code'],
        'currency_symbol' => (string)$currencyContext['currency_symbol'],
        'wallet_address_id' => (int)($assignment['wallet_address_id'] ?? $availableWallet['wallet_address_id'] ?? 0),
        'wallet_assignment_id' => (int)($assignment['wallet_assignment_id'] ?? 0),
        'wallet_address' => $walletAddress,
        'network_code' => (string)($assignment['network_code'] ?? $availableWallet['network_code'] ?? ''),
        'memo_tag' => (string)($assignment['memo_tag'] ?? $availableWallet['memo_tag'] ?? ''),
        'wallet_owner_full_name' => $walletOwner,
        'wallet_owner_location' => $walletOwnerLocation,
        'wallet_notes' => $walletNotes,
        'uses_existing_assignment' => $assignment ? 1 : 0,
    ];
    $preview['preview_html'] = admin_chat_payment_crypto_preview_html($preview, $messages);

    return $preview;
}

function admin_chat_bank_payment_preview(Mysql_ks $db, int $customerId, $amount, int $selectedBankAccountId, array $messages): array
{
    $currencyContext = admin_chat_payment_currency_context($db);
    $amountValue = admin_chat_payment_amount_normalize($amount);
    if ($customerId <= 0 || $amountValue <= 0) {
        return ['ok' => false, 'message' => 'Invalid bank payment preview payload.'];
    }

    $assignments = app_filter_bank_account_rows_by_monthly_limit($db, admin_customer_active_bank_assignments($db, $customerId));
    $assignment = $assignments ? $assignments[0] : null;
    $bankAccount = null;

    if ($assignment) {
        $bankAccount = $assignment;
    } else {
        $availableAccounts = admin_chat_available_bank_account_rows($db, (string)($currencyContext['currency_code'] ?? ''));
        foreach ($availableAccounts as $availableAccount) {
            if ((int)($availableAccount['id'] ?? 0) === $selectedBankAccountId) {
                $bankAccount = $availableAccount;
                break;
            }
        }
        if (!$bankAccount && $availableAccounts) {
            $bankAccount = $availableAccounts[0];
        }
    }

    if (!$bankAccount) {
        return ['ok' => false, 'message' => 'No bank account available.'];
    }

    $preview = [
        'ok' => true,
        'amount' => $amountValue,
        'amount_label' => app_format_money_value($amountValue, (string)$currencyContext['currency_symbol'], (string)$currencyContext['currency_code']),
        'currency_id' => (int)$currencyContext['currency_id'],
        'currency_code' => (string)$currencyContext['currency_code'],
        'currency_symbol' => (string)$currencyContext['currency_symbol'],
        'bank_account_id' => (int)($bankAccount['bank_account_id'] ?? $bankAccount['id'] ?? 0),
        'bank_account_assignment_id' => (int)($bankAccount['bank_account_assignment_id'] ?? 0),
        'account_holder_name' => (string)($bankAccount['account_holder_name'] ?? ''),
        'bank_name' => (string)($bankAccount['bank_name'] ?? ''),
        'iban' => (string)($bankAccount['iban'] ?? ''),
        'swift_bic' => (string)($bankAccount['swift_bic'] ?? ''),
        'transfer_instructions' => (string)($bankAccount['transfer_instructions'] ?? ''),
        'payment_reference_template' => (string)($bankAccount['payment_reference_template'] ?? ''),
        'uses_existing_assignment' => $assignment ? 1 : 0,
    ];
    $preview['preview_html'] = admin_chat_payment_bank_preview_html($preview, $messages);

    return $preview;
}

function admin_bank_assignment_search_state(Mysql_ks $db, int $accountId, int $customerId): array
{
    $assignments = admin_customer_active_bank_assignments($db, $customerId);
    foreach ($assignments as $assignment) {
        if ((int)$assignment['bank_account_id'] === $accountId) {
            return [
                'disabled' => true,
                'hint' => 'Already assigned to this bank account.',
            ];
        }
    }

    if ($assignments) {
        $current = $assignments[0];
        $label = trim((string)($current['label'] ?? ''));
        if ($label === '') {
            $label = trim((string)($current['bank_name'] ?? ''));
        }

        return [
            'disabled' => false,
            'hint' => $label !== ''
                ? 'Current: ' . $label . '. Click to move.'
                : 'Already assigned to another bank account. Click to move.',
        ];
    }

    return [
        'disabled' => false,
        'hint' => 'Click to assign this user.',
    ];
}

function admin_crypto_assignment_search_state(Mysql_ks $db, int $walletId, int $customerId, array $settings): array
{
    $wallet = admin_crypto_wallet_find($db, $walletId);
    if (!is_array($wallet) || empty($wallet['id'])) {
        return [
            'disabled' => true,
            'hint' => 'Wallet not found.',
        ];
    }

    $assetCode = strtoupper(trim((string)($wallet['asset_code'] ?? '')));
    $sharedEnabled = admin_crypto_wallet_shared_assignments_enabled($settings);
    $assignments = admin_customer_active_crypto_assignments($db, $customerId, $assetCode);

    foreach ($assignments as $assignment) {
        if ((int)$assignment['wallet_address_id'] === $walletId) {
            return [
                'disabled' => true,
                'hint' => 'Already assigned to this wallet.',
            ];
        }
    }

    if ($assignments) {
        $current = $assignments[0];
        $label = trim((string)($current['label'] ?? ''));
        if ($label === '') {
            $label = admin_string_truncate((string)($current['address'] ?? ''), 18);
        }

        return [
            'disabled' => false,
            'hint' => $sharedEnabled
                ? ($label !== '' ? 'Also assigned: ' . $label : 'User already has another wallet for this coin.')
                : ($label !== '' ? 'Current: ' . $label . '. Click to move.' : 'User already has another wallet for this coin. Click to move.'),
        ];
    }

    return [
        'disabled' => false,
        'hint' => 'Click to assign this user.',
    ];
}

function admin_crypto_wallet_find(Mysql_ks $db, int $walletId): ?array
{
    if ($walletId <= 0 || !schema_object_exists($db, 'crypto_wallet_addresses')) {
        return null;
    }

    $row = $db->select_user(
        "SELECT
            wallet.id,
            wallet.crypto_asset_id,
            wallet.label,
            wallet.owner_full_name,
            wallet.address,
            wallet.network_code,
            wallet.memo_tag,
            wallet.wallet_provider,
            wallet.status,
            wallet.notes,
            wallet.qr_url,
            wallet.is_reusable,
            wallet.disabled_at,
            wallet.updated_at,
            asset.code AS asset_code,
            asset.name AS asset_name,
            asset.is_active AS asset_is_active,
            assignment.id AS active_assignment_id,
            assignment.customer_id AS assigned_customer_id,
            assignment.status AS assignment_status,
            assignment.assigned_at,
            customer.email AS assigned_customer_email
         FROM crypto_wallet_addresses AS wallet
         LEFT JOIN crypto_assets AS asset
           ON asset.id = wallet.crypto_asset_id
         LEFT JOIN crypto_wallet_assignments AS assignment
           ON assignment.id = (
                SELECT inner_assignment.id
                FROM crypto_wallet_assignments AS inner_assignment
                WHERE inner_assignment.wallet_address_id = wallet.id
                  AND inner_assignment.status IN ('reserved', 'active')
                ORDER BY inner_assignment.assigned_at DESC, inner_assignment.id DESC
                LIMIT 1
           )
         LEFT JOIN customers AS customer
           ON customer.id = assignment.customer_id
         WHERE wallet.id = {$walletId}
         LIMIT 1"
    );

    return is_array($row) ? $row : null;
}

function admin_crypto_wallet_active_assignments(Mysql_ks $db, int $walletId): array
{
    if ($walletId <= 0 || !schema_object_exists($db, 'crypto_wallet_assignments')) {
        return [];
    }

    app_ensure_customer_runtime_columns($db);

    $rows = $db->select_full_user(
        "SELECT
            crypto_wallet_assignments.id,
            crypto_wallet_assignments.customer_id,
            crypto_wallet_assignments.status,
            crypto_wallet_assignments.assigned_at,
            crypto_wallet_assignments.assignment_note,
            customers.email AS customer_email,
            NULLIF(TRIM(customers.public_handle), '') AS customer_public_handle,
            CASE
                WHEN EXISTS (
                    SELECT 1
                    FROM crypto_deposit_requests
                    LEFT JOIN crypto_wallet_assignments AS payment_assignment
                        ON payment_assignment.id = crypto_deposit_requests.wallet_assignment_id
                    WHERE crypto_deposit_requests.customer_id = crypto_wallet_assignments.customer_id
                      AND (
                            crypto_deposit_requests.wallet_address_id = crypto_wallet_assignments.wallet_address_id
                         OR payment_assignment.wallet_address_id = crypto_wallet_assignments.wallet_address_id
                      )
                      AND crypto_deposit_requests.status NOT IN ('pending', 'pending_payment', 'cancelled')
                    LIMIT 1
                ) THEN 1
                ELSE 0
            END AS has_payment_history
         FROM crypto_wallet_assignments
         INNER JOIN customers ON customers.id = crypto_wallet_assignments.customer_id
         WHERE crypto_wallet_assignments.wallet_address_id = {$walletId}
           AND crypto_wallet_assignments.status IN ('reserved', 'active')
         ORDER BY crypto_wallet_assignments.assigned_at DESC, crypto_wallet_assignments.id DESC"
    );

    return admin_dedupe_wallet_assignment_rows($rows);
}

function admin_crypto_wallet_payment_rows(Mysql_ks $db, int $walletId, int $limit = 100): array
{
    if ($walletId <= 0 || !schema_object_exists($db, 'crypto_deposit_requests')) {
        return [];
    }

    app_ensure_customer_runtime_columns($db);

    $limit = max(1, min(200, $limit));
    $walletRow = $db->select_user(
        "SELECT crypto_asset_id, address, network_code
         FROM crypto_wallet_addresses
         WHERE id = {$walletId}
         LIMIT 1"
    );
    $walletAssetId = (int)($walletRow['crypto_asset_id'] ?? 0);

    return $db->select_full_user(
        "SELECT
            crypto_deposit_requests.id,
            crypto_deposit_requests.order_id,
            crypto_deposit_requests.customer_id,
            crypto_deposit_requests.status,
            crypto_deposit_requests.wallet_assignment_id,
            crypto_deposit_requests.requested_fiat_amount AS amount_value,
            crypto_deposit_requests.requested_crypto_amount AS amount_crypto,
            COALESCE(crypto_deposit_requests.requested_at, crypto_deposit_requests.expires_at) AS requested_at,
            crypto_deposit_requests.expires_at,
            customers.email AS customer_email,
            NULLIF(TRIM(customers.public_handle), '') AS customer_public_handle,
            currencies.code AS currency_code,
            currencies.symbol AS currency_symbol,
            crypto_assets.code AS asset_code,
            crypto_assets.name AS asset_name,
            COALESCE(direct_wallet.id, assigned_wallet.id, {$walletId}) AS wallet_address_id,
            COALESCE(direct_wallet.address, assigned_wallet.address, '" . $db->escape((string)($walletRow['address'] ?? '')) . "') AS wallet_address,
            COALESCE(direct_wallet.network_code, assigned_wallet.network_code, '" . $db->escape((string)($walletRow['network_code'] ?? '')) . "') AS network_code
         FROM crypto_deposit_requests
         LEFT JOIN customers ON customers.id = crypto_deposit_requests.customer_id
         LEFT JOIN currencies ON currencies.id = crypto_deposit_requests.fiat_currency_id
         LEFT JOIN crypto_assets ON crypto_assets.id = crypto_deposit_requests.crypto_asset_id
         LEFT JOIN crypto_wallet_addresses AS direct_wallet ON direct_wallet.id = crypto_deposit_requests.wallet_address_id
         LEFT JOIN crypto_wallet_assignments AS request_assignment ON request_assignment.id = crypto_deposit_requests.wallet_assignment_id
         LEFT JOIN crypto_wallet_addresses AS assigned_wallet ON assigned_wallet.id = request_assignment.wallet_address_id
         WHERE (
                crypto_deposit_requests.wallet_address_id = {$walletId}
             OR request_assignment.wallet_address_id = {$walletId}
             OR (
                    crypto_deposit_requests.wallet_address_id IS NULL
                AND crypto_deposit_requests.wallet_assignment_id IS NULL
                AND " . ($walletAssetId > 0 ? "crypto_deposit_requests.crypto_asset_id = {$walletAssetId}" : '1=0') . "
                AND crypto_deposit_requests.customer_id IN (
                    SELECT DISTINCT assignment.customer_id
                    FROM crypto_wallet_assignments AS assignment
                    WHERE assignment.wallet_address_id = {$walletId}
                )
             )
         )
         ORDER BY crypto_deposit_requests.id DESC
         LIMIT {$limit}"
    );
}

function admin_crypto_wallet_payment_conflict_rows(Mysql_ks $db, int $walletId): array
{
    if ($walletId <= 0 || !schema_object_exists($db, 'crypto_deposit_requests')) {
        return [];
    }

    return $db->select_full_user(
        "SELECT
            crypto_deposit_requests.customer_id,
            customers.email AS customer_email,
            NULLIF(TRIM(customers.public_handle), '') AS customer_public_handle,
            COUNT(*) AS payment_total,
            MAX(COALESCE(crypto_deposit_requests.requested_at, crypto_deposit_requests.expires_at)) AS last_payment_at,
            COUNT(DISTINCT active_assignment.id) AS active_assignment_total,
            GROUP_CONCAT(DISTINCT active_assignment.id ORDER BY active_assignment.id DESC SEPARATOR ',') AS active_assignment_ids
         FROM crypto_deposit_requests
         LEFT JOIN crypto_wallet_assignments AS payment_assignment
           ON payment_assignment.id = crypto_deposit_requests.wallet_assignment_id
         INNER JOIN customers
           ON customers.id = crypto_deposit_requests.customer_id
         LEFT JOIN crypto_wallet_assignments AS active_assignment
           ON active_assignment.customer_id = crypto_deposit_requests.customer_id
          AND active_assignment.wallet_address_id = {$walletId}
          AND active_assignment.status IN ('reserved', 'active')
         WHERE crypto_deposit_requests.customer_id > 0
           AND (
                crypto_deposit_requests.wallet_address_id = {$walletId}
             OR payment_assignment.wallet_address_id = {$walletId}
           )
           AND crypto_deposit_requests.status NOT IN ('pending', 'pending_payment', 'cancelled')
         GROUP BY crypto_deposit_requests.customer_id, customers.email, customers.public_handle
         ORDER BY payment_total DESC, last_payment_at DESC, crypto_deposit_requests.customer_id ASC"
    );
}

function admin_crypto_wallet_payment_conflict_summary(Mysql_ks $db, int $walletId): array
{
    $rows = admin_crypto_wallet_payment_conflict_rows($db, $walletId);
    $wallet = admin_crypto_wallet_find($db, $walletId);
    $assetId = (int)($wallet['crypto_asset_id'] ?? 0);

    $activeRows = array_values(array_filter($rows, static function (array $row): bool {
        return (int)($row['active_assignment_total'] ?? 0) > 0;
    }));

    $unresolvedRows = [];
    foreach ($rows as $row) {
        $customerId = (int)($row['customer_id'] ?? 0);
        if ($customerId <= 0 || $assetId <= 0) {
            continue;
        }

        $currentAssignments = $db->select_full_user(
            "SELECT crypto_wallet_assignments.wallet_address_id
             FROM crypto_wallet_assignments
             INNER JOIN crypto_wallet_addresses
               ON crypto_wallet_addresses.id = crypto_wallet_assignments.wallet_address_id
             WHERE crypto_wallet_assignments.customer_id = {$customerId}
               AND crypto_wallet_assignments.status IN ('reserved', 'active')
               AND crypto_wallet_addresses.crypto_asset_id = {$assetId}
             ORDER BY
                CASE WHEN crypto_wallet_assignments.wallet_address_id = {$walletId} THEN 0 ELSE 1 END ASC,
                crypto_wallet_assignments.id DESC"
        );

        if (!$currentAssignments) {
            $unresolvedRows[] = $row;
            continue;
        }

        $hasCurrentAssignmentOnWallet = false;
        foreach ($currentAssignments as $assignmentRow) {
            if ((int)($assignmentRow['wallet_address_id'] ?? 0) === $walletId) {
                $hasCurrentAssignmentOnWallet = true;
                break;
            }
        }

        if ($hasCurrentAssignmentOnWallet) {
            $unresolvedRows[] = $row;
        }
    }

    $conflictRows = $unresolvedRows;
    if (count($conflictRows) <= 1) {
        return [
            'can_split' => false,
            'rows' => $rows,
            'active_rows' => $activeRows,
            'unresolved_rows' => $unresolvedRows,
            'keeper' => null,
            'candidate' => null,
            'candidates' => [],
        ];
    }

    $keeperRows = $conflictRows;
    usort($keeperRows, static function (array $left, array $right): int {
        $countCompare = ((int)($right['payment_total'] ?? 0)) <=> ((int)($left['payment_total'] ?? 0));
        if ($countCompare !== 0) {
            return $countCompare;
        }

        $dateCompare = strcmp((string)($right['last_payment_at'] ?? ''), (string)($left['last_payment_at'] ?? ''));
        if ($dateCompare !== 0) {
            return $dateCompare;
        }

        return ((int)($left['customer_id'] ?? 0)) <=> ((int)($right['customer_id'] ?? 0));
    });
    $keeper = $keeperRows[0] ?? null;

    $candidateRows = $conflictRows;
    usort($candidateRows, static function (array $left, array $right): int {
        $countCompare = ((int)($left['payment_total'] ?? 0)) <=> ((int)($right['payment_total'] ?? 0));
        if ($countCompare !== 0) {
            return $countCompare;
        }

        $dateCompare = strcmp((string)($right['last_payment_at'] ?? ''), (string)($left['last_payment_at'] ?? ''));
        if ($dateCompare !== 0) {
            return $dateCompare;
        }

        return ((int)($left['customer_id'] ?? 0)) <=> ((int)($right['customer_id'] ?? 0));
    });

    $candidate = null;
    $candidates = [];
    foreach ($candidateRows as $row) {
        if ((int)($row['customer_id'] ?? 0) !== (int)($keeper['customer_id'] ?? 0)) {
            if ($candidate === null) {
                $candidate = $row;
            }
            $candidates[] = $row;
        }
    }

    return [
        'can_split' => !empty($candidates) && is_array($keeper) && (int)($keeper['customer_id'] ?? 0) > 0,
        'rows' => $rows,
        'active_rows' => $activeRows,
        'unresolved_rows' => $unresolvedRows,
        'keeper' => $keeper,
        'candidate' => $candidate,
        'candidates' => $candidates,
    ];
}

function admin_first_crypto_wallet_payment_conflict(Mysql_ks $db): ?array
{
    if (
        !schema_object_exists($db, 'crypto_wallet_addresses')
        || !schema_object_exists($db, 'crypto_wallet_assignments')
        || !schema_object_exists($db, 'crypto_deposit_requests')
    ) {
        return null;
    }

    $wallets = $db->select_full_user(
        "SELECT
            crypto_wallet_addresses.id,
            crypto_wallet_addresses.label,
            crypto_wallet_addresses.address,
            crypto_assets.code AS asset_code
         FROM crypto_wallet_addresses
         INNER JOIN crypto_assets
           ON crypto_assets.id = crypto_wallet_addresses.crypto_asset_id
         WHERE EXISTS (
            SELECT 1
            FROM crypto_deposit_requests
            LEFT JOIN crypto_wallet_assignments AS payment_assignment
              ON payment_assignment.id = crypto_deposit_requests.wallet_assignment_id
            WHERE crypto_deposit_requests.customer_id > 0
              AND (
                    crypto_deposit_requests.wallet_address_id = crypto_wallet_addresses.id
                 OR payment_assignment.wallet_address_id = crypto_wallet_addresses.id
              )
              AND crypto_deposit_requests.status NOT IN ('pending', 'pending_payment', 'cancelled')
         )
         ORDER BY crypto_wallet_addresses.id DESC
         LIMIT 200"
    );

    foreach ($wallets as $walletRow) {
        $walletId = (int)($walletRow['id'] ?? 0);
        if ($walletId <= 0) {
            continue;
        }

        $conflict = admin_crypto_wallet_payment_conflict_summary($db, $walletId);
        if (empty($conflict['can_split']) || empty($conflict['candidate']) || empty($conflict['keeper'])) {
            continue;
        }

        return [
            'wallet_id' => $walletId,
            'label' => (string)($walletRow['label'] ?? ''),
            'address' => (string)($walletRow['address'] ?? ''),
            'asset_code' => (string)($walletRow['asset_code'] ?? ''),
            'candidate' => $conflict['candidate'],
            'keeper' => $conflict['keeper'],
        ];
    }

    return null;
}

function admin_resolve_crypto_wallet_payment_conflict(
    Mysql_ks $db,
    int $walletId,
    int $adminUserId,
    array $settings,
    string $ipAddress = ''
): array {
    if ($walletId <= 0) {
        return ['ok' => false, 'message' => 'Wallet not found.'];
    }

    if (admin_crypto_wallet_shared_assignments_enabled($settings)) {
        return ['ok' => false, 'message' => 'Wallet conflict split is available only when shared wallets are OFF.'];
    }

    $wallet = admin_crypto_wallet_find($db, $walletId);
    if (!is_array($wallet) || empty($wallet['id'])) {
        return ['ok' => false, 'message' => 'Wallet not found.'];
    }

    $assetId = (int)($wallet['crypto_asset_id'] ?? 0);
    if ($assetId <= 0) {
        return ['ok' => false, 'message' => 'Wallet asset is missing.'];
    }

    $conflict = admin_crypto_wallet_payment_conflict_summary($db, $walletId);
    $candidates = array_values(array_filter($conflict['candidates'] ?? [], static function (array $row): bool {
        return (int)($row['customer_id'] ?? 0) > 0;
    }));

    if (empty($conflict['can_split']) || !$candidates || !is_array($conflict['keeper'])) {
        return ['ok' => false, 'message' => 'No wallet conflict was detected for this address.'];
    }

    $freeWalletCountRow = $db->select_user(
        "SELECT COUNT(DISTINCT crypto_wallet_addresses.id) AS total
         FROM crypto_wallet_addresses
	         LEFT JOIN crypto_wallet_assignments
	           ON crypto_wallet_assignments.wallet_address_id = crypto_wallet_addresses.id
	          AND crypto_wallet_assignments.status IN ('reserved', 'active')
	         WHERE crypto_wallet_addresses.crypto_asset_id = {$assetId}
	           AND crypto_wallet_addresses.id <> {$walletId}
	           AND crypto_wallet_addresses.status = 'available'
	           AND crypto_wallet_addresses.disabled_at IS NULL
	           AND crypto_wallet_assignments.id IS NULL
	           AND NOT EXISTS (
	                SELECT 1
	                FROM crypto_deposit_requests AS open_request
	                LEFT JOIN crypto_wallet_assignments AS open_assignment
	                  ON open_assignment.id = open_request.wallet_assignment_id
	                WHERE (
	                        open_request.wallet_address_id = crypto_wallet_addresses.id
	                     OR open_assignment.wallet_address_id = crypto_wallet_addresses.id
	                )
	                  AND open_request.status IN ('pending', 'pending_payment', 'awaiting_confirmation', 'awaiting_review')
	                LIMIT 1
	           )
	           AND NOT EXISTS (
	                SELECT 1
	                FROM crypto_deposit_requests AS historical_request
	                LEFT JOIN crypto_wallet_assignments AS historical_assignment
	                  ON historical_assignment.id = historical_request.wallet_assignment_id
	                WHERE (
	                        historical_request.wallet_address_id = crypto_wallet_addresses.id
	                     OR historical_assignment.wallet_address_id = crypto_wallet_addresses.id
	                )
	                  AND historical_request.status NOT IN ('pending', 'pending_payment', 'cancelled')
	                LIMIT 1
	           )"
	    );
    $freeWalletCount = (int)($freeWalletCountRow['total'] ?? 0);
    if ($freeWalletCount < count($candidates)) {
        return ['ok' => false, 'message' => 'Not enough free wallet addresses are available to split this conflict for every affected customer.'];
    }

    $oldWalletAddress = trim((string)($wallet['address'] ?? ''));
    $oldWalletCompact = admin_compact_wallet_address($oldWalletAddress, 8, 6);
    $assetCode = strtoupper(trim((string)($wallet['asset_code'] ?? '')));
    $keepLabel = trim((string)($conflict['keeper']['customer_public_handle'] ?? '')) !== ''
        ? '@' . trim((string)$conflict['keeper']['customer_public_handle'])
        : trim((string)($conflict['keeper']['customer_email'] ?? ''));
    $keeperCustomerId = (int)($conflict['keeper']['customer_id'] ?? 0);

    $movedLabels = [];
    $movedCount = 0;
    $db->start();

    $keeperAssignmentId = 0;
    $keeperAssignmentNeedsActivation = false;
    $keeperNeedsInsert = false;
    $keeperNote = 'Kept as primary wallet during wallet conflict split on wallet ' . $oldWalletCompact;

    if ($keeperCustomerId > 0) {
        $keeperAssignmentRow = $db->select_user(
            "SELECT id, status
             FROM crypto_wallet_assignments
             WHERE wallet_address_id = {$walletId}
               AND customer_id = {$keeperCustomerId}
             ORDER BY id DESC
             LIMIT 1
             FOR UPDATE"
        );
        $keeperAssignmentId = (int)($keeperAssignmentRow['id'] ?? 0);
        if ($keeperAssignmentId > 0) {
            $keeperAssignmentNeedsActivation = strtolower(trim((string)($keeperAssignmentRow['status'] ?? ''))) !== 'active';
        } else {
            $keeperNeedsInsert = true;
        }
    }

    foreach ($candidates as $candidate) {
        $customerId = (int)($candidate['customer_id'] ?? 0);
        if ($customerId <= 0) {
            continue;
        }

        $freeWallet = app_find_available_crypto_wallet_for_asset($db, $assetId, 0, $settings);
        $newWalletId = (int)($freeWallet['wallet_address_id'] ?? 0);
        if ($newWalletId === $walletId) {
            $freeWallet = $db->select_user(
                "SELECT
                    crypto_wallet_addresses.id AS wallet_address_id,
                    crypto_wallet_addresses.crypto_asset_id,
                    crypto_wallet_addresses.label,
                    crypto_wallet_addresses.owner_full_name,
                    crypto_wallet_addresses.address,
                    crypto_wallet_addresses.network_code,
                    crypto_wallet_addresses.memo_tag,
                    crypto_wallet_addresses.wallet_provider,
                    crypto_assets.code AS crypto_asset_code,
                    crypto_assets.name AS crypto_asset_name
                 FROM crypto_wallet_addresses
                 INNER JOIN crypto_assets
                   ON crypto_assets.id = crypto_wallet_addresses.crypto_asset_id
	                 LEFT JOIN crypto_wallet_assignments
	                   ON crypto_wallet_assignments.wallet_address_id = crypto_wallet_addresses.id
	                  AND crypto_wallet_assignments.status IN ('reserved', 'active')
	                 WHERE crypto_wallet_addresses.crypto_asset_id = {$assetId}
	                   AND crypto_wallet_addresses.id <> {$walletId}
	                   AND crypto_wallet_addresses.status = 'available'
	                   AND crypto_wallet_addresses.disabled_at IS NULL
	                   AND crypto_wallet_assignments.id IS NULL
	                   AND NOT EXISTS (
	                        SELECT 1
	                        FROM crypto_deposit_requests AS open_request
	                        LEFT JOIN crypto_wallet_assignments AS open_assignment
	                          ON open_assignment.id = open_request.wallet_assignment_id
	                        WHERE (
	                                open_request.wallet_address_id = crypto_wallet_addresses.id
	                             OR open_assignment.wallet_address_id = crypto_wallet_addresses.id
	                        )
	                          AND open_request.status IN ('pending', 'pending_payment', 'awaiting_confirmation', 'awaiting_review')
	                        LIMIT 1
	                   )
	                   AND NOT EXISTS (
	                        SELECT 1
	                        FROM crypto_deposit_requests AS historical_request
	                        LEFT JOIN crypto_wallet_assignments AS historical_assignment
	                          ON historical_assignment.id = historical_request.wallet_assignment_id
	                        WHERE (
	                                historical_request.wallet_address_id = crypto_wallet_addresses.id
	                             OR historical_assignment.wallet_address_id = crypto_wallet_addresses.id
	                        )
	                          AND historical_request.status NOT IN ('pending', 'pending_payment', 'cancelled')
	                        LIMIT 1
	                   )
	                 ORDER BY crypto_wallet_addresses.is_reusable DESC,
	                          crypto_wallet_addresses.last_assigned_at ASC,
	                          crypto_wallet_addresses.id ASC
                 LIMIT 1"
            );
            $newWalletId = (int)($freeWallet['wallet_address_id'] ?? 0);
        }

        if ($newWalletId <= 0) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Unable to find a free wallet for every conflicting customer.'];
        }
        if (!app_crypto_wallet_can_be_offered_to_customer($db, $newWalletId, 0, $settings)) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Unable to find a free wallet for every conflicting customer.'];
        }

        $newWalletAddress = trim((string)($freeWallet['address'] ?? ''));
        $newWalletCompact = admin_compact_wallet_address($newWalletAddress, 8, 6);
        $customerLabel = trim((string)($candidate['customer_public_handle'] ?? '')) !== ''
            ? '@' . trim((string)$candidate['customer_public_handle'])
            : trim((string)($candidate['customer_email'] ?? ''));

        $paymentRows = $db->select_full_user(
            "SELECT
                crypto_deposit_requests.id,
                crypto_deposit_requests.status,
                crypto_deposit_requests.request_note,
                COALESCE(crypto_deposit_requests.requested_at, crypto_deposit_requests.expires_at) AS requested_at
             FROM crypto_deposit_requests
             LEFT JOIN crypto_wallet_assignments AS payment_assignment
               ON payment_assignment.id = crypto_deposit_requests.wallet_assignment_id
             WHERE crypto_deposit_requests.customer_id = {$customerId}
               AND (
                    crypto_deposit_requests.wallet_address_id = {$walletId}
                 OR payment_assignment.wallet_address_id = {$walletId}
               )
             ORDER BY crypto_deposit_requests.id DESC"
        );

        $sameAssetAssignments = $db->select_full_user(
            "SELECT
                crypto_wallet_assignments.id,
                crypto_wallet_assignments.wallet_address_id
             FROM crypto_wallet_assignments
             INNER JOIN crypto_wallet_addresses
               ON crypto_wallet_addresses.id = crypto_wallet_assignments.wallet_address_id
             WHERE crypto_wallet_assignments.customer_id = {$customerId}
               AND crypto_wallet_assignments.status IN ('reserved', 'active')
               AND crypto_wallet_addresses.crypto_asset_id = {$assetId}
             ORDER BY crypto_wallet_assignments.id DESC"
        );

        $releaseNote = 'Released during wallet conflict split from [' . $oldWalletAddress . '] to [' . $newWalletAddress . ']';
        foreach ($sameAssetAssignments as $assignmentRow) {
            $assignmentId = (int)($assignmentRow['id'] ?? 0);
            if ($assignmentId <= 0) {
                continue;
            }
            if (!admin_release_crypto_wallet_assignment($db, $assignmentId, $adminUserId, $releaseNote)) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to release previous wallet assignment during wallet conflict split.'];
            }
        }

        $newAssignmentRow = $db->select_user(
            "SELECT id
             FROM crypto_wallet_assignments
             WHERE wallet_address_id = {$newWalletId}
               AND customer_id = {$customerId}
             ORDER BY id DESC
             LIMIT 1"
        );

        $newAssignmentId = (int)($newAssignmentRow['id'] ?? 0);
        $assignmentNote = 'Assigned during wallet conflict split from wallet ' . $oldWalletCompact . '. This customer previously paid on [' . $oldWalletAddress . '] and now uses [' . $newWalletAddress . '].';
        if ($newAssignmentId > 0) {
            $safeNote = $db->escape($assignmentNote);
            $reactivated = $db->query(
                "UPDATE crypto_wallet_assignments
                 SET status = 'active',
                     released_at = NULL,
                     released_by_admin_user_id = NULL,
                     assignment_note = CONCAT(COALESCE(assignment_note, ''), '\n{$safeNote}')
                 WHERE id = {$newAssignmentId}"
            );
            if ($reactivated === false) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to reactivate a replacement wallet assignment during wallet conflict split.'];
            }
        } else {
            $inserted = $db->insert(
                ['wallet_address_id', 'customer_id', 'assignment_reason', 'status', 'assigned_by_admin_user_id', 'assignment_note'],
                [$newWalletId, $customerId, 'admin_conflict_split', 'active', $adminUserId, $assignmentNote],
                'crypto_wallet_assignments'
            );
            if (!$inserted || (int)$db->id() <= 0) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to assign a new wallet during wallet conflict split.'];
            }
            $newAssignmentId = (int)$db->id();
        }

        $db->update_using_id(
            ['status', 'last_assigned_at', 'disabled_at'],
            ['assigned', $db->expr('NOW()'), null],
            'crypto_wallet_addresses',
            $newWalletId
        );

        foreach ($paymentRows as $paymentRow) {
            $paymentId = (int)($paymentRow['id'] ?? 0);
            if ($paymentId <= 0) {
                continue;
            }

            $paymentStatus = strtolower(trim((string)($paymentRow['status'] ?? '')));
            $paymentDate = substr((string)($paymentRow['requested_at'] ?? ''), 0, 10);
            if ($paymentDate === '') {
                $paymentDate = date('Y-m-d');
            }

            $noteLine = 'Wallet conflict fix: this customer paid on ' . $paymentDate . ' to wallet [' . $oldWalletAddress . ']. New assigned wallet: [' . $newWalletAddress . '].';
            $currentNote = trim((string)($paymentRow['request_note'] ?? ''));
            $updatedNote = $currentNote === '' ? $noteLine : $currentNote;
            if ($currentNote !== '' && strpos($currentNote, $noteLine) === false) {
                $updatedNote .= "\n" . $noteLine;
            }

            if (in_array($paymentStatus, ['pending', 'pending_payment'], true)) {
                $updated = $db->update_using_id(
                    ['wallet_assignment_id', 'wallet_address_id', 'request_note'],
                    [$newAssignmentId, $newWalletId, $updatedNote],
                    'crypto_deposit_requests',
                    $paymentId
                );
            } else {
                $updated = $db->update_using_id(
                    ['request_note'],
                    [$updatedNote],
                    'crypto_deposit_requests',
                    $paymentId
                );
            }

            if (!$updated) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to update payment notes during wallet conflict split.'];
            }
        }

        admin_cleanup_duplicate_crypto_wallet_assignments(
            $db,
            $newWalletId,
            $customerId,
            $newAssignmentId,
            $adminUserId,
            'Released duplicate crypto wallet assignments after wallet conflict split'
        );

        app_sync_crypto_wallet_address_statuses($db, $walletId);
        app_sync_crypto_wallet_address_statuses($db, $newWalletId);

        admin_log_customer_and_admin(
            $db,
            $customerId,
            $adminUserId,
            'crypto_wallet_conflict_split',
            'Wallet conflict resolved for ' . $assetCode . ': customer ' . $customerLabel . ' was moved from wallet ' . $oldWalletCompact . ' to ' . $newWalletCompact . '. Primary wallet holder kept on the original wallet: ' . $keepLabel . '.',
            $ipAddress
        );

        $movedLabels[] = $customerLabel !== '' ? $customerLabel : ('Customer #' . $customerId);
        $movedCount++;
    }

    if ($keeperCustomerId > 0) {
        $keeperSafeNote = $db->escape($keeperNote);
        if ($keeperAssignmentId > 0 && $keeperAssignmentNeedsActivation) {
            $keeperUpdated = $db->query(
                "UPDATE crypto_wallet_assignments
                 SET status = 'active',
                     released_at = NULL,
                     released_by_admin_user_id = NULL,
                     assignment_note = CONCAT(COALESCE(assignment_note, ''), '\n{$keeperSafeNote}')
                 WHERE id = {$keeperAssignmentId}"
            );
            if ($keeperUpdated === false) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to keep the primary customer assigned to the original wallet.'];
            }
        } elseif ($keeperNeedsInsert) {
            $keeperInserted = $db->insert(
                ['wallet_address_id', 'customer_id', 'assignment_reason', 'status', 'assigned_by_admin_user_id', 'assignment_note'],
                [$walletId, $keeperCustomerId, 'admin_conflict_primary', 'active', $adminUserId, $keeperNote],
                'crypto_wallet_assignments'
            );
            if (!$keeperInserted || (int)$db->id() <= 0) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to restore the primary customer on the original wallet.'];
            }
        }

        $db->update_using_id(
            ['status', 'last_assigned_at', 'disabled_at'],
            ['assigned', $db->expr('NOW()'), null],
            'crypto_wallet_addresses',
            $walletId
        );
    }

    $db->commit();

    if ($movedCount <= 0) {
        return ['ok' => false, 'message' => 'No conflicting customers were moved to a new wallet.'];
    }

    return [
        'ok' => true,
        'message' => 'Wallet conflict resolved. Moved ' . $movedCount . ' customer(s) to new ' . ($assetCode !== '' ? $assetCode . ' ' : '') . 'wallets: ' . implode(', ', $movedLabels) . '. The main payer stayed on ' . $oldWalletCompact . '.',
        'moved_customers' => $movedLabels,
        'moved_count' => $movedCount,
        'old_wallet_id' => $walletId,
    ];
}

function admin_crypto_wallet_assignment_has_payment_history(Mysql_ks $db, int $walletId, int $customerId): bool
{
    if ($walletId <= 0 || $customerId <= 0 || !schema_object_exists($db, 'crypto_deposit_requests')) {
        return false;
    }

    $row = $db->select_user(
        "SELECT crypto_deposit_requests.id
         FROM crypto_deposit_requests
         LEFT JOIN crypto_wallet_assignments AS payment_assignment
            ON payment_assignment.id = crypto_deposit_requests.wallet_assignment_id
         WHERE crypto_deposit_requests.customer_id = {$customerId}
           AND (
                crypto_deposit_requests.wallet_address_id = {$walletId}
             OR payment_assignment.wallet_address_id = {$walletId}
           )
           AND crypto_deposit_requests.status NOT IN ('pending', 'pending_payment', 'cancelled')
         ORDER BY crypto_deposit_requests.id DESC
         LIMIT 1"
    );

    return is_array($row) && !empty($row['id']);
}

function admin_crypto_payment_wallet_address_id(Mysql_ks $db, array $payment): int
{
    $walletAddressId = (int)($payment['wallet_address_id'] ?? 0);
    if ($walletAddressId > 0) {
        return $walletAddressId;
    }

    $walletAssignmentId = (int)($payment['wallet_assignment_id'] ?? 0);
    if ($walletAssignmentId <= 0 || !schema_object_exists($db, 'crypto_wallet_assignments')) {
        return 0;
    }

    $row = $db->select_user(
        "SELECT wallet_address_id
         FROM crypto_wallet_assignments
         WHERE id = {$walletAssignmentId}
         LIMIT 1"
    );

    return (int)($row['wallet_address_id'] ?? 0);
}

