function admin_save_crypto_wallet(Mysql_ks $db, int $walletId, array $payload, int $adminUserId, string $ipAddress = ''): array
{
    admin_ensure_crypto_wallet_address_indexes($db);
    $messages = admin_load_messages(admin_current_locale());
    $t = static fn(string $key, string $default): string => admin_t($messages, $key, $default);

    $isCreate = $walletId <= 0;
    $wallet = $isCreate ? null : admin_crypto_wallet_find($db, $walletId);
    if (!$isCreate && (!is_array($wallet) || empty($wallet['id']))) {
        return ['ok' => false, 'message' => $t('wallet_error_not_found', 'Wallet not found.')];
    }

    $cryptoAssetId = (int)($payload['crypto_asset_id'] ?? 0);
    $address = trim((string)($payload['address'] ?? ''));
    if ($address !== '' && app_panel_tiers_installed($db)) {
        $panelConfig=app_panel_tiers_config($db);
        foreach(app_panel_tiers_assets() as $code=>$spec){
            $reserved=trim((string)($panelConfig[$spec['wallet']]??''));
            if($reserved!=='' && ($address===$reserved || (in_array($code,['USDT','BTC'],true) && strtolower($address)===strtolower($reserved)))) return ['ok'=>false,'message'=>admin_panel_tiers_text('receivers')];
        }
    }
    $label = trim((string)($payload['label'] ?? ''));
    $ownerFullName = trim((string)($payload['owner_full_name'] ?? ''));
    $memoTag = trim((string)($payload['memo_tag'] ?? ''));
    $walletProvider = trim((string)($payload['wallet_provider'] ?? ''));
    $networkCode = trim((string)($payload['network_code'] ?? ''));
    $notes = trim((string)($payload['notes'] ?? ''));
    $statusChoice = strtolower(trim((string)($payload['wallet_status'] ?? 'available')));

    $asset = $cryptoAssetId > 0 ? $db->select_user("SELECT id, code, is_active FROM crypto_assets WHERE id = {$cryptoAssetId} LIMIT 1") : null;
    if ($cryptoAssetId <= 0 || !is_array($asset)) {
        return ['ok' => false, 'message' => $t('wallet_error_invalid_asset', 'Invalid crypto asset.')];
    }
    if ($isCreate && empty($asset['is_active'])) {
        return ['ok' => false, 'message' => $t('wallet_error_choose_active_asset', 'Choose an active cryptocurrency first.')];
    }
    if ($isCreate && !admin_crypto_asset_allows_customer_payments((string)($asset['code'] ?? ''))) {
        return ['ok' => false, 'message' => $t('wallet_error_asset_disabled_for_payments', 'This cryptocurrency is disabled for customer payments.')];
    }

    if ($address === '') {
        return ['ok' => false, 'message' => $t('wallet_error_address_required', 'Wallet address is required.')];
    }

    if ($label === '') {
        return ['ok' => false, 'message' => $t('wallet_error_label_required', 'Wallet name / info is required.')];
    }

    $networkCode = admin_normalize_crypto_wallet_network((string)($asset['code'] ?? ''), $networkCode, $address);
    if ($networkCode === '') {
        return ['ok' => false, 'message' => $t('wallet_error_network_required', 'Network is required for this wallet.')];
    }
    if (strtoupper(trim((string)($asset['code'] ?? ''))) === 'TRX' && preg_match('/^T[1-9A-HJ-NP-Za-km-z]{33}$/', $address) !== 1) {
        return ['ok' => false, 'message' => $t('wallet_error_invalid_tron_address', 'Enter a valid TRON address beginning with T.')];
    }

    $duplicateContext = admin_crypto_wallet_address_duplicate_context($db, $address, $cryptoAssetId, $networkCode, $walletId);
    if (!empty($duplicateContext['has_existing'])) {
        if (empty($duplicateContext['can_reuse'])) {
            return [
                'ok' => false,
                'message' => admin_t($messages, (string)($duplicateContext['message_key'] ?? ''), (string)($duplicateContext['message'] ?? 'This wallet address already exists in the database.')),
            ];
        }

        $canonicalWallet = is_array($duplicateContext['canonical'] ?? null) ? $duplicateContext['canonical'] : [];
        $canonicalOwnerFullName = trim((string)($canonicalWallet['owner_full_name'] ?? ''));
        $canonicalWalletProvider = trim((string)($canonicalWallet['wallet_provider'] ?? ''));
        $canonicalNotes = trim((string)($canonicalWallet['notes'] ?? ''));
        $canonicalMemoTag = trim((string)($canonicalWallet['memo_tag'] ?? ''));

        if ($canonicalOwnerFullName !== '') {
            $ownerFullName = $canonicalOwnerFullName;
        }
        if ($canonicalWalletProvider !== '') {
            $walletProvider = $canonicalWalletProvider;
        }
        if ($canonicalNotes !== '') {
            $notes = $canonicalNotes;
        }
        if ($canonicalMemoTag !== '' && $memoTag === '') {
            $memoTag = $canonicalMemoTag;
        }
    }

    $generatedOwnerProfile = null;
    if ($ownerFullName === '') {
        $generatedOwnerProfile = admin_random_wallet_owner_profile();
        $ownerFullName = (string)($generatedOwnerProfile['full_name'] ?? '');
    }

    if ($notes === '') {
        $locationSeed = '';
        if ($generatedOwnerProfile && !empty($generatedOwnerProfile['location'])) {
            $locationSeed = (string)$generatedOwnerProfile['location'];
        } else {
            $locationSeed = admin_wallet_owner_location_by_name($ownerFullName);
        }
        $notes = app_wallet_notes_with_location($notes, $locationSeed);
    }

    if (!in_array($statusChoice, array_keys(admin_crypto_wallet_status_options()), true)) {
        $statusChoice = 'available';
    }

    $activeAssignmentCount = $isCreate ? 0 : count(admin_crypto_wallet_active_assignments($db, $walletId));
    $finalWalletStatus = $activeAssignmentCount > 0 ? 'assigned' : ($statusChoice === 'disabled' ? 'disabled' : 'available');
    $disabledAtValue = $finalWalletStatus === 'disabled' ? $db->expr('NOW()') : null;
    $createdEvmCompanionWalletId = 0;

    $db->start();

    if ($isCreate) {
        $insertOk = $db->insert(
            ['crypto_asset_id', 'label', 'owner_full_name', 'address', 'network_code', 'memo_tag', 'wallet_provider', 'status', 'notes', 'disabled_at', 'created_by_admin_user_id'],
            [$cryptoAssetId, $label, $ownerFullName, $address, $networkCode, $memoTag !== '' ? $memoTag : null, $walletProvider !== '' ? $walletProvider : null, $finalWalletStatus, $notes !== '' ? $notes : null, $disabledAtValue, $adminUserId],
            'crypto_wallet_addresses'
        );

        if (!$insertOk || (int)$db->id() <= 0) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => $t('wallet_error_create_failed', 'Unable to create wallet.')];
        }

        $walletId = (int)$db->id();
        if (!empty($payload['create_usdt_companion_wallet'])) {
            $companionResult = admin_crypto_wallet_create_evm_companion(
                $db,
                (string)($asset['code'] ?? ''),
                $networkCode,
                $label,
                $ownerFullName,
                $address,
                $memoTag,
                $walletProvider,
                $finalWalletStatus,
                $notes,
                $disabledAtValue,
                $adminUserId
            );
            if (empty($companionResult['ok'])) {
                $db->query('ROLLBACK');
                return [
                    'ok' => false,
                    'message' => (string)($companionResult['message'] ?? $t('wallet_error_create_evm_companion_failed', 'Unable to create paired EVM wallet for this address.')),
                ];
            }
            if (!empty($companionResult['created'])) {
                $createdEvmCompanionWalletId = (int)($companionResult['wallet_id'] ?? 0);
            }
        }
    } else {
        $updateOk = $db->update_using_id(
            ['crypto_asset_id', 'label', 'owner_full_name', 'address', 'network_code', 'memo_tag', 'wallet_provider', 'status', 'notes', 'disabled_at'],
            [$cryptoAssetId, $label, $ownerFullName, $address, $networkCode, $memoTag !== '' ? $memoTag : null, $walletProvider !== '' ? $walletProvider : null, $finalWalletStatus, $notes !== '' ? $notes : null, $disabledAtValue],
            'crypto_wallet_addresses',
            $walletId
        );

        if (!$updateOk) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => $t('wallet_error_update_failed', 'Unable to update wallet.')];
        }
    }

    $db->commit();

    admin_activity_log(
        $db,
        0,
        $adminUserId,
        $isCreate ? 'crypto_wallet_created' : 'crypto_wallet_updated',
        'Crypto wallet #' . $walletId . ($isCreate ? ' created: ' : ' saved: ') . ($label !== '' ? $label : $address) . '.',
        $ipAddress
    );

    if ($createdEvmCompanionWalletId > 0) {
        admin_activity_log(
            $db,
            0,
            $adminUserId,
            'crypto_wallet_created',
            'EVM companion wallet #' . $createdEvmCompanionWalletId . ' created for EVM wallet #' . $walletId . '.',
            $ipAddress
        );
    }

    return [
        'ok' => true,
        'message' => $createdEvmCompanionWalletId > 0
            ? $t('wallet_created_with_evm_companion', 'Wallet and paired EVM wallet created successfully.')
            : ($isCreate ? $t('wallet_created_success', 'Wallet created successfully.') : $t('wallet_saved_success', 'Wallet saved successfully.')),
        'wallet_id' => $walletId,
        'evm_companion_wallet_id' => $createdEvmCompanionWalletId,
    ];
}

function admin_assign_crypto_wallet_customer(Mysql_ks $db, int $walletId, int $customerId, int $adminUserId, array $settings, string $ipAddress = '', bool $manageTransaction = true): array
{
    $wallet = admin_crypto_wallet_find($db, $walletId);
    if (!is_array($wallet) || empty($wallet['id'])) {
        return ['ok' => false, 'message' => 'Wallet not found.'];
    }

    $customer = admin_customer_basic_row($db, $customerId);
    if (!is_array($customer) || empty($customer['id'])) {
        return ['ok' => false, 'message' => 'Customer not found.'];
    }

    if ((string)($wallet['status'] ?? '') === 'disabled') {
        return ['ok' => false, 'message' => 'Disabled wallet cannot be assigned.'];
    }

    if (function_exists('app_crypto_wallet_has_non_cancelled_history_for_other_customer')
        && app_crypto_wallet_has_non_cancelled_history_for_other_customer($db, $walletId, $customerId)
    ) {
        return ['ok' => false, 'message' => 'This wallet already has payment history for another customer and cannot be assigned again.'];
    }

    $sharedEnabled = admin_crypto_wallet_shared_assignments_enabled($settings);
    if (!$sharedEnabled) {
        if (app_crypto_wallet_has_active_assignment_for_other_customer($db, $walletId, $customerId)) {
            return ['ok' => false, 'message' => 'This wallet is already assigned to another customer.'];
        }

        if (app_crypto_wallet_has_open_request_for_other_customer($db, $walletId, $customerId)) {
            return ['ok' => false, 'message' => 'This wallet already has an active payment request for another customer.'];
        }
    }

    $activeAssignments = admin_crypto_wallet_active_assignments($db, $walletId);
    $customerAssignments = admin_customer_active_crypto_assignments($db, $customerId, strtoupper(trim((string)($wallet['asset_code'] ?? ''))));
    $existingCustomerAssignmentId = 0;
    foreach ($customerAssignments as $assignment) {
        if ((int)$assignment['customer_id'] === $customerId) {
            if ((int)$assignment['wallet_address_id'] === $walletId) {
                $existingCustomerAssignmentId = (int)($assignment['wallet_assignment_id'] ?? 0);
                break;
            }
        }
    }

    if ($existingCustomerAssignmentId > 0 && ($sharedEnabled || count($customerAssignments) <= 1)) {
        $db->query(
            "UPDATE crypto_wallet_assignments
             SET status = 'active',
                 released_at = NULL,
                 released_by_admin_user_id = NULL
             WHERE id = {$existingCustomerAssignmentId}"
        );
        $db->update_using_id(
            ['status', 'last_assigned_at', 'disabled_at'],
            ['assigned', $db->expr('NOW()'), null],
            'crypto_wallet_addresses',
            $walletId
        );
        admin_cleanup_duplicate_crypto_wallet_assignments(
            $db,
            $walletId,
            $customerId,
            $existingCustomerAssignmentId,
            $adminUserId,
            'Released duplicate crypto wallet assignment from admin wallet editor'
        );
        return [
            'ok' => true,
            'message' => 'This wallet is already assigned to the selected customer.',
            'wallet_assignment_id' => $existingCustomerAssignmentId,
            'wallet_address_id' => $walletId,
        ];
    }

    if ($manageTransaction) { $db->start(); }
    $lockedWallet = $db->select_user(
        "SELECT id, status, disabled_at
         FROM crypto_wallet_addresses
         WHERE id = {$walletId}
         LIMIT 1
         FOR UPDATE"
    );
    if (!is_array($lockedWallet) || empty($lockedWallet['id']) || !empty($lockedWallet['disabled_at']) || (string)($lockedWallet['status'] ?? '') === 'disabled') {
        $db->query('ROLLBACK');
        return ['ok' => false, 'message' => 'Wallet is no longer available.'];
    }

    if (!$sharedEnabled) {
        $activeAssignments = $db->select_full_user(
            "SELECT
                crypto_wallet_assignments.id,
                crypto_wallet_assignments.customer_id,
                customers.email AS customer_email
             FROM crypto_wallet_assignments
             INNER JOIN customers ON customers.id = crypto_wallet_assignments.customer_id
             WHERE crypto_wallet_assignments.wallet_address_id = {$walletId}
               AND crypto_wallet_assignments.status IN ('reserved', 'active')
             ORDER BY crypto_wallet_assignments.assigned_at DESC, crypto_wallet_assignments.id DESC
             FOR UPDATE"
        );
    }

    $walletAssignmentId = $existingCustomerAssignmentId;

    if (!$sharedEnabled && $activeAssignments) {
        foreach ($activeAssignments as $assignment) {
            $assignedCustomerId = (int)($assignment['customer_id'] ?? 0);
            if ($assignedCustomerId === $customerId) {
                continue;
            }

            $releaseNote = 'Released from admin wallet editor';
            if (admin_crypto_wallet_assignment_has_payment_history($db, $walletId, $assignedCustomerId)) {
                $otherCustomerAssignments = admin_customer_active_crypto_assignments(
                    $db,
                    $assignedCustomerId,
                    strtoupper(trim((string)($wallet['asset_code'] ?? '')))
                );

                $hasReplacementWallet = false;
                foreach ($otherCustomerAssignments as $otherCustomerAssignment) {
                    $otherWalletId = (int)($otherCustomerAssignment['wallet_address_id'] ?? 0);
                    if ($otherWalletId > 0 && $otherWalletId !== $walletId) {
                        $hasReplacementWallet = true;
                        break;
                    }
                }

                if (!$hasReplacementWallet) {
                    $otherCustomerEmail = trim((string)($assignment['customer_email'] ?? ''));
                    $db->query('ROLLBACK');
                    return ['ok' => false, 'message' => 'This wallet already has payment history for ' . ($otherCustomerEmail !== '' ? $otherCustomerEmail : 'another customer') . ' and cannot be reassigned.'];
                }

                $releaseNote = 'Released from admin wallet editor after customer was moved to another active wallet of this coin';
            }

            $releaseOk = admin_release_crypto_wallet_assignment($db, (int)$assignment['id'], $adminUserId, $releaseNote);

            if (!$releaseOk) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to release current wallet assignment.'];
            }
        }
    }

    if (!$sharedEnabled && $customerAssignments) {
        foreach ($customerAssignments as $assignment) {
            $assignmentWalletId = (int)($assignment['wallet_address_id'] ?? 0);
            $assignmentId = (int)($assignment['wallet_assignment_id'] ?? 0);
            if ($assignmentWalletId === $walletId || $assignmentId <= 0) {
                continue;
            }

            $previousAddress = trim((string)($assignment['address'] ?? ''));
            $newAddress = trim((string)($wallet['address'] ?? ''));
            $releaseNote = 'Moved to a new wallet from admin wallet editor';
            if ($previousAddress !== '' || $newAddress !== '') {
                $releaseNote .= ' [' . $previousAddress . '] -> [' . $newAddress . ']';
            }

            $releaseOk = admin_release_crypto_wallet_assignment($db, $assignmentId, $adminUserId, $releaseNote);
            if (!$releaseOk) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to release previous wallet assignment.'];
            }
        }
    }

    if ($existingCustomerAssignmentId <= 0) {
        if (!$sharedEnabled) {
            if (app_crypto_wallet_has_active_assignment_for_other_customer($db, $walletId, $customerId)) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'This wallet is already assigned to another customer.'];
            }

            if (app_crypto_wallet_has_open_request_for_other_customer($db, $walletId, $customerId)) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'This wallet already has an active payment request for another customer.'];
            }

            if (app_crypto_wallet_has_non_cancelled_history_for_other_customer($db, $walletId, $customerId)) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'This wallet already has payment history for another customer and cannot be assigned again.'];
            }
        }

        $insertOk = $db->insert(
            ['wallet_address_id', 'customer_id', 'assignment_reason', 'status', 'assigned_by_admin_user_id', 'assignment_note'],
            [$walletId, $customerId, 'manual_customer_wallet', 'active', $adminUserId, 'Assigned from admin wallet editor'],
            'crypto_wallet_assignments'
        );

        if (!$insertOk) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Unable to assign wallet to the selected customer.'];
        }

        $walletAssignmentId = (int)$db->id();
        if ($walletAssignmentId <= 0) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Wallet assignment could not be created.'];
        }
    }

    $db->update_using_id(
        ['status', 'last_assigned_at', 'disabled_at'],
        ['assigned', $db->expr('NOW()'), null],
        'crypto_wallet_addresses',
        $walletId
    );
    admin_cleanup_duplicate_crypto_wallet_assignments(
        $db,
        $walletId,
        $customerId,
        $walletAssignmentId,
        $adminUserId,
        'Released duplicate crypto wallet assignment from admin wallet editor'
    );

    if ($manageTransaction) { $db->commit(); }

    admin_log_customer_and_admin(
        $db,
        $customerId,
        $adminUserId,
        'crypto_wallet_assignment_updated',
        'Crypto wallet #' . $walletId . ' assigned to customer #' . $customerId . '.',
        $ipAddress
    );

    return [
        'ok' => true,
        'message' => 'Wallet assignment updated.',
        'wallet_assignment_id' => $walletAssignmentId,
        'wallet_address_id' => $walletId,
    ];
}

function admin_remove_crypto_wallet_assignment(Mysql_ks $db, int $walletId, int $assignmentId, int $adminUserId, string $ipAddress = ''): array
{
    $assignment = $db->select_user(
        "SELECT id, customer_id
         FROM crypto_wallet_assignments
         WHERE id = {$assignmentId}
           AND wallet_address_id = {$walletId}
           AND status IN ('reserved', 'active')
         LIMIT 1"
    );

    if (!is_array($assignment) || empty($assignment['id'])) {
        return ['ok' => false, 'message' => 'Assignment not found.'];
    }

    $hasPaymentHistory = admin_crypto_wallet_assignment_has_payment_history(
        $db,
        $walletId,
        (int)($assignment['customer_id'] ?? 0)
    );

    if ($hasPaymentHistory) {
        return ['ok' => false, 'message' => 'This assignment cannot be removed because the customer already used this wallet for at least one payment.'];
    }

    $db->start();

    $releaseOk = admin_release_crypto_wallet_assignment(
        $db,
        $assignmentId,
        $adminUserId,
        'Removed from admin wallet editor'
    );

    if (!$releaseOk) {
        $db->query('ROLLBACK');
        return ['ok' => false, 'message' => 'Unable to remove wallet assignment.'];
    }

    $remainingAssignments = admin_crypto_wallet_active_assignments($db, $walletId);
    $walletStatus = $remainingAssignments ? 'assigned' : 'available';
    $db->update_using_id(
        ['status', 'disabled_at'],
        [$walletStatus, $walletStatus === 'available' ? null : null],
        'crypto_wallet_addresses',
        $walletId
    );

    $db->commit();

    admin_log_customer_and_admin(
        $db,
        (int)($assignment['customer_id'] ?? 0),
        $adminUserId,
        'crypto_wallet_assignment_removed',
        'Crypto wallet assignment #' . $assignmentId . ' removed from wallet #' . $walletId . '.',
        $ipAddress
    );

    return ['ok' => true, 'message' => 'Wallet assignment removed.'];
}

function admin_delete_crypto_wallet(Mysql_ks $db, int $walletId, int $adminUserId, string $ipAddress = ''): array
{
    $wallet = admin_crypto_wallet_find($db, $walletId);
    if (!is_array($wallet) || empty($wallet['id'])) {
        return ['ok' => false, 'message' => 'Wallet not found.'];
    }

    $summary = admin_crypto_wallet_delete_summary($db, $walletId);
    if (empty($summary['can_delete'])) {
        return ['ok' => false, 'message' => 'This wallet still has active assignments, payment history or transaction history and cannot be deleted.'];
    }

    $deletedAssignmentHistory = 0;
    $db->query('START TRANSACTION');

    if (schema_object_exists($db, 'crypto_wallet_assignments')) {
        $deletedAssignmentHistory = (int)($summary['assignments_total'] ?? 0);
        $deletedAssignmentsOk = $db->query("DELETE FROM crypto_wallet_assignments WHERE wallet_address_id = {$walletId}");
        if ($deletedAssignmentsOk === false) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Unable to clean wallet assignment history.'];
        }
    }

    $deleted = $db->delete_using_id('crypto_wallet_addresses', $walletId);
    if (!$deleted) {
        $db->query('ROLLBACK');
        return ['ok' => false, 'message' => 'Unable to delete wallet.'];
    }

    $db->query('COMMIT');

    $walletLabel = trim((string)($wallet['label'] ?? ''));
    $walletAddress = trim((string)($wallet['address'] ?? ''));
    admin_activity_log(
        $db,
        0,
        $adminUserId,
        'crypto_wallet_deleted',
        'Crypto wallet #' . $walletId . ' deleted: ' . ($walletLabel !== '' ? $walletLabel : $walletAddress) . '. Removed assignment history rows: ' . $deletedAssignmentHistory . '.',
        $ipAddress
    );

    return ['ok' => true, 'message' => 'Wallet deleted successfully.'];
}

function admin_release_crypto_wallet_assignment(Mysql_ks $db, int $assignmentId, int $adminUserId, string $note): bool
{
    $safeNote = $db->escape($note);

    $assignment = $db->select_user(
        "SELECT wallet_address_id
         FROM crypto_wallet_assignments
         WHERE id = {$assignmentId}
         LIMIT 1"
    );

    $released = (bool)$db->query(
        "UPDATE crypto_wallet_assignments
         SET status = 'released',
             released_at = NOW(),
             released_by_admin_user_id = {$adminUserId},
             assignment_note = CONCAT(COALESCE(assignment_note, ''), '\n{$safeNote}')
         WHERE id = {$assignmentId}"
    );

    if ($released) {
        app_sync_crypto_wallet_address_statuses($db, (int)($assignment['wallet_address_id'] ?? 0));
    }

    return $released;
}

function admin_ensure_crypto_wallet_assignment_for_payment(Mysql_ks $db, array $payment, int $adminUserId, array $settings, string $ipAddress = ''): array
{
    $paymentType = strtolower(trim((string)($payment['payment_type'] ?? '')));
    $customerId = (int)($payment['customer_id'] ?? 0);
    if ($paymentType !== 'crypto' || $customerId <= 0) {
        return ['ok' => true];
    }

    $walletAddressId = admin_crypto_payment_wallet_address_id($db, $payment);
    if ($walletAddressId <= 0) {
        return ['ok' => true];
    }

    if (!admin_crypto_wallet_shared_assignments_enabled($settings)) {
        if (app_crypto_wallet_has_active_assignment_for_other_customer($db, $walletAddressId, $customerId)) {
            return ['ok' => false, 'message' => 'This wallet is already assigned to another customer.'];
        }

        if (app_crypto_wallet_has_open_request_for_other_customer($db, $walletAddressId, $customerId)) {
            return ['ok' => false, 'message' => 'This wallet already has an active payment request for another customer.'];
        }

        if (app_crypto_wallet_has_non_cancelled_history_for_other_customer($db, $walletAddressId, $customerId)) {
            return ['ok' => false, 'message' => 'This wallet already has payment history for another customer and cannot be assigned again.'];
        }
    }

    $paymentId = (int)($payment['id'] ?? 0);
    $walletAssignmentId = (int)($payment['wallet_assignment_id'] ?? 0);
    $existingAssignment = null;

    if ($walletAssignmentId > 0) {
        $existingAssignment = $db->select_user(
            "SELECT id
             FROM crypto_wallet_assignments
             WHERE id = {$walletAssignmentId}
               AND wallet_address_id = {$walletAddressId}
               AND customer_id = {$customerId}
             LIMIT 1"
        );
    }

    if (!is_array($existingAssignment) || empty($existingAssignment['id'])) {
        $existingAssignment = $db->select_user(
            "SELECT id
             FROM crypto_wallet_assignments
             WHERE wallet_address_id = {$walletAddressId}
               AND customer_id = {$customerId}
             ORDER BY id DESC
             LIMIT 1"
        );
    }

    if (is_array($existingAssignment) && !empty($existingAssignment['id'])) {
        $walletAssignmentId = (int)$existingAssignment['id'];
        $db->query(
            "UPDATE crypto_wallet_assignments
             SET status = 'active',
                 released_at = NULL,
                 released_by_admin_user_id = NULL
             WHERE id = {$walletAssignmentId}"
        );
        $db->update_using_id(
            ['status', 'last_assigned_at', 'disabled_at'],
            ['assigned', $db->expr('NOW()'), null],
            'crypto_wallet_addresses',
            $walletAddressId
        );
    } else {
        $assignResult = admin_assign_crypto_wallet_customer($db, $walletAddressId, $customerId, $adminUserId, $settings, $ipAddress);
        if (empty($assignResult['ok'])) {
            return $assignResult;
        }
        $walletAssignmentId = (int)($assignResult['wallet_assignment_id'] ?? 0);
    }

    if ($walletAssignmentId > 0) {
        admin_cleanup_duplicate_crypto_wallet_assignments(
            $db,
            $walletAddressId,
            $customerId,
            $walletAssignmentId,
            $adminUserId,
            'Released duplicate crypto wallet assignment after payment confirmation'
        );
    }

    if ($paymentId > 0) {
        $db->update_using_id(
            ['wallet_address_id', 'wallet_assignment_id'],
            [$walletAddressId, $walletAssignmentId > 0 ? $walletAssignmentId : null],
            'crypto_deposit_requests',
            $paymentId
        );
    }

    return [
        'ok' => true,
        'wallet_address_id' => $walletAddressId,
        'wallet_assignment_id' => $walletAssignmentId,
    ];
}

function admin_ensure_bank_account_assignment_for_payment(Mysql_ks $db, array $payment, int $adminUserId, array $settings, string $ipAddress = ''): array
{
    $paymentType = strtolower(trim((string)($payment['payment_type'] ?? '')));
    $customerId = (int)($payment['customer_id'] ?? 0);
    $bankAccountId = (int)($payment['bank_account_id'] ?? 0);
    if ($paymentType !== 'bank' || $customerId <= 0 || $bankAccountId <= 0) {
        return ['ok' => true];
    }

    $paymentId = (int)($payment['id'] ?? 0);
    $bankAccountAssignmentId = (int)($payment['bank_account_assignment_id'] ?? 0);
    $existingAssignment = null;

    if ($bankAccountAssignmentId > 0) {
        $existingAssignment = $db->select_user(
            "SELECT id
             FROM bank_account_assignments
             WHERE id = {$bankAccountAssignmentId}
               AND bank_account_id = {$bankAccountId}
               AND customer_id = {$customerId}
             LIMIT 1"
        );
    }

    if (!is_array($existingAssignment) || empty($existingAssignment['id'])) {
        $existingAssignment = $db->select_user(
            "SELECT id
             FROM bank_account_assignments
             WHERE bank_account_id = {$bankAccountId}
               AND customer_id = {$customerId}
             ORDER BY id DESC
             LIMIT 1"
        );
    }

    if (is_array($existingAssignment) && !empty($existingAssignment['id'])) {
        $bankAccountAssignmentId = (int)$existingAssignment['id'];
        $db->query(
            "UPDATE bank_account_assignments
             SET status = 'active',
                 released_at = NULL,
                 released_by_admin_user_id = NULL
             WHERE id = {$bankAccountAssignmentId}"
        );
        $db->update_using_id(
            ['status', 'last_assigned_at', 'disabled_at'],
            ['assigned', $db->expr('NOW()'), null],
            'bank_accounts',
            $bankAccountId
        );
    } else {
        $assignResult = admin_assign_bank_account_customer($db, $bankAccountId, $customerId, $adminUserId, $settings, $ipAddress);
        if (empty($assignResult['ok'])) {
            return $assignResult;
        }
        $bankAccountAssignmentId = (int)($assignResult['bank_account_assignment_id'] ?? 0);
        if ($bankAccountAssignmentId <= 0) {
            $assignmentRow = $db->select_user(
                "SELECT id
                 FROM bank_account_assignments
                 WHERE bank_account_id = {$bankAccountId}
                   AND customer_id = {$customerId}
                 ORDER BY id DESC
                 LIMIT 1"
            );
            $bankAccountAssignmentId = (int)($assignmentRow['id'] ?? 0);
        }
    }

    if ($paymentId > 0) {
        $db->update_using_id(
            ['bank_account_assignment_id'],
            [$bankAccountAssignmentId > 0 ? $bankAccountAssignmentId : null],
            'bank_transfer_requests',
            $paymentId
        );
    }

    return [
        'ok' => true,
        'bank_account_id' => $bankAccountId,
        'bank_account_assignment_id' => $bankAccountAssignmentId,
    ];
}

function admin_bank_account_find(Mysql_ks $db, int $accountId): ?array
{
    if ($accountId <= 0 || !schema_object_exists($db, 'bank_accounts')) {
        return null;
    }

    app_ensure_bank_account_runtime_columns($db);

    $row = $db->select_user(
        "SELECT
            bank_accounts.*,
            currencies.code AS currency_code
         FROM bank_accounts
         LEFT JOIN currencies ON currencies.id = bank_accounts.currency_id
         WHERE bank_accounts.id = {$accountId}
         LIMIT 1"
    );

    return is_array($row) ? $row : null;
}

function admin_bank_account_active_assignments(Mysql_ks $db, int $accountId): array
{
    if ($accountId <= 0 || !schema_object_exists($db, 'bank_account_assignments')) {
        return [];
    }

    return $db->select_full_user(
        "SELECT
            bank_account_assignments.id,
            bank_account_assignments.customer_id,
            bank_account_assignments.status,
            bank_account_assignments.assigned_at,
            bank_account_assignments.assignment_note,
            customers.email AS customer_email
         FROM bank_account_assignments
         INNER JOIN customers ON customers.id = bank_account_assignments.customer_id
         WHERE bank_account_assignments.bank_account_id = {$accountId}
           AND bank_account_assignments.status IN ('reserved', 'active')
         ORDER BY bank_account_assignments.assigned_at DESC, bank_account_assignments.id DESC"
    );
}

function admin_save_bank_account(Mysql_ks $db, int $accountId, array $payload, int $adminUserId, string $ipAddress = ''): array
{
    app_ensure_bank_account_runtime_columns($db);

    $isCreate = $accountId <= 0;
    $account = $isCreate ? null : admin_bank_account_find($db, $accountId);
    if (!$isCreate && (!is_array($account) || empty($account['id']))) {
        return ['ok' => false, 'message' => 'Bank account not found.'];
    }

    $currencyId = (int)($payload['currency_id'] ?? 0);
    $label = trim((string)($payload['label'] ?? ''));
    $accountHolderName = trim((string)($payload['account_holder_name'] ?? ''));
    $bankName = trim((string)($payload['bank_name'] ?? ''));
    $bankAddress = trim((string)($payload['bank_address'] ?? ''));
    $countryCode = strtoupper(trim((string)($payload['country_code'] ?? '')));
    $iban = trim((string)($payload['iban'] ?? ''));
    $accountNumber = trim((string)($payload['account_number'] ?? ''));
    $routingNumber = trim((string)($payload['routing_number'] ?? ''));
    $swiftBic = strtoupper(trim((string)($payload['swift_bic'] ?? '')));
    $transferInstructions = trim((string)($payload['transfer_instructions'] ?? ''));
    $paymentReferenceTemplate = trim((string)($payload['payment_reference_template'] ?? ''));
    $monthlyLimitRaw = str_replace(',', '.', trim((string)($payload['monthly_limit_amount'] ?? '')));
    $monthlyLimitAmount = null;
    if ($monthlyLimitRaw !== '') {
        if (!is_numeric($monthlyLimitRaw) || (float)$monthlyLimitRaw < 0) {
            return ['ok' => false, 'message' => 'Monthly limit must be a valid amount or empty for no limit.'];
        }
        $monthlyLimitAmount = round((float)$monthlyLimitRaw, 2);
        if ($monthlyLimitAmount <= 0) {
            $monthlyLimitAmount = null;
        }
    }
    $notes = trim((string)($payload['notes'] ?? ''));
    $statusChoice = strtolower(trim((string)($payload['bank_account_status'] ?? 'available')));

    if ($accountHolderName === '') {
        return ['ok' => false, 'message' => 'Account holder name is required.'];
    }

    if ($bankName === '') {
        return ['ok' => false, 'message' => 'Bank name is required.'];
    }

    if ($iban === '' && $accountNumber === '') {
        return ['ok' => false, 'message' => 'IBAN or account number is required.'];
    }

    if ($isCreate) {
        $currencyRow = $currencyId > 0
            ? $db->select_user("SELECT id FROM currencies WHERE id = {$currencyId} LIMIT 1")
            : null;
        if ($currencyId <= 0 || !is_array($currencyRow)) {
            return ['ok' => false, 'message' => 'Choose a valid currency first.'];
        }
    }

    if (!in_array($statusChoice, array_keys(admin_bank_account_status_options()), true)) {
        $statusChoice = 'available';
    }

    $activeAssignmentCount = $isCreate ? 0 : count(admin_bank_account_active_assignments($db, $accountId));
    $finalStatus = $activeAssignmentCount > 0 ? 'assigned' : ($statusChoice === 'disabled' ? 'disabled' : 'available');
    $disabledAtValue = $finalStatus === 'disabled' ? $db->expr('NOW()') : null;

    if ($isCreate) {
        $insertOk = $db->insert(
            [
                'currency_id',
                'label',
                'account_holder_name',
                'bank_name',
                'bank_address',
                'country_code',
                'iban',
                'account_number',
                'routing_number',
                'swift_bic',
                'payment_reference_template',
                'transfer_instructions',
                'monthly_limit_amount',
                'status',
                'notes',
                'disabled_at',
                'created_by_admin_user_id',
            ],
            [
                $currencyId,
                $label !== '' ? $label : null,
                $accountHolderName,
                $bankName,
                $bankAddress !== '' ? $bankAddress : null,
                $countryCode !== '' ? $countryCode : null,
                $iban !== '' ? $iban : null,
                $accountNumber !== '' ? $accountNumber : null,
                $routingNumber !== '' ? $routingNumber : null,
                $swiftBic !== '' ? $swiftBic : null,
                $paymentReferenceTemplate !== '' ? $paymentReferenceTemplate : null,
                $transferInstructions !== '' ? $transferInstructions : null,
                $monthlyLimitAmount,
                $finalStatus,
                $notes !== '' ? $notes : null,
                $disabledAtValue,
                $adminUserId,
            ],
            'bank_accounts'
        );

        if (!$insertOk) {
            return ['ok' => false, 'message' => 'Unable to save bank account.'];
        }

        $newAccountId = (int)$db->last_insert_id;
        admin_activity_log(
            $db,
            0,
            $adminUserId,
            'bank_account_created',
            'Bank account #' . $newAccountId . ' created: ' . ($label !== '' ? $label : $bankName) . '.',
            $ipAddress
        );

        return ['ok' => true, 'message' => 'Bank account saved successfully.', 'bank_account_id' => $newAccountId];
    }

    $updateOk = $db->update_using_id(
        [
            'label',
            'account_holder_name',
            'bank_name',
            'bank_address',
            'country_code',
            'iban',
            'account_number',
            'routing_number',
            'swift_bic',
            'payment_reference_template',
            'transfer_instructions',
            'monthly_limit_amount',
            'status',
            'notes',
            'disabled_at',
        ],
        [
            $label !== '' ? $label : null,
            $accountHolderName,
            $bankName,
            $bankAddress !== '' ? $bankAddress : null,
            $countryCode !== '' ? $countryCode : null,
            $iban !== '' ? $iban : null,
            $accountNumber !== '' ? $accountNumber : null,
            $routingNumber !== '' ? $routingNumber : null,
            $swiftBic !== '' ? $swiftBic : null,
            $paymentReferenceTemplate !== '' ? $paymentReferenceTemplate : null,
            $transferInstructions !== '' ? $transferInstructions : null,
            $monthlyLimitAmount,
            $finalStatus,
            $notes !== '' ? $notes : null,
            $disabledAtValue,
        ],
        'bank_accounts',
        $accountId
    );

    if (!$updateOk) {
        return ['ok' => false, 'message' => 'Unable to save bank account.'];
    }

    admin_activity_log(
        $db,
        0,
        $adminUserId,
        'bank_account_updated',
        'Bank account #' . $accountId . ' saved: ' . ($label !== '' ? $label : $bankName) . '.',
        $ipAddress
    );

    return ['ok' => true, 'message' => 'Bank account saved successfully.'];
}

function admin_assign_bank_account_customer(Mysql_ks $db, int $accountId, int $customerId, int $adminUserId, array $settings, string $ipAddress = ''): array
{
    $account = admin_bank_account_find($db, $accountId);
    if (!is_array($account) || empty($account['id'])) {
        return ['ok' => false, 'message' => 'Bank account not found.'];
    }

    $customer = admin_customer_basic_row($db, $customerId);
    if (!is_array($customer) || empty($customer['id'])) {
        return ['ok' => false, 'message' => 'Customer not found.'];
    }

    if ((string)($account['status'] ?? '') === 'disabled') {
        return ['ok' => false, 'message' => 'Disabled bank account cannot be assigned.'];
    }

    $sharedEnabled = admin_bank_account_shared_assignments_enabled($settings);
    $activeAssignments = admin_bank_account_active_assignments($db, $accountId);
    $customerAssignments = admin_customer_active_bank_assignments($db, $customerId);
    $existingCustomerAssignmentId = 0;
    foreach ($customerAssignments as $assignment) {
        if ((int)$assignment['customer_id'] === $customerId) {
            if ((int)$assignment['bank_account_id'] === $accountId) {
                $existingCustomerAssignmentId = (int)($assignment['bank_account_assignment_id'] ?? 0);
                break;
            }
        }
    }

    if ($existingCustomerAssignmentId > 0 && ($sharedEnabled || count($customerAssignments) <= 1)) {
        $db->query(
            "UPDATE bank_account_assignments
             SET status = 'active',
                 released_at = NULL,
                 released_by_admin_user_id = NULL
             WHERE id = {$existingCustomerAssignmentId}"
        );
        $db->update_using_id(
            ['status', 'last_assigned_at', 'disabled_at'],
            ['assigned', $db->expr('NOW()'), null],
            'bank_accounts',
            $accountId
        );
        return [
            'ok' => true,
            'message' => 'This bank account is already assigned to the selected customer.',
            'bank_account_assignment_id' => $existingCustomerAssignmentId,
            'bank_account_id' => $accountId,
        ];
    }

    $db->start();

    if (!$sharedEnabled && $activeAssignments) {
        foreach ($activeAssignments as $assignment) {
            if ((int)$assignment['customer_id'] === $customerId) {
                continue;
            }

            $releaseOk = admin_release_bank_account_assignment($db, (int)$assignment['id'], $adminUserId, 'Released from admin bank account editor');

            if (!$releaseOk) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to release current bank account assignment.'];
            }
        }
    }

    if ($customerAssignments) {
        foreach ($customerAssignments as $assignment) {
            $assignmentAccountId = (int)($assignment['bank_account_id'] ?? 0);
            $assignmentId = (int)($assignment['bank_account_assignment_id'] ?? 0);
            if ($assignmentAccountId === $accountId || $assignmentId <= 0) {
                continue;
            }

            $releaseOk = admin_release_bank_account_assignment($db, $assignmentId, $adminUserId, 'Moved to a new bank account from admin editor');
            if (!$releaseOk) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to release previous bank account assignment.'];
            }
        }
    }

    if ($existingCustomerAssignmentId <= 0) {
        $insertOk = $db->insert(
            ['bank_account_id', 'customer_id', 'assignment_reason', 'status', 'assigned_by_admin_user_id', 'assignment_note'],
            [$accountId, $customerId, 'manual_bank_account', 'active', $adminUserId, 'Assigned from admin bank account editor'],
            'bank_account_assignments'
        );

        if (!$insertOk) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Unable to assign bank account to the selected customer.'];
        }
    }

    $db->update_using_id(
        ['status', 'last_assigned_at', 'disabled_at'],
        ['assigned', $db->expr('NOW()'), null],
        'bank_accounts',
        $accountId
    );

    $db->commit();

    admin_log_customer_and_admin(
        $db,
        $customerId,
        $adminUserId,
        'bank_account_assignment_updated',
        'Bank account #' . $accountId . ' assigned to customer #' . $customerId . '.',
        $ipAddress
    );

    return ['ok' => true, 'message' => 'Bank account assignment updated.'];
}

function admin_remove_bank_account_assignment(Mysql_ks $db, int $accountId, int $assignmentId, int $adminUserId, string $ipAddress = ''): array
{
    $assignment = $db->select_user(
        "SELECT id, customer_id
         FROM bank_account_assignments
         WHERE id = {$assignmentId}
           AND bank_account_id = {$accountId}
           AND status IN ('reserved', 'active')
         LIMIT 1"
    );

    if (!is_array($assignment) || empty($assignment['id'])) {
        return ['ok' => false, 'message' => 'Assignment not found.'];
    }

    $db->start();

    $releaseOk = admin_release_bank_account_assignment(
        $db,
        $assignmentId,
        $adminUserId,
        'Removed from admin bank account editor'
    );

    if (!$releaseOk) {
        $db->query('ROLLBACK');
        return ['ok' => false, 'message' => 'Unable to remove bank account assignment.'];
    }

    $remainingAssignments = admin_bank_account_active_assignments($db, $accountId);
    $accountStatus = $remainingAssignments ? 'assigned' : 'available';
    $db->update_using_id(
        ['status', 'disabled_at'],
        [$accountStatus, null],
        'bank_accounts',
        $accountId
    );

    $db->commit();

    admin_log_customer_and_admin(
        $db,
        (int)($assignment['customer_id'] ?? 0),
        $adminUserId,
        'bank_account_assignment_removed',
        'Bank account assignment #' . $assignmentId . ' removed from account #' . $accountId . '.',
        $ipAddress
    );

    return ['ok' => true, 'message' => 'Bank account assignment removed.'];
}

function admin_delete_bank_account(Mysql_ks $db, int $accountId, int $adminUserId, string $ipAddress = ''): array
{
    $account = admin_bank_account_find($db, $accountId);
    if (!is_array($account) || empty($account['id'])) {
        return ['ok' => false, 'message' => 'Bank account not found.'];
    }

    $activeAssignments = admin_bank_account_active_assignments($db, $accountId);
    if ($activeAssignments) {
        return ['ok' => false, 'message' => 'Release assigned users before deleting this bank account.'];
    }

    if (schema_object_exists($db, 'bank_account_assignments')) {
        $assignmentRow = $db->select_user(
            "SELECT COUNT(*) AS total
             FROM bank_account_assignments
             WHERE bank_account_id = {$accountId}"
        );
        if ((int)($assignmentRow['total'] ?? 0) > 0) {
            return ['ok' => false, 'message' => 'This bank account has assignment history and cannot be deleted.'];
        }
    }

    if (schema_object_exists($db, 'bank_transfer_requests')) {
        $paymentRow = $db->select_user(
            "SELECT COUNT(*) AS total
             FROM bank_transfer_requests
             WHERE bank_account_id = {$accountId}"
        );
        if ((int)($paymentRow['total'] ?? 0) > 0) {
            return ['ok' => false, 'message' => 'This bank account has payment history and cannot be deleted.'];
        }
    }

    $deleted = $db->delete_using_id('bank_accounts', $accountId);
    if (!$deleted) {
        return ['ok' => false, 'message' => 'Unable to delete bank account.'];
    }

    $bankLabel = trim((string)($account['label'] ?? ''));
    $bankName = trim((string)($account['bank_name'] ?? ''));
    admin_activity_log(
        $db,
        0,
        $adminUserId,
        'bank_account_deleted',
        'Bank account #' . $accountId . ' deleted: ' . ($bankLabel !== '' ? $bankLabel : $bankName) . '.',
        $ipAddress
    );

    return ['ok' => true, 'message' => 'Bank account deleted successfully.'];
}

function admin_release_bank_account_assignment(Mysql_ks $db, int $assignmentId, int $adminUserId, string $note): bool
{
    $safeNote = $db->escape($note);

    return (bool)$db->query(
        "UPDATE bank_account_assignments
         SET status = 'released',
             released_at = NOW(),
             released_by_admin_user_id = {$adminUserId},
             assignment_note = CONCAT(COALESCE(assignment_note, ''), '\n{$safeNote}')
         WHERE id = {$assignmentId}"
    );
}

