function admin_chat_inbox_rows(Mysql_ks $db, int $limit = 12, int $adminUserId = 0): array
{
    if (!schema_object_exists($db, 'support_conversations') || !schema_object_exists($db, 'support_messages')) {
        return [];
    }

    chat_ensure_message_interactions_runtime($db);
    app_ensure_customer_runtime_columns($db);
    $settings = function_exists('app_fetch_settings') ? app_fetch_settings($db) : [];
    $settings = is_array($settings) ? $settings : [];
    $globalGroupEnabled = admin_customer_global_group_enabled($settings);
    if ($adminUserId > 0 && $globalGroupEnabled && function_exists('chat_sync_global_group_members')) {
        chat_sync_global_group_members($db, $settings);
    }

    $limit = max(1, min(20, $limit));
    $safeChatEpoch = '1970-01-01 00:00:00';

    $rows = $db->select_full_user(
        "SELECT
            support_conversations.id,
            support_conversations.customer_id,
            support_conversations.subject,
            support_conversations.status,
            support_conversations.created_at,
            support_conversations.updated_at,
            support_conversations.last_customer_message_at,
            support_conversations.last_admin_message_at,
            customers.email AS customer_email,
            NULLIF(TRIM(customers.public_handle), '') AS customer_public_handle,
            customers.avatar_url AS customer_avatar_url,
            customers.last_login_at AS customer_last_login_at,
            (
                SELECT support_messages.message_body
                FROM support_messages
                WHERE support_messages.conversation_id = support_conversations.id
                ORDER BY support_messages.id DESC
                LIMIT 1
            ) AS last_message_body,
            (
                SELECT support_messages.attachment_path
                FROM support_messages
                WHERE support_messages.conversation_id = support_conversations.id
                ORDER BY support_messages.id DESC
                LIMIT 1
            ) AS last_attachment_path,
            (
                SELECT support_messages.message_type
                FROM support_messages
                WHERE support_messages.conversation_id = support_conversations.id
                ORDER BY support_messages.id DESC
                LIMIT 1
            ) AS last_message_type,
            (
                SELECT support_messages.audio_path
                FROM support_messages
                WHERE support_messages.conversation_id = support_conversations.id
                ORDER BY support_messages.id DESC
                LIMIT 1
            ) AS last_audio_path,
            (
                SELECT COUNT(*)
                FROM support_messages
                WHERE support_messages.conversation_id = support_conversations.id
                  AND support_messages.sender_type = 'customer'
                  AND support_messages.is_read = 0
            ) AS unread_count
         FROM support_conversations
         LEFT JOIN customers ON customers.id = support_conversations.customer_id
         WHERE support_conversations.conversation_type = 'live_chat'
         ORDER BY GREATEST(
            COALESCE(support_conversations.last_customer_message_at, '{$safeChatEpoch}'),
            COALESCE(support_conversations.last_admin_message_at, '{$safeChatEpoch}'),
            COALESCE(support_conversations.updated_at, '{$safeChatEpoch}'),
            COALESCE(support_conversations.created_at, '{$safeChatEpoch}')
         ) DESC, support_conversations.id DESC
         LIMIT {$limit}"
    );

    if ($adminUserId > 0) {
        $groupRows = chat_admin_group_conversation_rows($db, $adminUserId, $limit, $globalGroupEnabled);
        if (!$globalGroupEnabled) {
            $groupRows = array_values(array_filter($groupRows, static function (array $groupRow): bool {
                return trim((string)($groupRow['conversation_type'] ?? '')) !== 'global_group';
            }));
        }
        foreach ($groupRows as &$groupRow) {
            $summary = chat_group_conversation_summary(
                $db,
                (int)($groupRow['id'] ?? 0),
                ['participant_type' => 'admin', 'customer_id' => 0, 'admin_user_id' => $adminUserId],
                $groupRow
            );
            $groupRow['summary_title'] = (string)($summary['title'] ?? '');
            $groupRow['summary_presence_key'] = (string)($summary['presence']['key'] ?? 'offline');
            $groupRow['summary_presence_label'] = (string)($summary['presence']['label'] ?? 'Offline');
            $groupRow['summary_presence_class_name'] = (string)($summary['presence']['class_name'] ?? 'admin-chat-presence admin-chat-presence--offline');
            $groupRow['avatar_url'] = (string)($summary['avatar_url'] ?? '');
            $groupRow['avatar_text'] = (string)($summary['avatar_text'] ?? 'G');
            $groupRow['avatar_theme'] = (string)($summary['avatar_theme'] ?? 'theme-6');
        }
        unset($groupRow);
        $rows = array_merge($rows, $groupRows);
    }

    usort($rows, static function (array $left, array $right): int {
        $leftIsGlobal = trim((string)($left['conversation_type'] ?? '')) === 'global_group';
        $rightIsGlobal = trim((string)($right['conversation_type'] ?? '')) === 'global_group';
        if ($leftIsGlobal !== $rightIsGlobal) {
            return $leftIsGlobal ? -1 : 1;
        }

        $leftTime = max(
            strtotime((string)($left['last_customer_message_at'] ?? '')) ?: 0,
            strtotime((string)($left['last_admin_message_at'] ?? '')) ?: 0,
            strtotime((string)($left['updated_at'] ?? '')) ?: 0,
            strtotime((string)($left['created_at'] ?? '')) ?: 0
        );
        $rightTime = max(
            strtotime((string)($right['last_customer_message_at'] ?? '')) ?: 0,
            strtotime((string)($right['last_admin_message_at'] ?? '')) ?: 0,
            strtotime((string)($right['updated_at'] ?? '')) ?: 0,
            strtotime((string)($right['created_at'] ?? '')) ?: 0
        );
        if ($leftTime === $rightTime) {
            return (int)($right['id'] ?? 0) <=> (int)($left['id'] ?? 0);
        }
        return $rightTime <=> $leftTime;
    });

    if (count($rows) > $limit) {
        $rows = array_slice($rows, 0, $limit);
    }

    return $rows;
}

function admin_chat_inbox_unread_count(array $rows): int
{
    $total = 0;
    foreach ($rows as $row) {
        if (trim((string)($row['conversation_type'] ?? '')) === 'global_group') {
            continue;
        }
        $total += (int)($row['unread_count'] ?? 0);
    }

    return $total;
}

function admin_ensure_chat_quick_replies_runtime_table(Mysql_ks $db): void
{
    static $done = false;
    $tableCreated = false;
    if ($done) {
        return;
    }

    if (!schema_object_exists($db, 'support_quick_replies')) {
        $db->query(
            "CREATE TABLE IF NOT EXISTS support_quick_replies (
                id INT UNSIGNED NOT NULL AUTO_INCREMENT,
                locale_code VARCHAR(8) NOT NULL DEFAULT 'en',
                title VARCHAR(191) NOT NULL,
                message_body TEXT NOT NULL,
                is_active TINYINT(1) NOT NULL DEFAULT 1,
                sort_order INT NOT NULL DEFAULT 100,
                created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                PRIMARY KEY (id),
                UNIQUE KEY uniq_support_quick_replies_locale_title (locale_code, title),
                KEY idx_support_quick_replies_active_sort (is_active, locale_code, sort_order, id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
        );
        unset($GLOBALS['schema_object_exists_cache']['support_quick_replies']);
        $tableCreated = true;
    }

    if (schema_object_exists($db, 'support_quick_replies') && !schema_column_exists($db, 'support_quick_replies', 'locale_code')) {
        $db->query("ALTER TABLE support_quick_replies ADD COLUMN locale_code VARCHAR(8) NOT NULL DEFAULT 'en' AFTER id");
        schema_forget_column_cache('support_quick_replies', 'locale_code');
    }

    if ($tableCreated && schema_object_exists($db, 'support_quick_replies')) {
        $seedRows = [
            ['locale_code' => 'en', 'title' => 'Payment instructions', 'message_body' => "Please open the payment page in your account and follow the instructions shown there.\n\nIf you send a bank transfer or crypto payment from an external wallet or app, make sure the full amount reaches our account or wallet.", 'sort_order' => 10],
            ['locale_code' => 'pl', 'title' => 'Instrukcja płatności', 'message_body' => "Otwórz proszę stronę płatności w swoim koncie i postępuj zgodnie z widoczną instrukcją.\n\nJeśli wysyłasz przelew lub krypto z zewnętrznego portfela albo aplikacji, upewnij się, że pełna kwota dotrze do naszego konta lub portfela.", 'sort_order' => 10],
            ['locale_code' => 'en', 'title' => 'Restart app / device', 'message_body' => "Please restart the app and your device first.\n\nThen check if the subscription is active in your account and try again.", 'sort_order' => 20],
            ['locale_code' => 'pl', 'title' => 'Restart aplikacji / urządzenia', 'message_body' => "Najpierw zrestartuj proszę aplikację i urządzenie.\n\nNastępnie sprawdź, czy subskrypcja jest aktywna na koncie, i spróbuj ponownie.", 'sort_order' => 20],
            ['locale_code' => 'en', 'title' => 'Send payment confirmation', 'message_body' => "Please send the payment confirmation in this chat.\n\nAfter verification we will update the order status in your account.", 'sort_order' => 30],
            ['locale_code' => 'pl', 'title' => 'Wyślij potwierdzenie płatności', 'message_body' => "Wyślij proszę potwierdzenie płatności w tym czacie.\n\nPo weryfikacji zaktualizujemy status zamówienia na Twoim koncie.", 'sort_order' => 30],
            ['locale_code' => 'en', 'title' => 'Need app help', 'message_body' => "If you need help with setup, open the Apps page in your account and choose the app for your device.\n\nIf you still need support, write which app and device you use.", 'sort_order' => 40],
            ['locale_code' => 'pl', 'title' => 'Pomoc z aplikacją', 'message_body' => "Jeśli potrzebujesz pomocy z konfiguracją, otwórz podstronę Apps na swoim koncie i wybierz aplikację dla swojego urządzenia.\n\nJeśli nadal potrzebujesz wsparcia, napisz z jakiej aplikacji i urządzenia korzystasz.", 'sort_order' => 40],
        ];

        foreach ($seedRows as $seedRow) {
            $db->insert(
                ['locale_code', 'title', 'message_body', 'is_active', 'sort_order'],
                [(string)$seedRow['locale_code'], (string)$seedRow['title'], (string)$seedRow['message_body'], 1, (int)$seedRow['sort_order']],
                'support_quick_replies'
            );
        }
    }

    $done = true;
}

function admin_chat_quick_reply_rows(Mysql_ks $db, bool $onlyActive = false): array
{
    admin_ensure_chat_quick_replies_runtime_table($db);
    if (!schema_object_exists($db, 'support_quick_replies')) {
        return [];
    }

    $where = $onlyActive ? 'WHERE is_active = 1' : '';
    return $db->select_full_user(
        "SELECT
            id,
            locale_code,
            title,
            message_body,
            is_active,
            sort_order,
            created_at,
            updated_at
         FROM support_quick_replies
         {$where}
         ORDER BY is_active DESC, locale_code ASC, sort_order ASC, id ASC"
    );
}

function admin_chat_quick_reply_rows_for_locale(Mysql_ks $db, string $localeCode = '', bool $onlyActive = true): array
{
    $rows = admin_chat_quick_reply_rows($db, $onlyActive);
    if ($localeCode === '') {
        return $rows;
    }

    $localeCode = admin_normalize_locale($localeCode);
    $exactRows = array_values(array_filter($rows, static function (array $row) use ($localeCode): bool {
        return admin_normalize_locale((string)($row['locale_code'] ?? '')) === $localeCode;
    }));
    if ($exactRows !== []) {
        return $exactRows;
    }

    if ($localeCode !== 'en') {
        $fallbackRows = array_values(array_filter($rows, static function (array $row): bool {
            return admin_normalize_locale((string)($row['locale_code'] ?? '')) === 'en';
        }));
        if ($fallbackRows !== []) {
            return $fallbackRows;
        }
    }

    return $rows;
}

function admin_chat_quick_reply_find(Mysql_ks $db, int $replyId): ?array
{
    admin_ensure_chat_quick_replies_runtime_table($db);
    if ($replyId <= 0 || !schema_object_exists($db, 'support_quick_replies')) {
        return null;
    }

    $row = $db->select_user(
        "SELECT
            id,
            locale_code,
            title,
            message_body,
            is_active,
            sort_order,
            created_at,
            updated_at
         FROM support_quick_replies
         WHERE id = {$replyId}
         LIMIT 1"
    );

    return is_array($row) ? $row : null;
}

function admin_chat_quick_reply_locale_options(string $current = ''): array
{
    $options = ['pl', 'en'];
    $current = admin_normalize_locale($current !== '' ? $current : 'en');
    if (!in_array($current, $options, true)) {
        $options[] = $current;
    }

    return $options;
}

function admin_create_chat_quick_reply(Mysql_ks $db, array $input): array
{
    admin_ensure_chat_quick_replies_runtime_table($db);
    if (!schema_object_exists($db, 'support_quick_replies')) {
        return ['ok' => false, 'message' => 'Quick reply storage is unavailable.'];
    }

    $title = trim((string)($input['title'] ?? ''));
    $messageBody = trim((string)($input['message_body'] ?? ''));
    $localeCode = admin_normalize_locale((string)($input['locale_code'] ?? 'en'));
    $sortOrder = (int)($input['sort_order'] ?? 100);
    $isActive = isset($input['is_active']) && (string)($input['is_active'] ?? '') === '1' ? 1 : 0;

    if ($title === '') {
        return ['ok' => false, 'message' => 'Quick reply title is required.'];
    }

    if ($messageBody === '') {
        return ['ok' => false, 'message' => 'Quick reply message is required.'];
    }

    $inserted = $db->insert(
        ['locale_code', 'title', 'message_body', 'is_active', 'sort_order'],
        [$localeCode, $title, $messageBody, $isActive, $sortOrder],
        'support_quick_replies'
    );

    return [
        'ok' => (bool)$inserted,
        'message' => $inserted ? 'Quick reply created successfully.' : 'Unable to create quick reply.',
        'reply_id' => (int)$db->id(),
    ];
}

function admin_save_chat_quick_reply(Mysql_ks $db, int $replyId, array $input): array
{
    $reply = admin_chat_quick_reply_find($db, $replyId);
    if (!is_array($reply) || empty($reply['id'])) {
        return ['ok' => false, 'message' => 'Quick reply not found.'];
    }

    $title = trim((string)($input['title'] ?? ''));
    $messageBody = trim((string)($input['message_body'] ?? ''));
    $localeCode = admin_normalize_locale((string)($input['locale_code'] ?? (string)($reply['locale_code'] ?? 'en')));
    $sortOrder = (int)($input['sort_order'] ?? 100);
    $isActive = isset($input['is_active']) && (string)($input['is_active'] ?? '') === '1' ? 1 : 0;

    if ($title === '') {
        return ['ok' => false, 'message' => 'Quick reply title is required.'];
    }

    if ($messageBody === '') {
        return ['ok' => false, 'message' => 'Quick reply message is required.'];
    }

    $updated = $db->update_using_id(
        ['locale_code', 'title', 'message_body', 'is_active', 'sort_order'],
        [$localeCode, $title, $messageBody, $isActive, $sortOrder],
        'support_quick_replies',
        $replyId
    );

    return [
        'ok' => (bool)$updated,
        'message' => $updated ? 'Quick reply saved successfully.' : 'Unable to save quick reply.',
    ];
}

function admin_update_chat_quick_reply_message(Mysql_ks $db, int $replyId, string $messageBody): array
{
    $reply = admin_chat_quick_reply_find($db, $replyId);
    if (!is_array($reply) || empty($reply['id'])) {
        return ['ok' => false, 'message' => 'Quick reply not found.'];
    }

    $messageBody = trim($messageBody);
    if ($messageBody === '') {
        return ['ok' => false, 'message' => 'Quick reply message is required.'];
    }

    $updated = $db->update_using_id(
        ['message_body'],
        [$messageBody],
        'support_quick_replies',
        $replyId
    );

    if (!$updated) {
        return ['ok' => false, 'message' => 'Unable to save quick reply.'];
    }

    $freshReply = admin_chat_quick_reply_find($db, $replyId);
    return [
        'ok' => true,
        'message' => 'Quick reply saved successfully.',
        'reply' => is_array($freshReply) ? $freshReply : null,
    ];
}

function admin_delete_chat_quick_reply(Mysql_ks $db, int $replyId): array
{
    $reply = admin_chat_quick_reply_find($db, $replyId);
    if (!is_array($reply) || empty($reply['id'])) {
        return ['ok' => false, 'message' => 'Quick reply not found.'];
    }

    $deleted = $db->delete_using_id('support_quick_replies', $replyId);
    return [
        'ok' => (bool)$deleted,
        'message' => $deleted ? 'Quick reply deleted successfully.' : 'Unable to delete quick reply.',
    ];
}

function admin_chat_message_preview(array $row, array $messages): string
{
    $body = chat_message_preview_text_from_row(
        [
            'message_body' => (string)($row['last_message_body'] ?? ''),
            'attachment_path' => (string)($row['last_attachment_path'] ?? ''),
            'message_type' => (string)($row['last_message_type'] ?? ''),
            'audio_path' => (string)($row['last_audio_path'] ?? ''),
        ],
        admin_t($messages, 'chat_preview_image', 'Image attachment')
    );

    $body = preg_replace('/\s+/u', ' ', $body) ?? $body;
    if (mb_strlen($body) > 30) {
        $body = mb_substr($body, 0, 27) . '...';
    }

    return $body;
}

function admin_chat_list_timestamp(?string $timestamp): string
{
    $timestamp = trim((string)$timestamp);
    if ($timestamp === '') {
        return '';
    }

    $time = function_exists('app_timestamp_from_runtime_datetime')
        ? app_timestamp_from_runtime_datetime($timestamp)
        : strtotime($timestamp);
    if (!is_int($time) || $time <= 0) {
        return $timestamp;
    }

    return date('Y-m-d', $time) === date('Y-m-d') ? date('H:i', $time) : date('d.m', $time);
}

function admin_chat_message_is_structured_card(string $messageBody): bool
{
    $messageBody = trim($messageBody);
    if ($messageBody === '' || !function_exists('app_chat_card_decode')) {
        return false;
    }

    return is_array(app_chat_card_decode($messageBody));
}

function admin_format_last_login_date(?string $timestamp): string
{
    $timestamp = trim((string)$timestamp);
    if ($timestamp === '') {
        return '';
    }

    try {
        $timezone = function_exists('app_runtime_timezone_name')
            ? new DateTimeZone(app_runtime_timezone_name())
            : new DateTimeZone(date_default_timezone_get());
        $parsedTimestamp = function_exists('app_timestamp_from_runtime_datetime')
            ? app_timestamp_from_runtime_datetime($timestamp)
            : strtotime($timestamp);
        if (!is_int($parsedTimestamp) || $parsedTimestamp <= 0) {
            return $timestamp;
        }
        $date = (new DateTimeImmutable('@' . $parsedTimestamp))->setTimezone($timezone);
        $today = new DateTimeImmutable('now', $timezone);
    } catch (Throwable $exception) {
        return $timestamp;
    }

    $loginDate = $date->format('Y-m-d');
    $loginYear = $date->format('Y');
    $currentYear = $today->format('Y');

    if ($loginDate === $today->format('Y-m-d')) {
        return $date->format('H:i');
    } elseif ($loginYear === $currentYear) {
        return $date->format('d.m');
    } else {
        return $date->format('d.m.Y');
    }
}

function admin_chat_status_badge_class(string $status): string
{
    $status = strtolower(trim($status));

    if (in_array($status, ['open', 'active', 'new'], true)) {
        return 'admin-status-pill--available';
    }

    if (in_array($status, ['pending', 'waiting'], true)) {
        return 'admin-status-pill--warning';
    }

    if (in_array($status, ['closed', 'resolved', 'archived'], true)) {
        return 'admin-status-pill--muted';
    }

    return 'admin-status-pill--neutral';
}

function admin_chat_customer_presence(
    Mysql_ks $db,
    int $customerId,
    string $lastSeenAt = '',
    array $messages = [],
    ?int $currentTime = null
): array {
    $currentTime = $currentTime ?? time();
    $lastSeenAt = trim($lastSeenAt);
    $lastSeenTimestamp = $lastSeenAt !== '' ? strtotime($lastSeenAt) : false;
    $secondsSinceLastSeen = $lastSeenTimestamp !== false ? max(0, $currentTime - $lastSeenTimestamp) : null;

    static $supportsUserOnline = null;
    if ($supportsUserOnline === null) {
        $supportsUserOnline = schema_object_exists($db, 'user_online');
    }

    $hasActiveOnlineEntry = false;
    if ($supportsUserOnline && $customerId > 0) {
        $onlineEntry = $db->select_user(
            "SELECT id
             FROM user_online
             WHERE user = {$customerId}
               AND status = 1
             LIMIT 1"
        );
        $hasActiveOnlineEntry = is_array($onlineEntry) && !empty($onlineEntry['id']);
    }

    $statusKey = 'offline';
    if ($hasActiveOnlineEntry && ($secondsSinceLastSeen === null || $secondsSinceLastSeen <= 180)) {
        $statusKey = 'online';
    } elseif ($secondsSinceLastSeen !== null && $secondsSinceLastSeen <= 180) {
        $statusKey = 'online';
    } elseif ($secondsSinceLastSeen !== null && $secondsSinceLastSeen <= 600) {
        $statusKey = 'away';
    }

    $statusLabel = admin_t($messages, 'chat_presence_' . $statusKey, ucfirst($statusKey));

    if ($lastSeenTimestamp !== false && $statusKey !== 'online') {
        $statusLabel .= ' · ' . admin_chat_list_timestamp($lastSeenAt);
    }

    return [
        'key' => $statusKey,
        'label' => $statusLabel,
        'class_name' => 'admin-chat-presence admin-chat-presence--' . $statusKey,
    ];
}

function admin_chat_presence_dot_html(array $presence): string
{
    $className = trim((string)($presence['class_name'] ?? 'admin-chat-presence admin-chat-presence--offline'));
    $label = trim((string)($presence['label'] ?? 'Offline'));

    return '<span class="' . admin_e($className) . '" title="' . admin_e($label) . '" aria-label="' . admin_e($label) . '"></span>';
}

function admin_find_existing_admin_direct_conversation_id(Mysql_ks $db, int $adminUserId, int $targetAdminUserId): int
{
    if (
        $adminUserId <= 0
        || $targetAdminUserId <= 0
        || $adminUserId === $targetAdminUserId
        || !schema_object_exists($db, 'support_conversations')
        || !schema_object_exists($db, 'support_conversation_members')
    ) {
        return 0;
    }

    $selfKey = $db->escape(chat_participant_key_for_admin($adminUserId));
    $targetKey = $db->escape(chat_participant_key_for_admin($targetAdminUserId));
    $row = $db->select_user(
        "SELECT support_conversations.id
         FROM support_conversations
         INNER JOIN support_conversation_members AS member_self
            ON member_self.conversation_id = support_conversations.id
         INNER JOIN support_conversation_members AS member_target
            ON member_target.conversation_id = support_conversations.id
         WHERE support_conversations.conversation_type = 'group_chat'
           AND member_self.participant_key = '{$selfKey}'
           AND member_self.invite_status = 'accepted'
           AND member_target.participant_key = '{$targetKey}'
           AND member_target.invite_status = 'accepted'
           AND NOT EXISTS (
                SELECT 1
                FROM support_conversation_members AS other_members
                WHERE other_members.conversation_id = support_conversations.id
                  AND other_members.invite_status = 'accepted'
                  AND other_members.participant_key NOT IN ('{$selfKey}', '{$targetKey}')
           )
         ORDER BY support_conversations.id ASC
         LIMIT 1"
    );

    return (int)($row['id'] ?? 0);
}

function admin_find_or_create_admin_direct_conversation(Mysql_ks $db, int $adminUserId, int $targetAdminUserId): int
{
    $existingConversationId = admin_find_existing_admin_direct_conversation_id($db, $adminUserId, $targetAdminUserId);
    if ($existingConversationId > 0) {
        return $existingConversationId;
    }

    if ($targetAdminUserId <= 0 || !schema_object_exists($db, 'admin_users')) {
        return 0;
    }

    $targetAdmin = $db->select_user(
        "SELECT id, email
         FROM admin_users
         WHERE id = {$targetAdminUserId}
           AND status = 'active'
         LIMIT 1"
    );
    if (!is_array($targetAdmin) || empty($targetAdmin['id']) || trim((string)($targetAdmin['email'] ?? '')) === '') {
        return 0;
    }

    $result = admin_chat_create_group_conversation($db, $adminUserId, '', [(string)$targetAdmin['email']], false);
    if (empty($result['ok'])) {
        return 0;
    }

    return (int)($result['conversation_id'] ?? 0);
}

function admin_chat_search_customers(Mysql_ks $db, string $query, int $limit = 8, int $adminUserId = 0): array
{
    $query = trim($query);
    if ($query === '') {
        return [];
    }

    app_ensure_customer_runtime_columns($db);

    $limit = max(1, min(15, $limit));
    $isHandleSearch = strpos($query, '@') === 0;
    $needle = $isHandleSearch ? chat_normalize_public_handle((string)substr($query, 1)) : strtolower($query);
    if ($needle === '') {
        return [];
    }

    $rows = [];
    $safeLike = $db->escape('%' . $needle . '%');

    if (schema_object_exists($db, 'customers')) {
        $customerWhere = $isHandleSearch
            ? "LOWER(customers.public_handle) LIKE '{$safeLike}'"
            : "LOWER(customers.email) LIKE '{$safeLike}'";
        $customerRows = $db->select_full_user(
            "SELECT
                customers.id,
                customers.email,
                customers.status,
                customers.public_handle,
                customers.avatar_url,
                customers.customer_type,
                (
                    SELECT support_conversations.id
                    FROM support_conversations
                    WHERE support_conversations.customer_id = customers.id
                      AND support_conversations.conversation_type = 'live_chat'
                    ORDER BY support_conversations.id DESC
                    LIMIT 1
                ) AS conversation_id
             FROM customers
             WHERE {$customerWhere}
             ORDER BY customers.email ASC
             LIMIT {$limit}"
        );

        foreach ($customerRows as $customerRow) {
            $customerAvatar = admin_chat_avatar_payload([
                'conversation_type' => 'live_chat',
                'customer_email' => (string)($customerRow['email'] ?? ''),
                'customer_public_handle' => (string)($customerRow['public_handle'] ?? ''),
                'customer_avatar_url' => (string)($customerRow['avatar_url'] ?? ''),
            ]);
            $rows[] = [
                'participant_type' => 'customer',
                'id' => (int)($customerRow['id'] ?? 0),
                'email' => (string)($customerRow['email'] ?? ''),
                'display_name' => (string)($customerRow['public_handle'] ?? '') !== '' ? '@' . (string)$customerRow['public_handle'] : admin_string_truncate((string)($customerRow['email'] ?? ''), 20),
                'meta_label' => (string)($customerRow['email'] ?? ''),
                'conversation_id' => (int)($customerRow['conversation_id'] ?? 0),
                'avatar_url' => (string)($customerAvatar['url'] ?? ''),
                'avatar_text' => (string)($customerAvatar['text'] ?? 'U'),
                'avatar_theme' => (string)($customerAvatar['theme'] ?? 'theme-1'),
            ];
        }
    }

    if (schema_object_exists($db, 'admin_users')) {
        $adminWhere = $isHandleSearch
            ? "LOWER(admin_users.public_handle) LIKE '{$safeLike}'"
            : "(LOWER(admin_users.email) LIKE '{$safeLike}' OR LOWER(admin_users.login_name) LIKE '{$safeLike}')";
        $adminRows = $db->select_full_user(
            "SELECT
                admin_users.id,
                admin_users.email,
                admin_users.login_name,
                admin_users.public_handle,
                admin_users.avatar_url
             FROM admin_users
             WHERE admin_users.status = 'active'
               AND {$adminWhere}
             ORDER BY admin_users.email ASC
             LIMIT {$limit}"
        );

        foreach ($adminRows as $adminRow) {
            $targetAdminId = (int)($adminRow['id'] ?? 0);
            if ($targetAdminId <= 0 || $targetAdminId === $adminUserId) {
                continue;
            }
            $adminAvatar = chat_admin_avatar_payload_from_row([
                'public_handle' => (string)($adminRow['public_handle'] ?? ''),
                'login_name' => (string)($adminRow['login_name'] ?? ''),
                'avatar_url' => (string)($adminRow['avatar_url'] ?? ''),
            ]);
            $rows[] = [
                'participant_type' => 'admin',
                'id' => $targetAdminId,
                'email' => (string)($adminRow['email'] ?? ''),
                'display_name' => '@' . chat_admin_display_label($adminRow),
                'meta_label' => 'Administrator',
                'conversation_id' => admin_find_existing_admin_direct_conversation_id($db, $adminUserId, $targetAdminId),
                'avatar_url' => (string)($adminAvatar['avatar_url'] ?? ''),
                'avatar_text' => (string)($adminAvatar['avatar_text'] ?? 'A'),
                'avatar_theme' => (string)($adminAvatar['avatar_theme'] ?? 'theme-6'),
            ];
        }
    }

    usort($rows, static function (array $left, array $right): int {
        return strcasecmp((string)($left['display_name'] ?? ''), (string)($right['display_name'] ?? ''));
    });

    return array_slice($rows, 0, $limit);
}

function admin_string_truncate(string $value, int $maxLength = 20): string
{
    $value = trim($value);
    if ($value === '') {
        return '';
    }

    if (function_exists('mb_strlen') && function_exists('mb_substr')) {
        if (mb_strlen($value) <= $maxLength) {
            return $value;
        }
        return rtrim(mb_substr($value, 0, max(5, $maxLength - 4))) . '...';
    }

    if (strlen($value) <= $maxLength) {
        return $value;
    }

    return rtrim(substr($value, 0, max(5, $maxLength - 4))) . '...';
}

function admin_chat_display_name(array $row, array $messages, int $maxLength = 20): string
{
    if (function_exists('chat_is_group_like_conversation_type') && chat_is_group_like_conversation_type((string)($row['conversation_type'] ?? ''))) {
        $title = trim((string)($row['summary_title'] ?? ''));
        if ($title === '') {
            $title = chat_group_conversation_title($row, admin_t($messages, 'group_chat_badge', 'Group chat'));
        }
        return admin_string_truncate($title, $maxLength);
    }

    $email = trim((string)($row['customer_email'] ?? ''));
    if ($email === '') {
        $email = admin_t($messages, 'chat_unknown_customer', 'Customer');
    }

    return admin_string_truncate($email, $maxLength);
}

function admin_chat_avatar_payload(array $row, array $messages = []): array
{
    if (function_exists('chat_is_group_like_conversation_type') && chat_is_group_like_conversation_type((string)($row['conversation_type'] ?? ''))) {
        $avatarUrl = trim((string)($row['avatar_url'] ?? ''));
        $avatarText = trim((string)($row['avatar_text'] ?? 'G'));
        $avatarTheme = trim((string)($row['avatar_theme'] ?? 'theme-6'));

        return [
            'url' => $avatarUrl,
            'text' => $avatarText !== '' ? $avatarText : 'G',
            'theme' => $avatarTheme !== '' ? $avatarTheme : 'theme-6',
        ];
    }

    $customerRow = [
        'public_handle' => (string)($row['customer_public_handle'] ?? ''),
        'email' => (string)($row['customer_email'] ?? ''),
        'avatar_url' => (string)($row['customer_avatar_url'] ?? ''),
    ];

    $avatarUrl = function_exists('app_customer_avatar_url')
        ? app_customer_avatar_url((string)$customerRow['avatar_url'])
        : trim((string)$customerRow['avatar_url']);
    $avatarText = function_exists('app_customer_avatar_initial')
        ? app_customer_avatar_initial($customerRow)
        : strtoupper(substr((string)($customerRow['public_handle'] ?: $customerRow['email'] ?: 'U'), 0, 1));
    $avatarTheme = function_exists('app_customer_avatar_theme')
        ? app_customer_avatar_theme($customerRow)
        : admin_chat_avatar_theme($row);

    return [
        'url' => $avatarUrl,
        'text' => $avatarText !== '' ? $avatarText : 'U',
        'theme' => $avatarTheme !== '' ? $avatarTheme : 'theme-1',
    ];
}

function admin_chat_avatar_html(array $row, array $messages = [], string $extraClass = ''): string
{
    $avatar = admin_chat_avatar_payload($row, $messages);
    $classes = trim('admin-chat-inbox__avatar ' . (string)($avatar['theme'] ?? 'theme-1') . ' ' . $extraClass);
    $label = trim((string)($avatar['text'] ?? 'U'));
    $url = trim((string)($avatar['url'] ?? ''));

    if ($url !== '') {
        return '<span class="' . admin_e($classes) . '"><img src="' . admin_e($url) . '" alt="' . admin_e($label !== '' ? $label : 'Avatar') . '"></span>';
    }

    return '<span class="' . admin_e($classes) . '">' . admin_e($label !== '' ? $label : 'U') . '</span>';
}

function admin_chat_avatar_text(array $row, array $messages): string
{
    $avatar = admin_chat_avatar_payload($row, $messages);
    return (string)($avatar['text'] ?? 'U');
}

function admin_chat_avatar_theme(array $row): string
{
    if (function_exists('chat_is_group_like_conversation_type') && chat_is_group_like_conversation_type((string)($row['conversation_type'] ?? ''))) {
        $theme = trim((string)($row['avatar_theme'] ?? 'theme-6'));
        return $theme !== '' ? $theme : 'theme-6';
    }

    $seed = trim((string)($row['customer_email'] ?? ''));
    if ($seed === '') {
        return 'theme-1';
    }

    $index = abs((int)crc32(strtolower($seed))) % 6;
    return 'theme-' . ($index + 1);
}

function admin_chat_message_page_size(): int
{
    return 10;
}

function admin_chat_normalize_message_limit($value): int
{
    $defaultLimit = admin_chat_message_page_size();
    $limit = (int)$value;
    if ($limit <= 0) {
        return $defaultLimit;
    }

    if ($limit < $defaultLimit) {
        return $defaultLimit;
    }

    if ($limit > 200) {
        return 200;
    }

    return $limit;
}

function admin_chat_conversation_message_count(Mysql_ks $db, int $conversationId): int
{
    if ($conversationId <= 0 || !schema_object_exists($db, 'support_messages')) {
        return 0;
    }

    $row = $db->select_user(
        "SELECT COUNT(*) AS total
         FROM support_messages
         WHERE conversation_id = {$conversationId}"
    );

    return (int)($row['total'] ?? 0);
}

function admin_chat_conversation_messages(Mysql_ks $db, int $conversationId, int $messageLimit = 0, int $adminUserId = 0): array
{
    if ($conversationId <= 0 || !schema_object_exists($db, 'support_messages')) {
        return [];
    }

    chat_ensure_message_interactions_runtime($db);
    $safeLimit = admin_chat_normalize_message_limit($messageLimit);
    $readSelect = 'support_messages.is_read';
    if (schema_object_exists($db, 'support_conversation_members')) {
        $readSelect = "CASE
            WHEN support_messages.sender_type <> 'admin' THEN support_messages.is_read
            WHEN EXISTS (
                SELECT 1
                FROM support_conversation_members AS receipt_members
                WHERE receipt_members.conversation_id = support_messages.conversation_id
                  AND receipt_members.invite_status = 'accepted'
                  AND receipt_members.participant_key LIKE 'customer:%'
                  AND COALESCE(receipt_members.last_read_message_id, 0) >= support_messages.id
            ) THEN 1
            ELSE support_messages.is_read
        END";
    }
    $baseQuery = "SELECT
            support_messages.id,
            support_messages.sender_type,
            support_messages.customer_id,
            support_messages.admin_user_id,
            support_messages.message_body,
            support_messages.attachment_path,
            support_messages.message_type,
            support_messages.audio_path,
            support_messages.audio_mime_type,
            support_messages.audio_duration_seconds,
            support_messages.reply_to_message_id,
            {$readSelect} AS is_read,
            support_messages.created_at,
            NULLIF(TRIM(admin_users.public_handle), '') AS admin_public_handle,
            admin_users.login_name AS admin_login_name,
            customers.email AS customer_email,
            NULLIF(TRIM(customers.public_handle), '') AS customer_display_name,
            customers.status AS customer_status,
            COALESCE(global_customer_member.global_chat_blocked, 0) AS customer_global_chat_blocked
         FROM support_messages
         LEFT JOIN admin_users ON admin_users.id = support_messages.admin_user_id
         LEFT JOIN customers ON customers.id = support_messages.customer_id
         LEFT JOIN support_conversation_members AS global_customer_member
            ON global_customer_member.conversation_id = support_messages.conversation_id
           AND global_customer_member.customer_id = support_messages.customer_id
           AND global_customer_member.participant_type = 'customer'
         WHERE support_messages.conversation_id = {$conversationId}";

    $rows = $db->select_full_user(
        "SELECT *
         FROM (
            {$baseQuery}
            ORDER BY support_messages.created_at DESC, support_messages.id DESC
            LIMIT {$safeLimit}
         ) AS recent_messages
         ORDER BY created_at ASC, id ASC"
    );

    return chat_enrich_support_message_rows(
        $db,
        $rows,
        ['participant_type' => 'admin', 'customer_id' => 0, 'admin_user_id' => $adminUserId, 'participant_key' => chat_participant_key_for_admin($adminUserId)],
        [],
        admin_t([], 'chat_inbox_title', 'Live chat inbox')
    );
}

function admin_chat_conversation_row(Mysql_ks $db, int $conversationId): ?array
{
    if ($conversationId <= 0 || !schema_object_exists($db, 'support_conversations')) {
        return null;
    }

    app_ensure_customer_runtime_columns($db);

    $row = $db->select_user(
        "SELECT
            support_conversations.id,
            support_conversations.customer_id,
            support_conversations.conversation_type,
            support_conversations.status,
            support_conversations.subject,
            support_conversations.group_name,
            support_conversations.group_avatar_url,
            support_conversations.is_group_read_only,
            support_conversations.group_created_by_customer_id,
            support_conversations.group_created_by_admin_user_id,
            support_conversations.message_retention_hours,
            support_conversations.message_retention_minutes,
            support_conversations.created_at,
            support_conversations.updated_at,
            customers.email AS customer_email,
            NULLIF(TRIM(customers.public_handle), '') AS customer_public_handle,
            customers.avatar_url AS customer_avatar_url,
            customers.last_login_at AS customer_last_login_at,
            customers.locale_code AS customer_locale_code
         FROM support_conversations
         LEFT JOIN customers ON customers.id = support_conversations.customer_id
         WHERE support_conversations.id = {$conversationId}
         LIMIT 1"
    );

    return is_array($row) ? $row : null;
}

function admin_mark_chat_conversation_read(Mysql_ks $db, int $conversationId): void
{
    if ($conversationId <= 0 || !schema_object_exists($db, 'support_messages')) {
        return;
    }

    $db->query(
        "UPDATE support_messages
         SET is_read = 1
         WHERE conversation_id = {$conversationId}
           AND sender_type = 'customer'
           AND is_read = 0"
    );
}

function admin_chat_refresh_conversation_timestamps(Mysql_ks $db, int $conversationId): void
{
    if ($conversationId <= 0 || !schema_object_exists($db, 'support_conversations') || !schema_object_exists($db, 'support_messages')) {
        return;
    }

    $latestMessageAt = $db->select_user(
        "SELECT created_at
         FROM support_messages
         WHERE conversation_id = {$conversationId}
         ORDER BY id DESC
         LIMIT 1"
    );
    $latestCustomerMessageAt = $db->select_user(
        "SELECT created_at
         FROM support_messages
         WHERE conversation_id = {$conversationId}
           AND sender_type = 'customer'
         ORDER BY id DESC
         LIMIT 1"
    );
    $latestAdminMessageAt = $db->select_user(
        "SELECT created_at
         FROM support_messages
         WHERE conversation_id = {$conversationId}
           AND sender_type = 'admin'
         ORDER BY id DESC
         LIMIT 1"
    );

    $safeLatestMessageAt = isset($latestMessageAt['created_at']) ? "'" . $db->escape((string)$latestMessageAt['created_at']) . "'" : 'created_at';
    $safeLatestCustomerMessageAt = isset($latestCustomerMessageAt['created_at']) ? "'" . $db->escape((string)$latestCustomerMessageAt['created_at']) . "'" : 'NULL';
    $safeLatestAdminMessageAt = isset($latestAdminMessageAt['created_at']) ? "'" . $db->escape((string)$latestAdminMessageAt['created_at']) . "'" : 'NULL';

    $db->query(
        "UPDATE support_conversations
         SET updated_at = {$safeLatestMessageAt},
             last_customer_message_at = {$safeLatestCustomerMessageAt},
             last_admin_message_at = {$safeLatestAdminMessageAt}
         WHERE id = {$conversationId}
         LIMIT 1"
    );
}

function admin_find_or_create_chat_conversation(Mysql_ks $db, int $customerId, int $adminUserId): int
{
    if ($customerId <= 0 || !schema_object_exists($db, 'support_conversations')) {
        return 0;
    }

    $row = $db->select_user(
        "SELECT id
         FROM support_conversations
         WHERE customer_id = {$customerId}
           AND conversation_type = 'live_chat'
         ORDER BY id DESC
         LIMIT 1"
    );

    if (is_array($row) && !empty($row['id'])) {
        $conversationId = (int)$row['id'];
        $assignedAdminIdSql = $adminUserId > 0 ? (string)$adminUserId : 'NULL';
        @$db->query(
            "UPDATE support_conversations
             SET status = 'open',
                 assigned_admin_id = COALESCE({$assignedAdminIdSql}, assigned_admin_id),
                 updated_at = '" . $db->escape(date('Y-m-d H:i:s')) . "'
             WHERE id = {$conversationId}
             LIMIT 1"
        );
        return $conversationId;
    }

    $subject = 'Customer live chat #' . $customerId;
    $db->insert(
        ['conversation_type', 'customer_id', 'assigned_admin_id', 'subject', 'status', 'priority'],
        ['live_chat', $customerId, $adminUserId > 0 ? $adminUserId : null, $subject, 'open', 'normal'],
        'support_conversations'
    );

    return (int)$db->id();
}

