        chat_participant_key_for_admin($adminUserId),
        $enabled
    );
}

function admin_chat_payment_modal_data(Mysql_ks $db, string $type, int $customerId, array $messages = []): array
{
    $settings = admin_app_settings($db);
    $currencyContext = admin_chat_payment_currency_context($db);
    $payload = [
        'ok' => true,
        'type' => $type,
        'currency' => [
            'id' => (int)($currencyContext['currency_id'] ?? 0),
            'code' => (string)($currencyContext['currency_code'] ?? ''),
            'symbol' => (string)($currencyContext['currency_symbol'] ?? ''),
            'name' => (string)($currencyContext['currency_name'] ?? ''),
        ],
        'amount_options' => admin_chat_payment_amount_options(),
    ];

    if ($type === 'crypto') {
        if (empty($settings['crypto_payments_enabled'])) {
            return ['ok' => false, 'message' => 'Crypto payments are disabled.'];
        }

        $payload['items'] = admin_chat_payment_crypto_assets($db, $customerId, $currencyContext);
        $payload['product_presets'] = admin_chat_payment_product_presets($db, $currencyContext);
        if (!$payload['items']) {
            $payload['empty_state_html'] = admin_chat_crypto_wallet_pool_help_html($messages, $settings);
        }
        $refreshedRows = array_values(array_filter($payload['items'], static function (array $item): bool {
            return !empty($item['rate_refreshed_now']);
        }));
        if ($refreshedRows) {
            $latestRefreshLabel = '';
            foreach ($refreshedRows as $row) {
                $candidate = trim((string)($row['rate_refresh_label'] ?? ''));
                if ($candidate !== '') {
                    $latestRefreshLabel = $candidate;
                }
            }
            $payload['rate_notice'] = [
                'refreshed' => true,
                'label' => $latestRefreshLabel,
            ];
        }
        return $payload;
    }

    if ($type === 'bank') {
        if (!admin_bank_transfers_enabled($settings)) {
            return ['ok' => false, 'message' => 'Bank transfers are disabled.'];
        }

        $assignedAccounts = app_filter_bank_account_rows_by_monthly_limit($db, admin_customer_active_bank_assignments($db, $customerId));
        $availableAccounts = $assignedAccounts ? [] : admin_chat_available_bank_account_rows($db, (string)($currencyContext['currency_code'] ?? ''));

        $payload['assigned_accounts'] = array_map(static function (array $row): array {
            return [
                'bank_account_id' => (int)($row['bank_account_id'] ?? 0),
                'bank_account_assignment_id' => (int)($row['bank_account_assignment_id'] ?? 0),
                'label' => (string)($row['label'] ?? ''),
                'bank_name' => (string)($row['bank_name'] ?? ''),
                'account_holder_name' => (string)($row['account_holder_name'] ?? ''),
                'iban' => (string)($row['iban'] ?? ''),
            ];
        }, $assignedAccounts);
        $payload['available_accounts'] = array_map(static function (array $row): array {
            return [
                'bank_account_id' => (int)($row['id'] ?? 0),
                'label' => (string)($row['label'] ?? ''),
                'bank_name' => (string)($row['bank_name'] ?? ''),
                'account_holder_name' => (string)($row['account_holder_name'] ?? ''),
                'iban' => (string)($row['iban'] ?? ''),
            ];
        }, $availableAccounts);

        return $payload;
    }

    return ['ok' => false, 'message' => 'Unsupported payment modal type.'];
}

function admin_queue_crypto_payment_request_live_chat_card(
    Mysql_ks $db,
    int $customerId,
    array $preview,
    string $paymentUrl = ''
): bool {
    $customer = app_find_customer_by_id($db, $customerId);
    $localeCode = app_normalize_email_locale((string)($customer['locale_code'] ?? 'en'));
    $appSettings = app_fetch_settings($db);
    $siteUrl = rtrim((string)($appSettings['site_url'] ?? ''), '/');
    $paymentUrl = trim($paymentUrl);
    if ($paymentUrl === '') {
        $paymentUrl = $siteUrl !== '' ? $siteUrl . '/payments_crypto#tickets' : '/payments_crypto#tickets';
    }

    $messageBody = app_build_crypto_payment_chat_card_message([
        'asset_name' => (string)($preview['asset_name'] ?? ''),
        'asset_code' => (string)($preview['asset_code'] ?? ''),
        'asset_logo_url' => (string)($preview['asset_logo_url'] ?? ''),
        'requested_crypto_amount' => (string)($preview['crypto_amount'] ?? ''),
        'requested_fiat_amount' => (float)($preview['fiat_amount'] ?? 0),
        'currency_symbol' => (string)($preview['currency_symbol'] ?? ''),
        'currency_code' => (string)($preview['currency_code'] ?? ''),
        'wallet_address' => (string)($preview['wallet_address'] ?? ''),
        'wallet_owner_full_name' => (string)($preview['wallet_owner_full_name'] ?? ''),
        'wallet_owner_location' => (string)($preview['wallet_owner_location'] ?? ''),
        'wallet_notes' => (string)($preview['wallet_notes'] ?? ''),
        'network_code' => (string)($preview['network_code'] ?? ''),
        'memo_tag' => (string)($preview['memo_tag'] ?? ''),
        'payment_url' => $paymentUrl,
    ], $localeCode);

    if ($messageBody === '') {
        return false;
    }

    return app_insert_live_chat_admin_message($db, $customerId, $messageBody);
}

function admin_chat_create_crypto_payment_request(
    Mysql_ks $db,
    int $conversationId,
    int $customerId,
    int $assetId,
    $amount,
    int $adminUserId,
    array $messages,
    int $productId = 0
): array {
    $settings = admin_app_settings($db);
    if (empty($settings['crypto_payments_enabled'])) {
        return ['ok' => false, 'message' => 'Crypto payments are disabled.'];
    }

    $conversation = $db->select_user("SELECT id FROM support_conversations WHERE id = {$conversationId} AND customer_id = {$customerId} AND conversation_type = 'live_chat' LIMIT 1");
    $customer = admin_customer_basic_row($db, $customerId);
    if (!$conversation || !$customer || (string)($customer['status'] ?? '') !== 'active') {
        return ['ok' => false, 'message' => 'Customer or conversation is unavailable.'];
    }
    if ($productId > 0) {
        $product = admin_product_basic_row($db, $productId);
        $currency = admin_chat_payment_currency_context($db);
        if (!$product || empty($product['is_active'])
            || (int)$product['currency_id'] !== (int)$currency['currency_id']
            || !app_customer_provider_is_visible($db, $customerId, (int)($product['provider_id'] ?? 0))) {
            return ['ok' => false, 'message' => 'Selected product is unavailable or uses another currency.'];
        }
    }

    if (admin_customer_has_pending_crypto_payment($db, $customerId)) {
        return ['ok' => false, 'message' => 'pending_crypto_payment'];
    }

    $preview = admin_chat_crypto_payment_preview($db, $customerId, $assetId, $amount, $messages);
    if (empty($preview['ok'])) {
        return $preview;
    }

    $walletAddressId = (int)($preview['wallet_address_id'] ?? 0);
    if ($walletAddressId <= 0) {
        return ['ok' => false, 'message' => 'Wallet address is unavailable.'];
    }

    $db->start();
    try {
        $lockedCustomer = $db->select_user("SELECT id FROM customers WHERE id = {$customerId} AND status = 'active' FOR UPDATE");
        if (!$lockedCustomer || admin_customer_has_pending_crypto_payment($db, $customerId)) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'pending_crypto_payment'];
        }
        $lockedWallet = $db->select_user("SELECT id FROM crypto_wallet_addresses WHERE id = {$walletAddressId} AND disabled_at IS NULL AND status <> 'disabled' FOR UPDATE");
        if (!$lockedWallet) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Wallet is no longer available.'];
        }

        $walletAssignmentId = (int)($preview['wallet_assignment_id'] ?? 0);
        if ($walletAssignmentId <= 0) {
            $assignResult = admin_assign_crypto_wallet_customer($db, $walletAddressId, $customerId, $adminUserId, $settings, '', false);
            if (empty($assignResult['ok'])) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => (string)($assignResult['message'] ?? 'Unable to assign wallet.')];
            }

            $walletAssignmentId = (int)($assignResult['wallet_assignment_id'] ?? 0);
            if ($walletAssignmentId <= 0) {
                $assignments = admin_customer_active_crypto_assignments($db, $customerId, (string)($preview['asset_code'] ?? ''));
                foreach ($assignments as $assignment) {
                    if ((int)($assignment['wallet_address_id'] ?? 0) !== $walletAddressId) {
                        continue;
                    }

                    $walletAssignmentId = (int)($assignment['wallet_assignment_id'] ?? 0);
                    break;
                }
            }

            if ($walletAssignmentId <= 0) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Wallet assignment could not be confirmed.'];
            }
        }

        $requestId = 0;
        $now = date('Y-m-d H:i:s');
        $expiresAt = date('Y-m-d H:i:s', strtotime('+1 hour'));
        $db->query(
            "UPDATE crypto_deposit_requests
             SET status = 'archived'
             WHERE customer_id = {$customerId}
               AND status IN ('pending', 'pending_payment', 'awaiting_confirmation', 'awaiting_review')
               AND expires_at IS NOT NULL
               AND expires_at < '{$now}'"
        );
        $openWalletRequest = $db->select_user(
            "SELECT
                crypto_deposit_requests.id,
                crypto_deposit_requests.customer_id,
                crypto_deposit_requests.order_id
             FROM crypto_deposit_requests
             LEFT JOIN crypto_wallet_assignments AS open_assignment
               ON open_assignment.id = crypto_deposit_requests.wallet_assignment_id
             WHERE (
                    crypto_deposit_requests.wallet_address_id = {$walletAddressId}
                 OR open_assignment.wallet_address_id = {$walletAddressId}
             )
               AND crypto_deposit_requests.status IN ('pending', 'pending_payment', 'awaiting_confirmation', 'awaiting_review')
             ORDER BY crypto_deposit_requests.id DESC
             LIMIT 1"
        );

        if (is_array($openWalletRequest) && !empty($openWalletRequest['id'])) {
            if ((int)($openWalletRequest['customer_id'] ?? 0) !== $customerId || !empty($openWalletRequest['order_id'])) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'This wallet already has an active payment request.'];
            }

            if (!app_crypto_deposit_wallet_payload_is_valid($db, $customerId, (int)$preview['asset_id'], $walletAddressId, $walletAssignmentId, $settings)) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Wallet assignment could not be confirmed.'];
            }

            $updated = $db->update_using_id(
                [
                    'crypto_asset_id',
                    'wallet_address_id',
                    'wallet_assignment_id',
                    'requested_fiat_amount',
                    'fiat_currency_id',
                    'exchange_rate',
                    'requested_crypto_amount',
                    'created_by_admin_user_id',
                    'requested_at',
                    'expires_at',
                    'request_note',
                    'status',
                ],
                [
                    (int)$preview['asset_id'],
                    $walletAddressId,
                    $walletAssignmentId,
                    (float)$preview['fiat_amount'],
                    (int)$preview['currency_id'],
                    (float)$preview['rate'],
                    (float)$preview['crypto_amount'],
                    $adminUserId,
                    $now,
                    $expiresAt,
                    admin_localize_payment_request_note('Updated from admin live chat crypto request'),
                    'pending',
                ],
                'crypto_deposit_requests',
                (int)$openWalletRequest['id']
            );
            if (!$updated) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to update crypto payment request.'];
            }
            $requestId = (int)$openWalletRequest['id'];
        } else {
            $requestId = app_create_crypto_deposit_request($db, [
                'customer_id' => $customerId,
                'order_id' => null,
                'crypto_asset_id' => (int)$preview['asset_id'],
                'wallet_address_id' => $walletAddressId,
                'wallet_assignment_id' => $walletAssignmentId,
                'requested_fiat_amount' => (float)$preview['fiat_amount'],
                'fiat_currency_id' => (int)$preview['currency_id'],
                'exchange_rate' => (float)$preview['rate'],
                'requested_crypto_amount' => (float)$preview['crypto_amount'],
                'assignment_mode' => 'manual',
                'status' => 'pending',
                'created_by_admin_user_id' => $adminUserId,
                'requested_at' => $now,
                'expires_at' => $expiresAt,
                'request_note' => admin_localize_payment_request_note('Created from admin live chat crypto request'),
                'settings' => $settings,
            ], true);

            if ($requestId <= 0) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to create crypto payment request.'];
            }
        }

        $customer = app_find_customer_by_id($db, $customerId);
        $localeCode = app_normalize_email_locale((string)($customer['locale_code'] ?? 'en'));
        $appSettings = app_fetch_settings($db);
        $siteUrl = rtrim((string)($appSettings['site_url'] ?? ''), '/');
        $paymentUrl = $siteUrl !== '' ? $siteUrl . '/payments_crypto#tickets' : '/payments_crypto#tickets';

        $messageBody = app_build_crypto_payment_chat_card_message([
            'asset_name' => (string)$preview['asset_name'],
            'asset_code' => (string)$preview['asset_code'],
            'asset_logo_url' => (string)$preview['asset_logo_url'],
            'requested_crypto_amount' => (string)$preview['crypto_amount'],
            'requested_fiat_amount' => (float)$preview['fiat_amount'],
            'currency_symbol' => (string)$preview['currency_symbol'],
            'currency_code' => (string)$preview['currency_code'],
            'wallet_address' => (string)$preview['wallet_address'],
            'wallet_owner_full_name' => (string)$preview['wallet_owner_full_name'],
            'wallet_owner_location' => (string)($preview['wallet_owner_location'] ?? ''),
            'wallet_notes' => (string)($preview['wallet_notes'] ?? ''),
            'network_code' => (string)($preview['network_code'] ?? ''),
            'memo_tag' => (string)($preview['memo_tag'] ?? ''),
            'payment_url' => $paymentUrl,
        ], $localeCode);

        if ($messageBody === '' || !admin_chat_insert_message($db, $conversationId, $adminUserId, $messageBody)) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Unable to send crypto payment message to chat.'];
        }

        $orderId = 0;
        if ($productId > 0) {
            $orderResult = admin_create_order($db, [
                'customer_id' => $customerId, 'product_id' => $productId,
                'customer_note' => 'created from admin', 'has_delivery_link' => '0',
            ], (float)$preview['fiat_amount']);
            $orderId = (int)($orderResult['order_id'] ?? 0);
            if (empty($orderResult['ok']) || $orderId <= 0
                || !$db->update_using_id(['order_id'], [$orderId], 'crypto_deposit_requests', $requestId)) {
                $db->query('ROLLBACK');
                return ['ok' => false, 'message' => 'Unable to link the payment request to an order.'];
            }
        }

        app_delete_cancelled_crypto_requests_for_asset($db, $customerId, $assetId);

        if (!$db->query('COMMIT')) { throw new RuntimeException('Payment commit failed.'); }

        return ['ok' => true, 'request_id' => $requestId, 'order_id' => $orderId];
    } catch (Throwable $error) {
        $db->query('ROLLBACK');
        return ['ok' => false, 'message' => 'Unable to create crypto payment request.'];
    }
}

function admin_chat_create_bank_payment_request(
    Mysql_ks $db,
    int $conversationId,
    int $customerId,
    $amount,
    int $bankAccountId,
    int $adminUserId,
    array $messages
): array {
    $settings = admin_app_settings($db);
    if (!admin_bank_transfers_enabled($settings)) {
        return ['ok' => false, 'message' => 'Bank transfers are disabled.'];
    }

    $preview = admin_chat_bank_payment_preview($db, $customerId, $amount, $bankAccountId, $messages);
    if (empty($preview['ok'])) {
        return $preview;
    }

    $resolvedBankAccountId = (int)($preview['bank_account_id'] ?? 0);
    if ($resolvedBankAccountId <= 0) {
        return ['ok' => false, 'message' => 'Bank account is unavailable.'];
    }

    $db->start();

    $bankAccountAssignmentId = (int)($preview['bank_account_assignment_id'] ?? 0);
    if ($bankAccountAssignmentId <= 0) {
        $assignResult = admin_assign_bank_account_customer($db, $resolvedBankAccountId, $customerId, $adminUserId, $settings);
        if (empty($assignResult['ok'])) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => (string)($assignResult['message'] ?? 'Unable to assign bank account.')];
        }

        $assignments = admin_customer_active_bank_assignments($db, $customerId);
        foreach ($assignments as $assignment) {
            if ((int)($assignment['bank_account_id'] ?? 0) === $resolvedBankAccountId) {
                $preview = array_merge($preview, [
                    'bank_account_assignment_id' => (int)($assignment['bank_account_assignment_id'] ?? 0),
                    'account_holder_name' => (string)($assignment['account_holder_name'] ?? $preview['account_holder_name']),
                    'bank_name' => (string)($assignment['bank_name'] ?? $preview['bank_name']),
                    'iban' => (string)($assignment['iban'] ?? $preview['iban']),
                    'swift_bic' => (string)($assignment['swift_bic'] ?? $preview['swift_bic']),
                    'transfer_instructions' => (string)($assignment['transfer_instructions'] ?? $preview['transfer_instructions']),
                    'payment_reference_template' => (string)($assignment['payment_reference_template'] ?? $preview['payment_reference_template']),
                ]);
                break;
            }
        }
        $bankAccountAssignmentId = (int)($preview['bank_account_assignment_id'] ?? 0);
        if ($bankAccountAssignmentId <= 0) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Bank account assignment could not be confirmed.'];
        }
    }

    $requestId = 0;
    $now = date('Y-m-d H:i:s');
    $expiresAt = date('Y-m-d H:i:s', strtotime('+72 hours'));
    $sharedEnabled = admin_bank_account_shared_assignments_enabled($settings);
    $db->query(
        "UPDATE bank_transfer_requests
         SET status = 'archived'
         WHERE customer_id = {$customerId}
           AND status IN ('pending_payment', 'awaiting_review')
           AND expires_at IS NOT NULL
           AND expires_at < '{$now}'"
    );
    $openBankRequestWhere = $sharedEnabled
        ? "customer_id = {$customerId} AND (order_id IS NULL OR order_id = 0)"
        : "bank_account_id = {$resolvedBankAccountId}";
    $openBankRequest = $db->select_user(
        "SELECT id, customer_id, order_id
         FROM bank_transfer_requests
         WHERE {$openBankRequestWhere}
           AND status IN ('pending_payment', 'awaiting_review')
         ORDER BY id DESC
         LIMIT 1"
    );

    if (is_array($openBankRequest) && !empty($openBankRequest['id'])) {
        if ((int)($openBankRequest['customer_id'] ?? 0) !== $customerId || !empty($openBankRequest['order_id'])) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'This bank account already has an active payment request.'];
        }

        $updated = $db->update_using_id(
            [
                'bank_account_assignment_id',
                'requested_amount',
                'currency_id',
                'created_by_admin_user_id',
                'requested_at',
                'expires_at',
                'customer_transfer_note',
                'status',
            ],
            [
                $resolvedBankAccountId,
                $bankAccountAssignmentId,
                (float)$preview['amount'],
                (int)$preview['currency_id'],
                $adminUserId,
                $now,
                $expiresAt,
                'Updated from admin live chat bank request',
                'pending_payment',
            ],
            'bank_transfer_requests',
            (int)$openBankRequest['id']
        );
        if (!$updated) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Unable to update bank payment request.'];
        }
        $requestId = (int)$openBankRequest['id'];
    } else {
        $created = $db->insert(
            [
                'customer_id',
                'order_id',
                'bank_account_id',
                'bank_account_assignment_id',
                'requested_amount',
                'currency_id',
                'payment_reference',
                'status',
                'created_by_admin_user_id',
                'requested_at',
                'expires_at',
                'customer_transfer_note',
            ],
            [
                $customerId,
                null,
                $resolvedBankAccountId,
                $bankAccountAssignmentId,
                (float)$preview['amount'],
                (int)$preview['currency_id'],
                '',
                'pending_payment',
                $adminUserId,
                $now,
                $expiresAt,
                'Created from admin live chat bank request',
            ],
            'bank_transfer_requests'
        );

        if (!$created || (int)$db->id() <= 0) {
            $db->query('ROLLBACK');
            return ['ok' => false, 'message' => 'Unable to create bank payment request.'];
        }

        $requestId = (int)$db->id();
    }

    $paymentReference = admin_chat_bank_reference_build(
        (string)($preview['payment_reference_template'] ?? ''),
        $customerId,
        $requestId,
        0
    );
    $db->update_using_id(['payment_reference'], [$paymentReference], 'bank_transfer_requests', $requestId);

    $customer = app_find_customer_by_id($db, $customerId);
    $localeCode = app_normalize_email_locale((string)($customer['locale_code'] ?? 'en'));
    $messageBody = app_build_bank_payment_chat_card_message([
        'requested_amount' => (float)$preview['amount'],
        'currency_symbol' => (string)$preview['currency_symbol'],
        'currency_code' => (string)$preview['currency_code'],
        'account_holder_name' => (string)$preview['account_holder_name'],
        'bank_name' => (string)$preview['bank_name'],
        'iban' => (string)$preview['iban'],
        'swift_bic' => (string)$preview['swift_bic'],
        'payment_reference' => $paymentReference,
        'transfer_instructions' => (string)$preview['transfer_instructions'],
    ], $localeCode);

    if ($messageBody === '' || !admin_chat_insert_message($db, $conversationId, $adminUserId, $messageBody)) {
        $db->query('ROLLBACK');
        return ['ok' => false, 'message' => 'Unable to send bank payment message to chat.'];
    }

    $db->commit();

    return ['ok' => true, 'request_id' => $requestId];
}

function admin_delete_chat_conversation(Mysql_ks $db, int $conversationId): bool
{
    chat_ensure_message_interactions_runtime($db);
    if ($conversationId <= 0 || !schema_object_exists($db, 'support_conversations')) {
        return false;
    }

    $conversationRow = $db->select_user(
        "SELECT id
         FROM support_conversations
         WHERE id = {$conversationId}
         LIMIT 1"
    );
    if (!is_array($conversationRow) || empty($conversationRow['id'])) {
        return false;
    }

    $attachmentPaths = [];
    if (schema_object_exists($db, 'support_messages')) {
        $messageRows = $db->select_full_user(
            "SELECT attachment_path, audio_path
             FROM support_messages
             WHERE conversation_id = {$conversationId}"
        );
        foreach ($messageRows as $messageRow) {
            $attachmentPath = trim((string)($messageRow['attachment_path'] ?? ''));
            if ($attachmentPath !== '' && strpos($attachmentPath, '/uploads/chat/') === 0) {
                $attachmentPaths[] = $attachmentPath;
            }
            $audioPath = trim((string)($messageRow['audio_path'] ?? ''));
            if ($audioPath !== '' && strpos($audioPath, '/uploads/chat/') === 0) {
                $attachmentPaths[] = $audioPath;
            }
        }
    }

    $db->query('START TRANSACTION');

    if (schema_object_exists($db, 'support_conversation_members')) {
        if ($db->query("DELETE FROM support_conversation_members WHERE conversation_id = {$conversationId}") === false) {
            $db->query('ROLLBACK');
            return false;
        }
    }

    if (schema_object_exists($db, 'support_message_reactions')) {
        if ($db->query("DELETE reaction FROM support_message_reactions AS reaction
            INNER JOIN support_messages AS message_row ON message_row.id = reaction.message_id
            WHERE message_row.conversation_id = {$conversationId}") === false) {
            $db->query('ROLLBACK');
            return false;
        }
    }

    if (schema_object_exists($db, 'support_messages')) {
        if ($db->query("DELETE FROM support_messages WHERE conversation_id = {$conversationId}") === false) {
            $db->query('ROLLBACK');
            return false;
        }
    }

    if ($db->query("DELETE FROM support_conversations WHERE id = {$conversationId} LIMIT 1") === false) {
        $db->query('ROLLBACK');
        return false;
    }

    $conversationStillExists = $db->select_user(
        "SELECT id
         FROM support_conversations
         WHERE id = {$conversationId}
         LIMIT 1"
    );
    if (is_array($conversationStillExists) && !empty($conversationStillExists['id'])) {
        $db->query('ROLLBACK');
        return false;
    }

    $db->commit();

    foreach (array_unique($attachmentPaths) as $attachmentPath) {
        app_chat_delete_attachment_file($attachmentPath);
    }

    return true;
}

function admin_delete_chat_message(Mysql_ks $db, int $conversationId, int $messageId): bool
{
    chat_ensure_message_interactions_runtime($db);
    if ($conversationId <= 0 || $messageId <= 0 || !schema_object_exists($db, 'support_messages')) {
        return false;
    }

    $messageRow = $db->select_user(
        "SELECT id, attachment_path, audio_path
         FROM support_messages
         WHERE id = {$messageId}
           AND conversation_id = {$conversationId}
         LIMIT 1"
    );
    if (!is_array($messageRow) || empty($messageRow['id'])) {
        return false;
    }

    if (schema_object_exists($db, 'support_message_reactions')) {
        $db->query("DELETE FROM support_message_reactions WHERE message_id = {$messageId}");
    }
    $deleted = $db->delete_using_id('support_messages', $messageId);
    if (!$deleted) {
        return false;
    }

    $attachmentPath = trim((string)($messageRow['attachment_path'] ?? ''));
    if ($attachmentPath !== '' && strpos($attachmentPath, '/uploads/chat/') === 0) {
        app_chat_delete_attachment_file($attachmentPath);
    }
    $audioPath = trim((string)($messageRow['audio_path'] ?? ''));
    if ($audioPath !== '' && strpos($audioPath, '/uploads/chat/') === 0) {
        app_chat_delete_attachment_file($audioPath);
    }

    admin_chat_refresh_conversation_timestamps($db, $conversationId);
    return true;
}

function admin_render_chat_conversation_html(array $conversationRow, array $messageRows, array $messages): string
{
    $conversationType = (string)($conversationRow['conversation_type'] ?? '');
    $isGroupConversation = chat_is_group_like_conversation_type($conversationType);
    $isGlobalGroupConversation = function_exists('chat_is_global_group_conversation_type')
        ? chat_is_global_group_conversation_type($conversationType)
        : $conversationType === 'global_group';
    $retentionLabel = $isGroupConversation ? chat_group_retention_label(chat_group_retention_minutes_from_row($conversationRow)) : '';
    $previousAnchor = null;
    ob_start();
    ?>
    <div class="admin-chat-conversation" data-admin-chat-conversation data-conversation-id="<?php echo admin_e((string)($conversationRow['id'] ?? 0)); ?>">
        <div class="admin-chat-conversation__messages">
            <?php if ($isGroupConversation): ?>
                <div class="admin-chat-conversation__retention-hint">
                    <?php if ($retentionLabel !== ''): ?>
                        <?php echo admin_e('Auto-delete after ' . $retentionLabel); ?>
                    <?php else: ?>
                        <?php echo admin_e(admin_t($messages, 'group_chat_retention_hint_off', 'Auto-delete disabled')); ?>
                    <?php endif; ?>
                </div>
            <?php endif; ?>
            <?php if (!$messageRows): ?>
                <div class="admin-chat-conversation__empty admin-chat-conversation__empty--conversation">
                    <span class="admin-chat-conversation__empty-icon" aria-hidden="true"><i class="bi bi-chat-dots"></i></span>
                    <span><?php echo admin_e(admin_t($messages, 'chat_conversation_empty', 'No messages in this conversation yet.')); ?></span>
                </div>
            <?php else: ?>
                <?php foreach ($messageRows as $messageRow): ?>
                    <?php
                    $isCustomer = (string)($messageRow['sender_type'] ?? '') === 'customer';
                    $attachmentPath = trim((string)($messageRow['attachment_path'] ?? ''));
                    $audioPath = trim((string)($messageRow['audio_path'] ?? ''));
                    $audioStreamUrl = $audioPath !== '' ? chat_voice_message_stream_url((int)($messageRow['id'] ?? 0), 'admin') : '';
                    $audioMimeType = trim((string)($messageRow['audio_mime_type'] ?? ''));
                    $audioDurationLabel = trim((string)($messageRow['audio_duration_label'] ?? ''));
                    $messageBodyRaw = (string)($messageRow['message_body'] ?? '');
                    $systemNoticeText = chat_system_notice_text($messageBodyRaw);
                    $isSystemNotice = $systemNoticeText !== '';
                    $bubbleClass = $isSystemNotice ? 'is-system' : ($isCustomer ? 'is-customer' : 'is-admin');
                    $messageHtml = chat_format_message_html((string)($messageRow['message_body'] ?? ''));
                    $isAudioMessage = !empty($messageRow['is_audio_message']) && $audioPath !== '';
                    $isAudioExpired = !empty($messageRow['is_audio_expired']);
                    $isStructuredCard = admin_chat_message_is_structured_card($messageBodyRaw);
                    $canEdit = !$isSystemNotice && !$isAudioMessage && !$isAudioExpired && trim($messageBodyRaw) !== '' && !$isStructuredCard;
                    $canDelete = true;
                    $canInteract = !$isSystemNotice;
                    $showActionRow = $canEdit || $canDelete;
                    $anchorLabel = function_exists('chat_time_anchor_label') ? chat_time_anchor_label((string)($messageRow['created_at'] ?? '')) : '';
                    $showAnchor = $anchorLabel !== '' && $anchorLabel !== $previousAnchor;
                    if ($showAnchor) {
                        $previousAnchor = $anchorLabel;
                    }
                    $senderLabel = chat_sender_display_name(
                        [
                            'sender_type' => (string)($messageRow['sender_type'] ?? ''),
                            'admin_public_handle' => (string)($messageRow['admin_public_handle'] ?? ''),
                            'admin_login_name' => (string)($messageRow['admin_login_name'] ?? ''),
                            'customer_display_name' => (string)($messageRow['customer_display_name'] ?? ''),
                            'customer_email' => (string)($messageRow['customer_email'] ?? ''),
                        ],
                        [],
                        admin_t($messages, 'chat_inbox_title', 'Live chat inbox')
                    );
                    $senderBadgeLabel = '';
                    $senderBadgeClass = '';
                    $senderNameClass = !$isCustomer && $isGlobalGroupConversation ? ' admin-chat-conversation__sender-name--admin' : '';
                    if ($isGroupConversation) {
                        if (!$isCustomer) {
                            $senderBadgeLabel = admin_t($messages, 'chat_group_sender_admin_badge', 'Admin');
                            $senderBadgeClass = 'admin-chat-conversation__sender-badge--admin';
                        }
                    }
                    $customerStatus = strtolower(trim((string)($messageRow['customer_status'] ?? '')));
                    $customerGlobalChatBlocked = (int)($messageRow['customer_global_chat_blocked'] ?? 0) !== 0;
                    if ($isGlobalGroupConversation && $isCustomer && $customerGlobalChatBlocked) {
                        $senderBadgeLabel = admin_t($messages, 'status_blocked', 'Blocked');
                        $senderBadgeClass = 'admin-chat-conversation__sender-badge--blocked';
                    }
                    $isRead = (int)($messageRow['is_read'] ?? 0) === 1;
                    $receiptClass = $isRead ? 'is-read' : 'is-pending';
                    $receiptIcon = $isRead ? 'bi bi-check2-all' : 'bi bi-check2';
                    $receiptLabel = $isRead
                        ? admin_t($messages, 'chat_read_receipt_read', 'Read by customer')
                        : admin_t($messages, 'chat_read_receipt_pending', 'Waiting for customer to read');
                    $deleteLabel = admin_t($messages, 'chat_message_delete_button', 'Delete message');
                    $editLabel = admin_t($messages, 'chat_message_edit_button', 'Edit');
                    $blockCustomerLabel = $customerGlobalChatBlocked
                        ? admin_t($messages, 'chat_message_unblock_customer_button', 'Unblock user')
                        : admin_t($messages, 'chat_message_block_customer_button', 'Block user');
                    $saveLabel = admin_t($messages, 'chat_message_save_button', 'Save');
                    $savedLabel = admin_t($messages, 'chat_message_saved_label', 'Saved');
                    $canToggleCustomerBlock = $isGlobalGroupConversation && !$isSystemNotice && $isCustomer && (int)($messageRow['customer_id'] ?? 0) > 0;
                    $replyPreviewSender = (string)($messageRow['reply_preview_sender'] ?? '');
                    $replyPreviewText = (string)($messageRow['reply_preview_text'] ?? '');
                    $replyToMessageId = (int)($messageRow['reply_to_message_id'] ?? 0);
                    $reactionItems = isset($messageRow['reactions']) && is_array($messageRow['reactions']) ? $messageRow['reactions'] : [];
                    $replyActionLabel = admin_t($messages, 'chat_reply_action', 'Reply');
                    $isEmojiOnlyMessage = chat_message_is_emoji_only((string)($messageRow['message_body'] ?? ''));
                    ?>
                    <?php if ($showAnchor): ?>
                        <div class="messenger-time-anchor admin-chat-conversation__time-anchor">
                            <span><?php echo admin_e($anchorLabel); ?></span>
                        </div>
                    <?php endif; ?>
                    <div class="admin-chat-conversation__message <?php echo admin_e($bubbleClass); ?>" data-admin-chat-message data-message-id="<?php echo admin_e((string)($messageRow['id'] ?? 0)); ?>">
                        <div class="admin-chat-conversation__bubble<?php echo $isAudioMessage ? ' admin-chat-conversation__bubble--audio' : ''; ?>"<?php if ($canInteract): ?> data-admin-chat-message-bubble<?php endif; ?>>
                            <?php if ($isSystemNotice): ?>
                                <?php if ($messageHtml !== ''): ?>
                                    <div class="admin-chat-conversation__text<?php echo $isEmojiOnlyMessage ? ' admin-chat-conversation__text--emoji-only' : ''; ?>"><?php echo $messageHtml; ?></div>
                                <?php endif; ?>
                            <?php else: ?>
                                <div class="admin-chat-conversation__sender">
                                    <span class="admin-chat-conversation__sender-name<?php echo admin_e($senderNameClass); ?>"><?php if (!$isCustomer && $isGlobalGroupConversation): ?><span class="admin-chat-conversation__sender-admin-badge" aria-hidden="true">★</span><?php endif; ?><?php echo admin_e($senderLabel); ?></span>
                                    <?php if ($senderBadgeLabel !== ''): ?>
                                        <span class="admin-chat-conversation__sender-badge <?php echo admin_e($senderBadgeClass); ?>"><?php echo admin_e($senderBadgeLabel); ?></span>
                                    <?php endif; ?>
                                </div>
                                <?php if ($replyToMessageId > 0 && $replyPreviewText !== ''): ?>
                                    <button type="button" class="admin-chat-conversation__reply-preview" data-admin-chat-scroll-to-message="<?php echo admin_e((string)$replyToMessageId); ?>">
                                        <span class="admin-chat-conversation__reply-preview-sender"><?php echo admin_e($replyPreviewSender !== '' ? $replyPreviewSender : admin_t($messages, 'chat_reply_unknown', 'Message')); ?></span>
                                        <span class="admin-chat-conversation__reply-preview-text"><?php echo admin_e($replyPreviewText); ?></span>
                                    </button>
                                <?php endif; ?>
                                <?php if ($attachmentPath !== ''): ?>
                                    <?php app_chat_attachment_absolute_path($attachmentPath, true); ?>
                                    <a href="<?php echo admin_e($attachmentPath); ?>" target="_blank" rel="noopener noreferrer" class="admin-chat-conversation__image-link">
                                        <img src="<?php echo admin_e($attachmentPath); ?>" alt="attachment" class="admin-chat-conversation__image">
                                    </a>
                                <?php endif; ?>
                                <?php if ($isAudioMessage): ?>
                                    <div class="admin-chat-conversation__audio">
                                        <audio controls preload="metadata" class="admin-chat-conversation__audio-player" data-chat-audio-player src="<?php echo admin_e($audioStreamUrl !== '' ? $audioStreamUrl : $audioPath); ?>"<?php if ($audioMimeType !== ''): ?> type="<?php echo admin_e($audioMimeType); ?>"<?php endif; ?>></audio>
                                        <?php if ($audioDurationLabel !== ''): ?>
                                            <span class="admin-chat-conversation__audio-duration"><?php echo admin_e($audioDurationLabel); ?></span>
                                        <?php endif; ?>
                                    </div>
                                <?php elseif ($isAudioExpired): ?>
                                    <div class="admin-chat-conversation__audio-expired"><?php echo admin_e(chat_voice_message_expired_label()); ?></div>
                                <?php endif; ?>
                                <?php if ($messageHtml !== ''): ?>
                                    <div class="admin-chat-conversation__text"><?php echo $messageHtml; ?></div>
                                <?php endif; ?>
                                <?php if ($reactionItems): ?>
                                    <div class="admin-chat-conversation__reactions">
                                        <?php foreach ($reactionItems as $reactionItem): ?>
                                            <?php $reactionCode = trim((string)($reactionItem['code'] ?? '')); ?>
                                            <?php $reactionEmoji = trim((string)($reactionItem['emoji'] ?? '')); ?>
                                            <?php if ($reactionCode === '' || $reactionEmoji === '') { continue; } ?>
                                            <button
                                                type="button"
                                                class="admin-chat-conversation__reaction<?php echo !empty($reactionItem['is_selected']) ? ' is-selected' : ''; ?>"
                                                data-admin-chat-reaction-toggle="<?php echo admin_e($reactionCode); ?>"
                                                data-message-id="<?php echo admin_e((string)($messageRow['id'] ?? 0)); ?>">
                                                <span class="admin-chat-conversation__reaction-emoji"><?php echo admin_e($reactionEmoji); ?></span>
                                                <?php if ((int)($reactionItem['count'] ?? 0) > 1): ?>
                                                    <span class="admin-chat-conversation__reaction-count"><?php echo admin_e((string)((int)($reactionItem['count'] ?? 0))); ?></span>
                                                <?php endif; ?>
                                            </button>
                                        <?php endforeach; ?>
                                    </div>
                                <?php endif; ?>
                                <?php if ($canInteract): ?>
                                    <div class="admin-chat-conversation__message-actions" data-admin-chat-message-actions>
                                        <button
                                            type="button"
                                            class="admin-chat-conversation__message-action"
                                            data-admin-chat-reply-open
                                            data-message-id="<?php echo admin_e((string)($messageRow['id'] ?? 0)); ?>"
                                            data-reply-sender="<?php echo admin_e($senderLabel); ?>"
                                            data-reply-text="<?php echo admin_e($isAudioMessage ? chat_voice_message_label() : ($isAudioExpired ? chat_voice_message_expired_label() : chat_message_preview_excerpt($messageBodyRaw, $attachmentPath))); ?>">
                                            <i class="bi bi-reply" aria-hidden="true"></i>
                                        </button>
                                        <?php foreach (chat_message_reaction_catalog() as $reactionCode => $reactionEmoji): ?>
                                            <button
                                                type="button"
                                                class="admin-chat-conversation__message-action admin-chat-conversation__message-action--emoji"
                                                data-admin-chat-reaction-toggle="<?php echo admin_e($reactionCode); ?>"
                                                data-message-id="<?php echo admin_e((string)($messageRow['id'] ?? 0)); ?>">
                                                <?php echo admin_e($reactionEmoji); ?>
                                            </button>
                                        <?php endforeach; ?>
                                    </div>
                                <?php endif; ?>
                                <?php if ($canEdit): ?>
                                    <div class="admin-chat-conversation__editor" data-admin-chat-editor hidden>
