function admin_page_sort_rows(array $rows): array
{
    usort($rows, static function (array $left, array $right): int {
        $groupOrder = [
            'menu' => 10,
            'homepage' => 15,
            'applications' => 20,
            'payments' => 30,
            'other' => 40,
        ];
        $slugOrder = [
            'apps' => 10,
            'instructions' => 20,
            'instruction-ott-player' => 30,
            'instruction-newlook' => 40,
            'instruction-smart-iptv' => 50,
            'instruction-trust-wallet' => 60,
            'instruction-revolut' => 70,
            'instruction-crypto-exchange' => 80,
        ];
        $localeOrder = [
            'pl' => 10,
            'en' => 20,
        ];
        $leftSystem = !empty($left['is_system']) ? 1 : 0;
        $rightSystem = !empty($right['is_system']) ? 1 : 0;
        if ($leftSystem !== $rightSystem) {
            return $rightSystem <=> $leftSystem;
        }

        $leftBase = admin_page_slug_base((string)($left['slug'] ?? ''));
        $rightBase = admin_page_slug_base((string)($right['slug'] ?? ''));
        $leftGroupOrder = (int)($groupOrder[admin_page_group_key($left)] ?? 999);
        $rightGroupOrder = (int)($groupOrder[admin_page_group_key($right)] ?? 999);
        if ($leftGroupOrder !== $rightGroupOrder) {
            return $leftGroupOrder <=> $rightGroupOrder;
        }

        $leftMenuSortOrder = (int)($left['menu_sort_order'] ?? 100);
        $rightMenuSortOrder = (int)($right['menu_sort_order'] ?? 100);
        if ($leftMenuSortOrder !== $rightMenuSortOrder) {
            return $leftMenuSortOrder <=> $rightMenuSortOrder;
        }

        $leftSlugOrder = (int)($slugOrder[$leftBase] ?? 999);
        $rightSlugOrder = (int)($slugOrder[$rightBase] ?? 999);
        if ($leftSlugOrder !== $rightSlugOrder) {
            return $leftSlugOrder <=> $rightSlugOrder;
        }

        $slugCompare = strcmp($leftBase, $rightBase);
        if ($slugCompare !== 0) {
            return $slugCompare;
        }

        $leftLocale = admin_page_normalize_locale((string)($left['locale_code'] ?? 'pl'));
        $rightLocale = admin_page_normalize_locale((string)($right['locale_code'] ?? 'pl'));
        $leftLocaleOrder = (int)($localeOrder[$leftLocale] ?? 999);
        $rightLocaleOrder = (int)($localeOrder[$rightLocale] ?? 999);
        if ($leftLocaleOrder !== $rightLocaleOrder) {
            return $leftLocaleOrder <=> $rightLocaleOrder;
        }

        $localeCompare = strcmp($leftLocale, $rightLocale);
        if ($localeCompare !== 0) {
            return $localeCompare;
        }

        $leftSlug = (string)($left['slug'] ?? '');
        $rightSlug = (string)($right['slug'] ?? '');
        $fullSlugCompare = strcmp($leftSlug, $rightSlug);
        if ($fullSlugCompare !== 0) {
            return $fullSlugCompare;
        }

        return ((int)($left['id'] ?? 0)) <=> ((int)($right['id'] ?? 0));
    });

    return $rows;
}

function admin_create_page(Mysql_ks $db, array $input, array $files = [], int $adminUserId = 0): array
{
    if (!schema_object_exists($db, 'static_pages')) {
        return ['ok' => false, 'message' => 'Page storage is not available.'];
    }

    admin_page_seed_system_rows($db);
    admin_ensure_static_pages_locale_runtime($db);
    $title = trim((string)($input['title'] ?? ''));
    $slugInput = trim((string)($input['slug'] ?? ''));
    $body = trim((string)($input['body'] ?? ''));
    $localeCode = admin_page_normalize_locale((string)($input['locale_code'] ?? 'pl'));
    $isActive = isset($input['is_active']) && (string)$input['is_active'] === '1' ? 1 : 0;
    $menuSection = admin_page_normalize_section((string)($input['menu_section'] ?? 'other'));
    $menuTitle = trim((string)($input['menu_title'] ?? ''));
    $menuSortOrder = max(0, (int)($input['menu_sort_order'] ?? 100));
    $menuLogoUrl = '';
    $menuLogoFile = is_array($files['menu_logo_file'] ?? null) ? $files['menu_logo_file'] : null;
    $menuLogoUploadError = (int)($menuLogoFile['error'] ?? UPLOAD_ERR_NO_FILE);

    if ($menuTitle === '') {
        $menuTitle = $title;
    }

    if ($title === '') {
        return ['ok' => false, 'message' => 'Page title is required.'];
    }

    if ($body === '') {
        return ['ok' => false, 'message' => 'Page content is required.'];
    }

    if ($menuLogoUploadError !== UPLOAD_ERR_NO_FILE) {
        $menuLogoUrl = (string)admin_page_card_logo_public_path($menuLogoFile, $adminUserId);
        if ($menuLogoUrl === '') {
            return ['ok' => false, 'message' => 'Page card logo must be a valid JPG, PNG, GIF, WEBP or SVG image.'];
        }
    }

    $slug = admin_page_locale_aware_slug($db, $title, $slugInput, $localeCode);
    $inserted = $db->insert(
        ['slug', 'title', 'body', 'locale_code', 'menu_section', 'menu_title', 'menu_logo_url', 'menu_sort_order', 'page_type', 'is_system', 'is_active'],
        [$slug, $title, $body, $localeCode, $menuSection, $menuTitle, $menuLogoUrl !== '' ? $menuLogoUrl : null, $menuSortOrder, 'page', 0, $isActive],
        'static_pages'
    );

    if (!$inserted) {
        if ($menuLogoUrl !== '') {
            admin_delete_page_card_logo_file($menuLogoUrl);
        }
        return ['ok' => false, 'message' => 'Unable to create page.'];
    }

    return [
        'ok' => true,
        'message' => 'Page created successfully.',
        'page_id' => (int)$db->id(),
    ];
}

function admin_save_page(Mysql_ks $db, int $pageId, array $input, array $files = [], int $adminUserId = 0): array
{
    $page = admin_page_find($db, $pageId);
    if (!is_array($page) || empty($page['id'])) {
        return ['ok' => false, 'message' => 'Page not found.'];
    }

    $title = trim((string)($input['title'] ?? ''));
    $slugInput = trim((string)($input['slug'] ?? ''));
    $body = trim((string)($input['body'] ?? ''));
    $localeCode = admin_page_normalize_locale((string)($input['locale_code'] ?? (string)($page['locale_code'] ?? 'pl')));
    $isActive = isset($input['is_active']) && (string)$input['is_active'] === '1' ? 1 : 0;
    $menuSection = admin_page_normalize_section((string)($input['menu_section'] ?? (string)($page['menu_section'] ?? 'other')));
    $menuTitle = trim((string)($input['menu_title'] ?? ''));
    $menuSortOrder = max(0, (int)($input['menu_sort_order'] ?? ($page['menu_sort_order'] ?? 100)));
    $existingMenuLogoUrl = trim((string)($page['menu_logo_url'] ?? ''));
    $menuLogoUrl = $existingMenuLogoUrl;
    $removeMenuLogo = isset($input['remove_menu_logo']) && (string)$input['remove_menu_logo'] === '1';
    $menuLogoFile = is_array($files['menu_logo_file'] ?? null) ? $files['menu_logo_file'] : null;
    $menuLogoUploadError = (int)($menuLogoFile['error'] ?? UPLOAD_ERR_NO_FILE);
    $uploadedMenuLogoUrl = '';

    if ($title === '') {
        return ['ok' => false, 'message' => 'Page title is required.'];
    }

    if ($body === '') {
        return ['ok' => false, 'message' => 'Page content is required.'];
    }

    if ($menuTitle === '') {
        $menuTitle = $title;
    }

    if ($removeMenuLogo) {
        $menuLogoUrl = '';
    }

    if ($menuLogoUploadError !== UPLOAD_ERR_NO_FILE) {
        $uploadedMenuLogoUrl = (string)admin_page_card_logo_public_path($menuLogoFile, $adminUserId);
        if ($uploadedMenuLogoUrl === '') {
            return ['ok' => false, 'message' => 'Page card logo must be a valid JPG, PNG, GIF, WEBP or SVG image.'];
        }
        $menuLogoUrl = $uploadedMenuLogoUrl;
    }

    $slug = admin_page_locale_aware_slug($db, $title, $slugInput, $localeCode, $pageId);
    $updated = $db->update_using_id(
        ['slug', 'title', 'body', 'locale_code', 'menu_section', 'menu_title', 'menu_logo_url', 'menu_sort_order', 'page_type', 'is_system', 'is_active'],
        [$slug, $title, $body, $localeCode, $menuSection, $menuTitle, $menuLogoUrl !== '' ? $menuLogoUrl : null, $menuSortOrder, 'page', (int)($page['is_system'] ?? 0), $isActive],
        'static_pages',
        $pageId
    );

    if ($updated) {
        if ($uploadedMenuLogoUrl !== '' && $existingMenuLogoUrl !== '' && $existingMenuLogoUrl !== $uploadedMenuLogoUrl) {
            admin_delete_page_card_logo_file($existingMenuLogoUrl);
        } elseif ($removeMenuLogo && $uploadedMenuLogoUrl === '' && $existingMenuLogoUrl !== '') {
            admin_delete_page_card_logo_file($existingMenuLogoUrl);
        }
    } elseif ($uploadedMenuLogoUrl !== '') {
        admin_delete_page_card_logo_file($uploadedMenuLogoUrl);
    }

    return [
        'ok' => (bool)$updated,
        'message' => $updated ? 'Page saved successfully.' : 'Unable to save page.',
    ];
}

function admin_delete_page(Mysql_ks $db, int $pageId): array
{
    $page = admin_page_find($db, $pageId);
    if (!is_array($page) || empty($page['id'])) {
        return ['ok' => false, 'message' => 'Page not found.'];
    }

    // Keep only a tombstone for seeded pages so runtime seeding cannot resurrect them.
    $deleted = !empty($page['is_system'])
        ? $db->update_using_id(['page_type','is_active','title','body','menu_title','menu_logo_url'], ['deleted',0,'','',null,null], 'static_pages', $pageId)
        : $db->delete_using_id('static_pages', $pageId);
    if ($deleted) {
        admin_delete_page_card_logo_file((string)($page['menu_logo_url'] ?? ''));
    }

    return [
        'ok' => (bool)$deleted,
        'message' => $deleted ? 'Page deleted successfully.' : 'Unable to delete page.',
    ];
}

function admin_ensure_help_videos_runtime_table(Mysql_ks $db): void
{
    static $ready = false;
    if ($ready && schema_object_exists($db, 'admin_help_videos')) {
        return;
    }

    if (!schema_object_exists($db, 'admin_help_videos')) {
        $db->query(
            "CREATE TABLE IF NOT EXISTS admin_help_videos (
                id INT UNSIGNED NOT NULL AUTO_INCREMENT,
                title VARCHAR(191) NOT NULL,
                video_url VARCHAR(1000) NOT NULL,
                description_html LONGTEXT DEFAULT NULL,
                sort_order INT NOT NULL DEFAULT 100,
                is_active TINYINT(1) NOT NULL DEFAULT 1,
                created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                PRIMARY KEY (id),
                KEY idx_admin_help_videos_active_sort (is_active, sort_order, id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
        );
        unset($GLOBALS['schema_object_exists_cache']['admin_help_videos']);
    }

    if (!schema_object_exists($db, 'admin_help_videos')) {
        return;
    }

    $ready = true;
}

function admin_help_video_normalize_url(string $url): string
{
    $url = trim($url);
    if ($url === '') {
        return '';
    }

    if (!preg_match('~^https?://~i', $url)) {
        return '';
    }

    return $url;
}

function admin_help_video_rows(Mysql_ks $db, bool $activeOnly = false): array
{
    admin_ensure_help_videos_runtime_table($db);
    if (!schema_object_exists($db, 'admin_help_videos')) {
        return [];
    }

    $whereSql = $activeOnly ? 'WHERE is_active = 1' : '';

    return $db->select_full_user(
        "SELECT id, title, video_url, description_html, sort_order, is_active, created_at, updated_at
         FROM admin_help_videos
         {$whereSql}
         ORDER BY sort_order ASC, id ASC"
    );
}

function admin_help_video_rows_by_ids(Mysql_ks $db, array $videoIds, bool $activeOnly = true): array
{
    admin_ensure_help_videos_runtime_table($db);
    if (!schema_object_exists($db, 'admin_help_videos')) {
        return [];
    }

    $safeIds = [];
    foreach ($videoIds as $videoId) {
        $videoId = (int)$videoId;
        if ($videoId > 0) {
            $safeIds[$videoId] = $videoId;
        }
    }
    $safeIds = array_values($safeIds);
    if (!$safeIds) {
        return [];
    }

    $idList = implode(',', $safeIds);
    $activeSql = $activeOnly ? ' AND is_active = 1' : '';

    return $db->select_full_user(
        "SELECT id, title, video_url, description_html, sort_order, is_active, created_at, updated_at
         FROM admin_help_videos
         WHERE id IN ({$idList}){$activeSql}
         ORDER BY FIELD(id, {$idList})"
    );
}

function admin_help_video_find(Mysql_ks $db, int $videoId): ?array
{
    admin_ensure_help_videos_runtime_table($db);
    if ($videoId <= 0 || !schema_object_exists($db, 'admin_help_videos')) {
        return null;
    }

    $row = $db->select_user(
        "SELECT id, title, video_url, description_html, sort_order, is_active, created_at, updated_at
         FROM admin_help_videos
         WHERE id = {$videoId}
         LIMIT 1"
    );

    return is_array($row) && !empty($row['id']) ? $row : null;
}

