function admin_sql_runner_split_statements(string $sql): array
{
    $statements = [];
    $buffer = '';
    $length = strlen($sql);
    $quote = '';
    $escaped = false;
    $lineComment = false;
    $blockComment = false;

    for ($i = 0; $i < $length; $i++) {
        $char = $sql[$i];
        $next = $i + 1 < $length ? $sql[$i + 1] : '';

        if ($lineComment) {
            if ($char === "\n") {
                $lineComment = false;
            }
            $buffer .= $char;
            continue;
        }

        if ($blockComment) {
            $buffer .= $char;
            if ($char === '*' && $next === '/') {
                $buffer .= $next;
                $i++;
                $blockComment = false;
            }
            continue;
        }

        if ($quote !== '') {
            $buffer .= $char;
            if ($escaped) {
                $escaped = false;
                continue;
            }
            if ($char === '\\') {
                $escaped = true;
                continue;
            }
            if ($char === $quote) {
                $quote = '';
            }
            continue;
        }

        if (($char === '-' && $next === '-') || $char === '#') {
            $lineComment = true;
            $buffer .= $char;
            if ($char === '-' && $next === '-') {
                $buffer .= $next;
                $i++;
            }
            continue;
        }

        if ($char === '/' && $next === '*') {
            $blockComment = true;
            $buffer .= $char . $next;
            $i++;
            continue;
        }

        if ($char === '\'' || $char === '"' || $char === '`') {
            $quote = $char;
            $buffer .= $char;
            continue;
        }

        if ($char === ';') {
            $statement = trim($buffer);
            if ($statement !== '') {
                $statements[] = $statement;
            }
            $buffer = '';
            continue;
        }

        $buffer .= $char;
    }

    $statement = trim($buffer);
    if ($statement !== '') {
        $statements[] = $statement;
    }

    return $statements;
}

function admin_sql_runner_statement_head(string $statement): string
{
    $statement = preg_replace('~/\*.*?\*/~s', ' ', $statement) ?? $statement;
    $lines = preg_split('/\R/', $statement) ?: [];
    $clean = [];
    foreach ($lines as $line) {
        $trimmed = ltrim((string)$line);
        if ($trimmed === '' || str_starts_with($trimmed, '--') || str_starts_with($trimmed, '#')) {
            continue;
        }
        $clean[] = $trimmed;
    }

    return strtoupper(trim(implode(' ', $clean)));
}

function admin_sql_runner_create_table_name(string $statement): string
{
    if (preg_match('/^\s*CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?`?([a-zA-Z0-9_]+)`?/i', $statement, $matches)) {
        return (string)$matches[1];
    }

    return '';
}

function admin_sql_runner_validate_statement(string $statement): array
{
    $head = admin_sql_runner_statement_head($statement);
    if ($head === '') {
        return ['ok' => false, 'message' => 'Empty SQL statement.'];
    }

    $blockedPrefixes = [
        'DROP ',
        'TRUNCATE ',
        'DELETE ',
        'RENAME ',
        'GRANT ',
        'REVOKE ',
        'CREATE USER',
        'ALTER USER',
        'DROP USER',
        'SET PASSWORD',
        'LOCK TABLES',
        'UNLOCK TABLES',
        'KILL ',
        'SHUTDOWN',
    ];
    foreach ($blockedPrefixes as $prefix) {
        if (str_starts_with($head, $prefix)) {
            return ['ok' => false, 'message' => 'Blocked SQL statement: ' . trim($prefix)];
        }
    }

    $blockedFragments = [' INTO OUTFILE', ' INTO DUMPFILE', ' LOAD_FILE(', ' LOAD DATA'];
    foreach ($blockedFragments as $fragment) {
        if (str_contains($head, $fragment)) {
            return ['ok' => false, 'message' => 'Blocked SQL fragment: ' . trim($fragment)];
        }
    }

    if (str_starts_with($head, 'CREATE TABLE') && preg_match('/\)\s+AS\s+SELECT\b/i', $head)) {
        return ['ok' => false, 'message' => 'CREATE TABLE AS SELECT is blocked in this runner.'];
    }

    if (str_starts_with($head, 'INSERT ') && str_contains($head, ' ON DUPLICATE KEY UPDATE ')) {
        return ['ok' => false, 'message' => 'INSERT ... ON DUPLICATE KEY UPDATE is blocked because it can overwrite existing records.'];
    }

    if (str_starts_with($head, 'ALTER TABLE')) {
        // Keep ALTER TABLE narrowly scoped to additive schema changes.
        $blockedAlterFragments = [' DROP ', ' RENAME ', ' CHANGE ', ' MODIFY '];
        foreach ($blockedAlterFragments as $fragment) {
            if (str_contains($head, $fragment)) {
                return ['ok' => false, 'message' => 'Blocked ALTER TABLE operation: ' . trim($fragment)];
            }
        }
    }

    $allowedPrefixes = [
        'CREATE TABLE',
        'ALTER TABLE',
        'CREATE INDEX',
        'INSERT ',
    ];
    foreach ($allowedPrefixes as $prefix) {
        if (str_starts_with($head, $prefix)) {
            return ['ok' => true, 'message' => ''];
        }
    }

    return ['ok' => false, 'message' => 'Only CREATE TABLE, ALTER TABLE (additive), CREATE INDEX and INSERT statements are allowed here.'];
}

function admin_execute_sql_import(Mysql_ks $db, string $sql): array
{
    $sql = trim($sql);
    if ($sql === '') {
        return ['ok' => false, 'message' => 'SQL code is required.', 'executed' => 0, 'skipped' => 0];
    }

    if (strlen($sql) > 500000) {
        return ['ok' => false, 'message' => 'SQL code is too large for this runner.', 'executed' => 0, 'skipped' => 0];
    }

    $statements = admin_sql_runner_split_statements($sql);
    if ($statements === []) {
        return ['ok' => false, 'message' => 'No SQL statements found.', 'executed' => 0, 'skipped' => 0];
    }

    if (count($statements) > 100) {
        return ['ok' => false, 'message' => 'Too many SQL statements. Please split the import into smaller parts.', 'executed' => 0, 'skipped' => 0];
    }

    $executed = 0;
    $skipped = 0;
    $details = [];

    foreach ($statements as $index => $statement) {
        $validation = admin_sql_runner_validate_statement($statement);
        if (empty($validation['ok'])) {
            return [
                'ok' => false,
                'message' => 'Statement #' . ($index + 1) . ': ' . (string)$validation['message'],
                'executed' => 0,
                'skipped' => 0,
                'details' => [],
            ];
        }
    }

    foreach ($statements as $index => $statement) {
        $tableName = admin_sql_runner_create_table_name($statement);
        if ($tableName !== '' && schema_object_exists($db, $tableName)) {
            $skipped++;
            $details[] = 'Skipped CREATE TABLE `' . $tableName . '` because it already exists.';
            continue;
        }

        $result = $db->query($statement);
        if ($result === false) {
            $error = trim((string)($db->error ?? 'Unknown SQL error.'));
            return [
                'ok' => false,
                'message' => 'Statement #' . ($index + 1) . ' failed: ' . ($error !== '' ? $error : 'Unknown SQL error.'),
                'executed' => $executed,
                'skipped' => $skipped,
                'details' => $details,
            ];
        }

        $executed++;
    }

    return [
        'ok' => true,
        'message' => 'SQL import finished successfully.',
        'executed' => $executed,
        'skipped' => $skipped,
        'details' => $details,
    ];
}

function admin_ensure_dashboard_change_log_runtime_table(Mysql_ks $db): void
{
    static $ready = false;
    if ($ready && schema_object_exists($db, 'admin_dashboard_change_log')) {
        return;
    }

    if (!schema_object_exists($db, 'admin_dashboard_change_log')) {
        $db->query(
            "CREATE TABLE IF NOT EXISTS admin_dashboard_change_log (
                id INT UNSIGNED NOT NULL AUTO_INCREMENT,
                change_date DATE NOT NULL,
                change_text TEXT NOT NULL,
                admin_user_id INT UNSIGNED DEFAULT NULL,
                created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
                updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                PRIMARY KEY (id),
                KEY idx_admin_dashboard_change_log_change_date (change_date, id),
                KEY idx_admin_dashboard_change_log_admin_user_id (admin_user_id),
                CONSTRAINT fk_admin_dashboard_change_log_admin_user FOREIGN KEY (admin_user_id) REFERENCES admin_users (id) ON DELETE SET NULL
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
        );
        unset($GLOBALS['schema_object_exists_cache']['admin_dashboard_change_log']);
    }

    $ready = true;
}

function admin_dashboard_change_log_rows(Mysql_ks $db, int $limit = 100): array
{
    admin_ensure_dashboard_change_log_runtime_table($db);
    if (!schema_object_exists($db, 'admin_dashboard_change_log')) {
        return [];
    }

    $limit = max(1, min(500, $limit));

    return $db->select_full_user(
        "SELECT
            admin_dashboard_change_log.id,
            admin_dashboard_change_log.change_date,
            admin_dashboard_change_log.change_text,
            admin_dashboard_change_log.admin_user_id,
            admin_dashboard_change_log.created_at,
            admin_dashboard_change_log.updated_at,
            admin_users.login_name AS admin_login_name
         FROM admin_dashboard_change_log
         LEFT JOIN admin_users ON admin_users.id = admin_dashboard_change_log.admin_user_id
         ORDER BY admin_dashboard_change_log.change_date DESC, admin_dashboard_change_log.id DESC
         LIMIT {$limit}"
    );
}

function admin_dashboard_change_log_grouped_rows(Mysql_ks $db, int $limit = 100): array
{
    $rows = admin_dashboard_change_log_rows($db, $limit);
    if (!$rows) {
        return [];
    }

    $grouped = [];
    foreach ($rows as $row) {
        $changeDate = trim((string)($row['change_date'] ?? ''));
        if ($changeDate === '') {
            continue;
        }

        if (!isset($grouped[$changeDate])) {
            $timestamp = strtotime($changeDate . ' 00:00:00');
            $grouped[$changeDate] = [
                'date' => $changeDate,
                'date_label' => $timestamp ? date('d.m.Y', $timestamp) : $changeDate,
                'items' => [],
            ];
        }

        $grouped[$changeDate]['items'][] = [
            'id' => (int)($row['id'] ?? 0),
            'text' => trim((string)($row['change_text'] ?? '')),
            'created_at' => (string)($row['created_at'] ?? ''),
            'admin_login_name' => trim((string)($row['admin_login_name'] ?? '')),
        ];
    }

    return array_values($grouped);
}

function admin_create_dashboard_change_log_entry(Mysql_ks $db, array $input, int $adminUserId = 0): array
{
    admin_ensure_dashboard_change_log_runtime_table($db);
    if (!schema_object_exists($db, 'admin_dashboard_change_log')) {
        return ['ok' => false, 'message' => 'Change log storage is not available.'];
    }

    $changeDate = trim((string)($input['change_date'] ?? ''));
    $changeText = trim((string)($input['change_text'] ?? ''));

    if ($changeDate === '' || !preg_match('/^\d{4}-\d{2}-\d{2}$/', $changeDate)) {
        return ['ok' => false, 'message' => 'Change date is required.'];
    }

    if ($changeText === '') {
        return ['ok' => false, 'message' => 'Change description is required.'];
    }

    $inserted = $db->insert(
        ['change_date', 'change_text', 'admin_user_id'],
        [$changeDate, $changeText, $adminUserId > 0 ? $adminUserId : null],
        'admin_dashboard_change_log'
    );

    if (!$inserted) {
        return ['ok' => false, 'message' => 'Unable to create change log entry.'];
    }

    return [
        'ok' => true,
        'message' => 'Change log entry created successfully.',
        'entry_id' => (int)$db->id(),
    ];
}

function admin_delete_dashboard_change_log_entry(Mysql_ks $db, int $entryId): array
{
    admin_ensure_dashboard_change_log_runtime_table($db);
    if ($entryId <= 0 || !schema_object_exists($db, 'admin_dashboard_change_log')) {
        return ['ok' => false, 'message' => 'Change log entry not found.'];
    }

    $row = $db->select_user("SELECT id FROM admin_dashboard_change_log WHERE id = {$entryId} LIMIT 1");
    if (!is_array($row) || empty($row['id'])) {
        return ['ok' => false, 'message' => 'Change log entry not found.'];
    }

    $deleted = $db->delete_using_id('admin_dashboard_change_log', $entryId);

    return [
        'ok' => (bool)$deleted,
        'message' => $deleted ? 'Change log entry deleted successfully.' : 'Unable to delete change log entry.',
    ];
}

function admin_search_order_rows(Mysql_ks $db, string $query, int $limit = 20): array
{
    $query = trim($query);
    if ($query === '' || !schema_object_exists($db, 'orders') || !schema_object_exists($db, 'customers')) {
        return [];
    }

    $limit = max(1, min(50, $limit));
    $safeLike = $db->escape('%' . $query . '%');
    $deliveryLinkVisibleSelect = schema_column_exists($db, 'orders', 'delivery_link_visible')
        ? 'orders.delivery_link_visible'
        : '0';
    $supportsDeliveryLinksSelect = schema_column_exists($db, 'product_providers', 'supports_delivery_links')
        ? 'product_providers.supports_delivery_links'
        : '1';
    $customerPublicHandleSelect = schema_column_exists($db, 'customers', 'public_handle')
        ? 'customers.public_handle'
        : "''";
    $progressStartedAtSelect = admin_order_progress_started_at_sql($db);
    $progressDurationHoursSelect = admin_order_progress_duration_hours_sql($db);

    $whereParts = [
        "customers.email LIKE '{$safeLike}'",
    ];

    if (schema_column_exists($db, 'customers', 'public_handle')) {
        $safeHandle = $db->escape('%' . ltrim($query, '@') . '%');
        if (ltrim($query, '@') !== '') $whereParts[] = "customers.public_handle LIKE '{$safeHandle}'";
    }

    if (ctype_digit($query)) {
        $whereParts[] = 'orders.id = ' . (int)$query;
    }

    $hasCustomerCryptoWallets = schema_object_exists($db, 'customer_crypto_wallets');
    $hasCryptoDepositRequests = schema_object_exists($db, 'crypto_deposit_requests') && schema_object_exists($db, 'crypto_wallet_addresses');

    if ($hasCryptoDepositRequests) {
        $whereParts[] = "EXISTS (
            SELECT 1
            FROM crypto_deposit_requests
            INNER JOIN crypto_wallet_addresses ON crypto_wallet_addresses.id = crypto_deposit_requests.wallet_address_id
            WHERE crypto_deposit_requests.order_id = orders.id
              AND crypto_wallet_addresses.address LIKE '{$safeLike}'
        )";
    }

    if ($hasCustomerCryptoWallets) {
        $whereParts[] = "EXISTS (
            SELECT 1
            FROM customer_crypto_wallets
            WHERE customer_crypto_wallets.customer_id = orders.customer_id
              AND customer_crypto_wallets.address LIKE '{$safeLike}'
        )";
    }

    $walletAddressSelect = "''";
    $walletAssetSelect = "''";

    if ($hasCryptoDepositRequests && $hasCustomerCryptoWallets) {
        $walletAddressSelect = "COALESCE(
            (
                SELECT crypto_wallet_addresses.address
                FROM crypto_deposit_requests
                INNER JOIN crypto_wallet_addresses ON crypto_wallet_addresses.id = crypto_deposit_requests.wallet_address_id
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ),
            (
                SELECT customer_crypto_wallets.address
                FROM customer_crypto_wallets
                WHERE customer_crypto_wallets.customer_id = orders.customer_id
                ORDER BY customer_crypto_wallets.assigned_at DESC
                LIMIT 1
            )
        )";

        $walletAssetSelect = "COALESCE(
            (
                SELECT crypto_assets.code
                FROM crypto_deposit_requests
                INNER JOIN crypto_assets ON crypto_assets.id = crypto_deposit_requests.crypto_asset_id
                WHERE crypto_deposit_requests.order_id = orders.id
                ORDER BY crypto_deposit_requests.id DESC
                LIMIT 1
            ),
            (
                SELECT customer_crypto_wallets.crypto_asset_code
                FROM customer_crypto_wallets
                WHERE customer_crypto_wallets.customer_id = orders.customer_id
                ORDER BY customer_crypto_wallets.assigned_at DESC
                LIMIT 1
            )
        )";
    } elseif ($hasCryptoDepositRequests) {
        $walletAddressSelect = "(
            SELECT crypto_wallet_addresses.address
            FROM crypto_deposit_requests
            INNER JOIN crypto_wallet_addresses ON crypto_wallet_addresses.id = crypto_deposit_requests.wallet_address_id
            WHERE crypto_deposit_requests.order_id = orders.id
            ORDER BY crypto_deposit_requests.id DESC
            LIMIT 1
        )";

        $walletAssetSelect = "(
            SELECT crypto_assets.code
            FROM crypto_deposit_requests
            INNER JOIN crypto_assets ON crypto_assets.id = crypto_deposit_requests.crypto_asset_id
            WHERE crypto_deposit_requests.order_id = orders.id
            ORDER BY crypto_deposit_requests.id DESC
            LIMIT 1
        )";
    } elseif ($hasCustomerCryptoWallets) {
        $walletAddressSelect = "(
            SELECT customer_crypto_wallets.address
            FROM customer_crypto_wallets
            WHERE customer_crypto_wallets.customer_id = orders.customer_id
            ORDER BY customer_crypto_wallets.assigned_at DESC
            LIMIT 1
        )";

        $walletAssetSelect = "(
            SELECT customer_crypto_wallets.crypto_asset_code
            FROM customer_crypto_wallets
            WHERE customer_crypto_wallets.customer_id = orders.customer_id
            ORDER BY customer_crypto_wallets.assigned_at DESC
            LIMIT 1
        )";
    }

    $currencyJoin = schema_object_exists($db, 'currencies')
        ? 'LEFT JOIN currencies ON currencies.id = orders.currency_id'
        : '';
    $currencySelect = schema_object_exists($db, 'currencies')
        ? 'currencies.code AS currency_code'
        : "'' AS currency_code";

    return $db->select_full_user(
        "SELECT
            orders.id,
            orders.customer_id,
            orders.payment_method,
            orders.payment_status,
            orders.status,
            orders.fulfillment_status,
            orders.total_amount,
            orders.delivery_link,
            orders.support_note,
            orders.created_at,
            orders.started_at,
            orders.expires_at,
            {$progressStartedAtSelect} AS progress_started_at,
            {$progressDurationHoursSelect} AS progress_duration_hours,
            customers.email AS customer_email,
            {$customerPublicHandleSelect} AS public_handle,
            products.name AS product_name,
            products.duration_hours,
            products.product_type,
            product_providers.name AS provider_name,
            product_providers.dashboard_url,
            {$deliveryLinkVisibleSelect} AS delivery_link_visible,
            {$supportsDeliveryLinksSelect} AS supports_delivery_links,
            {$currencySelect},
            {$walletAddressSelect} AS wallet_address,
            {$walletAssetSelect} AS wallet_asset_code
         FROM orders
         INNER JOIN customers ON customers.id = orders.customer_id
         LEFT JOIN products ON products.id = orders.product_id
         LEFT JOIN product_providers ON product_providers.id = products.provider_id
         {$currencyJoin}
         WHERE (" . implode(' OR ', $whereParts) . ")
         ORDER BY orders.id DESC
         LIMIT {$limit}"
    );
}

function admin_search_customer_rows(Mysql_ks $db, string $query, int $limit = 20): array
{
    $query = trim($query);
    if ($query === '' || !schema_object_exists($db, 'customers')) {
        return [];
    }

    app_ensure_customer_runtime_columns($db);

    $limit = max(1, min(50, $limit));
    $isHandleSearch = strpos($query, '@') === 0;
    $needle = $isHandleSearch ? ltrim($query, '@') : $query;
    $needleLower = strtolower($needle);
    $safeLike = $db->escape('%' . $needle . '%');
    $safeNeedleLower = $db->escape($needleLower);
    $whereParts = [
        "customers.email LIKE '{$safeLike}'",
    ];
    $rankParts = [
        "CASE WHEN LOWER(customers.email) = '{$safeNeedleLower}' THEN 0 ELSE 100 END",
    ];

    if (schema_column_exists($db, 'customers', 'public_handle')) {
        $whereParts[] = "customers.public_handle LIKE '{$safeLike}'";
        $rankParts[] = "CASE WHEN LOWER(customers.public_handle) = '{$safeNeedleLower}' THEN 1 ELSE 100 END";
    }

    if (ctype_digit($query)) {
        $whereParts[] = 'customers.id = ' . (int)$query;
        $rankParts[] = 'CASE WHEN customers.id = ' . (int)$query . ' THEN 0 ELSE 100 END';
    }

    $rankExpression = implode(' + ', $rankParts);
    $subscriptionCountSelect = '0';
    $deliveryUrlCountSelect = '0';
    $deliveryCredentialsCountSelect = '0';

    if (
        schema_object_exists($db, 'orders')
        && schema_column_exists($db, 'orders', 'delivery_link')
    ) {
        $deliveryLinkExistsSql = "TRIM(COALESCE(customer_delivery_orders.delivery_link, '')) <> ''";
        $subscriptionProductJoin = '';
        $subscriptionProductWhere = '';
        if (
            schema_object_exists($db, 'products')
            && schema_column_exists($db, 'products', 'product_type')
        ) {
            $subscriptionProductJoin = 'LEFT JOIN products AS customer_delivery_products ON customer_delivery_products.id = customer_delivery_orders.product_id';
            $subscriptionProductWhere = "AND (customer_delivery_products.id IS NULL OR customer_delivery_products.product_type = 'subscription')";
        }
        $subscriptionCountSelect = "(
            SELECT COUNT(*)
            FROM orders AS customer_delivery_orders
            {$subscriptionProductJoin}
            WHERE customer_delivery_orders.customer_id = customers.id
              {$subscriptionProductWhere}
        )";
        if (schema_column_exists($db, 'orders', 'delivery_link_visible')) {
            $deliveryUrlCountSelect = "(
                SELECT COUNT(*)
                FROM orders AS customer_delivery_orders
                {$subscriptionProductJoin}
                WHERE customer_delivery_orders.customer_id = customers.id
                  AND {$deliveryLinkExistsSql}
                  AND customer_delivery_orders.delivery_link_visible = 1
                  {$subscriptionProductWhere}
            )";
            $deliveryCredentialsCountSelect = "(
                SELECT COUNT(*)
                FROM orders AS customer_delivery_orders
                {$subscriptionProductJoin}
                WHERE customer_delivery_orders.customer_id = customers.id
                  AND {$deliveryLinkExistsSql}
                  AND COALESCE(customer_delivery_orders.delivery_link_visible, 0) = 0
                  {$subscriptionProductWhere}
            )";
        } else {
            $deliveryCredentialsCountSelect = "(
                SELECT COUNT(*)
                FROM orders AS customer_delivery_orders
                {$subscriptionProductJoin}
                WHERE customer_delivery_orders.customer_id = customers.id
                  AND {$deliveryLinkExistsSql}
                  {$subscriptionProductWhere}
            )";
        }
    }

    return $db->select_full_user(
        "SELECT
            customers.id,
            customers.email,
            customers.public_handle,
            customers.status,
            customers.customer_type,
            customers.locale_code,
            customers.avatar_url,
            customers.registered_at,
            customers.last_login_at,
            {$subscriptionCountSelect} AS subscription_count,
            {$deliveryUrlCountSelect} AS delivery_url_count,
            {$deliveryCredentialsCountSelect} AS delivery_credentials_count,
            ({$rankExpression}) AS search_rank
         FROM customers
         WHERE (" . implode(' OR ', $whereParts) . ")
         ORDER BY search_rank ASC, customers.id DESC
         LIMIT {$limit}"
    );
}

function admin_search_wallet_rows(Mysql_ks $db, string $query, int $limit = 20): array
{
    $query = trim($query);
    if ($query === '' || !schema_object_exists($db, 'crypto_wallet_addresses')) {
        return [];
    }

    app_ensure_customer_runtime_columns($db);

    $limit = max(1, min(50, $limit));
    $safeLike = $db->escape('%' . $query . '%');
    $safeExact = $db->escape(strtolower($query));

    return $db->select_full_user(
        "SELECT
            wallet.id AS wallet_address_id,
            assignment.customer_id,
            customer.email AS customer_email,
            customer.public_handle,
            asset.code AS crypto_asset_code,
            asset.name AS crypto_asset_name,
            wallet.label,
            wallet.address,
            wallet.wallet_provider,
            wallet.status,
            assignment.assigned_at,
            assignment.released_at,
            (
                CASE WHEN LOWER(wallet.address) = '{$safeExact}' THEN 0 ELSE 100 END
                + CASE WHEN LOWER(customer.email) = '{$safeExact}' THEN 1 ELSE 100 END
                + CASE WHEN LOWER(customer.public_handle) = '{$safeExact}' THEN 2 ELSE 100 END
                + CASE WHEN LOWER(wallet.label) = '{$safeExact}' THEN 3 ELSE 100 END
                + CASE WHEN LOWER(asset.code) = '{$safeExact}' THEN 4 ELSE 100 END
            ) AS search_rank
         FROM crypto_wallet_addresses AS wallet
         LEFT JOIN crypto_assets AS asset
            ON asset.id = wallet.crypto_asset_id
         LEFT JOIN crypto_wallet_assignments AS assignment
            ON assignment.id = (
                SELECT inner_assignment.id
                FROM crypto_wallet_assignments AS inner_assignment
                WHERE inner_assignment.wallet_address_id = wallet.id
                  AND inner_assignment.status IN ('reserved', 'active')
                ORDER BY inner_assignment.assigned_at DESC, inner_assignment.id DESC
                LIMIT 1
            )
         LEFT JOIN customers AS customer
            ON customer.id = assignment.customer_id
         WHERE wallet.address LIKE '{$safeLike}'
            OR wallet.label LIKE '{$safeLike}'
            OR wallet.wallet_provider LIKE '{$safeLike}'
            OR asset.code LIKE '{$safeLike}'
            OR asset.name LIKE '{$safeLike}'
            OR customer.email LIKE '{$safeLike}'
            OR customer.public_handle LIKE '{$safeLike}'
         ORDER BY search_rank ASC, wallet.id DESC
         LIMIT {$limit}"
    );
}

function admin_crypto_asset_logo_url(string $assetCode): string
{
    $assetCode = strtolower(trim($assetCode));
    if ($assetCode !== '') {
        $directMap = [
            'btc' => 'btc.png',
            'bch' => 'btcash.png',
            'ltc' => 'ltc.png',
            'eth' => 'eth.png',
            'doge' => 'doge.png',
            'bnb' => 'bnb.png',
            'busd' => 'busd.png',
            'cro' => 'cro.png',
            'atom' => 'atom.png',
            'sol' => 'sol.png',
            'pol' => 'matic.png',
            'matic' => 'matic.png',
            'xrp' => 'xrp.png',
            'trx' => 'trx.png',
        ];

        if (isset($directMap[$assetCode])) {
            return '/img/crypto/' . $directMap[$assetCode];
        }
    }

    $map = [
        'usdt' => 'tether.png',
        'usdc' => 'usdc.png',
    ];

    if ($assetCode !== '' && isset($map[$assetCode])) {
        return '/img/crypto/' . $map[$assetCode];
    }

    return '/img/crypto/blockchain.png';
}

function admin_customer_status_badge_class(string $status): string
{
    $status = strtolower(trim($status));

    if (in_array($status, ['active', 'verified'], true)) {
        return 'admin-status-pill--available';
    }

    if (in_array($status, ['pending', 'awaiting_review', 'waiting'], true)) {
        return 'admin-status-pill--warning';
    }

    if (in_array($status, ['disabled', 'inactive', 'banned', 'blocked', 'deleted'], true)) {
        return 'admin-status-pill--danger';
    }

    return 'admin-status-pill--muted';
}

function admin_wallet_status_badge_class(string $status): string
{
    $status = strtolower(trim($status));

    if (in_array($status, ['active', 'available', 'assigned'], true)) {
        return 'admin-status-pill--available';
    }

    if (in_array($status, ['pending', 'reserved', 'awaiting_confirmation', 'awaiting_review'], true)) {
        return 'admin-status-pill--warning';
    }

    if (in_array($status, ['released', 'disabled', 'inactive', 'rejected', 'cancelled'], true)) {
        return 'admin-status-pill--danger';
    }

    return 'admin-status-pill--muted';
}

function admin_search_customer_avatar_visual(array $row): array
{
    $avatarUrl = function_exists('app_customer_avatar_url')
        ? app_customer_avatar_url((string)($row['avatar_url'] ?? ''))
        : trim((string)($row['avatar_url'] ?? ''));
    if ($avatarUrl !== '') {
        return [
            'type' => 'image',
            'src' => $avatarUrl,
            'alt' => (string)($row['email'] ?? 'User'),
        ];
    }

    $customerRow = [
        'public_handle' => (string)($row['public_handle'] ?? ''),
        'email' => (string)($row['email'] ?? ''),
    ];
    $initial = function_exists('app_customer_avatar_initial')
        ? app_customer_avatar_initial($customerRow)
        : strtoupper(substr((string)($row['email'] ?? 'U'), 0, 1));
    $theme = function_exists('app_customer_avatar_theme')
        ? app_customer_avatar_theme($customerRow)
        : 'theme-1';

    return [
        'type' => 'initial',
        'initial' => $initial !== '' ? $initial : 'U',
        'theme' => $theme,
    ];
}

function admin_render_search_results_html(array $resultSets, array $messages, string $query): string
{
    $title = admin_e(admin_t($messages, 'search_results_title', 'Search results'));
    $emptyTitle = admin_e(admin_t($messages, 'search_empty_title', 'No matching orders'));
    $emptyText = admin_e(admin_t($messages, 'search_empty_text', 'Try a different order ID, customer email or wallet address.'));
    $orders = isset($resultSets['orders']) && is_array($resultSets['orders']) ? $resultSets['orders'] : [];
    $customers = isset($resultSets['customers']) && is_array($resultSets['customers']) ? $resultSets['customers'] : [];
    $wallets = isset($resultSets['wallets']) && is_array($resultSets['wallets']) ? $resultSets['wallets'] : [];
    $hasResults = $orders || $customers || $wallets;
    $normalizedQuery = strtolower(trim($query));
    $canQuickCreateCustomer = $normalizedQuery !== '' && filter_var($normalizedQuery, FILTER_VALIDATE_EMAIL);
    $quickCreateLabel = admin_e(admin_t($messages, 'search_quick_create_customer', 'Add this email as a new user'));
    $quickCreateHint = admin_e(admin_t($messages, 'search_quick_create_customer_hint', 'The email is valid and does not exist in the database yet.'));

    ob_start();
    ?>
    <article class="admin-panel-card admin-search-card">
        <div class="admin-search-card__title">
            <div class="admin-search-card__heading">
                <span class="admin-search-card__icon" aria-hidden="true"><i class="bi bi-search"></i></span>
                <div><h2><?php echo $title; ?></h2><p><?php echo admin_e(admin_t($messages, 'search_results_hint', 'Customers, orders and wallets in one place.')); ?></p></div>
            </div>
            <div class="admin-search-card__summary">
                <span class="admin-search-card__query" title="<?php echo admin_e($query); ?>"><?php echo admin_e($query); ?></span>
                <span class="admin-search-card__count" role="status"><?php echo admin_e(admin_t($messages, 'search_results_count', 'Results: {count}', ['count' => count($customers) + count($orders) + count($wallets)])); ?></span>
            </div>
        </div>

        <?php if (!$hasResults): ?>
            <div class="admin-search-empty"><span class="admin-search-empty__icon" aria-hidden="true"><i class="bi bi-search"></i></span>
                <strong><?php echo $emptyTitle; ?></strong>
                <p><?php echo $emptyText; ?></p>
                <?php if ($canQuickCreateCustomer): ?>
                    <button type="button" class="btn btn-dark admin-search-empty__action" data-admin-search-create-user data-email="<?php echo admin_e($normalizedQuery); ?>">
                        <i class="bi bi-person-plus" aria-hidden="true"></i>
                        <span><?php echo $quickCreateLabel; ?></span>
                    </button>
                    <small><?php echo $quickCreateHint; ?></small>
                <?php endif; ?>
            </div>
        <?php else: ?>
            <?php if ($customers): ?>
                <section class="admin-search-section">
                    <h3 class="admin-search-section__label"><i class="bi bi-people" aria-hidden="true"></i><span><?php echo admin_e(admin_t($messages, 'search_section_users', 'Users')); ?></span><span class="admin-search-section__count"><?php echo count($customers); ?></span></h3>
                    <div class="admin-search-user-list">
                        <?php foreach ($customers as $row): ?>
                            <?php
                            $avatarVisual = admin_search_customer_avatar_visual($row);
                            $presence = admin_chat_customer_presence(
                                Mysql_ks::get_instance(),
